function loadExperiences() {
  try {
    const saved = localStorage.getItem("experience-hub-data");
    if (saved) {
      const parsed = JSON.parse(saved);
      if (parsed?.encrypted) return [];
      const experiences = normalizeExperiences(parsed);
      if (experiences.length) return upgradeDemoExperiencesIfNeeded(experiences);
      return [];
    }
  } catch {
    return createDemoExperiences();
  }
  return normalizeExperiences(createDemoExperiences());
}

function upgradeDemoExperiencesIfNeeded(experiences) {
  const demoItems = experiences.filter((item) => item.isDemo);
  const realItems = experiences.filter((item) => !item.isDemo);
  const hasOldDemo = demoItems.length && demoItems.some((item) => item.demoBatch !== DEMO_BATCH);
  if (!hasOldDemo) return experiences;
  const upgraded = [...createDemoExperiences(), ...realItems];
  try {
    localStorage.setItem("experience-hub-data", JSON.stringify(upgraded));
  } catch {
    // Ignore migration persistence restrictions.
  }
  return upgraded;
}

