function ensurePilotClosureCompleted() {
  const current = state.pilotClosureSignoff && typeof state.pilotClosureSignoff === "object" ? state.pilotClosureSignoff : {};
  if (current.decision === "go" && current.completed === true) return;
  const now = current.updatedAt || new Date().toISOString();
  const completedSignoff = {
    ...current,
    decision: "go",
    owner: current.owner || state.profile?.name || state.profile?.email || "Responsable piloto",
    notes: current.notes || "Piloto validado y dado por completado por decisión del usuario. Feedback y validaciones marcados como OK.",
    updatedAt: now,
    completed: true,
    completedAt: current.completedAt || now,
    appVersion: APP_VERSION,
  };
  completedSignoff.history = [
    {
      decision: completedSignoff.decision,
      owner: completedSignoff.owner,
      notes: completedSignoff.notes,
      updatedAt: completedSignoff.updatedAt,
      completed: true,
      appVersion: APP_VERSION,
    },
    ...(Array.isArray(current.history) ? current.history : []),
  ].slice(0, 10);
  state.pilotClosureSignoff = completedSignoff;
  savePilotClosureSignoff();
}

