function t(path) {
  const parts = path.split(".");
  const language = normalizeLanguage(state.language);
  let value = i18n[language] || i18n.es;
  for (const part of parts) value = value?.[part];
  if (value === undefined && (language === "fr" || language === "pt")) {
    value = i18n.en;
    for (const part of parts) value = value?.[part];
  }
  if (value === undefined && language !== "es") {
    value = i18n.es;
    for (const part of parts) value = value?.[part];
  }
  return value ? value : path;
}

function languageText(es, en, fr = en, pt = es) {
  if (state.language === "pt") return pt;
  if (state.language === "fr") return fr;
  return state.language === "es" ? es : en;
}

const API_FAILURES_BEFORE_OFFLINE = 3;
const API_RECENT_SUCCESS_GRACE_MS = 2 * 60 * 1000;

function markApiOnline(details = {}) {
  state.apiOnline = true;
  state.connectivity = {
    ...(state.connectivity || {}),
    status: "online",
    consecutiveFailures: 0,
    lastOkAt: new Date().toISOString(),
    lastFailureAt: state.connectivity?.lastFailureAt || "",
    lastFailureMessage: "",
  };
  if (details.health) state.health = details.health;
  if (details.persistence) state.persistence = details.persistence;
}

function markApiConnectivityFailure(error, options = {}) {
  const consecutiveFailures = Number(state.connectivity?.consecutiveFailures || 0) + 1;
  const lastFailureMessage = String(error?.message || error || "").trim();
  const lastOkMs = Date.parse(state.connectivity?.lastOkAt || "");
  const hasFreshSuccess = Number.isFinite(lastOkMs) && Date.now() - lastOkMs < API_RECENT_SUCCESS_GRACE_MS;
  const hadAnySuccess = Boolean(state.connectivity?.lastOkAt);
  const shouldDeclareOffline =
    options.forceOffline ||
    (options.immediate && !hasFreshSuccess) ||
    (!hadAnySuccess && !hasFreshSuccess) ||
    consecutiveFailures >= API_FAILURES_BEFORE_OFFLINE;
  state.connectivity = {
    ...(state.connectivity || {}),
    status: shouldDeclareOffline ? "offline" : "slow",
    consecutiveFailures,
    lastOkAt: state.connectivity?.lastOkAt || "",
    lastFailureAt: new Date().toISOString(),
    lastFailureMessage,
  };
  if (shouldDeclareOffline) state.apiOnline = false;
  return state.connectivity.status;
}

function getConnectivitySummary() {
  const pending = state.offlineQueue?.length || 0;
  const hasSession = Boolean(state.session?.access_token);
  const labels = {
    synced: languageText("Sincronizado", "Synced", "Synchronisé"),
    syncing: languageText("Sincronizando", "Syncing", "Synchronisation"),
    pending: languageText("guardado pendiente", "pending save", "enregistrement en attente"),
    signIn: languageText("Entrar para guardar", "Sign in to save", "Connexion requise"),
    slow: languageText("Servidor lento", "Server slow", "Serveur lent"),
    offline: languageText("Conexión pendiente", "Connection pending", "Connexion en attente"),
    local: languageText("Modo local", "Local mode", "Mode local"),
  };
  if (!state.config || state.config.persistence !== "supabase") {
    return { text: labels.local, tone: "neutral", action: "status" };
  }
  if (!hasSession) return { text: labels.signIn, tone: "warn", action: "auth" };
  if (pending) return { text: `${pending} ${labels.pending}`, tone: "warn", action: "sync" };
  if (state.attachmentRetryInProgress || state.serverSync?.inProgress) {
    return { text: labels.syncing, tone: "neutral", action: "status" };
  }
  if (state.connectivity?.status === "slow") return { text: labels.synced, tone: "ok", action: "status" };
  if ((!state.apiOnline || state.connectivity?.status === "offline") && pending) return { text: labels.offline, tone: "warn", action: "sync" };
  if (!state.apiOnline || state.connectivity?.status === "offline") return { text: labels.synced, tone: "neutral", action: "status" };
  return { text: labels.synced, tone: "ok", action: "status" };
}

