async function hydrateFromApi() {
  const startedAt = performance.now();
  try {
    const health = await apiRequest("/health", { skipAuth: true });
    markApiOnline({ health, persistence: health.persistence || "json-file" });
    state.persistence = health.persistence || "json-file";
    state.health = health;
    state.apiStatus = {
      ok: true,
      checkedAt: new Date().toISOString(),
      latencyMs: Math.round(performance.now() - startedAt),
      message: state.language !== "es" ? "Local API responded correctly." : "La API local respondió correctamente.",
      service: health.service || "experience-hub-api",
      mode: health.persistence || "json-file",
    };

    if (state.persistence === "supabase" && !state.session?.access_token) {
      if (!state.experiences.length) {
        state.experiences = createDemoExperiences();
        saveExperiences();
      }
      renderAuthStatus();
      saveExperiences();
      return;
    }

    const [profile, experiences, agendaEvents, latestDailyBriefing, serverAssets] = await Promise.all([
      apiRequest("/profile"),
      apiRequest("/experiences"),
      apiRequest("/agenda").catch(() => null),
      apiRequest(`/daily-briefing/latest?locale=${encodeURIComponent(state.language)}`).catch(() => null),
      apiRequest("/assets").catch(() => []),
    ]);
    state.profile = profile;
    saveLocalProfile(profile);
    if (profile.language && i18n[profile.language]) {
      state.language = profile.language;
      document.getElementById("languageSelect").value = state.language;
      applyLanguage();
    }
    if (Array.isArray(experiences) && experiences.length > 0) {
      const remoteExperiences = normalizeExperiences(experiences);
      reconcileOfflineQueueWithRemote(remoteExperiences);
      state.experiences = mergeLocalMediaCacheForExperiences(remoteExperiences, state.experiences);
      hydrateBiometricImportsFromExperiences(state.experiences);
      saveExperiences();
    } else if (state.persistence !== "supabase") {
      await Promise.all(state.experiences.map((experience) => saveExperienceToApi(experience)));
    } else {
      state.experiences = [];
      saveExperiences();
    }
    if (Array.isArray(agendaEvents)) {
      const mergedAgenda = mergeRemoteAgendaEvents(agendaEvents, state.agendaEvents);
      const remoteIds = new Set(agendaEvents.map((item) => item.id));
      state.agendaEvents = mergedAgenda;
      saveAgendaEvents();
      const localOnly = mergedAgenda.filter((item) => item.id && !remoteIds.has(item.id) && !item.isDemo);
      await Promise.all(localOnly.slice(0, 50).map((item) => saveAgendaEventToApi(item, { silent: true })));
    }
    state.serverAssets = normalizeServerAssets(serverAssets);
    applyLatestServerDailyBriefing(latestDailyBriefing?.briefing);
    await syncOfflineQueue({ silent: true, skipServerRefresh: true });
    await loadBackendRoutines();
    await updateServerSyncStateBaseline({ silent: true });
    scheduleAutomaticAssetBacklogProcessing({ reason: "hydrate", delayMs: 1200, silent: true });
  } catch (error) {
    markApiConnectivityFailure(error, { immediate: true });
    state.persistence = "local";
    state.health = null;
    state.apiStatus = {
      ok: false,
      checkedAt: new Date().toISOString(),
      latencyMs: Math.round(performance.now() - startedAt),
      message: state.language !== "es"
         ? `Local API did not respond. The app keeps working with local data. ${error.message || ""}`.trim()
        : `La API local no respondió. La app sigue funcionando con datos locales. ${error.message || ""}`.trim(),
      service: "",
      mode: "local",
    };
  }
}

function setupServerSyncPolling() {
  window.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") pollServerSyncState({ reason: "visible" });
  });
  window.addEventListener("online", () => pollServerSyncState({ reason: "online" }));
  window.setInterval(() => {
    pollServerSyncState({ reason: "interval" });
  }, 15000);
}

async function updateServerSyncStateBaseline(options = {}) {
  if (!state.apiOnline || !state.session?.access_token) return null;
  try {
    const syncState = await apiRequest("/sync/state");
    state.serverSync = {
      ...state.serverSync,
      token: syncState.token || "",
      checkedAt: syncState.generatedAt || new Date().toISOString(),
      status: "synced",
      failures: 0,
      lastState: syncState,
    };
    return syncState;
  } catch (error) {
    if (!options.silent) console.warn("Server sync baseline failed", error);
    return null;
  }
}

async function pollServerSyncState(options = {}) {
  if (!state.apiOnline || !state.session?.access_token || state.serverSync.inProgress) return;
  if (document.visibilityState && document.visibilityState !== "visible" && options.reason !== "online") return;
  state.serverSync.inProgress = true;
  try {
    const syncState = await apiRequest("/sync/state");
    const previousToken = state.serverSync.token || "";
    const nextToken = syncState.token || "";
    state.serverSync.checkedAt = syncState.generatedAt || new Date().toISOString();
    state.serverSync.lastState = syncState;
    state.serverSync.failures = 0;
    if (previousToken && nextToken && previousToken !== nextToken) {
      state.serverSync.status = "refreshing";
      state.serverSync.changedAt = new Date().toISOString();
      await hydrateFromApi();
      state.serverSync.status = "synced";
      state.serverSync.token = nextToken;
      renderAll();
      notify(
        state.language !== "es"
           ? "Updated with changes from another device."
          : "Actualizado con cambios de otro dispositivo.",
        "success",
      );
      return;
    }
    state.serverSync.status = "synced";
    state.serverSync.token = nextToken || previousToken;
  } catch (error) {
    state.serverSync.status = "attention";
    state.serverSync.failures = Number(state.serverSync.failures || 0) + 1;
    if (state.serverSync.failures <= 2) console.warn("Server sync polling failed", error);
  } finally {
    state.serverSync.inProgress = false;
  }
}

