async function apiRequest(pathname, options = {}) {
  const response = await fetchApi(pathname, options);
  if (response.status === 401 && !options.skipAuth && !options._retriedAuth && state.session?.refresh_token) {
    const refreshed = await refreshSupabaseSession({ preserveOnFailure: options.preserveSessionOnAuthFailure });
    if (refreshed) return apiRequest(pathname, { ...options, _retriedAuth: true });
  }
  if (!response.ok) {
    let message = `API ${response.status}`;
    try {
      const payload = await response.json();
      message = payload?.message || payload?.error || message;
    } catch {
      // Keep the generic status message if the response is not JSON.
    }
    const error = new Error(message);
    error.status = response.status;
    throw error;
  }
  return response.json();
}

async function fetchApi(pathname, options = {}) {
  const bodyIsFormData = typeof FormData !== "undefined" && options.body instanceof FormData;
  const response = await fetch(`${API_BASE}${pathname}`, {
    headers: {
      ...(bodyIsFormData ? {} : { "Content-Type": "application/json" }),
      ...(!options.skipAuth && state.session?.access_token ? { Authorization: `Bearer ${state.session.access_token}` } : {}),
      ...(options.headers || {}),
    },
    ...withoutClientOptions(options),
  });
  return response;
}

function withoutClientOptions(options) {
  const { skipAuth, _retriedAuth, preserveSessionOnAuthFailure, ...rest } = options;
  return rest;
}

async function refreshSupabaseSession(options = {}) {
  if (!state.config?.supabaseUrl || !state.config?.supabasePublishableKey || !state.session?.refresh_token) return false;
  try {
    const session = await supabaseAuthRequest("/token?grant_type=refresh_token", {
      refresh_token: state.session.refresh_token,
    });
    if (!session?.access_token) return false;
    saveSession(session);
    renderAuthStatus();
    const message = document.getElementById("authMessage");
    if (message && document.getElementById("authView").classList.contains("active-view")) {
      message.textContent = t("labels.authSessionRefreshed");
    }
    return true;
  } catch {
    if (!options.preserveOnFailure) expireAuthSession();
    return false;
  }
}

function normalizeExperiences(experiences) {
  return experiences.map((item) => ({
    ...item,
    category: normalizeCategoryName(item.category),
    objective: item.objective || "",
    pilotParticipantId: item.pilotParticipantId || "",
    pilotParticipantName: item.pilotParticipantName || "",
    workspaceId: item.workspaceId || item.metadata?.workspaceId || "",
    events: normalizeExperienceEvents(item.events || item.metadata?.events || [], item.id),
    attachments: Array.isArray(item.attachments) ? item.attachments : [],
  }));
}

function normalizeExperienceItem(experience) {
  return normalizeExperiences([experience || {}])[0];
}

function normalizeServerAssets(assets = []) {
  if (!Array.isArray(assets)) return [];
  return assets
    .map((asset) => {
      const metadata = asset.metadata || {};
      const experienceId = asset.experienceId || asset.experience_id || metadata.linkedExperienceId || "";
      const adoptionStatus = asset.adoptionStatus || asset.adoption_status || metadata.adoptionStatus || (experienceId ? "adopted" : "inbox");
      return {
        ...asset,
        id: asset.id || asset.assetId || asset.asset_id || createId(),
        assetKey: asset.assetKey || asset.id || asset.assetId || asset.asset_id || "",
        name: asset.name || asset.fileName || asset.filename || "Activo",
        kind: asset.kind || inferMediaKind(asset),
        type: asset.type || asset.mimeType || asset.mime_type || "application/octet-stream",
        size: Number(asset.size || asset.sizeBytes || asset.size_bytes || 0),
        experienceId,
        participantId: asset.participantId || asset.participant_id || metadata.participantId || "",
        eventId: asset.eventId || asset.event_id || metadata.linkedEventId || "",
        adoptionStatus,
        evidenceType: asset.evidenceType || asset.evidence_type || metadata.evidenceType || "intentional",
        payloadType: asset.payloadType || asset.payload_type || metadata.payloadType || "",
        capturedAt: asset.capturedAt || asset.captured_at || metadata.capturedAt || asset.createdAt || "",
        uploadedAt: asset.uploadedAt || asset.uploaded_at || metadata.uploadedAt || "",
        sourceType: asset.sourceType || asset.source_type || metadata.sourceType || "",
        sourceDevice: asset.sourceDevice || asset.source_device || metadata.sourceDevice || "",
        storage: asset.storage || (asset.path || asset.url ? "supabase" : ""),
        path: asset.path || asset.storagePath || asset.storage_path || "",
        previewText: asset.previewText || asset.preview_text || "",
        analysisText: asset.analysisText || asset.analysis_text || "",
        metadata,
      };
    })
    .filter((asset) => asset.id || asset.assetKey || asset.name);
}

function normalizeAgendaEvents(events = []) {
  if (!Array.isArray(events)) return [];
  return events
    .map((event) => ({
      ...event,
      id: event.id || event.eventId || createId(),
      title: String(event.title || "").trim() || (state.language !== "es" ? "Event" : "Evento"),
      type: event.type || "Personal",
      description: event.description || "",
      startAt: event.startAt || event.start_at || new Date().toISOString(),
      endAt: event.endAt || event.end_at || new Date(Date.now() + 60 * 60 * 1000).toISOString(),
      location: event.location || (state.language !== "es" ? "No location" : "Sin ubicación"),
      participants: event.participants || (state.language !== "es" ? "No participants" : "Sin participantes"),
      priority: event.priority || "normal",
      status: event.status || "Planificado",
      reminders: event.reminders || "",
      sourceType: event.sourceType || event.source || "manual",
      pilotParticipantId: event.pilotParticipantId || event.participantId || "",
      pilotParticipantName: event.pilotParticipantName || "",
      createdAt: event.createdAt || new Date().toISOString(),
      updatedAt: event.updatedAt || "",
    }))
    .filter((event) => event.id && event.title);
}

function mergeRemoteAgendaEvents(remoteEvents = [], localEvents = []) {
  const map = new Map();
  normalizeAgendaEvents(localEvents).forEach((event) => map.set(event.id, event));
  normalizeAgendaEvents(remoteEvents).forEach((event) => map.set(event.id, { ...map.get(event.id), ...event, remoteSynced: true }));
  return [...map.values()].sort((a, b) => new Date(a.startAt || 0) - new Date(b.startAt || 0));
}

function normalizeExperienceEvents(events = [], experienceId = "") {
  if (!Array.isArray(events)) return [];
  return events
    .map((event, index) => {
      const narrativeText = getEventNarrativeTextForExport(event);
      return {
        id: event.id || event.eventId || `evt-${experienceId || "experience"}-${index + 1}`,
        title: String(event.title || event.name || "").trim(),
        description: String(event.description || event.notes || "").trim(),
        order: Number.isFinite(Number(event.order)) ? Number(event.order) : index + 1,
        timestamp: event.timestamp || event.occurredAt || "",
        duration: event.duration ? Number(event.duration) : null,
        mood: event.mood || "",
        energy: event.energy ? Number(event.energy) : null,
        narrativeText,
        narrativeStatus: narrativeText ? "ok" : "pending",
      };
    })
    .filter((event) => event.title || event.description);
}

function getExperienceEventTimeline(item) {
  return normalizeExperienceEvents(item?.events || [], item?.id || "").sort((a, b) => a.order - b.order);
}

function buildReportEventTimeline(experiences = []) {
  return experiences
    .flatMap((experience) =>
      getExperienceEventTimeline(experience).map((event) => ({
        ...event,
        experienceId: experience.id,
        experienceTitle: experience.title,
        experienceTimestamp: experience.timestamp,
        category: displayCategory(experience.category),
        participantName: getExperiencePilotParticipantLabel(experience),
      })),
    )
    .sort((a, b) => {
      const dateDelta = new Date(a.experienceTimestamp || 0).getTime() - new Date(b.experienceTimestamp || 0).getTime();
      return dateDelta || a.order - b.order;
    });
}

function buildExperienceEventSearchText(item) {
  return getExperienceEventTimeline(item)
    .map((event) => `${event.title} ${event.description} ${event.mood || ""}`)
    .join(" ");
}

function buildExperienceEventSummary(item, limit = 6) {
  const events = getExperienceEventTimeline(item);
  const visible = events.slice(0, limit).map((event) => `${event.order}. ${event.title || event.description}`);
  const remaining = events.length - visible.length;
  return remaining > 0 ? `${visible.join(" | ")} | +${remaining}` : visible.join(" | ");
}

function parseExperienceEventsInput(value = "", experienceId = "") {
  return String(value || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line, index) => {
      const [title, ...descriptionParts] = line.split(/\s+[-:]\s+/);
      return {
        id: `evt-${experienceId || Date.now()}-${index + 1}`,
        title: (title || line).trim(),
        description: descriptionParts.join(" - ").trim(),
        order: index + 1,
      };
    });
}

function getCaptureEventOptions(experienceId = document.getElementById("editingId")?.value || "draft") {
  return parseExperienceEventsInput(document.getElementById("experienceEventsInput")?.value || "", experienceId)
    .sort((a, b) => a.order - b.order)
    .map((event) => ({
      ...event,
      ref: `event-${event.order}`,
      label: event.title || event.description || `${state.language !== "es" ? "Event" : "Evento"} ${event.order}`,
    }));
}

function getAttachmentEventRef(attachment = {}, eventOptions = []) {
  if (attachment.eventRef && eventOptions.some((event) => event.ref === attachment.eventRef)) return attachment.eventRef;
  if (attachment.eventId) {
    const matched = eventOptions.find((event) => event.id === attachment.eventId);
    if (matched) return matched.ref;
  }
  if (attachment.eventOrder) {
    const matched = eventOptions.find((event) => Number(event.order) === Number(attachment.eventOrder));
    if (matched) return matched.ref;
  }
  return "";
}

function linkAttachmentsToEvents(attachments = [], events = []) {
  return attachments.map((attachment) => {
    const eventRef = attachment.eventRef || (attachment.eventOrder ? `event-${attachment.eventOrder}` : "");
    const linkedEvent = eventRef ? events.find((event) => `event-${event.order}` === eventRef) : null;
    if (!linkedEvent) {
      const { eventId, eventTitle, eventOrder, ...rest } = attachment;
      return {
        ...rest,
        eventRef: "",
        metadata: {
          ...(attachment.metadata || {}),
          linkedEventId: "",
          linkedEventTitle: "",
          eventOrder: "",
        },
      };
    }
    return {
      ...attachment,
      eventRef,
      eventId: linkedEvent.id,
      eventTitle: linkedEvent.title,
      eventOrder: linkedEvent.order,
      metadata: {
        ...(attachment.metadata || {}),
        linkedEventId: linkedEvent.id,
        linkedEventTitle: linkedEvent.title,
        eventOrder: linkedEvent.order,
      },
    };
  });
}

function normalizeCategoryName(category) {
  return categoryAliases[category] || category || "Sin categoría";
}

function displayCategory(category) {
  const normalized = normalizeCategoryName(category);
  const label = t(`labels.categoryLabels.${normalized}`);
  return label && !String(label).startsWith("labels.") ? label : normalized;
}

function isRealExperienceCategory(category) {
  const normalized = normalizeCategoryName(category);
  return Boolean(normalized && categories.includes(normalized));
}

function getExperienceCategoryForExport(experience = {}) {
  const normalized = normalizeCategoryName(experience.category || "");
  if (!isRealExperienceCategory(normalized)) return null;
  if (/dato del usuario|user data/i.test(normalized)) return null;
  return normalized;
}

function getExperienceEnergyForExport(experience = {}) {
  const raw = Number(experience.energy);
  if (!Number.isFinite(raw) || raw < 1 || raw > 10) return null;
  const source = String(experience.metadata?.energySource || experience.energySource || "").toLowerCase();
  if (source === "default" || source === "placeholder") return null;
  if ((raw === 5 || raw === 7) && (isExperienceMapContextSignal(experience) || isTechnicalMediaOnlyExperience(experience))) return null;
  return raw;
}

function saveExperiences() {
  try {
    const localKey = document.getElementById("localKeyInput")?.value;
    if (readPrivacySettings().sensitiveMode && localKey) {
      encryptLocalPayload(state.experiences, localKey)
        .then((encrypted) => localStorage.setItem("experience-hub-data", JSON.stringify(encrypted)))
        .catch(() => {});
      return true;
    }
    localStorage.setItem("experience-hub-data", JSON.stringify(state.experiences));
    return true;
  } catch {
    // Some embedded browsers restrict localStorage on file:// URLs.
    return false;
  }
}

