function setupLanguage() {
  const select = document.getElementById("languageSelect");
  if (!select) return;
  select.innerHTML = SUPPORTED_LANGUAGES
    .map((language) => `<option value="${language.code}">${language.short}</option>`)
    .join("");
  select.value = state.language;
  select.addEventListener("change", async (event) => {
    state.language = normalizeLanguage(event.target.value);
    select.value = state.language;
    try {
      localStorage.setItem("experience-hub-language", state.language);
    } catch {
      // Ignore language persistence restrictions.
    }
    applyLanguage();
    populateStaticControls();
    renderAll();
    if (state.apiOnline) {
      try {
        await apiRequest("/profile", {
          method: "PUT",
          body: JSON.stringify({ language: state.language }),
        });
      } catch (error) {
        markApiConnectivityFailure(error);
      }
    }
  });
  renderAuthStatePanel();
}

