function setupForm() {
  const form = document.getElementById("experienceForm");
  document.getElementById("timestampInput").value = toDatetimeLocal(new Date().toISOString());

  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (requiresRemotePersistence() && !state.session?.access_token) {
      state.captureSaveStatus = buildCaptureBlockedStatus("auth_required");
      renderCaptureSaveStatus();
      renderPersistenceGateBanner();
      notify(state.captureSaveStatus.detail, "warn");
      state.pendingAuthReturn = "capture";
      showAuthView();
      return;
    }
    let savedCommitted = false;
    let savedExperience = null;
    let agendaRequested = false;
    let savePhase = "starting";
    try {
      savePhase = "validation";
      validateCaptureFormBeforeRead();
      savePhase = "read_form";
      const experience = await readForm();
      savedExperience = experience;
      const existingIndex = state.experiences.findIndex((item) => item.id === experience.id);

      savePhase = "local_state";
      if (existingIndex >= 0) {
        state.experiences[existingIndex] = experience;
      } else {
        state.experiences.unshift(experience);
      }

      savePhase = "local_persistence";
      const localSaved = saveExperiences();
      savedCommitted = true;
      savePhase = "remote_persistence";
      const apiResult = await saveExperienceToApi(experience);
      if (apiResult?.experience) {
        savePhase = "remote_merge";
        const remoteExperience = mergeLocalMediaCacheForExperience(normalizeExperienceItem(apiResult.experience), experience);
        const remoteIndex = state.experiences.findIndex((item) => item.id === remoteExperience.id);
        if (remoteIndex >= 0) state.experiences[remoteIndex] = remoteExperience;
        else state.experiences.unshift(remoteExperience);
        savedExperience = remoteExperience;
        saveExperiences();
      }
      if (apiResult?.remote) {
        savePhase = "evidence_adoption";
        await adoptSelectedEvidenceForExperience(savedExperience || experience);
        scheduleAutomaticAssetProcessing(savedExperience || experience);
      }
      state.lastSavedExperienceId = experience.id;
      state.captureSaveStatus = buildCaptureSaveStatus(savedExperience || experience, { ...apiResult, localSaved }, existingIndex >= 0);
      if (state.evidenceAdoptionStatus?.detail) {
        state.captureSaveStatus.detail += ` ${state.evidenceAdoptionStatus.detail}`;
      }
      agendaRequested = Boolean(document.getElementById("syncAgendaInput")?.checked);
      savePhase = "agenda_optional";
      const agendaSynced = agendaRequested ? syncExperienceToAgenda(experience) : false;
      if (agendaSynced) {
        state.captureSaveStatus.detail += state.language !== "es" ? " Agenda was updated because you selected it." : " Agenda/Calendario fue actualizado porque lo seleccionaste.";
      }
      notify(state.captureSaveStatus.detail, apiResult?.queued || !localSaved ? "warn" : "success");
      if (apiResult?.remote || localSaved) {
        clearForm();
      }
      try {
        savePhase = "interface_refresh";
        resetLibraryFilters({ syncInputs: false });
        renderAll();
        showView("capture");
      } catch (postSaveError) {
        console.warn("Post-save interface refresh failed", postSaveError);
        renderCaptureSaveStatus();
      }
    } catch (error) {
      if (savedCommitted && state.captureSaveStatus) {
        const detail = agendaRequested
          ? state.language !== "es"
             ? "The experience was saved. Agenda could not be updated; review it only if you intended to create a calendar event."
            : "La experiencia fue guardada. Agenda no pudo actualizarse; revísala solo si querías crear un evento de calendario."
          : state.captureSaveStatus.detail;
        if (agendaRequested) state.captureSaveStatus.detail = detail;
        state.captureSaveStatus.experienceId = savedExperience?.id || state.captureSaveStatus.experienceId;
        state.captureSaveStatus.experienceTitle = savedExperience?.title || state.captureSaveStatus.experienceTitle;
        renderCaptureSaveStatus();
        notify(detail, state.captureSaveStatus.type === "warn" ? "warn" : "success");
        console.warn("Post-save update failed", error);
        return;
      }
      const detail = getCaptureSaveErrorDetailActionable(error, savePhase);
      state.captureSaveStatus = {
        type: "warn",
        title: state.language !== "es" ? "Save failed" : "Guardado no completado",
        detail,
        experienceId: "",
        experienceTitle: "",
        savedAt: new Date().toISOString(),
      };
      renderCaptureSaveStatus();
      notify(detail, "warn");
      console.warn("Experience save failed", error);
    }
  });

  document.getElementById("clearFormButton").addEventListener("click", clearForm);
  document.getElementById("mediaInput").addEventListener("change", handleMediaSelection);
  form.addEventListener("input", renderCaptureWritingCoach);
  form.addEventListener("change", renderCaptureWritingCoach);
  document.getElementById("timestampInput")?.addEventListener("change", renderBiometricCaptureContext);
  document.getElementById("durationInput")?.addEventListener("change", renderBiometricCaptureContext);
  document.getElementById("timestampInput")?.addEventListener("change", renderCaptureEvidenceInbox);
  document.getElementById("durationInput")?.addEventListener("change", renderCaptureEvidenceInbox);
  document.getElementById("pilotParticipantInput")?.addEventListener("change", renderCaptureEvidenceInbox);
  document.getElementById("categoryInput")?.addEventListener("change", renderCaptureCategoryClassificationHelp);
  document.getElementById("energyInput")?.addEventListener("input", renderBiometricCaptureContext);
  document.getElementById("biometricCaptureContext")?.addEventListener("click", handleBiometricCaptureContextClick);
  form.addEventListener("input", () => scheduleCaptureDraftAutosave("input"));
  form.addEventListener("change", () => scheduleCaptureDraftAutosave("change"));
  document.getElementById("experienceEventsInput")?.addEventListener("input", () => {
    renderCaptureEventPreview();
    renderAttachmentPreview();
    scheduleCaptureDraftAutosave("events");
  });
  document.getElementById("attachmentPreview")?.addEventListener("change", handleAttachmentEventSelection);
  document.getElementById("captureEvidenceInbox")?.addEventListener("change", handleEvidenceInboxSelection);
  document.getElementById("captureEvidenceInbox")?.addEventListener("click", handleEvidenceInboxAction);
  document.getElementById("captureSaveStatus")?.addEventListener("click", handleCaptureSaveStatusClick);
}

function getCaptureCategoryLabel(category) {
  const normalized = normalizeCategoryName(category);
  const labels = {
    Salud: languageText("Salud (evento vivido)", "Health (lived event)", "Sante (evenement vecu)", "Saude (evento vivido)"),
    Compras: languageText("Compras (vivencia o decision)", "Shopping (lived moment or decision)", "Achats (experience ou decision)", "Compras (vivencia ou decisao)"),
  };
  return labels[normalized] || displayCategory(normalized);
}

