function syncReportFilterInputs() {
  const scope = document.getElementById("reportScopeFilter");
  const period = document.getElementById("reportPeriodFilter");
  const category = document.getElementById("reportCategoryFilter");
  const source = document.getElementById("reportSourceFilter");
  const dateFrom = document.getElementById("reportDateFromFilter");
  const dateTo = document.getElementById("reportDateToFilter");
  const pilotParticipant = document.getElementById("reportPilotParticipantFilter");
  const basis = document.getElementById("reportBasisFilter");
  const people = document.getElementById("reportPeopleFilter");
  const objective = document.getElementById("reportObjectiveFilter");
  const eventQuery = document.getElementById("reportEventFilter");
  const experience = document.getElementById("reportExperienceFilter");
  if (scope) scope.value = state.reportFilters.scope || "all";
  if (period) period.value = state.reportFilters.period || "all";
  if (category) category.value = state.reportFilters.category || "all";
  populateIntegrationSourceFilter("reportSourceFilter", state.reportFilters.source || "all");
  if (source) source.value = state.reportFilters.source || "all";
  if (dateFrom) dateFrom.value = state.reportFilters.dateFrom || "";
  if (dateTo) dateTo.value = state.reportFilters.dateTo || "";
  if (pilotParticipant) pilotParticipant.value = state.reportFilters.pilotParticipantId || "all";
  syncReportBasisSelect(state.reportFilters.basis || "all");
  if (basis) basis.value = state.reportFilters.basis || "all";
  if (people) people.value = state.reportFilters.people || "";
  if (objective) objective.value = state.reportFilters.objective || "";
  if (eventQuery) eventQuery.value = state.reportFilters.eventQuery || "";
  if (experience) experience.value = state.reportFilters.experienceId || "";
}

function syncAnalyticalScopeInputs() {
  const bindings = [
    ["insightsPilotParticipantFilter", state.insightsFilters.pilotParticipantId || "all"],
    ["insightsCategoryFilter", state.insightsFilters.category || "all"],
    ["insightsDateFromFilter", state.insightsFilters.dateFrom || ""],
    ["insightsDateToFilter", state.insightsFilters.dateTo || ""],
    ["publicationPilotParticipantFilter", state.publicationFilters.pilotParticipantId || "all"],
    ["publicationCategoryFilter", state.publicationFilters.category || "all"],
    ["publicationDateFromFilter", state.publicationFilters.dateFrom || ""],
    ["publicationDateToFilter", state.publicationFilters.dateTo || ""],
  ];
  bindings.forEach(([id, value]) => {
    const element = document.getElementById(id);
    if (element) element.value = value;
  });
  populateIntegrationSourceFilter("insightsSourceFilter", state.insightsFilters.source || "all");
  populateIntegrationSourceFilter("publicationSourceFilter", state.publicationFilters.source || "all");
  syncCustomBasisSelect("insightsBasisFilter", getInsightsBasisOptions(), state.insightsFilters.basis || "all");
  syncCustomBasisSelect("publicationBasisFilter", getPublicationBasisOptions(), state.publicationFilters.basis || "all");
  updateAnalyticalScopeStatus("insightsScopeStatus", state.insightsFilters, getInsightsOutputScope());
  updateAnalyticalScopeStatus("publicationScopeStatus", state.publicationFilters, getPublicationOutputScope());
}

function updateAnalyticalScopeStatus(statusId, filters = {}, count = 0) {
  const status = statusId ? document.getElementById(statusId) : null;
  if (!status) return;
  const parts = buildAnalyticalScopeParts(filters);
  if (count && typeof count === "object") {
    const baseText = parts.length ? parts.join(" / ") : languageText("Fuente general", "General source", "Source generale", "Fonte geral");
    const stories = Array.isArray(count.stories) ? count.stories.length : 0;
    const evidence = Array.isArray(count.evidence) ? count.evidence.length : 0;
    const context = Array.isArray(count.context) ? count.context.length : 0;
    status.textContent = `${baseText} / ${languageText(
      `${stories} historias, ${evidence} evidencias, ${context} contextos`,
      `${stories} stories, ${evidence} evidence items, ${context} context signals`,
      `${stories} histoires, ${evidence} preuves, ${context} contextes`,
      `${stories} historias, ${evidence} evidencias, ${context} contextos`,
    )}`;
    return;
  }
  const base = parts.length ? parts.join(" · ") : state.language !== "es" ? "General source" : "Fuente general";
  status.textContent = `${base} · ${count} ${state.language !== "es" ? "items" : "experiencias"}`;
}

function buildAnalyticalScopeParts(filters = {}) {
  const parts = [];
  const participantName = filters.pilotParticipantId && filters.pilotParticipantId !== "all" ? getPilotParticipantName(filters.pilotParticipantId) : "";
  if (participantName) parts.push(participantName);
  if (filters.category && filters.category !== "all") parts.push(displayCategory(filters.category));
  if (filters.source && filters.source !== "all") parts.push(getIntegrationSourceFilterLabel(filters.source));
  if (filters.dateFrom || filters.dateTo) parts.push(`${filters.dateFrom || "inicio"} - ${filters.dateTo || "hoy"}`);
  parts.push(getOutputBasisLabel(filters.basis || "all"));
  return parts;
}

function renderSharedScopeContext(containerId, filters = {}, count = 0, outputLabel = "", extraParts = []) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const labels = state.language !== "es"
     ? {
        title: "Scope used in this output",
        fallback: "Full view",
        count: "experiences",
        aligned: "Aligned with the shared analytical scope.",
        output: "Output",
      }
    : {
        title: "Alcance usado en esta salida",
        fallback: "Vista completa",
        count: "experiencias",
        aligned: "Alineado con el alcance analitico compartido.",
        output: "Salida",
      };
  const parts = [...buildAnalyticalScopeParts(filters), ...extraParts.filter(Boolean)].filter(Boolean);
  const visibleParts = parts.length ? parts : [labels.fallback];
  const countLabel = count && typeof count === "object"
    ? languageText(
        `${count.stories?.length || 0} historias / ${count.evidence?.length || 0} evidencias / ${count.context?.length || 0} contextos`,
        `${count.stories?.length || 0} stories / ${count.evidence?.length || 0} evidence items / ${count.context?.length || 0} context signals`,
        `${count.stories?.length || 0} histoires / ${count.evidence?.length || 0} preuves / ${count.context?.length || 0} contextes`,
        `${count.stories?.length || 0} historias / ${count.evidence?.length || 0} evidencias / ${count.context?.length || 0} contextos`,
      )
    : `${count} ${labels.count}`;
  container.innerHTML = `
    <div>
      <strong>${escapeHtml(labels.title)}</strong>
      <p>${escapeHtml(labels.aligned)}</p>
    </div>
    <div class="shared-scope-chip-row">
      <span>${escapeHtml(labels.output)}: ${escapeHtml(outputLabel || "-")}</span>
      ${visibleParts.slice(0, 6).map((part) => `<span>${escapeHtml(part)}</span>`).join("")}
      <span>${escapeHtml(countLabel)}</span>
    </div>
  `;
}

function generateReportFromScope() {
  renderReport();
  const outputScope = getReportOutputScope();
  const count = outputScope.stories.length;
  const scope = state.reportFilters.scope || "all";
  const scopeText = getReportScopeLabel(scope);
  setReportFlowStatus(
    state.language !== "es"
       ? `Report generated for ${count} experience(s). Scope: ${scopeText}. Continue with the acceptance pack.`
      : `Reporte generado para ${count} experiencia(s). Alcance: ${scopeText}. Lee la síntesis principal y luego usa el paquete de aceptación.`,
  );
  document.getElementById("reportSummary")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  notify(state.language !== "es" ? "Report generated." : "Reporte generado.", "success");
}

function resetReportScope() {
  state.reportFilters = {
    scope: "filters",
    period: "7",
    experienceId: "",
    basis: "all",
    category: "all",
    source: "all",
    pilotParticipantId: "all",
    ...getDefaultOutputScopeDates(),
    people: "",
    objective: "",
    eventQuery: "",
  };
  syncReportFilterInputs();
  renderReport();
  setReportFlowStatus(languageText(
    "Alcance restablecido a los ultimos 7 dias con historias y evidencia.",
    "Scope reset to the last 7 days with stories and evidence.",
    "Portee reinitialisee aux 7 derniers jours avec histoires et preuves.",
    "Escopo redefinido para os ultimos 7 dias com historias e evidencias.",
  ));
}

function scrollToReportAcceptance() {
  renderReportAcceptancePanel();
  document.getElementById("reportAcceptancePanel")?.scrollIntoView({ behavior: "smooth", block: "start" });
  setReportFlowStatus(state.language !== "es" ? "Review the acceptance pack and run the needed export buttons." : "Revisa el paquete de aceptación y ejecuta los botones de exportación necesarios.");
}

function setReportFlowStatus(message) {
  const status = document.getElementById("reportFlowStatus");
  if (status) status.textContent = message;
}

function handleReportScopeAction(event) {
  const target = event.target.closest("button");
  if (!target) return;
  if (target.id === "jumpReportAcceptanceButton") scrollToReportAcceptance();
}

function getReportScopeLabel(scope = state.reportFilters.scope) {
  const labels =
    state.language !== "es"
       ? {
          all: "all experiences",
          period: "quick range",
          filters: "category, person, origin, or objective filters",
          single: "one specific experience",
        }
      : {
          all: "todas las experiencias",
          period: "rango rápido",
          filters: "categoría, persona, origen u objetivo",
          single: "una experiencia específica",
        };
  return labels[scope] || labels.all;
}

