function handleParallelBacklogClick(event) {
  const button = event.target.closest("[data-backlog-view]");
  if (!button) return;
  const view = button.dataset.backlogView;
  if (button.dataset.backlogReturn === "coreMvpGatePanel") {
    state.coreMvpReturn = {
      fromView: view || "",
      focus: "coreMvpGatePanel",
      stepKey: button.dataset.mvpReturnStep || "",
      label: button.textContent.trim(),
      at: new Date().toISOString(),
    };
  }
  if (view) showView(view);
  const run = button.dataset.backlogRun;
  if (run === "syncOffline") syncOfflineQueue();
  if (run === "refreshOps") refreshOps();
  if (run === "backfillEmbeddings") backfillEmbeddings();
  if (run === "syncWorkspaceStructure") syncWorkspaceStructure();
  if (run === "showPendingAssetText") showPendingAssetText();
  if (run === "openAuthDiagnostics") {
    state.pendingAuthReturn = "quickQaDiagnostics";
    showAuthView();
    requestAnimationFrame(() => {
      const message = document.getElementById("authMessage");
      if (message) message.textContent = t("labels.authReturnQuickQa");
    });
  }
  if (run === "runSupabaseDiagnostics") runSupabaseDiagnostics();
  if (run === "runSupabaseSelfTest") runSupabaseSelfTest();
  const focusId = button.dataset.backlogFocus;
  if (focusId) requestAnimationFrame(() => focusAppElement(focusId));
  renderCoreMvpReturnBanner(view);
}

function focusAppElement(id) {
  const element = document.getElementById(id);
  if (!element) return;
  document.querySelectorAll(".focus-target").forEach((item) => item.classList.remove("focus-target"));
  if (!element.hasAttribute("tabindex")) element.setAttribute("tabindex", "-1");
  element.scrollIntoView({ behavior: "smooth", block: "start" });
  element.focus({ preventScroll: true });
  element.classList.add("focus-target");
  window.setTimeout(() => element.classList.remove("focus-target"), 2600);
}

function showPendingAssetText() {
  state.assetFilters.analysis = "without";
  state.assetFilters.processing = "pending";
  const select = document.getElementById("assetAnalysisFilter");
  if (select) select.value = "without";
  const processingSelect = document.getElementById("assetProcessingFilter");
  if (processingSelect) processingSelect.value = "pending";
  renderAssetLibrary();
  requestAnimationFrame(() => focusAppElement("assetProcessingActionPlan"));
}

function suggestAnalysisForFilteredAssets() {
  const assets = filterMultimodalAssets().filter((asset) => !String(asset.analysisText || "").trim());
  if (!assets.length) {
    const intro = document.getElementById("assetLibraryIntro");
    if (intro) intro.textContent = t("labels.assetBulkSuggestedAnalysisEmpty");
    notify(t("labels.assetBulkSuggestedAnalysisEmpty"), "warn");
    return;
  }
  assets.forEach((asset) => {
    const existing = state.assetMetadata[asset.assetKey] || {};
    const tags = Array.isArray(existing.tags) ? existing.tags : Array.isArray(asset.manualTags) ? asset.manualTags : [];
    const note = Object.hasOwn(existing, "note") ? existing.note : asset.manualNote || "";
    const analysisText = buildSuggestedAssetAnalysisText(asset, { tags, note });
    state.assetMetadata[asset.assetKey] = { tags, note, analysisText, updatedAt: new Date().toISOString(), suggested: true };
  });
  saveAssetMetadata();
  renderAssetLibrary();
  const message = t("labels.assetBulkSuggestedAnalysisSaved").replace("{count}", String(assets.length));
  const intro = document.getElementById("assetLibraryIntro");
  if (intro) intro.textContent = message;
  notify(message);
}

function clearAssetFilters() {
  state.assetFilters = {
    query: "",
    type: "all",
    category: "all",
    readiness: "all",
    processing: "all",
    provenance: "all",
    eventLink: "all",
    analysis: "all",
    sort: "newest",
    dateFrom: "",
    dateTo: "",
  };
  const search = document.getElementById("assetSearchInput");
  if (search) search.value = "";
  ["assetTypeFilter", "assetCategoryFilter", "assetReadinessFilter", "assetProcessingFilter", "assetProvenanceFilter", "assetEventLinkFilter", "assetAnalysisFilter"].forEach((id) => {
    const element = document.getElementById(id);
    if (element) element.value = "all";
  });
  const sort = document.getElementById("assetSortFilter");
  if (sort) sort.value = "newest";
  const dateFrom = document.getElementById("assetDateFromFilter");
  const dateTo = document.getElementById("assetDateToFilter");
  if (dateFrom) dateFrom.value = "";
  if (dateTo) dateTo.value = "";
  renderAssetLibrary();
  requestAnimationFrame(() => document.getElementById("assetSearchInput")?.focus());
}

function clearSingleAssetFilter(key) {
  const defaults = {
    query: "",
    type: "all",
    category: "all",
    readiness: "all",
    processing: "all",
    provenance: "all",
    eventLink: "all",
    analysis: "all",
    sort: "newest",
    dateFrom: "",
    dateTo: "",
  };
  if (!Object.hasOwn(defaults, key)) return;
  state.assetFilters[key] = defaults[key];
  const inputMap = {
    query: "assetSearchInput",
    type: "assetTypeFilter",
    category: "assetCategoryFilter",
    readiness: "assetReadinessFilter",
    processing: "assetProcessingFilter",
    provenance: "assetProvenanceFilter",
    eventLink: "assetEventLinkFilter",
    analysis: "assetAnalysisFilter",
    sort: "assetSortFilter",
    dateFrom: "assetDateFromFilter",
    dateTo: "assetDateToFilter",
  };
  const input = document.getElementById(inputMap[key]);
  if (input) input.value = defaults[key];
  renderAssetLibrary();
  requestAnimationFrame(() => document.getElementById(inputMap[key])?.focus());
}

function handleCaptureCoachClick(event) {
  const applyButton = event.target.closest("[data-writing-apply]");
  if (applyButton) {
    applyCaptureWritingSuggestion(Number(applyButton.dataset.writingApply));
    return;
  }
  const copilotButton = event.target.closest("[data-writing-copilot]");
  if (copilotButton) {
    openCaptureWritingCopilot(Number(copilotButton.dataset.writingCopilot));
    return;
  }
  const button = event.target.closest("[data-coach-field]");
  if (!button) return;
  const field = document.getElementById(button.dataset.coachField);
  field?.focus();
}

async function loadDemoData() {
  if (state.experiences.some((item) => !item.isDemo)) {
    const message =
      "Esto agregará datos de ejemplo sin borrar tus experiencias reales. Podrás quitarlos luego con Eliminar ejemplo. ¿Continuar?";
    if (!confirm(message)) return;
  }
  const existingDemo = state.experiences.filter((item) => item.isDemo);
  const existingReal = state.experiences.filter((item) => !item.isDemo);
  const nextDemo = createDemoExperiences();
  const nextDemoAgenda = createDemoAgendaEvents();
  state.experiences = [...nextDemo, ...existingReal];
  state.agendaEvents = [...nextDemoAgenda, ...state.agendaEvents.filter((item) => !item.isDemo)];
  saveExperiences();
  saveAgendaEvents();
  if (state.apiOnline && state.session?.access_token) {
    try {
      await Promise.all(existingDemo.map((experience) => deleteExperienceFromApi(experience.id)));
      await Promise.all(nextDemo.map((experience) => saveExperienceToApi(experience)));
    } catch (error) {
      markApiConnectivityFailure(error);
    }
  }
  renderAll();
  showView("assetLibrary");
  const agendaDetail = t("labels.demoAgendaLoaded").replace("{count}", String(nextDemoAgenda.length));
  const baseMessage = `${nextDemo.length} experiencias de ejemplo multimodales cargadas. ${agendaDetail}`;
  document.getElementById("embeddingStatus").textContent = state.session?.access_token
     baseMessage
    : `${baseMessage} Entra para sincronizarlas con Supabase.`;
}

async function clearDemoData() {
  const demoItems = state.experiences.filter((item) => item.isDemo);
  const demoAgendaItems = state.agendaEvents.filter((item) => item.isDemo);
  if (!demoItems.length && !demoAgendaItems.length) {
    document.getElementById("embeddingStatus").textContent = "No hay datos de ejemplo para eliminar.";
    return;
  }
  if (!confirm(`Se eliminarán ${demoItems.length} experiencias y ${demoAgendaItems.length} eventos de Agenda de ejemplo. Tus datos reales se conservan. ¿Continuar?`)) return;
  state.experiences = state.experiences.filter((item) => !item.isDemo);
  state.agendaEvents = state.agendaEvents.filter((item) => !item.isDemo);
  saveExperiences();
  saveAgendaEvents();
  if (state.apiOnline && state.session?.access_token) {
    await Promise.all(demoItems.map((experience) => deleteExperienceFromApi(experience.id))).catch((error) => {
      markApiConnectivityFailure(error);
    });
  }
  renderAll();
  document.getElementById("embeddingStatus").textContent = "Datos de ejemplo eliminados.";
}

