function renderPublicationPresetSuggestions(type, channel) {
  const direct = publicationTemplates.filter((template) => template.channel === channel);
  const related = publicationTemplates.filter((template) => template.type === type && template.channel !== channel);
  const suggestions = [...direct, ...related]
    .filter((template, index, list) => list.findIndex((item) => item.id === template.id) === index)
    .slice(0, 4);
  if (!suggestions.length) return "";
  const title = state.language !== "es" ? "Suggested formats before generating" : "Formatos sugeridos antes de generar";
  const help = state.language !== "es"
     ? "Choose one to align type, style, and PDF structure before creating the draft."
    : "Elige uno para alinear tipo, estilo y estructura del PDF antes de crear el borrador.";
  return `
    <div class="publication-preset-panel">
      <div>
        <strong>${escapeHtml(title)}</strong>
        <p>${escapeHtml(help)}</p>
      </div>
      <div class="publication-preset-list">
        ${suggestions.map((template) => `
          <button type="button" data-publication-preset="${escapeHtml(template.id)}">
            <span>${escapeHtml(displayPublicationType(template.type))}</span>
            <b>${escapeHtml(displayPublicationStyle(template.style))}</b>
            <small>${escapeHtml(template.channel)}</small>
          </button>
        `).join("")}
      </div>
    </div>
  `;
}

function getPublicationCompositionProfile(type, channel, style) {
  const visualTypes = new Set(["Álbum experiencial", "Carrusel visual", "Guion de story/reel"]);
  const formalTypes = new Set(["Resumen ejecutivo", "Dossier PDF", "Ficha de salud", "Jornada de trabajo", "Reporte dashboard"]);
  const isVisual = visualTypes.has(type);
  const isFormal = formalTypes.has(type);
  const isWorkday = type === "Jornada de trabajo";
  const isDashboard = type === "Reporte dashboard";
  const layout = isDashboard
     ? "Portada ejecutiva, KPIs, dashboard visual, hallazgos, evidencia y acciones"
    : isWorkday
       ? "Resumen de jornada, acuerdos, decisiones, pendientes y evidencia"
      : isVisual
     ? "Portada visual, bloques cortos y galería curada"
    : isFormal
       ? "Portada sobria, resumen, evidencia y cierre accionable"
      : "Portada editorial, relato por secciones y momentos clave";
  const media = isDashboard
     ? "Indicadores, tablas, imagenes, documentos y biometria como evidencia visual"
    : isWorkday
       ? "Notas, documentos, agenda, audios transcritos e imagenes de soporte"
      : isVisual
     ? "Imágenes y video primero; audio/documentos como notas de apoyo"
    : isFormal
       ? "Documentos, datos y texto interpretado primero; multimedia solo si aporta evidencia"
      : "Mezcla de narrativa, imágenes destacadas y anexos resumidos";
  const text = "Texto completo, con secciones editadas, cronologia y lectura final";
  const action = "Generar documento maestro en PDF revista premium";
  return { layout, media, text, action, style };
}

function renderPublicationCompositionPlan(type, channel, style) {
  const profile = getPublicationCompositionProfile(type, channel, style);
  const title = state.language !== "es" ? "Composition recipe" : "Receta de composición";
  const help = state.language !== "es"
     ? "This is the structure the draft will follow before export."
    : "Esta es la estructura que seguirá el borrador antes de exportar.";
  const items = state.language !== "es"
     ? [
        ["Layout", translatePublicationGuideText(profile.layout)],
        ["Media", translatePublicationGuideText(profile.media)],
        ["Text depth", translatePublicationGuideText(profile.text)],
        ["Final action", translatePublicationGuideText(profile.action)],
      ]
    : [
        ["Diseño", profile.layout],
        ["Multimedia", profile.media],
        ["Texto", profile.text],
        ["Salida", profile.action],
      ];
  return `
    <div class="publication-composition-panel">
      <div class="publication-composition-heading">
        <strong>${escapeHtml(title)}</strong>
        <span>${escapeHtml(displayPublicationStyle(style))} · ${escapeHtml(channel)}</span>
      </div>
      <p>${escapeHtml(help)}</p>
      <div class="publication-composition-grid">
        ${items.map(([label, detail]) => `
          <article>
            <b>${escapeHtml(label)}</b>
            <span>${escapeHtml(detail)}</span>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function renderPublicationTypeChannelFit(type, channel) {
  const guide = getPublicationTypeGuide(type);
  const recommended = guide.channels || [];
  const exact = recommended.includes(channel);
  const indirect = channel === PUBLICATION_OUTPUT_CHANNEL;
  const status = exact || indirect ? "ok" : "review";
  const label = state.language !== "es"
     ? exact
       ? "Strong PDF fit"
      : indirect
         ? "Good as master document"
        : "Review PDF fit"
    : exact
       ? "Buen encaje PDF"
      : indirect
         ? "Buen documento maestro"
        : "Revisar encaje del PDF";
  const detail = state.language !== "es"
     ? exact
       ? `${displayPublicationType(type)} is naturally suited for the premium PDF.`
      : indirect
         ? `${displayPublicationType(type)} can be exported as the master piece and adapted later outside Vibe.`
        : `${displayPublicationType(type)} can still work, but review the PDF structure before export.`
    : exact
       ? `${displayPublicationType(type)} esta naturalmente alineado con el PDF premium.`
      : indirect
         ? `${displayPublicationType(type)} puede salir como pieza maestra y adaptarse despues fuera de Vibe.`
        : `${displayPublicationType(type)} puede funcionar, pero revisa la estructura del PDF antes de exportar.`;
  return `
    <div class="publication-fit-panel is-${status}">
      <strong>${escapeHtml(label)}</strong>
      <p>${escapeHtml(detail)}</p>
    </div>
  `;
}

function handlePublicationPresetClick(event) {
  const button = event.target.closest("[data-publication-preset]");
  if (!button) return;
  const template = publicationTemplates.find((item) => item.id === button.dataset.publicationPreset);
  if (!template) return;
  document.getElementById("publicationTypeInput").value = template.type;
  document.getElementById("publicationStyleInput").value = template.style;
  document.getElementById("publicationChannelInput").value = PUBLICATION_OUTPUT_CHANNEL;
  updatePublicationTypeHelp();
  document.getElementById("publicationStatus").textContent = state.language !== "es"
     ? "Suggested publication format applied."
    : "Formato sugerido aplicado.";
}

