function populateExperienceTypeControl() {
  const select = document.getElementById("profileExperienceTypeInput");
  if (!select) return;
  const current = select.value || "auto";
  select.innerHTML = "";
  experienceTypes.forEach((type) => select.append(new Option(type.label, type.id)));
  select.value = experienceTypes.some((type) => type.id === current) ? current : "auto";
}

function getPilotParticipantName(idOrName = "") {
  const value = String(idOrName || "").trim();
  if (!value) return "";
  return state.pilotParticipants.find((item) => item.id === value)?.name || value;
}

function getExperiencePilotParticipantLabel(experience = {}) {
  return getPilotParticipantName(experience.pilotParticipantId) || experience.pilotParticipantName || "";
}

function experienceMatchesPilotParticipant(experience = {}, participantId = "all") {
  if (!participantId || participantId === "all") return true;
  if (experience.pilotParticipantId === participantId) return true;
  const participant = state.pilotParticipants.find((item) => item.id === participantId);
  const participantName = String(participant?.name || participant?.role || "").trim().toLowerCase();
  const participantRole = String(participant?.role || "").trim().toLowerCase();
  if (!participantName && !participantRole) return false;
  const fields = [
    experience.pilotParticipantName,
    getPilotParticipantName(experience.pilotParticipantId),
    experience.people,
    experience.participants,
    experience.person,
    experience.ownerName,
  ]
    .map((value) => String(value || "").toLowerCase())
    .filter(Boolean);
  return fields.some((field) => (participantName && field.includes(participantName)) || (participantRole && field.includes(participantRole)));
}

function normalizePilotParticipantId(value = "") {
  const id = String(value || "").trim();
  if (!id || id === "all") return "";
  return state.pilotParticipants.some((item) => item.id === id && !isArchivedPilotParticipant(item)) ? id : "";
}

function getActivePilotParticipantId(preferredScopes = []) {
  const sources = {
    agenda: state.agendaFilters?.pilotParticipantId,
    dashboard: state.dashboardFilters?.pilotParticipantId,
    report: state.reportFilters?.pilotParticipantId,
    insights: state.insightsFilters?.pilotParticipantId,
    publications: state.publicationFilters?.pilotParticipantId,
    library: state.libraryFilters?.pilotParticipantId,
  };
  const ordered = [...preferredScopes, "agenda", "dashboard", "report", "insights", "publications", "library"];
  for (const scope of ordered) {
    const id = normalizePilotParticipantId(sources[scope]);
    if (id) return id;
  }
  return "";
}

function resolveActivePilotParticipantId(preferredScopes = []) {
  return getActivePilotParticipantId(preferredScopes);
}

function buildPilotParticipantFields(participantId = "") {
  const id = normalizePilotParticipantId(participantId);
  return {
    pilotParticipantId: id,
    pilotParticipantName: getPilotParticipantName(id),
  };
}

function getDashboardExperiences() {
  const participantId = state.dashboardFilters?.pilotParticipantId || "all";
  return getExperiencesByPilotParticipant(participantId);
}

function getDashboardAgendaEvents() {
  const participantId = state.dashboardFilters?.pilotParticipantId || "all";
  if (!participantId || participantId === "all") return state.agendaEvents;
  return state.agendaEvents.filter((item) => item.pilotParticipantId === participantId);
}

function getExperiencesByPilotParticipant(participantId = "all") {
  const visible = state.experiences.filter((item) => !isSupersededExperience(item));
  if (!participantId || participantId === "all") return visible;
  return visible.filter((item) => experienceMatchesPilotParticipant(item, participantId));
}

function experienceMatchesDateRange(item, dateFrom = "", dateTo = "") {
  const time = new Date(item.timestamp).getTime();
  if (!Number.isFinite(time)) return false;
  if (dateFrom) {
    const fromTime = new Date(`${dateFrom}T00:00:00`).getTime();
    if (Number.isFinite(fromTime) && time < fromTime) return false;
  }
  if (dateTo) {
    const toTime = new Date(`${dateTo}T23:59:59`).getTime();
    if (Number.isFinite(toTime) && time > toTime) return false;
  }
  return true;
}

function getDefaultOutputScopeDates(reference = new Date()) {
  const end = new Date(reference);
  const start = new Date(reference);
  start.setDate(start.getDate() - 6);
  return {
    dateFrom: toDateFilterValue(start),
    dateTo: toDateFilterValue(end),
  };
}

