function syncReportBasisSelect(value = "all") {
  syncCustomBasisSelect("reportBasisFilter", getReportBasisOptions(), value);
}

function assetMatchesOutputDateRange(asset = {}, dateFrom = "", dateTo = "") {
  return experienceMatchesDateRange({
    timestamp: asset.capturedAt || asset.timestamp || asset.uploadedAt || asset.createdAt || "",
  }, dateFrom, dateTo);
}

function assetMatchesOutputParticipant(asset = {}, participantId = "all") {
  if (!participantId || participantId === "all") return true;
  const directId = asset.pilotParticipantId || asset.participantId || asset.groupId || asset.metadata?.participantId || "";
  if (directId) return normalizePilotParticipantId(directId) === normalizePilotParticipantId(participantId);
  const parent = asset.experienceId ? state.experiences.find((item) => item.id === asset.experienceId) : null;
  return parent ? experienceMatchesPilotParticipant(parent, participantId) : false;
}

function isOutputContextAsset(asset = {}) {
  if (asset.contextOnly) return true;
  const profile = getIntegrationSourceProfile(asset);
  const text = [
    asset.evidenceType,
    asset.payloadType,
    asset.kind,
    asset.type,
    asset.name,
    profile.family,
    profile.payloadType,
  ].filter(Boolean).join(" ").toLowerCase();
  return /(biometric|biometr|health|sleep|readiness|heart|steps|location|gps|weather|climate|news|agenda|sensor|context)/.test(text);
}

function buildAnalyticalOutputScope(filters = {}, outputType = "report", storiesOverride = null) {
  const basis = ["all", "stories", "evidence"].includes(filters.basis) ? filters.basis : "all";
  const stories = Array.isArray(storiesOverride)
    ? storiesOverride
    : getExperiencesByAnalyticalFilters(filters);
  const selectedStoryIds = new Set(stories.map((item) => item.id).filter(Boolean));
  const participantId = filters.pilotParticipantId || "all";
  const source = filters.source || "all";
  const category = filters.category || "all";
  const allAssets = collectMultimodalAssets()
    .filter((asset) => assetMatchesOutputDateRange(asset, filters.dateFrom || "", filters.dateTo || ""))
    .filter((asset) => assetMatchesOutputParticipant(asset, participantId))
    .filter((asset) => experienceMatchesIntegrationSource(asset, source));
  const context = allAssets.filter(isOutputContextAsset);
  const eligibleEvidence = allAssets.filter((asset) => !isOutputContextAsset(asset));
  const evidence = eligibleEvidence.filter((asset) => {
    if (category === "all") return true;
    return Boolean(asset.experienceId && selectedStoryIds.has(asset.experienceId));
  });
  const visibleStories = basis === "evidence" ? [] : stories;
  const visibleEvidence = basis === "stories"
    ? evidence.filter((asset) => asset.experienceId && selectedStoryIds.has(asset.experienceId))
    : evidence;
  return {
    outputType,
    basis,
    stories: visibleStories,
    evidence: visibleEvidence,
    context,
    excludedUnclassifiedEvidence: category === "all" ? 0 : Math.max(0, eligibleEvidence.length - evidence.length),
    dateFrom: filters.dateFrom || "",
    dateTo: filters.dateTo || "",
    participantId,
  };
}

function buildScopedEvidenceSummary(scope = {}) {
  const evidence = Array.isArray(scope.evidence) ? scope.evidence : [];
  const byKind = evidence.reduce((acc, asset) => {
    const kind = String(asset.kind || inferMediaKind(asset) || "document").toLowerCase();
    acc[kind] = (acc[kind] || 0) + 1;
    return acc;
  }, {});
  const withReadableText = evidence.filter((asset) =>
    String(asset.analysisText || asset.translatedText || asset.extractedText || asset.manualNote || asset.previewText || "").trim(),
  ).length;
  return {
    total: evidence.length,
    byKind,
    withReadableText,
    context: Array.isArray(scope.context) ? scope.context.length : 0,
    excludedUnclassifiedEvidence: Number(scope.excludedUnclassifiedEvidence || 0),
  };
}

function getReportPresentationMode(scope = {}) {
  return scope.basis === "evidence" ? "evidence_inventory" : "life_area_coverage";
}

function buildScopedBiometricMeasurements(scope = {}) {
  const from = scope.dateFrom ? new Date(`${scope.dateFrom}T00:00:00`) : null;
  const to = scope.dateTo ? new Date(`${scope.dateTo}T23:59:59.999`) : null;
  const rows = getAllBiometricRows().filter((row) => {
    const date = new Date(row.date || row.capturedAt || row.timestamp || "");
    if (Number.isNaN(date.getTime())) return false;
    return (!from || date >= from) && (!to || date <= to);
  });
  const metrics = aggregateBiometricRows(rows);
  return {
    records: rows.length,
    metrics,
    suggestedEnergy: estimateBiometricEnergy(metrics),
    hasMeasurements: Boolean(rows.length && Object.values(metrics).some((value) => Number(value) > 0)),
  };
}

function buildEvidenceInventoryReport(scope = {}) {
  const assets = [...(scope.evidence || []), ...(scope.context || [])]
    .slice()
    .sort((left, right) => new Date(right.capturedAt || right.timestamp || 0) - new Date(left.capturedAt || left.timestamp || 0));
  const byKind = assets.reduce((result, asset) => {
    const kind = String(asset.kind || inferMediaKind(asset) || "document").toLowerCase();
    result[kind] = (result[kind] || 0) + 1;
    return result;
  }, {});
  const readable = assets.filter((asset) =>
    String(asset.analysisText || asset.translatedText || asset.extractedText || asset.manualNote || asset.previewText || "").trim(),
  ).length;
  return {
    total: assets.length,
    evidence: (scope.evidence || []).length,
    context: (scope.context || []).length,
    readable,
    byKind,
    measurements: buildScopedBiometricMeasurements(scope),
  };
}

function renderEvidenceInventoryReport(scope = {}) {
  const inventory = buildEvidenceInventoryReport(scope);
  const kinds = Object.entries(inventory.byKind)
    .map(([kind, count]) => `<span>${escapeHtml(getAssetKindLabel(kind))}: ${count}</span>`)
    .join("");
  const measurements = inventory.measurements;
  const metricCards = [
    [languageText("Registros biométricos", "Biometric records", "Registres biométriques", "Registros biometricos"), measurements.records],
    [languageText("Frecuencia promedio", "Average heart rate", "Frequence moyenne", "Frequencia media"), measurements.metrics.heartAvg ? `${Math.round(measurements.metrics.heartAvg)} bpm` : "-"],
    [languageText("Pasos", "Steps", "Pas", "Passos"), measurements.metrics.steps ? Math.round(measurements.metrics.steps).toLocaleString() : "-"],
    [languageText("Sueño", "Sleep", "Sommeil", "Sono"), measurements.metrics.sleepMinutes ? `${(measurements.metrics.sleepMinutes / 60).toFixed(1)} h` : "-"],
  ];
  return `
    <section class="report-executive-card">
      <span class="report-kicker">${escapeHtml(languageText("Inventario de evidencia", "Evidence inventory", "Inventaire des preuves", "Inventario de evidencias"))}</span>
      <h3>${escapeHtml(languageText("Archivos y mediciones del período", "Files and measurements in this period", "Fichiers et mesures de la periode", "Arquivos e medicoes do periodo"))}</h3>
      <p>${escapeHtml(languageText("Esta vista no calcula balance por Áreas de vida porque no incluye historias. Revisa los archivos disponibles y las mediciones reales del período.", "This view does not calculate life-area balance because it does not include stories. Review the available files and real measurements for the period.", "Cette vue ne calcule pas l equilibre par domaines de vie car elle n inclut pas d histoires.", "Esta visualizacao nao calcula equilibrio por areas de vida porque nao inclui historias."))}</p>
    </section>
    <section class="report-finding-section">
      <h3>${escapeHtml(languageText("Contenido disponible", "Available content", "Contenu disponible", "Conteudo disponivel"))}</h3>
      <div class="report-finding-grid">
        <article class="report-finding-card"><span>${escapeHtml(languageText("Evidencia", "Evidence", "Preuves", "Evidencias"))}</span><strong>${inventory.evidence}</strong></article>
        <article class="report-finding-card"><span>${escapeHtml(languageText("Contexto", "Context", "Contexte", "Contexto"))}</span><strong>${inventory.context}</strong></article>
        <article class="report-finding-card"><span>${escapeHtml(languageText("Texto interpretable", "Readable text", "Texte lisible", "Texto legivel"))}</span><strong>${inventory.readable}</strong></article>
        <article class="report-finding-card"><span>${escapeHtml(languageText("Mediciones", "Measurements", "Mesures", "Medicoes"))}</span><strong>${measurements.hasMeasurements ? measurements.records : "-"}</strong></article>
      </div>
      <div class="shared-scope-chip-row">${kinds || `<span>${escapeHtml(languageText("Sin tipos de evidencia disponibles", "No evidence types available", "Aucun type de preuve disponible", "Nenhum tipo de evidencia disponivel"))}</span>`}</div>
    </section>
    <section class="human-kpi-section">
      <div class="report-section-heading"><h3>${escapeHtml(languageText("Mediciones disponibles", "Available measurements", "Mesures disponibles", "Medicoes disponiveis"))}</h3></div>
      <div class="human-kpi-grid">
        ${metricCards.map(([label, value]) => `<article class="human-kpi-card"><div class="human-kpi-content"><header><span>${escapeHtml(label)}</span></header><strong>${escapeHtml(String(value))}</strong></div></article>`).join("")}
      </div>
      <p class="card-meta">${escapeHtml(measurements.hasMeasurements ? languageText("Las mediciones se muestran solo cuando existen registros reales dentro del período seleccionado.", "Measurements are shown only when real records exist in the selected period.", "Les mesures sont affichees uniquement lorsqu il existe des enregistrements reels.", "As medicoes so aparecem quando ha registros reais no periodo.") : languageText("No hay mediciones biométricas legibles dentro de este período. No se estima energía ni balance.", "There are no readable biometric measurements in this period. Energy and balance are not estimated.", "Aucune mesure biométrique lisible dans cette periode.", "Nao ha medicoes biometricas legiveis neste periodo."))}</p>
    </section>
  `;
}

function renderEvidenceInventoryTable(scope = {}) {
  const assets = [...(scope.evidence || []), ...(scope.context || [])]
    .slice()
    .sort((left, right) => new Date(right.capturedAt || right.timestamp || 0) - new Date(left.capturedAt || left.timestamp || 0));
  if (!assets.length) return `<p class="card-meta">${escapeHtml(languageText("No hay evidencia ni contexto en este alcance.", "There is no evidence or context in this scope.", "Aucune preuve ni contexte dans cette portee.", "Nao ha evidencia nem contexto neste escopo."))}</p>`;
  return `
    <table>
      <thead><tr><th>${escapeHtml(languageText("Fecha", "Date", "Date", "Data"))}</th><th>${escapeHtml(languageText("Elemento", "Item", "Element", "Item"))}</th><th>${escapeHtml(languageText("Tipo", "Type", "Type", "Tipo"))}</th><th>${escapeHtml(languageText("Estado", "Status", "Statut", "Status"))}</th></tr></thead>
      <tbody>${assets.slice(0, 36).map((asset) => {
        const text = String(asset.analysisText || asset.translatedText || asset.extractedText || asset.manualNote || asset.previewText || "").trim();
        return `<tr><td>${escapeHtml(formatShortDate(asset.capturedAt || asset.timestamp || asset.uploadedAt || ""))}</td><td>${escapeHtml(asset.name || getAssetKindLabel(asset.kind))}</td><td>${escapeHtml(getAssetKindLabel(asset.kind || inferMediaKind(asset)))}</td><td>${escapeHtml(text ? languageText("Con lectura", "With reading", "Avec lecture", "Com leitura") : languageText("Disponible", "Available", "Disponible", "Disponivel"))}</td></tr>`;
      }).join("")}</tbody>
    </table>
  `;
}

function renderScopedEvidenceSummary(scope = {}, title = "") {
  const summary = buildScopedEvidenceSummary(scope);
  const sourceExplanation = scope.outputType === "publication"
    ? languageText(
        "Los relatos de experiencias y eventos forman la historia editorial; la evidencia y el contexto la documentan y enriquecen.",
        "Experience and event narratives form the editorial story; evidence and context document and enrich it.",
        "Les recits d'experiences et d'evenements forment l'histoire editoriale ; les preuves et le contexte l'enrichissent.",
        "Os relatos de experiencias e eventos formam a historia editorial; evidencias e contexto a documentam e enriquecem.",
      )
    : languageText(
        "La lectura se basa en hechos y datos observables del periodo. Los registros estructurados, la evidencia y el contexto se mantienen diferenciados.",
        "The reading is based on observable facts and data from the period. Structured records, evidence, and context remain distinct.",
        "La lecture repose sur les faits et les donnees observables de la periode. Registres, preuves et contexte restent distincts.",
        "A leitura se baseia em fatos e dados observaveis do periodo. Registros, evidencias e contexto permanecem separados.",
      );
  const kinds = Object.entries(summary.byKind)
    .map(([kind, count]) => `${getAssetKindLabel(kind)}: ${count}`)
    .join(" / ");
  return `
    <section class="shared-scope-context output-evidence-summary">
      <div>
        <strong>${escapeHtml(title || languageText("Fuentes del alcance", "Scope sources", "Sources de la portee", "Fontes do escopo"))}</strong>
        <p>${escapeHtml(sourceExplanation)}</p>
      </div>
      <div class="shared-scope-chip-row">
        <span>${summary.total} ${escapeHtml(languageText("evidencias", "evidence items", "preuves", "evidencias"))}</span>
        <span>${summary.withReadableText} ${escapeHtml(languageText("con texto interpretable", "with readable text", "avec texte lisible", "com texto legivel"))}</span>
        <span>${summary.context} ${escapeHtml(languageText("señales de contexto", "context signals", "signaux de contexte", "sinais de contexto"))}</span>
        ${kinds ? `<span>${escapeHtml(kinds)}</span>` : ""}
        ${summary.excludedUnclassifiedEvidence
          ? `<span>${summary.excludedUnclassifiedEvidence} ${escapeHtml(languageText("sin clasificar, excluidas por categoría", "unclassified, excluded by category", "non classees, exclues par categorie", "nao classificadas, excluidas por categoria"))}</span>`
          : ""}
      </div>
    </section>
  `;
}

function getExperiencesByAnalyticalFilters(filters = {}) {
  return filterExperiencesByAnalyticalFilters(state.experiences.filter((item) => !isSupersededExperience(item)), filters);
}

function filterExperiencesByAnalyticalFilters(experiences = [], filters = {}) {
  const participantId = filters.pilotParticipantId || "all";
  const source = filters.source || "all";
  return experiences
    .filter((item) => !participantId || participantId === "all" || experienceMatchesPilotParticipant(item, participantId))
    .filter((item) => !filters.category || filters.category === "all" || item.category === filters.category)
    .filter((item) => experienceMatchesIntegrationSource(item, source))
    .filter((item) => experienceMatchesDateRange(item, filters.dateFrom || "", filters.dateTo || ""));
}

function getInsightsExperiences() {
  return getInsightsOutputScope().stories;
}

function getPublicationExperiences() {
  return getPublicationOutputScope().stories;
}

function getInsightsOutputScope() {
  return buildAnalyticalOutputScope(state.insightsFilters || {}, "insights");
}

function getInsightsPresentationMode(scope = {}) {
  return scope.basis === "evidence" ? "signal_inventory" : "life_area_findings";
}

function getPublicationOutputScope() {
  return buildAnalyticalOutputScope(state.publicationFilters || {}, "publication");
}

function getReportOutputScope() {
  return buildAnalyticalOutputScope(state.reportFilters || {}, "report", getReportExperiences());
}

function getIntegrationSourceFilterOptions() {
  return [
    ["all", state.language !== "es" ? "All origins" : "Todos los origenes"],
    ["pwa", state.language !== "es" ? "PWA / manual capture" : "PWA / captura manual"],
    ["vibeapp", "Vibeapp"],
    ["health-connect", "Health Connect / Samsung"],
    ["oura", "Oura"],
    ["apple-health", "Apple Health"],
    ["meta-oakley", "Meta/Oakley"],
    ["wearable", state.language !== "es" ? "Wearables / biometrics" : "Wearables / biometria"],
    ["external", state.language !== "es" ? "Other external sources" : "Otras fuentes externas"],
  ];
}

function getIntegrationSourceFilterLabel(value = "all") {
  return getIntegrationSourceFilterOptions().find(([key]) => key === value)?.[1] || getIntegrationSourceFilterOptions()[0][1];
}

function populateIntegrationSourceFilter(id, value = "all") {
  const select = document.getElementById(id);
  if (!select) return;
  const options = getIntegrationSourceFilterOptions();
  select.innerHTML = options.map(([key, label]) => `<option value="${escapeHtml(key)}">${escapeHtml(label)}</option>`).join("");
  select.value = options.some(([key]) => key === value) ? value : "all";
}

function experienceMatchesIntegrationSource(item = {}, sourceFilter = "all") {
  const filter = sourceFilter || "all";
  if (filter === "all") return true;
  const profile = getIntegrationSourceProfile(item);
  const metadata = item.metadata || {};
  const text = [
    profile.family,
    profile.source,
    profile.payloadType,
    profile.syncContract,
    item.sourceType,
    item.source,
    item.device,
    item.externalSource,
    item.externalPayloadType,
    metadata.source,
    metadata.sourceType,
    metadata.payloadType,
  ]
    .join(" ")
    .toLowerCase();
  if (filter === "pwa") return !profile.active || /pwa|web|manual|local|captura/.test(text);
  if (filter === "vibeapp") return /vibeapp|vibeapp-native/.test(text);
  if (filter === "health-connect") return /health connect|android-health|samsung|galaxy/.test(text);
  if (filter === "oura") return /oura/.test(text);
  if (filter === "apple-health") return /apple health|healthkit/.test(text);
  if (filter === "meta-oakley") return /meta|oakley|ray-ban/.test(text);
  if (filter === "wearable") return /wearable|biometric|biometr/.test(text);
  if (filter === "external") return profile.active;
  return true;
}

