function setCaptureLiveSyncStatus(status = "pending", reason = "") {
  const hasContent = canLiveSyncCaptureDraft();
  if (!hasContent) return;
  const labels = state.language !== "es"
     ? {
        pending: "Preparing live sync...",
        syncing: "Syncing draft across devices...",
        title: "Live draft",
      }
    : {
        pending: "Preparando sincronización...",
        syncing: "Sincronizando borrador en tus dispositivos...",
        title: "Borrador vivo",
      };
  state.captureSaveStatus = {
    type: "info",
    title: labels.title,
    detail: status === "syncing" ? labels.syncing : labels.pending,
    experienceId: document.getElementById("editingId")?.value || "",
    experienceTitle: document.getElementById("titleInput")?.value.trim() || "",
    savedAt: new Date().toISOString(),
    reason: `autosave_${reason}_${status}`,
    remote: false,
    queued: false,
    transient: true,
  };
  renderCaptureSaveStatus();
}

function ensureCaptureDraftId() {
  const input = document.getElementById("editingId");
  if (input && !input.value) input.value = createId();
}

async function readAutosaveCaptureDraft() {
  const experience = await readForm();
  const notes = String(experience.notes || "").trim();
  const objective = String(experience.objective || "").trim();
  if (!experience.title) experience.title = buildAutosaveDraftTitle(notes || objective || experience.attachments?.[0]?.name || "");
  if (!experience.objective) experience.objective = state.language !== "es" ? "Live capture in progress" : "Captura en curso";
  experience.sourceType = experience.sourceType || "live_capture";
  experience.updatedAt = new Date().toISOString();
  return experience.title || notes || objective || experience.attachments?.length ? experience : null;
}

function buildAutosaveDraftTitle(seed = "") {
  const text = String(seed || "").replace(/\s+/g, " ").trim();
  if (text) return buildAudioDraftTitle(text);
  return state.language !== "es" ? "Experience draft" : "Borrador de experiencia";
}

function applyTemplate(template) {
  document.getElementById("titleInput").value = template.title;
  document.getElementById("categoryInput").value = template.category;
  document.getElementById("objectiveInput").value = template.objective || "";
  document.getElementById("durationInput").value = template.duration;
  document.getElementById("moodInput").value = template.mood;
  document.getElementById("notesInput").value = template.notes;
}

async function handleMediaSelection() {
  const newAttachments = await readSelectedFiles();
  state.pendingAttachments = [...state.pendingAttachments, ...newAttachments];
  document.getElementById("mediaInput").value = "";
  resetMediaInputMode();
  renderAttachmentPreview();
  scheduleCaptureDraftAutosave("attachment", { delayMs: 350 });
}

function resetMediaInputMode() {
  const input = document.getElementById("mediaInput");
  if (!input) return;
  input.removeAttribute("capture");
  input.setAttribute("accept", "image/*,video/*,audio/*,.heic,.heif,.avif,.webp,.tif,.tiff,.raw,.dng,.cr2,.nef,.arw,.mp3,.wav,.m4a,.aac,.flac,.ogg,.opus,.wma,.aiff,.aif,.amr,.mp4,.mov,.m4v,.webm,.mkv,.avi,.wmv,.mpeg,.mpg,.3gp,.hevc,.txt,.md,.markdown,.html,.htm,.rtf,.docx,.pdf,.csv,.json,.zip,.rar,.7z");
}

function readSelectedFiles() {
  const input = document.getElementById("mediaInput");
  const files = Array.from(input.files || []);
  const canUploadBinary = Boolean(state.apiOnline && state.session?.access_token);
  const maxSize = (canUploadBinary ? 75 : 25) * 1024 * 1024;
  const accepted = files.filter((file) => {
    const validType = isAcceptedAttachmentFile(file);
    return validType && file.size <= maxSize;
  });
  if (accepted.length !== files.length) {
    notify(
      state.language !== "es"
         ? `Some files were skipped. Vibe accepts supported image, audio, video, document, and compressed-file formats up to ${canUploadBinary ? 75 : 25} MB per file.`
        : `Algunos archivos se omitieron. Vibe acepta formatos compatibles de imagen, audio, video, documentos y comprimidos de hasta ${canUploadBinary ? 75 : 25} MB por archivo.`,
      "warn",
    );
  }
  return Promise.all(accepted.map((file) => readAndPersistMedia(file)));
}

async function readAndPersistMedia(file, overrides = {}) {
  const metadata = { ...(await buildFileAttachmentMetadata(file)), ...overrides };
  if (state.apiOnline && state.session?.access_token) {
    try {
      const uploaded = await uploadFileAttachment(file, metadata);
      if (uploaded.kind === "audio") {
        await appendBackendTranscript(uploaded);
      }
      return uploaded;
    } catch (error) {
      markApiConnectivityFailure(error);
    }
  }
  const attachment = await readFileAsAttachment(file, metadata);
  if (attachment.kind === "audio") await appendBackendTranscript(attachment);
  return attachment;
}

async function uploadFileAttachment(file, metadata) {
  const form = new FormData();
  form.append("metadata", JSON.stringify(stripInlineMediaForRemote(metadata)));
  form.append("file", file, file.name || metadata.name || "media");
  return apiRequest("/media", {
    method: "POST",
    body: form,
  });
}

async function buildFileAttachmentMetadata(file) {
  const extension = getFileExtension(file.name);
  const kind = inferMediaKind(file);
  const type = file.type || mimeFromExtension(extension, kind);
  const previewText = kind === "document" && TEXT_PREVIEW_DOCUMENT_EXTENSIONS.has(extension) ? await readFileTextPreview(file) : "";
  return {
    id: createId(),
    name: file.name,
    type,
    originalType: file.type || "",
    extension,
    kind,
    size: file.size,
    dataUrl: null,
    createdAt: new Date().toISOString(),
    storage: "pending",
    previewable: isBrowserPreviewable(kind, extension, type),
    previewText,
  };
}

function readFileAsAttachment(file, baseMetadata = null) {
  const metadataPromise = baseMetadata ? Promise.resolve(baseMetadata) : buildFileAttachmentMetadata(file);
  try {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = async () => {
      const metadata = await metadataPromise;
      resolve({
        ...metadata,
        dataUrl: reader.result,
        storage: "inline",
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
  } catch {
    return metadataPromise;
  }
}

function isAcceptedAttachmentFile(file) {
  const type = file.type || "";
  if (type.startsWith("image/") || type.startsWith("video/") || type.startsWith("audio/")) return true;
  const extension = getFileExtension(file.name);
  return Boolean(MEDIA_EXTENSION_KIND[extension] || DOCUMENT_EXTENSIONS.has(extension));
}

function inferMediaKind(fileOrAttachment) {
  if (fileOrAttachment.kind) return fileOrAttachment.kind;
  const type = fileOrAttachment.type || "";
  if (type.startsWith("image/")) return "image";
  if (type.startsWith("audio/")) return "audio";
  const extension = getFileExtension(fileOrAttachment.name);
  if (extension === "webm" && isLikelyAudioWebm(fileOrAttachment)) return "audio";
  if (type.startsWith("video/")) return "video";
  return MEDIA_EXTENSION_KIND[extension] || (DOCUMENT_EXTENSIONS.has(extension) ? "document" : "document");
}

function isLikelyAudioWebm(fileOrAttachment = {}) {
  const extension = getFileExtension(fileOrAttachment.name || fileOrAttachment.url || "");
  const type = String(fileOrAttachment.type || fileOrAttachment.originalType || "").toLowerCase();
  const name = String(fileOrAttachment.name || "").toLowerCase();
  const source = String(fileOrAttachment.sourceType || fileOrAttachment.source || fileOrAttachment.metadata?.sourceType || "").toLowerCase();
  return extension === "webm"
    && (type === "audio/webm"
      || source.includes("audio")
      || /(^|[-_\s])(audio|voz|voice|record|recording|grabacion|grabación|captura)([-_\s]|\d|$)/i.test(name));
}

function getFileExtension(name = "") {
  return String(name).split(".").pop()?.toLowerCase() || "";
}

function mimeFromExtension(extension, kind) {
  if (!extension || !kind) return "application/octet-stream";
  if (kind === "document") {
    const map = {
      txt: "text/plain",
      md: "text/markdown",
      markdown: "text/markdown",
      html: "text/html",
      htm: "text/html",
      csv: "text/csv",
      json: "application/json",
      pdf: "application/pdf",
      rtf: "application/rtf",
      docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      zip: "application/zip",
      rar: "application/vnd.rar",
      "7z": "application/x-7z-compressed",
    };
    return map[extension] || "application/octet-stream";
  }
  if (extension === "svg") return "image/svg+xml";
  if (extension === "jpg") return "image/jpeg";
  if (extension === "webm" && kind === "audio") return "audio/webm";
  if (extension === "m4a") return "audio/mp4";
  if (extension === "mov") return "video/quicktime";
  return `${kind}/${extension}`;
}

function isBrowserPreviewable(kind, extension, type = "") {
  if (type.startsWith("image/svg")) return true;
  if (kind === "audio" && type.includes("webm")) return true;
  return BROWSER_PREVIEWABLE[kind]?.has(extension) || false;
}

async function readFileTextPreview(file) {
  try {
    return (await file.text()).slice(0, 1200);
  } catch {
    return "";
  }
}

async function appendBackendTranscript(attachment) {
  if (!state.apiOnline || !state.session?.access_token) return;
  try {
    const result = await apiRequest("/transcribe", {
      method: "POST",
      body: JSON.stringify(attachment),
    });
    if (result.transcript) {
      applyAudioTranscriptToCapture(result.transcript, { source: "backend" });
      appendTranscriptToNotes("Transcripción del servidor local", result.transcript);
      processAudioTranscriptCommands(result.transcript);
    }
  } catch {
    // Browser transcription remains the fallback.
  }
}

function renderAttachmentPreview() {
  const preview = document.getElementById("attachmentPreview");
  if (!state.pendingAttachments.length) {
    preview.innerHTML = `<p class="card-meta">${t("labels.noAttachments")}</p>`;
    return;
  }
  preview.innerHTML = state.pendingAttachments
    .map(renderPendingAttachmentCard)
    .join("");
}

function renderCaptureEventPreview() {
  const box = document.getElementById("captureEventPreview");
  if (!box) return;
  const events = getCaptureEventOptions();
  const attachments = state.pendingAttachments || [];
  const labels = state.language !== "es"
     ? {
        title: "Internal events",
        empty: "If the experience has several moments, write one event per line. If not, leave this empty and the record will stay as one complete experience.",
        count: "events detected",
        evidence: "linked attachments",
        none: "No attachment linked yet",
        whole: "Attachments without an event stay linked to the whole experience.",
      }
    : {
        title: "Eventos internos",
        empty: "Si la experiencia tiene varios momentos, escribe un evento por línea. Si no, déjalo vacío y el registro quedará como una experiencia completa.",
        count: "eventos detectados",
        evidence: "adjuntos vinculados",
        none: "Sin adjuntos vinculados aún",
        whole: "Los adjuntos sin evento quedan vinculados a toda la experiencia.",
      };
  if (!events.length) {
    box.innerHTML = `
      <section class="capture-event-empty">
        <strong>${escapeHtml(labels.title)}</strong>
        <p>${escapeHtml(labels.empty)}</p>
      </section>
    `;
    return;
  }
  const cards = events.map((event) => {
    const linkedCount = attachments.filter((attachment) => getAttachmentEventRef(attachment, events) === event.ref).length;
    return `
      <article class="capture-event-card">
        <span class="capture-event-number">${escapeHtml(String(event.order))}</span>
        <div>
          <strong>${escapeHtml(event.title || `${state.language !== "es" ? "Event" : "Evento"} ${event.order}`)}</strong>
          ${event.description ? `<p>${escapeHtml(event.description)}</p>` : ""}
          <small>${escapeHtml(linkedCount ? `${linkedCount} ${labels.evidence}` : labels.none)}</small>
        </div>
      </article>
    `;
  }).join("");
  box.innerHTML = `
    <section class="capture-event-summary">
      <div class="capture-event-heading">
        <strong>${escapeHtml(labels.title)}</strong>
        <span class="pill">${escapeHtml(`${events.length} ${labels.count}`)}</span>
      </div>
      <div class="capture-event-grid">${cards}</div>
      <p class="card-meta">${escapeHtml(labels.whole)}</p>
    </section>
  `;
}

function renderPendingAttachmentCard(attachment) {
  const kind = inferMediaKind(attachment);
  const extension = attachment.extension || getFileExtension(attachment.name);
  const previewable = attachment.previewable !== false && Boolean(attachment.dataUrl || attachment.url);
  const source = attachment.url || attachment.dataUrl || "";
  const eventOptions = getCaptureEventOptions();
  const selectedEventRef = getAttachmentEventRef(attachment, eventOptions);
  const eventSelectOptions = [
    `<option value="">${escapeHtml(state.language !== "es" ? "Whole experience" : "Toda la experiencia")}</option>`,
    ...eventOptions.map((event) => `<option value="${escapeHtml(event.ref)}" ${event.ref === selectedEventRef ? "selected" : ""}>${escapeHtml(`${event.order}. ${event.label}`)}</option>`),
  ].join("");
  const previewMarkup =
    kind === "image" && previewable
      ? `<img src="${source}" alt="${escapeHtml(attachment.name)}" />`
      : kind === "video" && previewable
        ? `<video src="${source}" controls muted></video>`
        : kind === "audio" && previewable
          ? `<audio src="${source}" controls></audio>`
          : kind === "document" && attachment.previewText
            ? `<div class="attachment-preview-document"><strong>${escapeHtml((extension || "doc").toUpperCase())}</strong><pre>${escapeHtml(attachment.previewText.slice(0, 260))}</pre></div>`
            : `<div class="attachment-preview-fallback"><strong>${escapeHtml(getAssetKindLabel(kind))}</strong><span>${escapeHtml((extension || "file").toUpperCase())}</span></div>`;
  const previewStatus = kind === "document" && attachment.previewText
    ? t("labels.attachmentDocumentPreview")
    : previewable
      ? t("labels.attachmentPreviewAvailable")
      : t("labels.attachmentPreviewUnsupported");
  return `
    <article class="attachment-card">
      <div class="attachment-card-preview">${previewMarkup}</div>
      <div class="attachment-card-body">
        <div class="pill-row">
          <span class="pill">${escapeHtml(getAssetKindLabel(kind))}</span>
          <span class="pill">${escapeHtml(extension ? extension.toUpperCase() : attachment.type || "FILE")}</span>
          <span class="pill ${previewable ? "pill-approved" : "pill-review"}">${escapeHtml(previewStatus)}</span>
        </div>
        <strong>${escapeHtml(attachment.name)}</strong>
        <p class="card-meta">${escapeHtml(formatFileSize(attachment.size))} · ${escapeHtml(t("labels.attachmentStoredInline"))} · ${escapeHtml(t("labels.attachmentReady"))}</p>
        <p>${escapeHtml(t("labels.attachmentProcessingHint"))}</p>
        <label class="attachment-event-link">
          <span>${escapeHtml(state.language !== "es" ? "Evidence belongs to" : "Evidencia de")}</span>
          <select data-attachment-event-select="${escapeHtml(attachment.id)}">
            ${eventSelectOptions}
          </select>
        </label>
      </div>
      <button class="ghost-button" type="button" onclick="removePendingAttachment('${attachment.id}')">${escapeHtml(t("buttons.remove"))}</button>
    </article>
  `;
}

function removePendingAttachment(id) {
  state.pendingAttachments = state.pendingAttachments.filter((attachment) => attachment.id !== id);
  renderAttachmentPreview();
  renderCaptureEvidenceInbox();
}

function buildPendingMediaDetail(experience, apiResult = {}, label = "") {
  const attachments = [
    ...(experience?.attachments || []),
    ...(apiResult?.experience?.attachments || []),
  ];
  const pending = attachments
    .filter((attachment) => attachment?.remoteSyncFailed || (!attachment?.path && !attachment?.url && !attachment?.dataUrl))
    .map((attachment) => {
      const fallbackName = state.language !== "es" ? "unnamed file" : "archivo sin nombre";
      const fallbackReason = state.language !== "es" ? "upload did not complete" : "la subida no se completó";
      const name = attachment.name || fallbackName;
      const reason = attachment.remoteSyncError || attachment.uploadError || fallbackReason;
      return `${name}: ${reason}`;
    });
  const unique = [...new Set(pending)].slice(0, 3);
  return unique.length ? `${label} ${unique.join(" · ")}` : "";
}

function handleAttachmentEventSelection(event) {
  const select = event.target.closest("[data-attachment-event-select]");
  if (!select) return;
  const attachmentId = select.dataset.attachmentEventSelect;
  const eventOptions = getCaptureEventOptions();
  const selected = eventOptions.find((item) => item.ref === select.value);
  state.pendingAttachments = state.pendingAttachments.map((attachment) => {
    if (attachment.id !== attachmentId) return attachment;
    if (!selected) {
      const { eventId, eventTitle, eventOrder, ...rest } = attachment;
      return {
        ...rest,
        eventRef: "",
        metadata: {
          ...(attachment.metadata || {}),
          linkedEventId: "",
          linkedEventTitle: "",
          eventOrder: "",
        },
      };
    }
    return {
      ...attachment,
      eventRef: selected.ref,
      eventId: selected.id,
      eventTitle: selected.title,
      eventOrder: selected.order,
      metadata: {
        ...(attachment.metadata || {}),
        linkedEventId: selected.id,
        linkedEventTitle: selected.title,
        eventOrder: selected.order,
      },
    };
  });
  renderAttachmentPreview();
  renderCaptureEvidenceInbox();
}

function setupAudioCapture() {
  const button = document.getElementById("recordAudioButton");
  const status = document.getElementById("recordingStatus");
  renderAudioCaptureGuide();
  if (!navigator.mediaDevices || typeof MediaRecorder === "undefined") {
    button.disabled = true;
    status.textContent = t("labels.audioCaptureUnavailable");
    return;
  }
  button.textContent = t("labels.recordAudio");
  updateAudioCaptureStatus("ready");
  button.addEventListener("click", async () => {
    if (state.mediaRecorder?.state === "recording") {
      button.disabled = true;
      state.mediaRecorder.stop();
      stopSpeechTranscription();
      button.textContent = t("labels.recordAudio");
      updateAudioCaptureStatus("processing");
      return;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = MediaRecorder.isTypeSupported?.("audio/webm") ? "audio/webm" : "";
      state.audioChunks = [];
      state.liveTranscript = "";
      state.mediaRecorder = new MediaRecorder(stream, mimeType ? { mimeType } : undefined);
      state.mediaRecorder.addEventListener("dataavailable", (event) => {
        if (event.data.size) state.audioChunks.push(event.data);
      });
      state.mediaRecorder.addEventListener("stop", async () => {
        try {
          stream.getTracks().forEach((track) => track.stop());
          const blobType = state.mediaRecorder?.mimeType || "audio/webm";
          const blob = new Blob(state.audioChunks, { type: blobType });
          const file = new File([blob], `audio-captura-${Date.now()}.webm`, { type: blobType });
          const attachment = await readAndPersistMedia(file, { sourceType: "audio_capture", kind: "audio", type: "audio/webm" });
          state.pendingAttachments.push({
            ...attachment,
            kind: "audio",
            type: attachment.type?.startsWith("audio/") ? attachment.type : "audio/webm",
            originalType: attachment.originalType || blobType,
            sourceType: "audio_capture",
          });
          if (state.liveTranscript) appendLiveTranscriptToNotes();
          renderAttachmentPreview();
          updateAudioCaptureStatus(state.liveTranscript ? "addedTranscript" : "added");
        } catch {
          updateAudioCaptureStatus("error");
        } finally {
          button.disabled = false;
          state.mediaRecorder = null;
        }
      });
      state.mediaRecorder.start();
      startSpeechTranscription();
      button.textContent = t("labels.stopAudioRecording");
      updateAudioCaptureStatus("recording");
    } catch {
      updateAudioCaptureStatus("error");
    }
  });
}

function updateAudioCaptureStatus(statusKey, detail = "") {
  const status = document.getElementById("recordingStatus");
  const guide = document.getElementById("audioCaptureGuide");
  const labels = {
    ready: t("labels.audioCaptureReady"),
    recording: t("labels.audioCaptureRecording"),
    processing: t("labels.audioCaptureProcessing"),
    added: t("labels.audioCaptureAdded"),
    addedTranscript: t("labels.audioCaptureAddedTranscript"),
    error: t("labels.audioCaptureError"),
  };
  const message = detail || labels[statusKey] || t("labels.audioCaptureOptional");
  if (status) status.textContent = message;
  if (guide) {
    guide.dataset.audioStatus = statusKey || "ready";
  }
}

function startSpeechTranscription() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) return;
  const recognition = new SpeechRecognition();
  recognition.continuous = true;
  recognition.interimResults = true;
  recognition.lang = state.language !== "es" ? "en-US" : "es-ES";
  recognition.addEventListener("result", (event) => {
    const transcript = Array.from(event.results)
      .map((result) => result[0]?.transcript || "")
      .join(" ")
      .trim();
    state.liveTranscript = transcript;
    if (transcript) {
      updateAudioCaptureStatus("recording", `${state.language !== "es" ? "Recording" : "Grabando"}: ${transcript.slice(-70)}`);
    }
  });
  recognition.addEventListener("error", () => {
    state.speechRecognition = null;
  });
  state.speechRecognition = recognition;
  try {
    recognition.start();
  } catch {
    state.speechRecognition = null;
  }
}

function stopSpeechTranscription() {
  if (!state.speechRecognition) return;
  try {
    state.speechRecognition.stop();
  } catch {
    // Browser recognition can already be stopped.
  }
}

function appendLiveTranscriptToNotes() {
  const transcript = state.liveTranscript.trim();
  if (!transcript) return;
  applyAudioTranscriptToCapture(transcript, { source: "browser" });
  appendTranscriptToNotes("Transcripción audio", transcript);
  processAudioTranscriptCommands(transcript);
}

function appendTranscriptToNotes(label, transcript) {
  const notes = document.getElementById("notesInput");
  const prefix = notes.value.trim() ? "\n\n" : "";
  notes.value = `${notes.value}${prefix}${label}:\n${transcript}`;
}

function processAudioTranscriptCommands(transcript = "") {
  const normalized = normalizeVoiceCommand(transcript);
  if (!hasVoiceWakePhrase(normalized) && !/\b(pon en mi agenda|agrega a mi agenda|agenda|schedule)\b/i.test(normalized)) return false;
  const key = normalized.slice(0, 240);
  if (state.processedVoiceTranscriptKeys.has(key)) return false;
  state.processedVoiceTranscriptKeys.add(key);
  const command = stripVoiceWakePhrase(normalized);
  const handled = handleVoiceContentCommand(command, transcript, { source: "audio_transcript" });
  if (handled) {
    updateAudioCaptureStatus("addedTranscript", t("labels.audioCommandDetected"));
    notify(t("labels.audioCommandDetected"));
  }
  return handled;
}

function renderAudioCaptureGuide() {
  const guide = document.getElementById("audioCaptureGuide");
  if (!guide) return;
  guide.innerHTML = `
    <div>
      <strong>${escapeHtml(t("labels.audioCaptureGuideTitle"))}</strong>
      <p>${escapeHtml(t("labels.audioCaptureGuideText"))}</p>
    </div>
    <ol>
      <li>${escapeHtml(state.language !== "es" ? "Press Record audio." : "Pulsa Grabar audio.")}</li>
      <li>${escapeHtml(state.language !== "es" ? "Speak naturally and press Stop." : "Habla con naturalidad y pulsa Detener.")}</li>
      <li>${escapeHtml(state.language !== "es" ? "Review the draft fields, attach more files if needed, and save." : "Revisa el borrador, adjunta más archivos si hace falta y guarda.")}</li>
    </ol>
  `;
}

function applyAudioTranscriptToCapture(transcript, options = {}) {
  const text = String(transcript || "").replace(/\s+/g, " ").trim();
  if (!text) return;
  const titleInput = document.getElementById("titleInput");
  const objectiveInput = document.getElementById("objectiveInput");
  const durationInput = document.getElementById("durationInput");
  const categoryInput = document.getElementById("categoryInput");
  const notesInput = document.getElementById("notesInput");
  if (titleInput && !titleInput.value.trim()) titleInput.value = buildAudioDraftTitle(text);
  if (objectiveInput && !objectiveInput.value.trim()) {
    objectiveInput.value = state.language !== "es" ? "Record and understand this experience" : "Registrar y comprender esta experiencia";
  }
  if (durationInput && !String(durationInput.value || "").trim()) durationInput.value = inferDurationFromTranscript(text);
  if (categoryInput && (!categoryInput.value || categoryInput.value === "Trabajo")) {
    const inferred = inferCategoryFromTranscript(text);
    if (inferred) categoryInput.value = inferred;
  }
  if (notesInput && !notesInput.value.trim() && options.source === "backend") notesInput.value = text;
  renderCaptureWritingCoach();
  renderCaptureEventPreview();
  scheduleCaptureDraftAutosave("audio-transcript", { delayMs: 500 });
}

function buildAudioDraftTitle(text) {
  const words = text.split(/\s+/).filter(Boolean).slice(0, 9).join(" ");
  const cleaned = words.charAt(0).toUpperCase() + words.slice(1);
  return cleaned.length > 70 ? `${cleaned.slice(0, 67)}...` : cleaned;
}

function inferDurationFromTranscript(text) {
  const lower = text.toLowerCase();
  const minutes = lower.match(/(\d{1,3})\s*(minuto|minutos|minute|minutes|min)\b/);
  if (minutes) return Math.max(1, Math.min(Number(minutes[1]), 1440));
  const hours = lower.match(/(\d{1,2})\s*(hora|horas|hour|hours|h)\b/);
  if (hours) return Math.max(1, Math.min(Number(hours[1]) * 60, 1440));
  return 5;
}

function inferCategoryFromTranscript(text) {
  const lower = text.toLowerCase();
  const rules = [
    ["Salud", ["salud", "medico", "médico", "doctor", "ejercicio", "caminar", "bienestar", "estres", "estrés"]],
    ["Viajes / Paseos", ["viaje", "paseo", "playa", "hotel", "aeropuerto", "ruta", "turismo"]],
    ["Trabajo", ["trabajo", "reunion", "reunión", "cliente", "proyecto", "contrato", "oficina"]],
    ["Social", ["familia", "amigo", "amiga", "cena", "conversacion", "conversación", "cumpleaños"]],
    ["Compras", ["compra", "tienda", "precio", "pago", "mercado"]],
    ["Aprendizaje", ["curso", "clase", "aprendi", "aprendí", "estudio", "lectura"]],
    ["Entretenimiento", ["cine", "musica", "música", "concierto", "teatro", "juego"]],
    ["Hogar", ["casa", "hogar", "cocina", "limpieza", "jardin", "jardín"]],
  ];
  const match = rules.find(([, terms]) => terms.some((term) => lower.includes(term)));
  if (match?.[0] === "Hogar") return "";
  return match?.[0] || "";
}

function isSupersededExperience(experience = {}) {
  return ["merged", "split", "degraded"].includes(String(experience.curationStatus || experience.metadata?.curationStatus || "").toLowerCase());
}

function addCurationHistory(experience = {}, operation = "updated", detail = "") {
  const history = Array.isArray(experience.metadata?.curationHistory) ? experience.metadata.curationHistory : [];
  return {
    ...experience,
    updatedAt: new Date().toISOString(),
    metadata: {
      ...(experience.metadata || {}),
      curationHistory: [...history, { operation, detail, at: new Date().toISOString() }].slice(-30),
    },
  };
}

function replaceExperienceLocally(experience = {}) {
  const normalized = normalizeExperienceItem(experience);
  const index = state.experiences.findIndex((item) => item.id === normalized.id);
  if (index >= 0) state.experiences[index] = normalized;
  else state.experiences.unshift(normalized);
  return normalized;
}

async function persistCuratedExperiences(experiences = []) {
  const unique = Array.from(new Map(experiences.filter(Boolean).map((item) => [item.id, replaceExperienceLocally(item)])).values());
  saveExperiences();
  for (const experience of unique) {
    await saveExperienceToApi(experience);
  }
  renderAll();
  return unique;
}

function toggleExperienceCuration(id) {
  state.curationExperienceId = state.curationExperienceId === id ? "" : id;
  renderLibrary();
}

function getCurationTargetExperiences(sourceId = "") {
  return state.experiences
    .filter((item) => item.id !== sourceId && !isSupersededExperience(item))
    .sort((a, b) => new Date(b.timestamp || 0) - new Date(a.timestamp || 0));
}

function getAttachmentId(attachment = {}) {
  return attachment.id || attachment.assetKey || attachment.assetId || attachment.asset_id || "";
}

async function reassignEvidenceFromCuration(sourceId, attachmentId, targetId = "") {
  const source = state.experiences.find((item) => item.id === sourceId);
  const target = targetId ? state.experiences.find((item) => item.id === targetId) : null;
  const attachment = source?.attachments?.find((item) => getAttachmentId(item) === attachmentId);
  if (!source || !attachment || (targetId && !target)) return;
  const release = !target;
  const hasRemoteAssetId = Boolean(attachmentId);
  if (release && !hasRemoteAssetId) {
    notify("Este archivo todavía se está sincronizando. Espera a que llegue al servidor antes de devolverlo a la Bandeja de evidencia.", "warn");
    return;
  }
  const action = release ? "soltar" : "mover";
  const confirmation = release
    ? `¿Soltar \"${attachment.name || "este archivo"}\"? Volverá a la Bandeja de evidencia; el archivo no se borrará.`
    : `¿Mover \"${attachment.name || "este archivo"}\" a \"${target.title}\"? El archivo dejará de pertenecer a \"${source.title}\".`;
  if (!confirm(confirmation)) return;
  if (hasRemoteAssetId && (!state.apiOnline || !state.session?.access_token)) {
    notify("No se puede reorganizar evidencia sin conexión segura. Inténtalo de nuevo cuando el servidor esté disponible.", "warn");
    return;
  }
  try {
    let reassignedAssets = [attachment];
    if (hasRemoteAssetId) {
      const result = await apiRequest("/assets/reassign", {
        method: "POST",
        body: JSON.stringify({
          assetIds: [attachmentId],
          release,
          experienceId: target?.id || "",
          experienceTitle: target?.title || "",
          method: release ? "released_from_story" : "story_curation_move",
        }),
        preserveSessionOnAuthFailure: true,
      });
      if (!result.ok || !result.updated) throw new Error(result.reason || "asset_reassignment_failed");
      reassignedAssets = result.assets || [attachment];
      mergeAdoptedServerAssets(reassignedAssets);
    }
    const nextSource = addCurationHistory({
      ...source,
      attachments: source.attachments.filter((item) => hasRemoteAssetId ? getAttachmentId(item) !== attachmentId : item !== attachment),
    }, release ? "evidence_released" : "evidence_moved", attachment.name || attachmentId);
    const nextTarget = target
      ? addCurationHistory({ ...target, attachments: [...(target.attachments || []), ...reassignedAssets] }, "evidence_received", attachment.name || attachmentId)
      : null;
    await persistCuratedExperiences([nextSource, nextTarget]);
    notify(release ? "El archivo volvió a la Bandeja de evidencia." : "El archivo se movió a la historia elegida.", "success");
  } catch (error) {
    console.warn("Story evidence reassignment failed", error);
    notify(`No se pudo reorganizar el archivo: ${error.message || error}`, "warn");
  }
}

async function mergeExperiencesFromCuration(primaryId) {
  const select = document.getElementById(`curationMergeTarget-${primaryId}`);
  const secondaryId = select?.value || "";
  const primary = state.experiences.find((item) => item.id === primaryId);
  const secondary = state.experiences.find((item) => item.id === secondaryId);
  if (!primary || !secondary) {
    notify("Elige la otra historia que representa el mismo episodio.", "warn");
    return;
  }
  if (!confirm(`¿Unir \"${secondary.title}\" dentro de \"${primary.title}\"? La segunda quedará conservada como antecedente y no aparecerá dos veces en reportes.`)) return;
  const assets = secondary.attachments || [];
  const remoteAssetIds = assets.map(getAttachmentId).filter(Boolean);
  try {
    if (remoteAssetIds.length) {
      const result = await apiRequest("/assets/reassign", {
        method: "POST",
        body: JSON.stringify({ assetIds: remoteAssetIds, experienceId: primary.id, experienceTitle: primary.title, method: "story_merge" }),
        preserveSessionOnAuthFailure: true,
      });
      if (!result.ok || result.updated !== remoteAssetIds.length) throw new Error(result.reason || "merge_asset_transfer_failed");
      mergeAdoptedServerAssets(result.assets || []);
    }
    const attachments = Array.from(new Map([...(primary.attachments || []), ...assets].map((item) => [getAttachmentId(item) || item.name, item])).values());
    const mergedNarrative = getExperienceNarrativeTextForExport(secondary);
    const mergedNarrativeEvent = mergedNarrative
      ? [{
          id: createId(),
          title: secondary.title || "Momento incorporado",
          description: mergedNarrative,
          narrativeText: mergedNarrative,
          timestamp: secondary.timestamp || primary.timestamp,
          duration: secondary.duration || 0,
          mood: secondary.mood || "",
          energy: secondary.energy || null,
        }]
      : [];
    const events = normalizeExperienceEvents([...(primary.events || []), ...mergedNarrativeEvent, ...(secondary.events || [])], primary.id)
      .map((event, index) => ({ ...event, order: index + 1 }));
    const start = Math.min(new Date(primary.timestamp || 0).getTime() || Date.now(), new Date(secondary.timestamp || 0).getTime() || Date.now());
    const nextPrimary = addCurationHistory({
      ...primary,
      timestamp: new Date(start).toISOString(),
      duration: Math.max(Number(primary.duration || 0), Number(secondary.duration || 0)),
      attachments,
      events,
      // Preserve the primary account. The secondary account is a dated child event,
      // not a paragraph pasted into the main experience narrative.
      notes: primary.notes || "",
    }, "merged_from", secondary.id);
    const nextSecondary = addCurationHistory({
      ...secondary,
      attachments: [],
      events: [],
      curationStatus: "merged",
      mergedIntoId: primary.id,
      metadata: { ...(secondary.metadata || {}), curationStatus: "merged", mergedIntoId: primary.id },
    }, "merged_into", primary.id);
    await persistCuratedExperiences([nextPrimary, nextSecondary]);
    state.curationExperienceId = primary.id;
    notify("Las historias se unieron. La original secundaria quedó preservada como antecedente.", "success");
  } catch (error) {
    console.warn("Story merge failed", error);
    notify(`No se pudieron unir las historias: ${error.message || error}`, "warn");
  }
}

async function promoteEventFromCuration(experienceId) {
  const select = document.getElementById(`curationPromoteEvent-${experienceId}`);
  const eventId = select?.value || "";
  const source = state.experiences.find((item) => item.id === experienceId);
  const event = normalizeExperienceEvents(source?.events || [], experienceId).find((item) => item.id === eventId);
  if (!source || !event) {
    notify("Elige un evento para convertirlo en una historia independiente.", "warn");
    return;
  }
  if (!confirm(`¿Convertir \"${event.title}\" en una experiencia independiente? Se conservará la historia principal sin ese evento.`)) return;
  const eventAttachments = (source.attachments || []).filter((asset) => (asset.eventId || asset.metadata?.linkedEventId || "") === event.id);
  const remoteAssetIds = eventAttachments.map(getAttachmentId).filter(Boolean);
  const child = addCurationHistory({
    ...source,
    id: createId(),
    title: event.title,
    timestamp: event.timestamp || source.timestamp,
    duration: event.duration || source.duration,
    mood: event.mood || source.mood,
    energy: event.energy || source.energy,
    notes: event.narrativeText || event.description || "",
    events: [],
    attachments: eventAttachments,
    createdAt: new Date().toISOString(),
    sourceType: "story_curation",
  }, "promoted_from_event", `${source.id}:${event.id}`);
  try {
    if (remoteAssetIds.length) {
      const result = await apiRequest("/assets/reassign", {
        method: "POST",
        body: JSON.stringify({ assetIds: remoteAssetIds, experienceId: child.id, experienceTitle: child.title, method: "event_promoted" }),
        preserveSessionOnAuthFailure: true,
      });
      if (!result.ok || result.updated !== remoteAssetIds.length) throw new Error(result.reason || "event_asset_transfer_failed");
      mergeAdoptedServerAssets(result.assets || []);
    }
    const nextSource = addCurationHistory({
      ...source,
      events: normalizeExperienceEvents(source.events || [], source.id).filter((item) => item.id !== event.id),
      attachments: (source.attachments || []).filter((asset) => !eventAttachments.includes(asset)),
    }, "event_promoted", event.id);
    await persistCuratedExperiences([nextSource, child]);
    notify("El evento ahora tiene su propia historia. Puedes editarla cuando quieras.", "success");
  } catch (error) {
    console.warn("Event promotion failed", error);
    notify(`No se pudo promover el evento: ${error.message || error}`, "warn");
  }
}

async function splitExperienceFromCuration(experienceId) {
  const source = state.experiences.find((item) => item.id === experienceId);
  const boundaryValue = document.getElementById(`curationSplitAt-${experienceId}`)?.value || "";
  const boundary = new Date(boundaryValue);
  const start = new Date(source?.timestamp || "");
  const duration = Number(source?.duration || 0);
  const end = new Date(start.getTime() + duration * 60 * 1000);
  if (!source || Number.isNaN(boundary.getTime()) || Number.isNaN(start.getTime()) || duration < 2 || boundary <= start || boundary >= end) {
    notify("Elige una hora dentro del rango de esta historia para dividirla.", "warn");
    return;
  }
  if (!confirm(`¿Dividir \"${source.title}\" en dos historias? La original se conservará como antecedente y podrás editar los títulos y relatos después.`)) return;
  const beforeAttachments = [];
  const afterAttachments = [];
  (source.attachments || []).forEach((asset) => {
    const captured = new Date(asset.capturedAt || asset.timestamp || source.timestamp || 0);
    (Number.isNaN(captured.getTime()) || captured <= boundary ? beforeAttachments : afterAttachments).push(asset);
  });
  const beforeEvents = [];
  const afterEvents = [];
  normalizeExperienceEvents(source.events || [], source.id).forEach((event) => {
    const occurred = new Date(event.timestamp || source.timestamp || 0);
    (Number.isNaN(occurred.getTime()) || occurred <= boundary ? beforeEvents : afterEvents).push(event);
  });
  const beforeMinutes = Math.max(1, Math.round((boundary.getTime() - start.getTime()) / 60000));
  const afterMinutes = Math.max(1, duration - beforeMinutes);
  const first = addCurationHistory({
    ...source,
    id: createId(),
    title: `${source.title} · 1`,
    duration: beforeMinutes,
    attachments: beforeAttachments,
    events: beforeEvents,
    createdAt: new Date().toISOString(),
    sourceType: "story_curation",
  }, "split_from", source.id);
  const second = addCurationHistory({
    ...source,
    id: createId(),
    title: `${source.title} · 2`,
    timestamp: boundary.toISOString(),
    duration: afterMinutes,
    notes: "",
    attachments: afterAttachments,
    events: afterEvents,
    createdAt: new Date().toISOString(),
    sourceType: "story_curation",
  }, "split_from", source.id);
  try {
    for (const [assets, target] of [[beforeAttachments, first], [afterAttachments, second]]) {
      const assetIds = assets.map(getAttachmentId).filter(Boolean);
      if (!assetIds.length) continue;
      const result = await apiRequest("/assets/reassign", {
        method: "POST",
        body: JSON.stringify({ assetIds, experienceId: target.id, experienceTitle: target.title, method: "story_split" }),
        preserveSessionOnAuthFailure: true,
      });
      if (!result.ok || result.updated !== assetIds.length) throw new Error(result.reason || "split_asset_transfer_failed");
      mergeAdoptedServerAssets(result.assets || []);
    }
    const archived = addCurationHistory({
      ...source,
      attachments: [],
      events: [],
      curationStatus: "split",
      splitIntoIds: [first.id, second.id],
      metadata: { ...(source.metadata || {}), curationStatus: "split", splitIntoIds: [first.id, second.id] },
    }, "split_into", `${first.id},${second.id}`);
    await persistCuratedExperiences([first, second, archived]);
    state.curationExperienceId = first.id;
    notify("La historia se dividió. Revisa y ajusta el relato de cada parte antes de publicar.", "success");
  } catch (error) {
    console.warn("Story split failed", error);
    notify(`No se pudo dividir la historia: ${error.message || error}`, "warn");
  }
}

async function degradeExperienceFromCuration(sourceId) {
  const targetId = document.getElementById(`curationDegradeTarget-${sourceId}`)?.value || "";
  const source = state.experiences.find((item) => item.id === sourceId);
  const target = state.experiences.find((item) => item.id === targetId);
  if (!source || !target) {
    notify("Elige la historia mayor que recibirá este momento como evento.", "warn");
    return;
  }
  if (!confirm(`¿Convertir \"${source.title}\" en un evento dentro de \"${target.title}\"? La historia original quedará conservada como antecedente.`)) return;
  const event = {
    id: createId(),
    title: source.title,
    description: source.notes || "",
    narrativeText: source.notes || "",
    timestamp: source.timestamp,
    duration: source.duration,
    mood: source.mood,
    energy: source.energy,
    order: normalizeExperienceEvents(target.events || [], target.id).length + 1,
  };
  const assets = source.attachments || [];
  try {
    const assetIds = assets.map(getAttachmentId).filter(Boolean);
    if (assetIds.length) {
      const result = await apiRequest("/assets/reassign", {
        method: "POST",
        body: JSON.stringify({ assetIds, experienceId: target.id, experienceTitle: target.title, eventId: event.id, eventTitle: event.title, method: "experience_degraded" }),
        preserveSessionOnAuthFailure: true,
      });
      if (!result.ok || result.updated !== assetIds.length) throw new Error(result.reason || "degrade_asset_transfer_failed");
      mergeAdoptedServerAssets(result.assets || []);
    }
    const nextTarget = addCurationHistory({
      ...target,
      events: [...normalizeExperienceEvents(target.events || [], target.id), event],
      attachments: [...(target.attachments || []), ...assets.map((asset) => ({ ...asset, eventId: event.id, eventTitle: event.title }))],
    }, "experience_received_as_event", source.id);
    const nextSource = addCurationHistory({
      ...source,
      attachments: [],
      events: [],
      curationStatus: "degraded",
      degradedIntoId: target.id,
      metadata: { ...(source.metadata || {}), curationStatus: "degraded", degradedIntoId: target.id },
    }, "degraded_into_event", target.id);
    await persistCuratedExperiences([nextTarget, nextSource]);
    state.curationExperienceId = target.id;
    notify("La historia ahora vive como un evento dentro de la historia elegida.", "success");
  } catch (error) {
    console.warn("Experience demotion failed", error);
    notify(`No se pudo reorganizar la historia: ${error.message || error}`, "warn");
  }
}

function editExperience(id) {
  const experience = state.experiences.find((item) => item.id === id);
  if (!experience) return;
  loadExperienceIntoForm(experience);
}

function loadExperienceIntoForm(experience) {
  document.getElementById("editingId").value = experience.id;
  document.getElementById("titleInput").value = experience.title;
  document.getElementById("categoryInput").value = experience.category;
  updatePilotParticipantControls();
  document.getElementById("pilotParticipantInput").value = experience.pilotParticipantId || "";
  document.getElementById("syncAgendaInput").checked = state.agendaEvents.some((item) => item.sourceExperienceId === experience.id);
  document.getElementById("objectiveInput").value = experience.objective || "";
  document.getElementById("timestampInput").value = toDatetimeLocal(experience.timestamp);
  document.getElementById("durationInput").value = experience.duration;
  document.getElementById("moodInput").value = experience.mood;
  document.getElementById("energyInput").value = experience.energy;
  document.getElementById("locationInput").value = experience.location;
  document.getElementById("peopleInput").value = experience.people;
  document.getElementById("notesInput").value = experience.notes;
  const eventsInput = document.getElementById("experienceEventsInput");
  if (eventsInput) {
    eventsInput.value = normalizeExperienceEvents(experience.events || [], experience.id)
      .sort((a, b) => a.order - b.order)
      .map((event) => event.description ? `${event.title} - ${event.description}` : event.title)
      .join("\n");
  }
  state.pendingAttachments = [...(experience.attachments || [])];
  renderAttachmentPreview();
  renderCaptureEvidenceInbox();
  showView("capture");
}

async function deleteExperience(id) {
  const experience = state.experiences.find((item) => item.id === id);
  const title = experience?.title || (state.language !== "es" ? "this experience" : "esta experiencia");
  const message = state.language !== "es"
     ? `Delete "${title}" This removes it from Library, Timeline, reports, and local assets linked to it.`
    : `¿Eliminar "${title}" Se quitará de Librería, Línea de tiempo, reportes y activos locales vinculados.`;
  if (!confirm(message)) return;
  state.experiences = state.experiences.filter((item) => item.id !== id);
  saveExperiences();
  await deleteExperienceFromApi(id);
  renderAll();
  notify(state.language !== "es" ? "Experience deleted." : "Experiencia eliminada.", "success");
}

