function getEvidenceInboxAssets(options = {}) {
  const assets = collectMultimodalAssets();
  const dateFilter = options.ignoreDate ? "" : getEvidenceInboxDateFilterValue();
  return assets
    .filter((asset) => {
      if (!isIntentionalAdoptableEvidenceAsset(asset)) return false;
      if (isEvidenceAssetAdopted(asset)) return false;
      if (dateFilter && getEvidenceAssetDateKey(asset) !== dateFilter) return false;
      const status = getEvidenceAdoptionStatus(asset);
      return asset.inboxEvidence || status === "inbox" || !asset.experienceId;
    })
    .sort((a, b) => new Date(b.capturedAt || b.timestamp || b.uploadedAt || 0) - new Date(a.capturedAt || a.timestamp || a.uploadedAt || 0));
}

function getEvidenceAdoptionStatus(asset = {}) {
  return String(asset.adoptionStatus || asset.adoption_status || asset.metadata?.adoptionStatus || "").toLowerCase();
}

function isEvidenceAssetAdopted(asset = {}) {
  return getEvidenceAdoptionStatus(asset) === "adopted" || Boolean(asset.experienceId || asset.experience_id);
}

function isIntentionalAdoptableEvidenceAsset(asset = {}) {
  if (!asset || asset.contextOnly) return false;
  const metadata = asset.metadata || {};
  const evidenceType = String(asset.evidenceType || asset.evidence_type || metadata.evidenceType || "intentional").toLowerCase();
  const payloadType = String(asset.payloadType || asset.payload_type || asset.externalPayloadType || metadata.payloadType || metadata.externalPayloadType || "").toLowerCase();
  const sourceType = String(asset.sourceType || asset.source_type || metadata.sourceType || asset.source || "").toLowerCase();
  const kind = String(asset.kind || inferMediaKind(asset) || "").toLowerCase();
  const name = String(asset.name || asset.fileName || asset.filename || "").toLowerCase();
  const type = String(asset.type || asset.mimeType || asset.mime_type || "").toLowerCase();
  const combined = [evidenceType, payloadType, sourceType, kind, name, type].join(" ");

  if (evidenceType === "context" || evidenceType === "ambient" || evidenceType === "ambient_snapshot") return false;
  if (/(biometric|biometr|health|healthkit|health-connect|oura|sleep|readiness|heart|steps|activity|location|gps|weather|climate|news|context|sensor)/.test(combined)) return false;
  if (name.startsWith("vibeapp-health-")) return false;

  if (["image", "video", "audio", "document", "media"].includes(payloadType)) return true;
  if (["image", "video", "audio", "document"].includes(kind)) return true;
  if (/^(image|video|audio)\//.test(type)) return true;
  if (/(pdf|msword|officedocument|text\/plain|text\/markdown|application\/zip)/.test(type)) return true;
  return Boolean(asset.inboxEvidence);
}

function getEvidenceAssetDateKey(asset = {}) {
  const raw = asset.capturedAt || asset.timestamp || asset.uploadedAt || asset.createdAt || "";
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return "";
  // The picker uses the person's local calendar. UTC days would move evening
  // captures into tomorrow and hide them from the intended date.
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getCaptureDateKey() {
  const value = document.getElementById("timestampInput")?.value || "";
  return String(value).slice(0, 10);
}

function getEvidenceInboxDateFilterValue() {
  const current = String(state.evidenceInboxDateFilter || "capture");
  if (current === "all") return "";
  if (current === "capture") return getCaptureDateKey();
  return current;
}

function getEvidenceInboxStats(inbox = getEvidenceInboxAssets()) {
  const dateFilter = getEvidenceInboxDateFilterValue();
  const serverAssets = normalizeServerAssets(state.serverAssets || [])
    .filter(isIntentionalAdoptableEvidenceAsset)
    .filter((asset) => !dateFilter || getEvidenceAssetDateKey(asset) === dateFilter);
  const serverAdopted = serverAssets.filter(isEvidenceAssetAdopted);
  const serverPending = serverAssets.filter((asset) => !isEvidenceAssetAdopted(asset));
  const suggested = inbox.filter(isEvidenceSuggestedForCapture).length;
  return {
    serverTotal: serverAssets.length,
    serverPending: serverPending.length,
    serverAdopted: serverAdopted.length,
    selectable: inbox.length,
    suggested,
    outsideRange: Math.max(0, inbox.length - suggested),
  };
}

function getCurrentCaptureWindow() {
  const startValue = document.getElementById("timestampInput")?.value || "";
  const duration = Number(document.getElementById("durationInput")?.value || 30);
  const start = new Date(startValue);
  if (Number.isNaN(start.getTime())) return null;
  const minutes = Number.isFinite(duration) && duration > 0 ? duration : 30;
  const end = new Date(start.getTime() + minutes * 60 * 1000);
  return { start, end, minutes };
}

function isEvidenceSuggestedForCapture(asset = {}) {
  const windowRange = getCurrentCaptureWindow();
  if (!windowRange) return false;
  const timestamp = new Date(asset.capturedAt || asset.timestamp || asset.uploadedAt || asset.createdAt || 0);
  if (Number.isNaN(timestamp.getTime())) return false;
  const marginMs = 30 * 60 * 1000;
  const selectedParticipantId = document.getElementById("pilotParticipantInput")?.value || "";
  const participantId = asset.participantId || asset.pilotParticipantId || asset.metadata?.participantId || "";
  const participantMatches = !selectedParticipantId || !participantId || participantId === selectedParticipantId;
  return participantMatches && timestamp.getTime() >= windowRange.start.getTime() - marginMs && timestamp.getTime() <= windowRange.end.getTime() + marginMs;
}

function getSelectedEvidenceAssets() {
  const selected = state.selectedEvidenceAssetIds instanceof Set ? state.selectedEvidenceAssetIds : new Set();
  return getEvidenceInboxAssets().filter((asset) => selected.has(asset.id));
}

function scheduleEvidenceInboxRefresh(reason = "auto", options = {}) {
  if (!state.apiOnline || !state.session?.access_token) {
    if (reason === "manual") {
      state.evidenceAdoptionStatus = {
        type: "warn",
        detail: languageText(
          "No se pudo actualizar la bandeja: la sesion o el servidor no estan disponibles.",
          "Could not refresh the inbox: the session or server is unavailable.",
          "Impossible d'actualiser la boite : la session ou le serveur n'est pas disponible.",
          "Nao foi possivel atualizar a bandeja: a sessao ou o servidor nao estao disponiveis.",
        ),
      };
      renderCaptureEvidenceInbox();
    }
    return;
  }
  if (state.evidenceInboxRefreshInProgress) return;
  const now = Date.now();
  if (!options.force && now - Number(state.evidenceInboxLastRefreshAt || 0) < 15000) return;
  if (state.evidenceInboxRefreshTimer) clearTimeout(state.evidenceInboxRefreshTimer);
  const delayMs = Number.isFinite(options.delayMs) ? options.delayMs : 250;
  state.evidenceInboxRefreshTimer = setTimeout(() => {
    state.evidenceInboxRefreshTimer = null;
    refreshServerAssetsForEvidenceInbox({ silent: reason !== "manual" });
  }, delayMs);
}

async function refreshServerAssetsForEvidenceInbox(options = {}) {
  const silent = Boolean(options.silent);
  state.evidenceInboxRefreshInProgress = true;
  if (!silent) {
    state.evidenceAdoptionStatus = {
      type: "ok",
      detail: languageText(
        "Actualizando bandeja de evidencia...",
        "Refreshing evidence inbox...",
        "Actualisation de la boite de preuves...",
        "Atualizando bandeja de evidencias...",
      ),
    };
  }
  renderCaptureEvidenceInbox();
  try {
    const assets = await apiRequest("/assets", { preserveSessionOnAuthFailure: true });
    state.serverAssets = normalizeServerAssets(assets);
    state.evidenceInboxLastRefreshAt = Date.now();
    markApiOnline({ source: "evidence_inbox_refresh" });
    if (!silent) {
      const inboxCount = getEvidenceInboxAssets().length;
      state.evidenceAdoptionStatus = {
        type: "ok",
        detail: languageText(
          `Bandeja actualizada: ${inboxCount} evidencia(s) pendiente(s).`,
          `Inbox refreshed: ${inboxCount} pending evidence item(s).`,
          `Boite actualisee : ${inboxCount} preuve(s) en attente.`,
          `Bandeja atualizada: ${inboxCount} evidencia(s) pendente(s).`,
        ),
      };
    }
    return state.serverAssets;
  } catch (error) {
    markApiConnectivityFailure(error);
    state.evidenceAdoptionStatus = {
      type: "warn",
      detail: languageText(
        `No se pudo actualizar la bandeja de evidencia: ${error.message || error}`,
        `Could not refresh the evidence inbox: ${error.message || error}`,
        `Impossible d'actualiser la boite de preuves : ${error.message || error}`,
        `Nao foi possivel atualizar a bandeja de evidencias: ${error.message || error}`,
      ),
    };
    return [];
  } finally {
    state.evidenceInboxRefreshInProgress = false;
    renderCaptureEvidenceInbox();
  }
}

function mergeAdoptedServerAssets(assets = []) {
  if (!Array.isArray(assets) || !assets.length) return;
  const byId = new Map((state.serverAssets || []).map((asset) => [asset.id || asset.assetKey, asset]));
  normalizeServerAssets(assets).forEach((asset) => byId.set(asset.id || asset.assetKey, asset));
  state.serverAssets = Array.from(byId.values());
}

async function adoptSelectedEvidenceForExperience(experience = {}) {
  const selectedAssets = getSelectedEvidenceAssets();
  if (!selectedAssets.length) return { ok: true, updated: 0 };
  if (!state.apiOnline || !state.session?.access_token) {
    state.evidenceAdoptionStatus = {
      type: "warn",
      detail: languageText(
        "La experiencia se guardo, pero la evidencia seleccionada queda pendiente porque no hay conexion segura.",
        "The experience was saved, but selected evidence is still pending because the secure connection is unavailable.",
        "L'experience a ete enregistree, mais les preuves selectionnees restent en attente car la connexion securisee est indisponible.",
        "A experiencia foi salva, mas a evidencia selecionada segue pendente porque a conexao segura nao esta disponivel.",
      ),
    };
    return { ok: false, updated: 0, reason: "offline" };
  }
  try {
    const result = await apiRequest("/assets/adopt", {
      method: "POST",
      body: JSON.stringify({
        assetIds: selectedAssets.map((asset) => asset.id),
        experienceId: experience.id,
        experienceTitle: experience.title,
        participantId: experience.pilotParticipantId || "",
        method: "manual_window",
        confidence: 1,
      }),
      preserveSessionOnAuthFailure: true,
    });
    const adoptedAssets = normalizeServerAssets(result.assets || []).map((asset) => ({
      ...asset,
      inboxEvidence: false,
      adoptedAt: asset.adoptedAt || new Date().toISOString(),
      adoptionMethod: asset.adoptionMethod || "manual_window",
      adoptionConfidence: Number(asset.adoptionConfidence ?? 1),
      metadata: {
        ...(asset.metadata || {}),
        linkedExperienceId: experience.id,
        adoptionStatus: "adopted",
      },
    }));
    mergeAdoptedServerAssets(adoptedAssets);
    // Keep the local experience aligned with the server adoption. This makes the
    // evidence immediately available to exports without waiting for a refresh.
    if (experience?.id && adoptedAssets.length) {
      const current = state.experiences.find((item) => item.id === experience.id) || experience;
      const byId = new Map((current.attachments || []).map((asset) => [asset.id || asset.assetKey, asset]));
      adoptedAssets.forEach((asset) => byId.set(asset.id || asset.assetKey, asset));
      const mergedExperience = normalizeExperienceItem({
        ...current,
        attachments: Array.from(byId.values()),
        updatedAt: new Date().toISOString(),
      });
      const experienceIndex = state.experiences.findIndex((item) => item.id === experience.id);
      if (experienceIndex >= 0) state.experiences[experienceIndex] = mergedExperience;
      else state.experiences.unshift(mergedExperience);
      Object.assign(experience, mergedExperience);
      saveExperiences();
    }
    const adoptedIds = new Set((result.assets || []).map((asset) => asset.id || asset.assetKey).filter(Boolean));
    selectedAssets.filter((asset) => adoptedIds.has(asset.id)).forEach((asset) => state.selectedEvidenceAssetIds.delete(asset.id));
    const incomplete = selectedAssets.length > (result.updated || 0);
    state.evidenceAdoptionStatus = {
      type: incomplete ? "warn" : "ok",
      detail: incomplete
        ? languageText(
            `${result.updated || 0}/${selectedAssets.length} evidencia(s) adoptada(s). Revisa las restantes en Activos.`,
            `${result.updated || 0}/${selectedAssets.length} evidence item(s) adopted. Review the rest in Assets.`,
            `${result.updated || 0}/${selectedAssets.length} preuve(s) adoptee(s). Verifie le reste dans les fichiers.`,
            `${result.updated || 0}/${selectedAssets.length} evidencia(s) adotada(s). Revise o restante em Ativos.`,
          )
        : languageText(
            `${result.updated || 0} evidencia(s) adoptada(s) en esta experiencia.`,
            `${result.updated || 0} evidence item(s) adopted into this experience.`,
            `${result.updated || 0} preuve(s) adoptee(s) dans cette experience.`,
            `${result.updated || 0} evidencia(s) adotada(s) nesta experiencia.`,
          ),
    };
    return result;
  } catch (error) {
    state.evidenceAdoptionStatus = {
      type: "warn",
      detail: languageText(
        `La experiencia se guardo, pero no se pudo adoptar evidencia: ${error.message || error}`,
        `The experience was saved, but evidence adoption failed: ${error.message || error}`,
        `L'experience a ete enregistree, mais l'adoption des preuves a echoue: ${error.message || error}`,
        `A experiencia foi salva, mas a adocao da evidencia falhou: ${error.message || error}`,
      ),
    };
    console.warn("Evidence adoption failed", error);
    return { ok: false, updated: 0, error: error.message || String(error) };
  }
}

