function handleEvidenceInboxSelection(event) {
  const dateInput = event.target.closest("[data-evidence-date-filter]");
  if (dateInput) {
    state.evidenceInboxDateFilter = String(dateInput.value || "").trim() || "capture";
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
    return;
  }
  const checkbox = event.target.closest("[data-evidence-asset-select]");
  if (!checkbox) return;
  const id = checkbox.dataset.evidenceAssetSelect;
  if (!id) return;
  if (!(state.selectedEvidenceAssetIds instanceof Set)) state.selectedEvidenceAssetIds = new Set();
  if (checkbox.checked) state.selectedEvidenceAssetIds.add(id);
  else state.selectedEvidenceAssetIds.delete(id);
  state.evidenceAdoptionStatus = null;
  renderCaptureEvidenceInbox();
}

function handleEvidenceInboxAction(event) {
  const refreshButton = event.target.closest("[data-evidence-refresh-inbox]");
  const dateCaptureButton = event.target.closest("[data-evidence-date-capture]");
  const dateAllButton = event.target.closest("[data-evidence-date-all]");
  const visibleButton = event.target.closest("[data-evidence-select-visible]");
  const suggestedButton = event.target.closest("[data-evidence-select-suggested]");
  const clearButton = event.target.closest("[data-evidence-clear-selection]");
  if (refreshButton) {
    scheduleEvidenceInboxRefresh("manual", { force: true, delayMs: 0 });
    return;
  }
  if (dateCaptureButton) {
    state.evidenceInboxDateFilter = "capture";
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
    return;
  }
  if (dateAllButton) {
    state.evidenceInboxDateFilter = "all";
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
    return;
  }
  if (visibleButton) {
    if (!(state.selectedEvidenceAssetIds instanceof Set)) state.selectedEvidenceAssetIds = new Set();
    getEvidenceInboxAssets().slice(0, 12).forEach((asset) => state.selectedEvidenceAssetIds.add(asset.id));
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
    return;
  }
  if (suggestedButton) {
    if (!(state.selectedEvidenceAssetIds instanceof Set)) state.selectedEvidenceAssetIds = new Set();
    getEvidenceInboxAssets().filter(isEvidenceSuggestedForCapture).forEach((asset) => state.selectedEvidenceAssetIds.add(asset.id));
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
    return;
  }
  if (clearButton) {
    state.selectedEvidenceAssetIds = new Set();
    state.evidenceAdoptionStatus = null;
    renderCaptureEvidenceInbox();
  }
}

function applyInitialViewFromUrl() {
  const params = new URLSearchParams(window.location.search);
  const view = params.get("view") || (window.location.hash || "").replace("#", "");
  if (view && document.querySelector(`[data-view="${view}"]`)) safeShowView(view);
}

async function handleIntegrationReturnFromUrl() {
  const url = new URL(window.location.href);
  const integration = url.searchParams.get("integration");
  if (integration !== "oura") return;
  const status = url.searchParams.get("status") || "";
  const detail = url.searchParams.get("detail") || "";
  const message = url.searchParams.get("message")
    || (status === "connected" || status === "diagnostic-ok"
      ? state.language !== "es" ? "Oura connected successfully." : "Oura quedo conectado correctamente."
      : state.language !== "es" ? "Oura did not finish connecting." : "Oura no termino de conectarse.");
  const callbackResult = {
    ok: status === "connected" || status === "diagnostic-ok",
    status,
    detailCode: detail,
    message,
    checkedAt: new Date().toISOString(),
  };
  notify(detail ? `${message} (${detail})` : message, callbackResult.ok ? "ok" : "warn");
  try {
    await refreshOuraConnectionStatus({ silent: true });
  } catch (error) {
    state.ouraConnectionStatus = {
      connected: false,
      lastConnection: {
        ok: false,
        message: error.message,
        checkedAt: new Date().toISOString(),
      },
    };
  }
  state.ouraConnectionStatus = {
    ...(state.ouraConnectionStatus || {}),
    connected: status === "connected" ? true : Boolean(state.ouraConnectionStatus?.connected),
    lastConnection: callbackResult,
  };
  ["integration", "status", "message", "detail"].forEach((key) => url.searchParams.delete(key));
  if (!url.searchParams.get("v")) url.searchParams.set("v", APP_VERSION);
  window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
  showView("dashboard");
  renderDashboardIntegrationHandoff();
  renderDeviceIntegrationPanel();
}

async function refreshOuraConnectionStatus(options = {}) {
  try {
    state.ouraConnectionStatus = await apiRequest("/integration/oura/status");
    return state.ouraConnectionStatus;
  } catch (error) {
    state.ouraConnectionStatus = {
      connected: false,
      configured: false,
      lastConnection: {
        ok: false,
        message: error.message,
        checkedAt: new Date().toISOString(),
      },
    };
    if (!options.silent) notify(`Oura: ${error.message}`, "warn");
    return state.ouraConnectionStatus;
  }
}

