function renderDailyMedia(media, mediaLinks) {
  const previews = media
    .slice(0, 3)
    .map(
      (item) => `
        <button class="daily-media-preview" type="button" data-daily-open-url="${escapeHtml(item.sourceUrl || item.url)}">
          <img src="${escapeHtml(item.url)}" alt="" loading="lazy" data-news-image="true" />
        </button>
      `,
    )
    .join("");
  const links = mediaLinks
    .map(
      (link) => `
        <button class="daily-media-tile daily-media-${escapeHtml(link.type || "link")}" type="button" data-daily-open-url="${escapeHtml(link.url)}">
          <span>${escapeHtml(getDailyMediaLabel(link))}</span>
          <small>${escapeHtml(link.label)}</small>
        </button>
      `,
    )
    .join("");
  if (!previews && !links) return "";
  return `
    <div class="daily-media-block">
      <span class="card-meta">${previews ? t("labels.dailyMediaSpecific") : t("labels.dailyMediaExternalSearch")}</span>
      ${previews ? `<div class="daily-media-strip">${previews}</div>` : ""}
      ${links ? `<div class="daily-media-links">${links}</div>` : ""}
    </div>
  `;
}

function getDailyMediaLabel(link) {
  if (link.type === "image") return t("labels.dailyImageSearch");
  if (link.type === "video") return t("labels.dailyVideoSearch");
  if (link.type === "audio") return t("labels.dailyAudioSearch");
  return link.label || t("labels.dailyMedia");
}

