function buildDailyArticleMediaLinks(section, article) {
  const cleanTitle = stripNewsSource(article?.title || section?.title || "");
  const domain = article?.domain || section?.source || "";
  const location = state.dailyBriefing?.location || getDailyOperationalLocation();
  const query = [cleanTitle, domain, location].filter(Boolean).join(" ");
  return [
    { type: "image", label: t("labels.dailyMediaExternalSearch"), query, url: `https://www.google.com/search?tbm=isch&q=${encodeURIComponent(query)}` },
    { type: "video", label: t("labels.dailyMediaExternalSearch"), query, url: `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}` },
    { type: "audio", label: t("labels.dailyMediaExternalSearch"), query: `${query} podcast audio`, url: `https://www.google.com/search?q=${encodeURIComponent(`${query} podcast audio`)}` },
  ];
}

async function handleDailyBriefingClick(event) {
  const flowButton = event.target.closest("[data-daily-flow]");
  if (flowButton) {
    handleDailyFlowAction(flowButton.dataset.dailyFlow);
    return;
  }
  const scheduleListingsButton = event.target.closest("[data-static-daily-schedule], [data-daily-schedule-listings]");
  if (scheduleListingsButton) {
    scheduleDailyListingsReview(scheduleListingsButton.dataset.staticDailySchedule || "");
    return;
  }
  const staticQueryButton = event.target.closest("[data-static-daily-query]");
  if (staticQueryButton) {
    const query = staticQueryButton.dataset.staticDailyQuery;
    renderDailyActionOptions(query, {
      title: getStaticDailyActionTitle(staticQueryButton),
      detail: buildStaticDailyActionDetail(query),
    });
    return;
  }
  const staticMediaButton = event.target.closest("[data-static-daily-media]");
  if (staticMediaButton) {
    const type = staticMediaButton.dataset.staticDailyMedia;
    renderDailyActionOptions(type, {
      title: getStaticDailyActionTitle(staticMediaButton),
      detail: buildStaticDailyActionDetail(type),
    });
    return;
  }
  const scheduleActionButton = event.target.closest("[data-daily-action-schedule]");
  if (scheduleActionButton) {
    scheduleDailyListingsReview(scheduleActionButton.dataset.dailyActionSchedule || "");
    return;
  }
  const menuActionButton = event.target.closest("[data-daily-action-menu]");
  if (menuActionButton) {
    const kind = menuActionButton.dataset.dailyActionMenu;
    renderDailyActionOptions(kind, {
      title: menuActionButton.textContent?.trim() || t("labels.dailyActionResultTitle"),
      detail: buildStaticDailyActionDetail(kind),
    });
    return;
  }
  const voiceButton = event.target.closest("[data-start-voice-command]");
  if (voiceButton) {
    startVoiceCommand();
    return;
  }
  const voiceExampleButton = event.target.closest("[data-voice-example]");
  if (voiceExampleButton) {
    executeVoiceCommand(voiceExampleButton.dataset.voiceExample || "");
    return;
  }
  const scrollButton = event.target.closest("[data-daily-scroll]");
  if (scrollButton) {
    const target = document.querySelector(scrollButton.dataset.dailyScroll);
    if (target) {
      target.scrollIntoView({ behavior: "smooth", block: "start" });
      setDailyActionResult({
        title: t("labels.dailyActionHoroscope"),
        detail: t("labels.dailyHoroscopeVisible"),
      });
    } else {
      setDailyActionResult({
        title: t("labels.dailyActionHoroscope"),
        detail: t("labels.dailyHoroscopeMissing"),
      });
    }
    return;
  }
  const openButton = event.target.closest("[data-daily-open-url]");
  if (openButton) {
    event.preventDefault();
    openDailyExternalResource(openButton.dataset.dailyOpenUrl, {
      title: openButton.textContent?.trim() || t("labels.dailyOpenMedia"),
      detail: t("labels.dailyActionResultHelp"),
    });
    return;
  }
  const saveExperienceButton = event.target.closest("[data-daily-save-experience]");
  if (saveExperienceButton) {
    await saveDailyArticleAsExperience();
    return;
  }
  const image = event.target.closest("[data-news-image]");
  if (image) return;
  const speakButton = event.target.closest("[data-daily-speak]");
  if (speakButton) {
    speakSelectedDailyArticle();
    return;
  }
  const stopAudioButton = event.target.closest("[data-daily-stop-audio]");
  if (stopAudioButton) {
    stopDailyAudio();
    return;
  }
  const closeButton = event.target.closest("[data-daily-close-detail]");
  if (closeButton) {
    state.selectedDailyArticle = null;
    clearDailyHash();
    renderDailyBriefing();
    return;
  }
  const button = event.target.closest("[data-daily-route][data-daily-section][data-daily-article]");
  if (!button) return;
  event.preventDefault();
  state.selectedDailyArticle = {
    sectionId: button.dataset.dailySection,
    articleIndex: Number(button.dataset.dailyArticle || 0),
  };
  updateDailyHash(state.selectedDailyArticle.sectionId, state.selectedDailyArticle.articleIndex);
  renderDailyBriefing();
  document.getElementById("dailyDetailPanel")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function handleDailyFlowAction(flow) {
  if (flow === "read") {
    setDailyActionResult({
      title: t("labels.dailyFlowRead"),
      detail: t("labels.dailyFlowReadDetail"),
    });
    return;
  }
  if (flow === "explore") {
    setDailyActionResult({
      title: t("labels.dailyExploreTitle"),
      detail: t("labels.dailyExploreDetail"),
      bodyHtml: renderDailyExplorePanel(),
    });
    return;
  }
  if (flow === "voice") {
    startVoiceCommand();
    setDailyActionResult({
      title: t("labels.dailyFlowVoice"),
      detail: t("labels.voiceCommandHelp"),
    });
  }
}

function buildDailyExploreActions() {
  return [
    { label: t("labels.dailyStaticCinema"), menu: "cartelera cine" },
    { label: t("labels.dailyStaticConcerts"), menu: "conciertos" },
    { label: t("labels.dailyStaticTheater"), menu: "teatro eventos" },
    { label: t("labels.dailySearchImages"), menu: "image" },
    { label: t("labels.dailySearchVideos"), menu: "video" },
    { label: t("labels.dailySearchAudio"), menu: "audio" },
    { label: t("labels.dailyScheduleFollowUp"), schedule: "cartelera y multimedia" },
  ];
}

