function collectDailyMediaPreviews() {
  const previews = [];
  const sections = Array.isArray(state.dailyBriefing?.sections) ? state.dailyBriefing.sections : [];
  sections.forEach((section) => {
    (section.articles || []).forEach((article) => {
      if (article?.image) {
        previews.push({
          url: article.image,
          sourceUrl: article.url || article.image,
          title: article.title,
          sectionTitle: section.title,
        });
      }
    });
  });
  const seen = new Set();
  return previews.filter((item) => {
    const key = item.url;
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function renderDailyHoroscopeInline() {
  const items = state.dailyBriefing?.horoscope?.length ? state.dailyBriefing.horoscope : buildClientDailyHoroscope();
  return `
    <div class="daily-inline-horoscope">
      ${items
        .map((item) => `<article><strong>${escapeHtml(item.sign)}</strong><p>${escapeHtml(item.text)}</p></article>`)
        .join("")}
    </div>
  `;
}

function buildStaticDailySearchUrl(query) {
  const location = document.getElementById("dailyLocationInput")?.value?.trim() || inferPrimaryLocation() || getDefaultOperationalLocation();
  return `https://www.google.com/search?q=${encodeURIComponent(`${query} ${location}`)}`;
}

function buildStaticDailyMediaUrl(type) {
  const location = document.getElementById("dailyLocationInput")?.value?.trim() || inferPrimaryLocation() || getDefaultOperationalLocation();
  const query = state.language !== "es" ? `${location} news events today` : `${location} noticias eventos hoy`;
  if (type === "image") return `https://www.google.com/search?tbm=isch&q=${encodeURIComponent(query)}`;
  if (type === "video") return `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`;
  return `https://www.google.com/search?q=${encodeURIComponent(`${query} podcast audio`)}`;
}

function renderDailyActionOptions(kind, meta = {}) {
  const actions = buildDailyActionOptions(kind);
  setDailyActionResult({
    title: meta.title || t("labels.dailyActionResultTitle"),
    detail: meta.detail || t("labels.dailyActionResultHelp"),
    actions,
  });
}

function buildDailyActionOptions(kind) {
  const location = document.getElementById("dailyLocationInput")?.value?.trim() || inferPrimaryLocation() || getDefaultOperationalLocation();
  const baseQuery = buildDailyActionQuery(kind, location);
  const googleUrl = `https://www.google.com/search?q=${encodeURIComponent(baseQuery)}`;
  const mapsUrl = `https://www.google.com/maps/search/${encodeURIComponent(baseQuery)}`;
  const ticketsQuery = state.language !== "es" ? `${baseQuery} tickets` : `${baseQuery} entradas`;
  const common = [{ label: t("labels.dailySearchGoogle"), url: googleUrl }];
  if (kind === "image") {
    return [
      { label: t("labels.dailySearchImages"), url: `https://www.google.com/search?tbm=isch&q=${encodeURIComponent(baseQuery)}` },
      { label: t("labels.dailySearchGoogle"), url: googleUrl },
      { label: t("labels.dailyScheduleFollowUp"), schedule: "galería multimedia" },
    ];
  }
  if (kind === "video") {
    return [
      { label: t("labels.dailySearchVideos"), url: `https://www.youtube.com/results?search_query=${encodeURIComponent(baseQuery)}` },
      { label: t("labels.dailySearchGoogle"), url: googleUrl },
      { label: t("labels.dailyScheduleFollowUp"), schedule: "videos del Diario" },
    ];
  }
  if (kind === "audio") {
    return [
      { label: t("labels.dailySearchAudio"), url: `https://www.google.com/search?q=${encodeURIComponent(`${baseQuery} podcast audio`)}` },
      { label: t("labels.dailySearchGoogle"), url: googleUrl },
      { label: t("labels.dailyScheduleFollowUp"), schedule: "audio y podcasts del Diario" },
    ];
  }
  if (kind === "cartelera cine") {
    return [
      { label: t("labels.dailyStaticCinema"), url: googleUrl },
      { label: t("labels.dailySearchMaps"), url: mapsUrl },
      { label: t("labels.dailyScheduleFollowUp"), schedule: kind },
    ];
  }
  if (kind === "conciertos" || kind === "teatro eventos") {
    return [
      ...common,
      { label: t("labels.dailySearchTickets"), url: `https://www.google.com/search?q=${encodeURIComponent(ticketsQuery)}` },
      { label: t("labels.dailyScheduleFollowUp"), schedule: kind },
    ];
  }
  return [...common, { label: t("labels.dailyScheduleFollowUp"), schedule: kind }];
}

function buildDailyActionQuery(kind, location) {
  const place = location || getDefaultOperationalLocation();
  const queries = {
    "cartelera cine": state.language !== "es" ? `movie showtimes ${place}` : `cartelera cine ${place}`,
    conciertos: state.language !== "es" ? `concerts ${place}` : `conciertos ${place}`,
    "teatro eventos": state.language !== "es" ? `theater events ${place}` : `teatro eventos ${place}`,
    image: state.language !== "es" ? `${place} news events today images` : `${place} noticias eventos hoy imágenes`,
    video: state.language !== "es" ? `${place} news events today videos` : `${place} noticias eventos hoy videos`,
    audio: state.language !== "es" ? `${place} news events today podcast audio` : `${place} noticias eventos hoy podcast audio`,
  };
  return queries[kind] || `${kind} ${place}`;
}

