async function saveDailyArticleAsExperience() {
  const selected = getSelectedDailyArticle();
  if (!selected) return;
  const { section, article } = selected;
  const participantId = getActivePilotParticipantId(["dashboard"]);
  const existing = findExistingDailyArticleExperience(section, article, participantId);
  if (existing) {
    renderAll();
    showView("capture");
    loadExperienceIntoForm(existing);
    const status = document.getElementById("embeddingStatus");
    if (status) status.textContent = t("labels.dailyAlreadySavedExperience");
    return;
  }
  const analysis = buildDailyStoryAnalysis(section, article);
  const image = article.image || "";
  const sourceLine = article.url
    ? `${state.language !== "es" ? "Original story" : "Noticia original"}: ${article.url}`
    : "";
  const experience = {
    id: createId(),
    title: article.title || section.title || (state.language !== "es" ? "Daily story" : "Noticia del Diario"),
    category: mapDailySectionToExperienceCategory(section),
    objective: state.language !== "es" ? "informational context" : "contexto informativo",
    timestamp: article.seenAt ? new Date(article.seenAt).toISOString() : new Date().toISOString(),
    duration: 10,
    mood: state.language !== "es" ? "Reflective" : "Reflexivo",
    energy: 5,
    location: state.dailyBriefing?.location || inferPrimaryLocation() || "Sin ubicación",
    people: state.language !== "es" ? "Public context" : "Contexto público",
    notes: [
      `${t("labels.dailyWhatHappens")}: ${analysis.what}`,
      `${t("labels.dailyWhyMatters")}: ${analysis.why}`,
      `${t("labels.dailyWatch")}: ${analysis.watch}`,
      `${state.language !== "es" ? "Section" : "Sección"}: ${section.title || ""}`,
      `${state.language !== "es" ? "Source" : "Fuente"}: ${article.domain || section.source || ""}`,
      sourceLine,
    ]
      .filter(Boolean)
      .join("\n\n"),
    attachments: image
      ? [
          {
            id: createId(),
            name: state.language !== "es" ? "Daily editorial image" : "Imagen editorial del Diario",
            type: "image/external",
            originalType: "image/external",
            extension: "external",
            kind: "image",
            size: 0,
            url: image,
            sourceUrl: article.url || image,
            createdAt: new Date().toISOString(),
            storage: "external",
            previewable: true,
          },
        ]
      : [],
    source: "daily-briefing",
    sourceArticleUrl: article.url || "",
    sourceArticleDomain: article.domain || section.source || "",
    ...buildPilotParticipantFields(participantId),
  };
  state.experiences.unshift(experience);
  saveExperiences();
  await saveExperienceToApi(experience);
  renderAll();
  showView("capture");
  loadExperienceIntoForm(experience);
  const status = document.getElementById("formStatus") || document.getElementById("embeddingStatus");
  if (status) status.textContent = t("labels.dailySavedAsExperience");
}

function findExistingDailyArticleExperience(section, article, participantId = "") {
  const articleUrl = normalizeComparableText(article?.url || "");
  const articleTitle = normalizeComparableText(article?.title || section?.title || "");
  const articleDomain = normalizeComparableText(article?.domain || section?.source || "");
  const normalizedParticipantId = normalizePilotParticipantId(participantId);
  return state.experiences.find((experience) => {
    if (experience.source !== "daily-briefing") return false;
    if ((experience.pilotParticipantId || "") !== normalizedParticipantId) return false;
    const savedUrl = normalizeComparableText(experience.sourceArticleUrl || "");
    if (articleUrl && savedUrl && articleUrl === savedUrl) return true;
    const savedTitle = normalizeComparableText(experience.title || "");
    const savedDomain = normalizeComparableText(experience.sourceArticleDomain || "");
    return Boolean(articleTitle && savedTitle === articleTitle && (!articleDomain || !savedDomain || articleDomain === savedDomain));
  });
}

function mapDailySectionToExperienceCategory(section) {
  const text = `${section?.id || ""} ${section?.title || ""}`.toLowerCase();
  if (text.includes("sport") || text.includes("deporte") || text.includes("health") || text.includes("salud")) return "Salud";
  if (text.includes("econom") || text.includes("finanz")) return "Compras";
  if (text.includes("entertain") || text.includes("entreten") || text.includes("cine") || text.includes("concert")) return "Entretenimiento";
  if (text.includes("tech") || text.includes("ai") || text.includes("tecnolog")) return "Aprendizaje";
  if (text.includes("travel") || text.includes("viaje")) return "Viajes / Paseos";
  return "Aprendizaje";
}

function scheduleDailyListingsReview(query = "") {
  const location = getDailyOperationalLocation();
  saveDailyLocationPreference(location);
  syncDailyLocationInputs(location);
  const start = skipBlockedDates(new Date(Date.now() + 24 * 60 * 60 * 1000), state.agendaBlockedDates, "18:00");
  start.setHours(18, 0, 0, 0);
  const end = new Date(start.getTime() + 45 * 60 * 1000);
  const searchHint =
    query ||
    (state.language !== "es"
       ? `movies, concerts, theater, events, and exhibitions in ${location}`
      : `cartelera, conciertos, teatro, eventos y exposiciones en ${location}`);
  const participantFields = buildPilotParticipantFields(getActivePilotParticipantId(["dashboard", "agenda"]));
  const agendaEvent = {
    id: createId(),
    title: state.language !== "es" ? `Review listings and events in ${location}` : `Revisar cartelera y eventos en ${location}`,
    type: "Personal",
    description:
      state.language !== "es"
         ? `Daily action created from the Dashboard. Review current listings and decide whether to add a concrete plan.\n\nSearch focus: ${searchHint}`
        : `Acción creada desde el Panel del Diario. Revisa la cartelera vigente y decide si conviene agregar un plan concreto.\n\nFoco de búsqueda: ${searchHint}`,
    startAt: start.toISOString(),
    endAt: end.toISOString(),
    location,
    participants: participantFields.pilotParticipantName || (state.language !== "es" ? "Personal follow-up" : "Seguimiento personal"),
    ...participantFields,
    priority: "normal",
    status: "Planificado",
    reminders: state.language !== "es" ? "30 min before" : "30 min antes",
    createdAt: new Date().toISOString(),
    source: "daily-briefing",
  };
  state.agendaEvents.unshift(agendaEvent);
  state.agendaFilters.date = formatLocalDateKey(start);
  state.agendaFilters.range = "week";
  state.agendaFilters.pilotParticipantId = agendaEvent.pilotParticipantId || "all";
  saveAgendaEvents();
  renderAll();
  showView("agenda");
  const dateFilter = document.getElementById("agendaDateFilter");
  const rangeFilter = document.getElementById("agendaRangeFilter");
  if (dateFilter) dateFilter.value = state.agendaFilters.date;
  if (rangeFilter) rangeFilter.value = state.agendaFilters.range;
  renderAgenda();
  const status = document.getElementById("agendaFormStatus");
  if (status) status.textContent = t("labels.dailyScheduledAgenda");
}

function speakSelectedDailyArticle() {
  const selected = getSelectedDailyArticle();
  if (!selected || !("speechSynthesis" in window)) return;
  const analysis = buildDailyStoryAnalysis(selected.section, selected.article);
  const text = [
    selected.article.title,
    t("labels.dailyWhatHappens"),
    analysis.what,
    t("labels.dailyWhyMatters"),
    analysis.why,
    t("labels.dailyWatch"),
    analysis.watch,
  ].filter(Boolean).join(". ");
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = state.language !== "es" ? "en-US" : "es-ES";
  utterance.rate = 0.95;
  window.speechSynthesis.speak(utterance);
}

function stopDailyAudio() {
  if ("speechSynthesis" in window) window.speechSynthesis.cancel();
}

function startVoiceCommand() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  const button = document.getElementById("voiceCommandButton");
  const staticButton = document.getElementById("dailyStaticVoiceButton");
  if (!SpeechRecognition) {
    notify(t("labels.voiceCommandUnsupported"));
    setVoiceCommandStatus(t("labels.voiceCommandStatusUnsupported"), "warning");
    return;
  }
  if (state.voiceRecognition) {
    state.voiceWakeActive = false;
    state.voiceRecognition.stop();
    state.voiceRecognition = null;
    setVoiceCommandStatus(t("labels.voiceCommandStatusReady"));
    return;
  }
  state.voiceWakeActive = true;
  const recognition = new SpeechRecognition();
  recognition.lang = state.language !== "es" ? "en-US" : "es-ES";
  recognition.continuous = true;
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;
  state.voiceRecognition = recognition;
  if (button) button.textContent = t("labels.voiceCommandListening");
  if (staticButton) staticButton.textContent = t("labels.voiceCommandListening");
  setVoiceCommandStatus(t("labels.voiceCommandContinuousHelp"), "active");
  notify(t("labels.voiceCommandContinuousHelp"));
  recognition.onresult = (event) => {
    const transcript = event.results?.[0]?.[0]?.transcript || "";
    notify(`${t("labels.voiceCommandHeard")}: ${transcript}`);
    setVoiceCommandStatus(`${t("labels.voiceCommandHeard")}: ${transcript}`, "success");
    executeVoiceCommand(transcript);
  };
  recognition.onerror = (event) => {
    if (["not-allowed", "service-not-allowed", "audio-capture"].includes(event?.error)) state.voiceWakeActive = false;
    notify(t("labels.voiceCommandUnknown"));
    setVoiceCommandStatus(t("labels.voiceCommandUnknown"), "warning");
  };
  recognition.onend = () => {
    if (state.voiceWakeActive) {
      try {
        recognition.start();
        return;
      } catch {
        state.voiceWakeActive = false;
      }
    }
    state.voiceRecognition = null;
    if (button) button.textContent = t("buttons.voiceCommand");
    if (staticButton) staticButton.textContent = t("labels.dailyStartVoice");
  };
  recognition.start();
}

function executeVoiceCommand(transcript) {
  const command = stripVoiceWakePhrase(normalizeVoiceCommand(transcript));
  if (!command) {
    setVoiceCommandStatus(t("labels.voiceCommandWakeReady"), "active");
    notify(t("labels.voiceCommandWakeReady"));
    return;
  }
  if (handleVoiceContentCommand(command, transcript)) return;
  const viewMatch = [
    ["dashboard", ["panel", "dashboard", "inicio", "home"]],
    ["capture", ["captura", "capture", "nueva experiencia", "new experience"]],
    ["library", ["librería", "libreria", "library"]],
    ["assetLibrary", ["activos", "multimodal", "multimedia assets", "assets"]],
    ["agenda", ["agenda", "calendario", "calendar"]],
    ["timeline", ["línea de tiempo", "linea de tiempo", "timeline"]],
    ["experienceMap", ["mapa", "experience map", "mapa de experiencias"]],
    ["report", ["reporte", "report"]],
    ["publications", ["publicaciones", "publications"]],
    ["insights", ["hallazgos", "insights"]],
    ["automation", ["automatizaciones", "automations", "rutinas"]],
    ["manual", ["manual", "ayuda", "help"]],
    ["admin", ["admin", "administración", "administracion"]],
  ].find(([, aliases]) => aliases.some((alias) => command.includes(alias)));
  if (command.includes("actualizar diario") || command.includes("refresh daily") || command.includes("update daily")) {
    showView("dashboard");
    setVoiceCommandStatus(`${t("labels.voiceCommandStatusExecuted")}: ${transcript}`, "success");
    refreshDailyBriefing({ force: true });
    return;
  }
  if (command.includes("actualizar contexto") || command.includes("update context") || command.includes("analizar contexto") || command.includes("analyze context") || command.includes("impacto")) {
    showView("dashboard");
    setVoiceCommandStatus(`${t("labels.voiceCommandStatusExecuted")}: ${transcript}`, "success");
    analyzeContextImpact();
    return;
  }
  if (command.includes("cargar ejemplo") || command.includes("load example")) {
    setVoiceCommandStatus(`${t("labels.voiceCommandStatusExecuted")}: ${transcript}`, "success");
    loadDemoData();
    return;
  }
  if (command.includes("respaldo") || command.includes("backup")) {
    setVoiceCommandStatus(`${t("labels.voiceCommandStatusExecuted")}: ${transcript}`, "success");
    exportLocalBackup();
    return;
  }
  if (viewMatch) {
    showView(viewMatch[0]);
    if (viewMatch[0] === "capture") document.getElementById("titleInput")?.focus();
    setVoiceCommandStatus(`${t("labels.voiceCommandStatusExecuted")}: ${transcript}`, "success");
    return;
  }
  notify(t("labels.voiceCommandUnknown"));
  setVoiceCommandStatus(t("labels.voiceCommandUnknown"), "warning");
}

function handleVoiceContentCommand(command, originalTranscript = command, options = {}) {
  const mediaCommand = extractVoiceMediaCommand(command);
  if (mediaCommand) {
    openMediaCaptureFromVoice(mediaCommand, originalTranscript);
    return true;
  }
  const note = extractVoiceNoteText(command);
  if (note) {
    appendVoiceNoteToCapture(note, originalTranscript);
    return true;
  }
  const quickExperienceNote = extractVoiceQuickExperienceText(command);
  if (quickExperienceNote) {
    saveVoiceQuickExperience(quickExperienceNote, originalTranscript);
    return true;
  }
  if (isVoiceAgendaCommand(command)) {
    createVoiceAgendaEvent(command, originalTranscript, options);
    return true;
  }
  return false;
}

function extractVoiceMediaCommand(command = "") {
  if (/\b(toma|tomar|saca|sacar|captura|hacer|take|capture)\b.*\b(foto|imagen|photo|picture|image)\b/i.test(command)) return "image";
  if (/\b(graba|grabar|toma|tomar|record|capture)\b.*\b(video)\b/i.test(command)) return "video";
  if (/\b(graba|grabar|record)\b.*\b(audio|voz|voice|nota de voz)\b/i.test(command)) return "audio";
  return "";
}

function openMediaCaptureFromVoice(kind = "image", originalTranscript = "") {
  showView("capture");
  const input = document.getElementById("mediaInput");
  if (!input) return;
  const config = {
    image: { accept: "image/*", capture: "environment", label: state.language !== "es" ? "Choose or take a photo." : "Elige o toma una foto." },
    video: { accept: "video/*", capture: "environment", label: state.language !== "es" ? "Choose or record a video." : "Elige o graba un video." },
    audio: { accept: "audio/*", capture: "microphone", label: state.language !== "es" ? "Choose or record audio." : "Elige o graba un audio." },
  }[kind] || {};
  input.setAttribute("accept", config.accept || "image/*,video/*,audio/*");
  if (config.capture) input.setAttribute("capture", config.capture);
  setVoiceCommandStatus(`${config.label || ""} ${originalTranscript}`.trim(), "success");
  notify(config.label || t("labels.voiceCommandStatusExecuted"));
  try {
    input.click();
  } catch {
    input.focus();
  }
  window.setTimeout(resetMediaInputMode, 30000);
}

function extractVoiceNoteText(command = "") {
  const match = command.match(/(?:toma nota|tomar nota|anota|nota que|take note|note that)\s*(?:que|:)?\s*(.+)$/i);
  return match?.[1]?.trim() || "";
}

function extractVoiceQuickExperienceText(command = "") {
  const match = command.match(/(?:guarda esto|guardar esto|crea experiencia|nueva experiencia|save this|create experience)\s*(?:que|:)?\s*(.+)$/i);
  return match?.[1]?.trim() || "";
}

function isVoiceAgendaCommand(command = "") {
  if (/\b(abrir|open)\s+(agenda|calendar)\b/i.test(command)) return false;
  return /\b(pon en mi agenda|agrega a mi agenda|agenda|calendario|schedule|calendar)\b/i.test(command);
}

function appendVoiceNoteToCapture(note, originalTranscript = "") {
  showView("capture");
  const notesInput = document.getElementById("notesInput");
  const prefix = notesInput?.value.trim() ? "\n\n" : "";
  const label = state.language !== "es" ? "V note" : "Nota de V";
  if (notesInput) notesInput.value = `${notesInput.value}${prefix}${label} (${formatDate(new Date().toISOString())}):\n${note}`;
  if (!document.getElementById("titleInput")?.value.trim()) {
    document.getElementById("titleInput").value = buildAudioDraftTitle(note);
  }
  renderCaptureWritingCoach();
  renderCaptureEventPreview();
  scheduleCaptureDraftAutosave("voice-note", { delayMs: 500 });
  setVoiceCommandStatus(`${t("labels.voiceNoteSaved")}: ${originalTranscript}`, "success");
  notify(t("labels.voiceNoteSaved"));
}

async function saveVoiceQuickExperience(note, originalTranscript = "") {
  const now = new Date();
  const participantFields = buildPilotParticipantFields(getActivePilotParticipantId(["capture", "dashboard"]));
  const experience = {
    id: createId(),
    title: buildAudioDraftTitle(note),
    category: inferCategoryFromTranscript(note) || "Social",
    timestamp: now.toISOString(),
    duration: inferDurationFromTranscript(note),
    objective: state.language !== "es" ? "Quick voice capture" : "Captura rápida por voz",
    mood: "",
    energy: 5,
    location: "",
    people: participantFields.pilotParticipantName || "",
    attachments: [],
    notes: note,
    sourceType: "voice_quick_note",
    createdAt: now.toISOString(),
    ...participantFields,
  };
  state.experiences.unshift(experience);
  saveExperiences();
  await saveExperienceToApi(experience);
  state.lastSavedExperienceId = experience.id;
  renderAll();
  showView("library");
  setVoiceCommandStatus(`${t("labels.voiceQuickExperienceSaved")}: ${originalTranscript}`, "success");
  notify(t("labels.voiceQuickExperienceSaved"));
}

function createVoiceAgendaEvent(command, originalTranscript = command, options = {}) {
  const start = parseVoiceAgendaStart(command);
  const end = new Date(start.getTime() + 90 * 60 * 1000);
  const title = buildVoiceAgendaTitle(command);
  const participantFields = buildPilotParticipantFields(getActivePilotParticipantId(["agenda", "dashboard"]));
  const agendaEvent = {
    id: createId(),
    title,
    type: inferAgendaTypeFromVoice(command),
    description: originalTranscript,
    startAt: start.toISOString(),
    endAt: end.toISOString(),
    location: "",
    participants: inferVoiceAgendaParticipants(command) || participantFields.pilotParticipantName || "Sin participantes",
    ...participantFields,
    priority: "normal",
    status: "Planificado",
    reminders: state.language !== "es" ? "30 min before" : "30 min antes",
    sourceType: "voice_command",
    createdAt: new Date().toISOString(),
  };
  state.agendaEvents.unshift(agendaEvent);
  state.agendaFilters.date = formatLocalDateKey(start);
  state.agendaFilters.range = "day";
  state.agendaFilters.pilotParticipantId = agendaEvent.pilotParticipantId || "all";
  saveAgendaEvents();
  void saveAgendaEventToApi(agendaEvent, { silent: true });
  renderAgenda();
  if (!options.source || options.source !== "audio_transcript") showView("agenda");
  const message = `${t("labels.voiceAgendaSaved")}: ${title} · ${formatDate(agendaEvent.startAt)}`;
  const agendaStatus = document.getElementById("agendaFormStatus");
  if (agendaStatus) agendaStatus.textContent = message;
  setVoiceCommandStatus(message, "success");
  notify(message);
}

function parseVoiceAgendaStart(command = "") {
  const now = new Date();
  const lower = String(command || "").toLowerCase();
  const base = new Date(now);
  if (/\b(mañana|tomorrow)\b/.test(lower)) base.setDate(base.getDate() + 1);
  const explicitDate = lower.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
  if (explicitDate) {
    const day = Number(explicitDate[1]);
    const month = Number(explicitDate[2]) - 1;
    const year = explicitDate[3] ? Number(explicitDate[3].length === 2 ? `20${explicitDate[3]}` : explicitDate[3]) : base.getFullYear();
    base.setFullYear(year, month, day);
  }
  const time = lower.match(/\b(?:a las|at)?\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm|a m|p m|de la mañana|de la tarde|de la noche)?\b/);
  if (time) {
    let hour = Number(time[1]);
    const minute = Number(time[2] || 0);
    const marker = String(time[3] || "").replace(/\s/g, "");
    if ((marker === "pm" || marker === "pm" || marker.includes("tarde") || marker.includes("noche")) && hour < 12) hour += 12;
    if ((marker === "am" || marker.includes("mañana")) && hour === 12) hour = 0;
    base.setHours(hour, minute, 0, 0);
  } else {
    base.setHours(now.getHours() + 1, 0, 0, 0);
  }
  return base;
}

function buildVoiceAgendaTitle(command = "") {
  const cleaned = String(command || "")
    .replace(/\b(pon en mi agenda|agrega a mi agenda|agenda|calendario|schedule|calendar)\b/gi, "")
    .replace(/\b(que|tengo|tendre|tendré|hoy|mañana|tomorrow|today|at|a las|pm|am|de la tarde|de la noche|de la mañana)\b/gi, "")
    .replace(/\b\d{1,2}(?::\d{2})?\b/g, "")
    .replace(/\s+/g, " ")
    .trim();
  return buildAudioDraftTitle(cleaned || (state.language !== "es" ? "Voice agenda event" : "Evento de voz"));
}

function inferAgendaTypeFromVoice(command = "") {
  const lower = String(command || "").toLowerCase();
  if (/(cena|almuerzo|familia|esposa|esposo|personal|dinner|lunch|family|wife|husband)/.test(lower)) return "Personal";
  if (/(reunion|reunión|trabajo|cliente|meeting|work|client)/.test(lower)) return "Laboral";
  if (/(doctor|medic|médic|salud|health)/.test(lower)) return "Médica";
  if (/(viaje|vuelo|hotel|travel|flight)/.test(lower)) return "Viajes";
  return "Personal";
}

function inferVoiceAgendaParticipants(command = "") {
  const lower = String(command || "").toLowerCase();
  if (lower.includes("esposa")) return "Esposa";
  if (lower.includes("esposo")) return "Esposo";
  if (lower.includes("familia")) return "Familia";
  const withMatch = command.match(/\b(?:con|with)\s+(.+?)(?:\s+(?:hoy|mañana|tomorrow|today|a las|at)\b|$)/i);
  return withMatch?.[1]?.trim() || "";
}

function normalizeVoiceCommand(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[.,;:!?¿¡]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function stripVoiceWakePhrase(command = "") {
  const raw = String(command || "").trim();
  const greeted = raw.match(/^(hola|hello|hi|hey|oye)\s+([a-z]+)\b[,:;\s-]*(.*)$/i);
  if (greeted && isVoiceWakeToken(greeted[2], greeted[3])) return greeted[3].trim();
  const direct = raw.match(/^([a-z]+)\b[,:;\s-]*(.*)$/i);
  if (direct && isVoiceWakeToken(direct[1], direct[2])) return direct[2].trim();
  return raw.replace(/^(por favor|please)\b/, "").trim();
}

function hasVoiceWakePhrase(command = "") {
  const raw = String(command || "").trim();
  const greeted = raw.match(/^(hola|hello|hi|hey|oye)\s+([a-z]+)\b[,:;\s-]*(.*)$/i);
  if (greeted) return isVoiceWakeToken(greeted[2], greeted[3]);
  const direct = raw.match(/^([a-z]+)\b[,:;\s-]*(.*)$/i);
  return Boolean(direct && isVoiceWakeToken(direct[1], direct[2]));
}

function isVoiceWakeToken(token = "", followingCommand = "") {
  const normalized = String(token || "").toLowerCase().trim();
  if (/^(v|ve|vee)$/.test(normalized)) return true;
  if (/^(by|bye|bay|vai)$/.test(normalized)) return looksLikeVoiceActionCommand(followingCommand);
  return false;
}

function looksLikeVoiceActionCommand(command = "") {
  const lower = String(command || "").toLowerCase().trim();
  if (!lower) return false;
  return /\b(abrir|abre|open|panel|dashboard|captura|capture|libreria|library|activos|assets|agenda|calendario|calendar|reporte|report|publicaciones|publications|hallazgos|insights|manual|ayuda|help|actualizar|refresh|diario|daily|analizar|impacto|contexto|toma nota|tomar nota|anota|nota que|guarda esto|guardar esto|take note|note that|save this|nueva experiencia|new experience|inicia|iniciar|empieza|graba|grabar|start|begin|cerrar|cierra|close|end|toma|tomar|saca|sacar|foto|imagen|photo|picture|video|audio|voz|voice)\b/.test(lower);
}

async function clearAppShellCaches() {
  try {
    if ("serviceWorker" in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      await Promise.all(registrations.map((registration) => registration.unregister().catch(() => {})));
    }
    if ("caches" in window) {
      const keys = await caches.keys();
      await Promise.all(keys.filter((key) => /^experience-hub-pwa-/i.test(key)).map((key) => caches.delete(key)));
    }
  } catch (error) {
    console.warn("App shell cache refresh skipped", error);
  }
}

async function reloadCurrentAppVersion() {
  notify(t("labels.appReloading"));
  const currentView = document.querySelector(".nav-item.active")?.dataset.view || "dashboard";
  const nextUrl = new URL(window.location.href);
  nextUrl.pathname = nextUrl.pathname.endsWith("/index.html") ? nextUrl.pathname : `${nextUrl.pathname.replace(/\/$/, "")}/index.html`;
  nextUrl.search = "";
  nextUrl.searchParams.set("v", APP_VERSION);
  nextUrl.searchParams.set("view", currentView);
  nextUrl.hash = "";
  await clearAppShellCaches();
  window.location.replace(nextUrl.toString());
}

function renderAppVersionBadge() {
  const badge = document.getElementById("appVersionBadge");
  const reloadButton = document.getElementById("reloadAppButton");
  if (!badge) return;
  const urlVersion = new URLSearchParams(window.location.search).get("v") || "";
  const mismatch = Boolean(urlVersion && urlVersion !== APP_VERSION);
  badge.textContent = mismatch
     ? `${t("labels.appVersion")} ${APP_VERSION} · ${t("labels.appVersionMismatch")}`
    : `${t("labels.appVersion")} ${APP_VERSION}`;
  badge.classList.toggle("is-warning", mismatch);
  reloadButton?.classList.toggle("reload-warning", mismatch);
  if (reloadButton) {
    reloadButton.title = mismatch
       ? `${t("labels.appVersionMismatch")}: ${urlVersion}. ${t("labels.appVersionNoticeAction")}.`
      : t("buttons.reloadApp");
  }
  badge.title = mismatch
     ? `${t("labels.appVersionMismatch")}: ${urlVersion}`
    : `${t("labels.appVersion")} ${APP_VERSION}`;
}

function normalizeVisibleVersionUrl() {
  const currentView = new URLSearchParams(window.location.search).get("view") || document.querySelector(".nav-item.active")?.dataset.view || "dashboard";
  const urlVersion = new URLSearchParams(window.location.search).get("v") || "";
  if (urlVersion === APP_VERSION) return false;
  const nextUrl = new URL(window.location.href);
  nextUrl.pathname = nextUrl.pathname.endsWith("/index.html") ? nextUrl.pathname : `${nextUrl.pathname.replace(/\/$/, "")}/index.html`;
  nextUrl.searchParams.set("v", APP_VERSION);
  nextUrl.searchParams.set("view", currentView);
  window.history.replaceState({}, "", nextUrl.toString());
  renderAppVersionBadge();
  renderVersionNotice(urlVersion);
  return true;
}

function renderVersionNotice(previousVersion = "") {
  const notice = document.getElementById("versionNotice");
  if (!notice) return;
  const urlVersion = new URLSearchParams(window.location.search).get("v") || "";
  const mismatch = Boolean((previousVersion && previousVersion !== APP_VERSION) || (urlVersion && urlVersion !== APP_VERSION));
  notice.hidden = !mismatch;
  if (!mismatch) {
    notice.innerHTML = "";
    return;
  }
  notice.innerHTML = `
    <div>
      <strong>${escapeHtml(t("labels.appVersionNoticeTitle"))}</strong>
      <p>${escapeHtml(t("labels.appVersionNoticeDetail"))}</p>
      <small>${escapeHtml(t("labels.appVersionMismatch"))}: ${escapeHtml(previousVersion || urlVersion)} · ${escapeHtml(t("labels.appVersion"))}: ${escapeHtml(APP_VERSION)}</small>
    </div>
    <button class="primary-button" type="button" data-version-refresh="true">${escapeHtml(t("labels.appVersionNoticeAction"))}</button>
  `;
}

function handleDailyRouteFromHash() {
  hydrateDailyRouteFromHash(true);
}

function hydrateDailyRouteFromHash(shouldRender = false) {
  const route = parseDailyHash();
  if (!route) return;
  const section = (state.dailyBriefing?.sections || []).find((item) => item.id === route.sectionId);
  const article = section?.articles?.[route.articleIndex];
  if (!section || !article) return;
  const current = state.selectedDailyArticle;
  if (current?.sectionId === route.sectionId && Number(current.articleIndex) === route.articleIndex) return;
  state.selectedDailyArticle = route;
  if (shouldRender) {
    renderDailyBriefing();
    document.getElementById("dailyDetailPanel")?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }
}

function parseDailyHash() {
  const match = decodeURIComponent(window.location.hash || "").match(/^#daily=([^:]+):(\d+)$/);
  return match ? { sectionId: match[1], articleIndex: Number(match[2]) } : null;
}

function buildDailyArticleHash(sectionId, articleIndex) {
  return `#daily=${encodeURIComponent(sectionId)}:${articleIndex}`;
}

function updateDailyHash(sectionId, articleIndex) {
  const nextHash = buildDailyArticleHash(sectionId, articleIndex);
  if (window.location.hash !== nextHash) window.history.replaceState(null, "", nextHash);
}

function clearDailyHash() {
  if (window.location.hash.startsWith("#daily=")) {
    window.history.replaceState(null, "", window.location.pathname + window.location.search);
  }
}

function handleNewsImageFailure(event) {
  const image = event.target?.closest?.("[data-news-image]");
  if (image) removeNewsImageContainer(image);
}

function handleNewsImageLoad(event) {
  const image = event.target?.closest?.("[data-news-image]");
  if (!image) return;
  const tooSmall = image.naturalWidth && image.naturalHeight && (image.naturalWidth < 260 || image.naturalHeight < 140);
  const tooNarrow = image.naturalWidth && image.naturalHeight && image.naturalWidth / image.naturalHeight > 5;
  if (tooSmall || tooNarrow || isLikelyLogoImage(image.src)) removeNewsImageContainer(image);
}

function removeNewsImageContainer(image) {
  const container = image.closest(".daily-section-visual, .daily-detail-media, .daily-media-preview");
  container?.remove();
}

function isLikelyLogoImage(src = "") {
  const value = String(src).toLowerCase();
  return ["logo", "favicon", "icon", "sprite", "placeholder", "avatar", "brand", "gstatic.com", "googleusercontent.com"].some((token) => value.includes(token));
}

function getSelectedDailyArticle() {
  if (!state.selectedDailyArticle || !state.dailyBriefing) return null;
  const section = (state.dailyBriefing.sections || []).find((item) => item.id === state.selectedDailyArticle.sectionId);
  const index = Number(state.selectedDailyArticle.articleIndex || 0);
  const article = section?.articles?.[index];
  return section && article ? { section, article, index } : null;
}

function buildDailyStoryAnalysis(section, article = {}) {
  const language = state.language !== "es" ? "en" : "es";
  const title = article?.title || section?.title || "";
  const cleanTitle = stripNewsSource(title);
  const source = article?.domain || section?.source || "";
  const peers = (section?.articles || [])
    .filter((item) => item && item.title && item.title !== title)
    .slice(0, 3)
    .map((item) => stripNewsSource(item.title));
  const category = section?.title || (language === "en" ? "this topic" : "este tema");
  const scope = section?.scope === "world" ? (language === "en" ? "global" : "mundial") : (language === "en" ? "local" : "local");

  if (language === "en") {
    return {
      what: `${cleanTitle}${source ? `, reported by ${source}` : ""}. This is part of the ${scope} ${category.toLowerCase()} agenda currently appearing in the briefing.`,
      why: `It can affect how the user reads context, mobility, conversations, market mood, cultural plans, or public attention around ${category.toLowerCase()}.`,
      watch: peers.length ? `Related signals to compare: ${peers.join("; ")}.` : "Check whether more sources confirm the same angle before acting on it.",
    };
  }

  return {
    what: `${cleanTitle}${source ? `, reportado por ${source}` : ""}. Forma parte de la agenda ${scope} de ${category.toLowerCase()} que aparece hoy en el Diario.`,
    why: `Puede afectar la lectura del contexto, movilidad, conversaciones, ánimo económico, planes culturales o atención pública alrededor de ${category.toLowerCase()}.`,
    watch: peers.length ? `Señales relacionadas para comparar: ${peers.join("; ")}.` : "Conviene revisar si otras fuentes confirman el mismo ángulo antes de tomar decisiones.",
  };
}

function stripNewsSource(title = "") {
  return String(title)
    .replace(/\s+-\s+[^-]{2,80}$/g, "")
    .replace(/\s+\|\s+[^|]{2,80}$/g, "")
    .trim();
}

async function refreshDailyBriefing(options = {}) {
  const status = document.getElementById("dailyBriefingStatus");
  const input = document.getElementById("dailyLocationInput");
  const cachedAt = state.dailyBriefing?.generatedAt ? new Date(state.dailyBriefing.generatedAt).getTime() : 0;
  const stillFresh = cachedAt && !isDailyBriefingStale(state.dailyBriefing);
  const location = options.location || input?.value?.trim() || getDailyOperationalLocation();
  const contextLabel = resolveOperationalContextLabel(location);
  const sameLocation = locationsEquivalent(location, state.dailyBriefing?.location);
  const sameLanguage = !state.dailyBriefing?.locale || state.dailyBriefing.locale === state.language;
  if (!options.force && stillFresh && sameLocation && sameLanguage) return;
  saveDailyLocationPreference(location);
  syncDailyLocationInputs(location);
  if (status && !options.silent) status.textContent = t("labels.dailyLoading");
  try {
    const forceParam = options.force ? "&force=1" : "";
    const labelParam = contextLabel ? `&label=${encodeURIComponent(contextLabel)}` : "";
    state.dailyBriefing = await apiRequest(`/daily-briefing?location=${encodeURIComponent(location)}&locale=${encodeURIComponent(state.language)}${forceParam}${labelParam}`);
    saveDailyLocationPreference(state.dailyBriefing?.location || location);
    syncDailyLocationInputs(state.dailyBriefing?.location || location);
    state.selectedDailyArticle = null;
    clearDailyHash();
    saveDailyBriefing();
    if (status) status.textContent = t("labels.dailyUpdated");
    renderDailyBriefing();
  } catch {
    if (status && !options.silent) status.textContent = state.dailyBriefing ? t("labels.dailyReady") : "No se pudo actualizar Diario.";
  }
}

function isDailyBriefingStale(briefing) {
  if (!briefing?.generatedAt) return true;
  if (briefing.schemaVersion !== "20260522-daily-media-specific-35") return true;
  const refreshMs = Number(briefing.refreshEveryHours || 6) * 60 * 60 * 1000;
  return Date.now() - new Date(briefing.generatedAt).getTime() >= refreshMs;
}

function setupDailyBriefingRefresh() {
  syncDailyLocationInputs(getDailyOperationalLocation());
  if (!state.dailyBriefing || isDailyBriefingStale(state.dailyBriefing)) {
    window.setTimeout(() => refreshDailyBriefing({ silent: true }), 1200);
  }
  window.setTimeout(() => refreshDashboardOperationalContext({ silent: true }), 1800);
  window.setInterval(() => {
    refreshDailyBriefing({ silent: true });
    refreshDashboardOperationalContext({ silent: true });
  }, 15 * 60 * 1000);
}

async function refreshDashboardOperationalContext(options = {}) {
  if (!state.session?.access_token || state.dashboardContextRefreshInProgress) return false;
  const lastRefresh = new Date(state.dashboardContextRefreshedAt || 0).getTime();
  const maxAgeMs = options.force ? 0 : 3 * 60 * 1000;
  if (lastRefresh && Date.now() - lastRefresh < maxAgeMs) return false;
  state.dashboardContextRefreshInProgress = true;
  try {
    await hydrateFromApi();
    await refreshMobileHealthSummary({ silent: true });
    if (!state.dailyBriefing || isDailyBriefingStale(state.dailyBriefing)) {
      await refreshDailyBriefing({ silent: true });
    }
    await refreshContextImpactAutomatically({ silent: true });
    state.dashboardContextRefreshedAt = new Date().toISOString();
    const activeView = document.querySelector(".view.active-view")?.id || "";
    if (activeView === "dashboardView") {
      renderDashboardBiometricContext();
      renderDashboardIntegrationHandoff();
      renderDailyBriefing();
      renderContextImpact();
      renderMetrics();
      renderRecentSignals();
    }
    return true;
  } catch (error) {
    markApiConnectivityFailure(error, { immediate: false });
    return false;
  } finally {
    state.dashboardContextRefreshInProgress = false;
  }
}

async function refreshMobileHealthSummary(options = {}) {
  if (!state.session?.access_token) return null;
  const end = new Date();
  const start = new Date(end.getTime() - 45 * 24 * 60 * 60 * 1000);
  try {
    const query = new URLSearchParams({
      locale: state.language,
      from: start.toISOString(),
      to: end.toISOString(),
    });
    state.mobileHealthSummary = await apiRequest(`/mobile/context/health-summary?${query.toString()}`, {
      preserveSessionOnAuthFailure: true,
    });
    return state.mobileHealthSummary;
  } catch (error) {
    if (!options.silent) notify(state.language !== "es" ? "Health context could not be refreshed." : "No se pudo actualizar el contexto de salud.", "warn");
    return null;
  }
}

function getDailyOperationalLocation() {
  return resolveOperationalContextLocation() || getDefaultOperationalLocation();
}

function resolveOperationalContextLocation(preferred = "") {
  const candidates = [
    preferred,
    ...getMobileContextLocationCandidates(),
    state.dailyLocationPreference,
    document.getElementById("dailyLocationInput")?.value?.trim(),
    document.getElementById("contextLocationInput")?.value?.trim(),
    state.dailyBriefing?.location,
    state.dailyBriefing?.scope,
    inferPrimaryLocation(),
  ];
  return candidates.map(normalizeContextLocationValue).find(isUsableContextLocation) || "";
}

function resolveOperationalContextLabel(location = "") {
  const candidates = [
    state.dailyLocationPreference,
    document.getElementById("dailyLocationInput")?.value?.trim(),
    document.getElementById("contextLocationInput")?.value?.trim(),
    state.dailyBriefing?.location,
    state.dailyBriefing?.scope,
    inferPrimaryHumanLocation(),
    getDefaultOperationalLocation(),
  ];
  const label = candidates
    .map(normalizeContextLocationValue)
    .find((candidate) => isUsableContextLocation(candidate) && !isCoordinateLocation(candidate));
  if (label && (!isCoordinateLocation(location) || !locationsEquivalent(label, location))) return label;
  return isCoordinateLocation(location) ? getDefaultOperationalLocation() : "";
}

function getMobileContextLocationCandidates() {
  return collectStructuredMobileContexts(state.experiences)
    .flatMap((item) => {
      const context = item.context || {};
      const location = context.location || context.place || context.geo || {};
      return [
        location.label,
        location.city,
        location.name,
        location.displayName,
        context.locationLabel,
        context.locationName,
        item.experience?.location,
      ];
    })
    .filter(Boolean);
}

function normalizeContextLocationValue(value = "") {
  return String(value || "").trim();
}

function isCoordinateLocation(value = "") {
  const text = normalizeContextLocationValue(value);
  const match = text.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/);
  if (!match) return false;
  const latitude = Number(match[1]);
  const longitude = Number(match[2]);
  return Number.isFinite(latitude) && Number.isFinite(longitude) && latitude >= -90 && latitude <= 90 && longitude >= -180 && longitude <= 180;
}

function isUsableContextLocation(value = "") {
  const text = normalizeContextLocationValue(value);
  if (text.length < 2) return false;
  const comparable = normalizeComparableText(text);
  if (!comparable || comparable === "sin ubicacion" || comparable === "no location") return false;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) return false;
  if (/^https?:\/\//i.test(text)) return false;
  if (/^(todos?|all|none|null|undefined|sin datos)$/i.test(comparable)) return false;
  return true;
}

function locationsEquivalent(a = "", b = "") {
  return Boolean(a && b && normalizeComparableText(a) === normalizeComparableText(b));
}

function syncDailyLocationInputs(location = "") {
  const value = String(location || "").trim();
  if (!value) return;
  const dailyInput = document.getElementById("dailyLocationInput");
  const contextInput = document.getElementById("contextLocationInput");
  if (dailyInput && dailyInput.value.trim() !== value) dailyInput.value = value;
  if (contextInput && contextInput.value.trim() !== value) contextInput.value = value;
}

function handleDailyLocationChange(event) {
  const value = event.target.value.trim();
  if (!value) return;
  const previous = state.dailyLocationPreference;
  saveDailyLocationPreference(value);
  syncDailyLocationInputs(value);
  const status = document.getElementById("dailyBriefingStatus");
  if (status) status.textContent = t("labels.dailyLocationSaved");
  if (!locationsEquivalent(previous, value)) {
    refreshDailyBriefing({ force: true, location: value });
    refreshContextImpactAutomatically({ force: true, preferredLocation: value, silent: true });
  }
}

function handleContextLocationChange(event) {
  const value = event.target.value.trim();
  if (!value) return;
  saveDailyLocationPreference(value);
  syncDailyLocationInputs(value);
  refreshContextImpactAutomatically({ force: true, preferredLocation: value, silent: true });
}

async function analyzeContextImpact() {
  return refreshContextImpactAutomatically({ force: true, silent: false, manual: true });
}

async function refreshContextImpactAutomatically(options = {}) {
  if (state.contextImpactRefreshInProgress) return false;
  const input = document.getElementById("contextLocationInput");
  const box = document.getElementById("contextImpactBox");
  const location = resolveOperationalContextLocation(options.preferredLocation || input?.value?.trim() || "");
  const contextLabel = resolveOperationalContextLabel(location);
  if (!location) {
    if (box && !options.silent) box.innerHTML = `<p class="card-meta">${t("labels.contextEmpty")}</p>`;
    updateContextStatus();
    return false;
  }
  const lastRefresh = new Date(state.contextImpactRefreshedAt || 0).getTime();
  const sameLocation = locationsEquivalent(location, state.contextImpactRefreshedFor);
  const currentReady = state.contextImpact
    && locationsEquivalent(location, state.contextImpact.location || state.contextImpact.queryLocation)
    && hasUsableEnvironmentalImpact(state.contextImpact);
  if (!options.force && sameLocation && currentReady && lastRefresh && Date.now() - lastRefresh < 45 * 60 * 1000) return false;
  if (box && (!options.silent || !state.contextImpact)) box.innerHTML = `<p class="card-meta">${t("labels.contextLoading")}</p>`;
  saveDailyLocationPreference(location);
  syncDailyLocationInputs(location);
  updateContextStatus("loading");
  state.contextImpactRefreshInProgress = true;
  try {
    const experienceType = getContextExperienceType();
    const labelParam = contextLabel ? `&label=${encodeURIComponent(contextLabel)}` : "";
    const impact = await apiRequest(`/context/impact?location=${encodeURIComponent(location)}&experienceType=${encodeURIComponent(experienceType)}${labelParam}`);
    state.contextImpact = { ...impact, queryLocation: location };
    state.contextImpactRefreshedAt = new Date().toISOString();
    state.contextImpactRefreshedFor = location;
    renderContextImpact();
    renderReport();
    return true;
  } catch (error) {
    updateContextStatus("error");
    if (box && (!options.silent || !state.contextImpact)) {
      box.innerHTML = `<p class="card-meta">${state.language !== "es" ? "Environmental/geopolitical impact could not be refreshed now. Vibe will retry automatically." : "No se pudo actualizar el impacto ambiental/geopolitico ahora. Vibe reintentara automaticamente."}</p>`;
    }
    return false;
  } finally {
    state.contextImpactRefreshInProgress = false;
  }
}

async function applyPrimaryContextLocation() {
  const input = document.getElementById("contextLocationInput");
  const location = resolveOperationalContextLocation(inferPrimaryLocation());
  input.value = location;
  saveDailyLocationPreference(location);
  syncDailyLocationInputs(location);
  updateContextStatus("primary", { location });
  await refreshContextImpactAutomatically({ force: true, preferredLocation: location, silent: false });
}

function getContextExperienceType() {
  if (state.profile?.experienceType && state.profile.experienceType !== "auto") {
    return state.profile.experienceType;
  }
  const top = getTopCategory();
  return experienceTypes.find((type) => type.categories.includes(top))?.id || "auto";
}

function renderContextImpact() {
  const impact = state.contextImpact;
  const box = document.getElementById("contextImpactBox");
  const input = document.getElementById("contextLocationInput");
  if (input && !isUsableContextLocation(input.value)) {
    input.value = getDailyOperationalLocation();
    syncDailyLocationInputs(input.value);
  }
  if (!impact) {
    updateContextStatus();
    box.innerHTML = `<p class="card-meta">${t("labels.contextEmpty")}</p>`;
    return;
  }
  updateContextStatus("ready", impact);
  const weather = impact.weather.current;
  const articles = impact.geopoliticalNews.articles || [];
  const weatherStatus = hasUsableEnvironmentalImpact(impact) ? t("labels.environmentalActive") : t("labels.environmentalUnavailable");
  const newsStatus = impact.geopoliticalNews.unavailable ? t("labels.geopoliticalUnavailable") : t("labels.geopoliticalActive");
  const profileImpact = impact.profileImpact;
  box.innerHTML = `
    <div class="impact-status-grid">
      <article class="impact-status-card">
        <span class="${hasUsableEnvironmentalImpact(impact) ? "status-ok" : "status-warn"}">${weatherStatus}</span>
        <p class="card-meta">Open-Meteo · ${impact.weather.current?.time ? escapeHtml(impact.weather.current.time) : "consulta bajo demanda"}</p>
      </article>
      <article class="impact-status-card">
        <span class="${impact.geopoliticalNews.unavailable ? "status-warn" : "status-ok"}">${newsStatus}</span>
        <p class="card-meta">${escapeHtml(impact.geopoliticalNews.source || "GDELT DOC 2.0")} · ${impact.geopoliticalNews.articleCount || 0} artículos analizados</p>
        ${renderContextSourceNote(impact.geopoliticalNews)}
      </article>
    </div>
    <div class="impact-grid">
      <div class="impact-score">
        <div>
          <span class="card-meta">Índice de impacto</span>
          <strong>${impact.impactScore}</strong>
          <span>${escapeHtml(impact.location)}, ${escapeHtml(impact.country || "")}</span>
        </div>
      </div>
      <div class="signal-card">
        <strong>Impacto ambiental / climático</strong>
        <div class="pill-row">
          <span class="pill">${weather.temperatureC ?? "-"} °C</span>
          <span class="pill">${weather.humidityPct ?? "-"}% humedad</span>
          <span class="pill">${weather.windKmh ?? "-"} km/h viento</span>
          <span class="pill">${weather.precipitationMm ?? "0"} mm lluvia</span>
        </div>
        <p>${impact.weather.riskSignals.length ? impact.weather.riskSignals.join(", ") : "Sin señales climáticas críticas."}</p>
      </div>
      <div class="signal-card">
        <strong>Impacto geopolítico</strong>
        <p>${impact.geopoliticalNews.articleCount} artículos recientes vinculados al lugar.</p>
        <p>${impact.geopoliticalNews.unavailable ? t("labels.contextNoArticles") : impact.geopoliticalNews.riskSignals.length ? `Señales: ${impact.geopoliticalNews.riskSignals.join(", ")}` : "Sin señales geopolíticas fuertes en titulares."}</p>
      </div>
    </div>
    ${renderContextNewsDigest(impact.geopoliticalNews)}
    <div class="signal-card">
        <strong>${escapeHtml(impact.summary)}</strong>
        ${profileImpact ? renderProfileImpact(profileImpact) : ""}
    </div>
  `;
}

function renderContextNewsDigest(news) {
  const articles = news?.articles || [];
  if (!articles.length) {
    return `
      <section class="context-news-digest is-empty">
        <div class="context-news-heading">
          <div>
            <span class="card-meta">${t("labels.contextNewsTitle")}</span>
            <h3>Sin cobertura reciente suficiente</h3>
          </div>
          <span class="pill">${escapeHtml(news?.source || "GDELT DOC 2.0")}</span>
        </div>
        <p>${t("labels.contextNoArticles")}</p>
        ${renderContextSourceNote(news)}
      </section>
    `;
  }
  const lead = articles[0];
  const secondary = articles.slice(1, 5);
  const sourceLabel = news.fallbackReason ? `${t("labels.contextFallbackSource")}: ${news.source}` : news.source;
  return `
    <section class="context-news-digest">
      <div class="context-news-heading">
        <div>
          <span class="card-meta">${t("labels.contextNewsTitle")}</span>
          <h3>${escapeHtml(news.riskSignals?.length ? `Señales detectadas: ${news.riskSignals.join(", ")}` : "Cobertura reciente sin alertas fuertes")}</h3>
        </div>
        <span class="pill">${escapeHtml(sourceLabel || "GDELT DOC 2.0")}</span>
      </div>
      <article class="context-lead-news">
        <div>
          <span class="card-meta">${t("labels.contextLeadStory")} · ${escapeHtml(lead.domain || lead.source || "")}${lead.seenAt ? ` · ${escapeHtml(formatDate(lead.seenAt))}` : ""}</span>
          <h4>${escapeHtml(lead.title || "Artículo")}</h4>
          <p>${escapeHtml(buildContextArticleTakeaway(lead, news))}</p>
        </div>
        ${lead.url ? `<a class="primary-button" href="${escapeHtml(lead.url)}" target="_blank" rel="noreferrer">${t("labels.contextOpenStory")}</a>` : ""}
      </article>
      ${
        secondary.length
           ? `<div class="context-news-secondary">
              <span class="card-meta">${t("labels.contextMoreSignals")}</span>
              ${secondary.map(renderContextNewsCard).join("")}
            </div>`
          : ""
      }
      ${renderContextSourceNote(news)}
    </section>
  `;
}

function renderContextNewsCard(article) {
  return `
    <a class="context-news-card" href="${escapeHtml(article.url || "#")}" target="_blank" rel="noreferrer">
      <span>${escapeHtml(article.domain || article.source || "Fuente")}${article.seenAt ? ` · ${escapeHtml(formatDate(article.seenAt))}` : ""}</span>
      <strong>${escapeHtml(article.title || "Artículo")}</strong>
    </a>
  `;
}

function buildContextArticleTakeaway(article, news) {
  const domain = article.domain || article.source || "la fuente consultada";
  if (news?.fallbackReason) {
    return state.language !== "es"
       ? `This item is shown from a fallback source because the primary geopolitical feed did not return enough coverage. Use it as a context signal, not as a final assessment.`
      : `Esta noticia se muestra desde una fuente de respaldo porque la fuente geopolítica primaria no entregó cobertura suficiente. Úsala como señal de contexto, no como conclusión final.`;
  }
  return state.language !== "es"
     ? `Reported by ${domain}. It helps explain what public, political, security, or economic topics may affect the experience context.`
    : `Reportado por ${domain}. Ayuda a entender qué temas públicos, políticos, de seguridad o económicos pueden influir en el contexto de la experiencia.`;
}

function renderContextSourceNote(news) {
  if (!news) return "";
  if (news.fallbackReason && !news.unavailable) {
    return `<p class="card-meta">${t("labels.contextFallbackSource")}: ${escapeHtml(news.source || "Google News RSS")}</p>`;
  }
  if (news.unavailable && news.error) {
    return `<p class="card-meta">${t("labels.contextUnavailableReason")}: ${escapeHtml(news.error)}</p>`;
  }
  return "";
}

function renderProfileImpact(profileImpact) {
  const weights = profileImpact.weights || {};
  return `
    <div class="profile-impact-grid">
      <article>
        <span class="card-meta">Perfil aplicado</span>
        <strong>${escapeHtml(profileImpact.matchedActivity || "Sin actividad equivalente")}</strong>
        <p>${escapeHtml(profileImpact.profileSegment || "perfil_neutro")}</p>
      </article>
      <article>
        <span class="card-meta">Ajuste al score</span>
        <strong>${profileImpact.scoreAdjustment >= 0 ? "+" : ""}${profileImpact.scoreAdjustment || 0}</strong>
        <p>Biométrico ${weights.biometric || 0} · Geopolítico ${weights.geopolitical || 0} · Climático ${weights.climate || 0}</p>
      </article>
    </div>
    <p>${escapeHtml(profileImpact.summary || "")}</p>
    ${
      profileImpact.recommendations?.length
        ? `<div class="pill-row">${profileImpact.recommendations.map((item) => `<span class="pill">${escapeHtml(item)}</span>`).join("")}</div>`
        : ""
    }
  `;
}

function updateContextStatus(status = "idle", impact = null) {
  const statusEl = document.getElementById("contextStatus");
  if (!statusEl) return;
  if (status === "loading") {
    statusEl.textContent = t("labels.contextLoading");
    return;
  }
  if (status === "error") {
    statusEl.textContent = "Impacto no disponible en este momento";
    return;
  }
  if (status === "primary" && impact?.location) {
    statusEl.textContent = `${t("labels.contextPrimaryApplied")}: ${impact.location}`;
    return;
  }
  if (status === "ready" && impact) {
    const environmental = hasUsableEnvironmentalImpact(impact) ? t("labels.environmentalActive") : t("labels.environmentalUnavailable");
    const geopolitical = impact.geopoliticalNews?.unavailable ? t("labels.geopoliticalUnavailable") : t("labels.geopoliticalActive");
    statusEl.textContent = `${environmental} · ${geopolitical}`;
    return;
  }
  statusEl.textContent = t("labels.contextReady");
}

function hasUsableEnvironmentalImpact(impact = {}) {
  const weather = impact.weather || {};
  const current = weather.current || {};
  const values = [
    current.temperatureC,
    current.humidityPct,
    current.precipitationMm,
    current.windKmh,
  ];
  return values.some((value) => Number.isFinite(Number(value))) || (Array.isArray(weather.forecast) && weather.forecast.length > 0);
}

function inferPrimaryLocation() {
  const counts = state.experiences.reduce((acc, item) => {
    if (item.location && item.location !== "Sin ubicación") acc[item.location] = (acc[item.location] || 0) + 1;
    return acc;
  }, {});
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "";
}

function inferPrimaryHumanLocation() {
  const counts = state.experiences.reduce((acc, item) => {
    const value = normalizeContextLocationValue(item.location || "");
    if (isUsableContextLocation(value) && !isCoordinateLocation(value)) acc[value] = (acc[value] || 0) + 1;
    return acc;
  }, {});
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "";
}

function getDefaultOperationalLocation() {
  return "Winter Garden, Florida";
}

function renderLibrary() {
  const items = getFilteredLibraryExperiences();
  const filtersActive = areLibraryFiltersActive();
  const lastSaved = state.lastSavedExperienceId ? state.experiences.find((item) => item.id === state.lastSavedExperienceId) : null;
  document.getElementById("libraryCount").textContent = `${items.length} ${t("labels.items")}`;
  const notice = buildLibraryVisibilityNotice(items, filtersActive, lastSaved);
  document.getElementById("libraryGrid").innerHTML =
    notice +
    (items.length === 0
      ? `<p class="card-meta">${escapeHtml(t("labels.noLibrary"))}</p>`
      : items
          .map(
            (item) => `
              <article class="library-card ${item.id === state.lastSavedExperienceId ? "is-last-saved" : ""}">
                ${renderPrimaryMedia(item)}
                <div>
                  <p class="card-meta">${formatDate(item.timestamp)}</p>
                  <h3>${escapeHtml(item.title)}</h3>
                  <div class="pill-row">
                    <span class="pill">${displayCategory(item.category)}</span>
                    <span class="pill">${escapeHtml(getExperienceSourceLabel(item))}</span>
                    ${getExperiencePilotParticipantLabel(item) ? `<span class="pill">${escapeHtml(state.language !== "es" ? "Pilot" : "Piloto")}: ${escapeHtml(getExperiencePilotParticipantLabel(item))}</span>` : ""}
                    ${item.objective ? `<span class="pill">${escapeHtml(item.objective)}</span>` : ""}
                    <span class="pill">${normalizeExperienceEvents(item.events || [], item.id).length} ${state.language !== "es" ? "events" : "eventos"}</span>
                    <span class="pill">${item.attachments?.length || 0} ${t("labels.attachments")}</span>
                    <span class="pill">${escapeHtml(item.mood)}</span>
                  </div>
                  <p>${escapeHtml(item.notes || (state.language !== "es" ? "No notes." : "Sin notas."))}</p>
                  ${renderLibraryEventPreview(item)}
                </div>
                <div class="timeline-actions">
                  <button class="ghost-button" type="button" onclick="editExperience('${item.id}')">${t("buttons.edit")}</button>
                  <button class="ghost-button" type="button" onclick="showExperienceInTimeline('${item.id}')">${t("buttons.viewTimeline")}</button>
                  <button class="ghost-button" type="button" onclick="toggleExperienceCuration('${item.id}')">${state.language === "es" ? "Organizar" : state.language === "fr" ? "Organiser" : state.language === "pt" ? "Organizar" : "Organize"}</button>
                  <button class="danger-button" type="button" onclick="deleteExperience('${item.id}')">${t("buttons.delete")}</button>
                </div>
                ${renderStoryCurationPanel(item)}
              </article>
            `,
          )
          .join(""));
}

function areLibraryFiltersActive() {
  return Boolean(
    state.libraryFilters.query ||
      state.libraryFilters.category !== "all" ||
      state.libraryFilters.media !== "all" ||
      state.libraryFilters.source !== "all" ||
      state.libraryFilters.pilotParticipantId !== "all",
  );
}

function buildLibraryVisibilityNotice(items, filtersActive, lastSaved) {
  const savedVisible = lastSaved && items.some((item) => item.id === lastSaved.id);
  if (lastSaved && savedVisible) {
    const labels = state.language !== "es"
       ? { title: "Last saved experience is visible", detail: "This is the record you just saved from Capture." }
      : { title: "La última experiencia guardada está visible", detail: "Este es el registro que acabas de guardar desde Captura." };
    return `
      <article class="library-notice is-success">
        <strong>${escapeHtml(labels.title)}</strong>
        <p>${escapeHtml(labels.detail)}</p>
      </article>
    `;
  }
  if (lastSaved && filtersActive) {
    const labels = state.language !== "es"
       ? { title: "Saved, but hidden by filters", detail: "The experience exists, but the current Library filters are hiding it.", action: "Show all experiences" }
      : { title: "Guardada, pero oculta por filtros", detail: "La experiencia existe, pero los filtros actuales de Librería la están ocultando.", action: "Ver todas las experiencias" };
    return `
      <article class="library-notice is-warn">
        <div>
          <strong>${escapeHtml(labels.title)}</strong>
          <p>${escapeHtml(labels.detail)}</p>
        </div>
        <button class="ghost-button" type="button" onclick="clearLibraryFiltersAndRender()">${escapeHtml(labels.action)}</button>
      </article>
    `;
  }
  if (!items.length && state.experiences.length && filtersActive) {
    const labels = state.language !== "es"
       ? { title: "No results with active filters", detail: "There are saved experiences, but none match the current filters.", action: "Clear filters" }
      : { title: "Sin resultados con filtros activos", detail: "Hay experiencias guardadas, pero ninguna coincide con los filtros actuales.", action: "Limpiar filtros" };
    return `
      <article class="library-notice is-warn">
        <div>
          <strong>${escapeHtml(labels.title)}</strong>
          <p>${escapeHtml(labels.detail)}</p>
        </div>
        <button class="ghost-button" type="button" onclick="clearLibraryFiltersAndRender()">${escapeHtml(labels.action)}</button>
      </article>
    `;
  }
  return "";
}

function clearLibraryFiltersAndRender() {
  resetLibraryFilters();
  updateLibraryFilterOptions();
  renderLibrary();
}

function renderLibraryEventPreview(item) {
  const events = getExperienceEventTimeline(item);
  if (!events.length) return "";
  const visibleEvents = events.slice(0, 3);
  const remaining = events.length - visibleEvents.length;
  return `
    <div class="library-event-preview" aria-label="${escapeHtml(state.language !== "es" ? "Experience events" : "Eventos de la experiencia")}">
      ${visibleEvents
        .map(
          (event) => `
            <div class="library-event-item">
              <span>${escapeHtml(String(event.order).padStart(2, "0"))}</span>
              <div>
                <strong>${escapeHtml(event.title || (state.language !== "es" ? "Untitled event" : "Evento sin título"))}</strong>
                ${event.description ? `<small>${escapeHtml(event.description)}</small>` : ""}
              </div>
            </div>
          `,
        )
        .join("")}
      ${remaining > 0 ? `<small class="card-meta">${escapeHtml(state.language !== "es" ? `+${remaining} more event(s)` : `+${remaining} evento(s) más`)}</small>` : ""}
    </div>
  `;
}

function renderPrimaryMedia(item) {
  const media = item.attachments?.[0];
  if (!media) {
    return `<div class="media-frame">${t("labels.noMedia")}</div>`;
  }
  const markup = renderAttachmentMedia(media, { primary: true });
  if (!markup) {
    return `<div class="media-frame">${t("labels.noMedia")}</div>`;
  }
  return `<div class="media-frame">${markup}</div>`;
}

function getExperienceSourceLabel(item) {
  if (item?.source === "daily-briefing") return t("labels.experienceSourceDaily");
  if (item?.source === "agenda") return t("labels.experienceSourceAgenda");
  if (item?.source === "insight") return t("labels.experienceSourceInsight");
  if (item?.source === "predictive-outlook") return t("labels.experienceSourcePredictive");
  return t("labels.experienceSourceManual");
}

function getExperienceSourceKey(item) {
  if (item?.source === "daily-briefing") return "daily-briefing";
  if (item?.source === "agenda") return "agenda";
  if (item?.source === "insight") return "insight";
  if (item?.source === "predictive-outlook") return "predictive-outlook";
  return "manual";
}

function updateLibraryFilterOptions() {
  const search = document.getElementById("librarySearchInput");
  if (search) search.placeholder = t("labels.librarySearchPlaceholder");
  const mediaSelect = document.getElementById("libraryMediaFilter");
  if (mediaSelect) {
    const current = state.libraryFilters.media || mediaSelect.value || "all";
    mediaSelect.innerHTML = [
      ["all", t("labels.libraryContentAll")],
      ["with-media", t("labels.libraryWithMedia")],
      ["without-media", t("labels.libraryWithoutMedia")],
    ]
      .map(([value, label]) => `<option value="${value}">${escapeHtml(label)}</option>`)
      .join("");
    mediaSelect.value = current;
  }
  const sourceSelect = document.getElementById("librarySourceFilter");
  if (sourceSelect) {
    const current = state.libraryFilters.source || sourceSelect.value || "all";
    sourceSelect.innerHTML = [
      ["all", t("labels.librarySourceAll")],
      ["manual", t("labels.experienceSourceManual")],
      ["daily-briefing", t("labels.experienceSourceDaily")],
      ["agenda", t("labels.experienceSourceAgenda")],
      ["insight", t("labels.experienceSourceInsight")],
      ["predictive-outlook", t("labels.experienceSourcePredictive")],
    ]
      .map(([value, label]) => `<option value="${value}">${escapeHtml(label)}</option>`)
      .join("");
    sourceSelect.value = current;
  }
  const participantSelect = document.getElementById("libraryPilotParticipantFilter");
  if (participantSelect) {
    const current = state.libraryFilters.pilotParticipantId || participantSelect.value || "all";
    const allLabel = state.language !== "es" ? "All groups/people" : "Todos los grupos/personas";
    const options = state.pilotParticipants
      .map((item) => ({ value: item.id, label: item.name || item.role || item.id }))
      .filter((item) => item.value && item.label);
    participantSelect.innerHTML = [`<option value="all">${escapeHtml(allLabel)}</option>`, ...options.map((item) => `<option value="${escapeHtml(item.value)}">${escapeHtml(item.label)}</option>`)].join("");
    participantSelect.value = options.some((item) => item.value === current) ? current : "all";
    state.libraryFilters.pilotParticipantId = participantSelect.value;
  }
}

function renderMediaStrip(item) {
  const media = item.attachments || [];
  if (!media.length) return "";
  return `
    <div class="media-strip">
      ${media.map((attachment) => renderAttachmentMedia(attachment)).join("")}
    </div>
  `;
}

function renderAttachmentMedia(attachment, options = {}) {
  const kind = inferMediaKind(attachment);
  const source = attachment.url || attachment.dataUrl;
  const extension = attachment.extension || getFileExtension(attachment.name);
  if (kind === "document") {
    if (isArchiveAsset(attachment)) return renderArchiveMediaCard(attachment, source, options);
    if (!source && !attachment.previewText) return renderAttachmentNeedsSync(attachment, kind);
    const text = attachment.previewText || decodeTextDataUrl(source);
    const isPdf = isPdfAsset(attachment);
    return `
      <div class="media-document-card ${options.primary ? "is-primary" : ""}">
        <strong>${escapeHtml((extension || "doc").toUpperCase())}</strong>
        <span>${escapeHtml(attachment.name || getAssetKindLabel(kind))}</span>
        ${isPdf && source ? `<iframe src="${escapeHtml(source)}" title="${escapeHtml(attachment.name || "PDF")}" loading="lazy"></iframe>` : ""}
        ${text ? `<pre>${escapeHtml(text.slice(0, options.primary ? 320 : 140))}</pre>` : `<small>${escapeHtml(t("labels.attachmentPreviewUnsupported"))}</small>`}
        ${source ? `<a href="${escapeHtml(source)}" download="${escapeHtml(attachment.name || "document")}" target="_blank" rel="noreferrer">${escapeHtml(t("labels.assetDownloadFile"))}</a>` : ""}
      </div>
    `;
  }
  if (!source) return renderAttachmentNeedsSync(attachment, kind);
  const safeSource = escapeHtml(source);
  const syncAttrs = attachment.path || attachment.storage === "supabase" ? ` data-media-path="${escapeHtml(attachment.path || "")}" data-media-name="${escapeHtml(attachment.name || "")}"` : "";
  if (kind === "video") return `<video src="${safeSource}" controls muted playsinline preload="metadata"${syncAttrs}></video>`;
  if (kind === "audio") return `<audio src="${safeSource}" controls preload="metadata"${syncAttrs}></audio>`;
  if (kind === "image") return `<img src="${safeSource}" alt="${escapeHtml(attachment.name || "")}" loading="lazy"${syncAttrs} />`;
  return "";
}

function isArchiveAsset(asset = {}) {
  const extension = asset.extension || getFileExtension(asset.name || asset.url || "");
  return asset.kind === "document" && ARCHIVE_EXTENSIONS.has(extension);
}

function isPdfAsset(asset = {}) {
  const extension = asset.extension || getFileExtension(asset.name || asset.url || "");
  const type = String(asset.type || asset.originalType || "").toLowerCase();
  return extension === "pdf" || type.includes("pdf");
}

function renderArchiveMediaCard(attachment, source = "", options = {}) {
  return `
    <div class="media-document-card media-archive-card ${options.primary ? "is-primary" : ""}">
      <strong>${escapeHtml((attachment.extension || getFileExtension(attachment.name) || "zip").toUpperCase())}</strong>
      <span>${escapeHtml(attachment.name || t("labels.assetArchiveOnly"))}</span>
      <small>${escapeHtml(t("labels.assetArchiveOnlyDetail"))}</small>
      ${source ? `<a href="${escapeHtml(source)}" download="${escapeHtml(attachment.name || "archive")}" target="_blank" rel="noreferrer">${escapeHtml(t("labels.assetDownloadFile"))}</a>` : ""}
    </div>
  `;
}

function renderAttachmentNeedsSync(attachment, kind = "document") {
  return `
    <div class="attachment-preview-fallback media-sync-missing">
      <strong>${escapeHtml(attachment.name || getAssetKindLabel(kind))}</strong>
      <span>${escapeHtml(t("labels.attachmentNeedsSync"))}</span>
      <small>${escapeHtml(t("labels.attachmentNeedsSyncDetail"))}</small>
    </div>
  `;
}

function collectMultimodalAssets() {
  const experienceAssets = state.experiences.flatMap((experience) =>
    (experience.attachments || []).map((attachment) => {
      const kind = getAssetKind(attachment);
      const assetKey = getAssetMetadataKey({ ...attachment, experienceId: experience.id });
      const manual = state.assetMetadata[assetKey] || {};
      const manualTags = Array.isArray(manual.tags) ? manual.tags : Array.isArray(attachment.manualTags) ? attachment.manualTags : [];
      const manualNote = Object.hasOwn(manual, "note") ? manual.note : attachment.manualNote || "";
      const analysisText = Object.hasOwn(manual, "analysisText") ? manual.analysisText : attachment.analysisText || "";
      const extractedText = Object.hasOwn(manual, "extractedText") ? manual.extractedText : attachment.extractedText || "";
      const detectedLanguage = Object.hasOwn(manual, "detectedLanguage") ? manual.detectedLanguage : attachment.detectedLanguage || attachment.language || "";
      const translatedText = Object.hasOwn(manual, "translatedText") ? manual.translatedText : attachment.translatedText || "";
      const translationLanguage = Object.hasOwn(manual, "translationLanguage") ? manual.translationLanguage : attachment.translationLanguage || "";
      const extractionMethod = Object.hasOwn(manual, "extractionMethod") ? manual.extractionMethod : attachment.extractionMethod || "";
      const extractionStatus = Object.hasOwn(manual, "extractionStatus") ? manual.extractionStatus : attachment.extractionStatus || "";
      const signalMetadata = attachment.metadata || {};
      const sourceDevice = attachment.sourceDevice || signalMetadata.sourceDevice || attachment.device || attachment.source || "";
      const sourceType = attachment.sourceType || signalMetadata.sourceType || signalMetadata.source || attachment.source || "";
      const linkedEventId = attachment.eventId || signalMetadata.linkedEventId || "";
      const linkedEventTitle = attachment.eventTitle || signalMetadata.linkedEventTitle || "";
      const externalProfile = getExternalAssetProfile({ ...attachment, metadata: signalMetadata });
      return {
        ...attachment,
        kind,
        assetKey,
        experienceId: experience.id,
        experienceTitle: experience.title,
        isDemo: Boolean(attachment.demo || experience.isDemo),
        category: experience.category,
        objective: experience.objective || "",
        eventId: linkedEventId,
        eventTitle: linkedEventTitle,
        timestamp: experience.timestamp,
        location: experience.location || "",
        people: experience.people || "",
        notes: experience.notes || "",
        language: detectedLanguage || attachment.language || state.language,
        detectedLanguage,
        translatedText,
        translationLanguage,
        device: sourceDevice || (attachment.storage === "supabase" ? "Supabase Storage" : "Navegador local"),
        sourceType,
        externalSource: externalProfile.source,
        externalPayloadType: externalProfile.payloadType,
        externalProcessingIntent: externalProfile.intent,
        externalCaptureOrigin: externalProfile.captureOrigin,
        externalTreatment: externalProfile.treatment,
        externalPrivacyHint: externalProfile.privacy,
        externalExpectedConsumer: externalProfile.consumer,
        externalTransportOnly: externalProfile.transportOnly,
        externalAutoInterpret: externalProfile.autoInterpret,
        externalProfileLabel: externalProfile.label,
        capturedAt: attachment.capturedAt || signalMetadata.capturedAt || attachment.createdAt || experience.timestamp || "",
        uploadedAt: attachment.uploadedAt || signalMetadata.uploadedAt || "",
        processingStatusRaw: attachment.processingStatus || signalMetadata.processingStatus || "",
        permissions: attachment.permissions || signalMetadata.permissions || "",
        metadataFingerprint: attachment.metadataFingerprint || signalMetadata.metadataFingerprint || "",
        storageLabel: attachment.url ? "Servidor/Supabase" : "Local",
        manualTags,
        manualNote,
        analysisText,
        extractedText,
        extractionMethod,
        extractionStatus,
        processedAt: manual.processedAt || attachment.processedAt || "",
        analysisSuggested: Boolean(manual.suggested),
      };
    }),
  );
  const experienceAssetKeys = new Set(experienceAssets.map((asset) => asset.assetKey || asset.id).filter(Boolean));
  const standaloneServerAssets = normalizeServerAssets(state.serverAssets)
    .filter((asset) => !asset.experienceId && !experienceAssetKeys.has(asset.assetKey || asset.id))
    .map((asset) => {
      const externalProfile = getExternalAssetProfile(asset);
      return {
        ...asset,
        assetKey: asset.assetKey || asset.id,
        experienceTitle: languageText("Bandeja de evidencia", "Evidence inbox", "Boite de preuves", "Bandeja de evidencias"),
        isDemo: false,
        category: "",
        objective: languageText("Evidencia pendiente de adoptar", "Evidence waiting for adoption", "Preuve en attente d'adoption", "Evidencia aguardando adocao"),
        timestamp: asset.capturedAt || asset.uploadedAt || new Date().toISOString(),
        location: asset.metadata?.location || "",
        people: "",
        notes: asset.previewText || asset.analysisText || "",
        language: asset.detectedLanguage || state.language,
        device: asset.sourceDevice || languageText("Servidor/Supabase", "Server/Supabase", "Serveur/Supabase", "Servidor/Supabase"),
        externalSource: externalProfile.source,
        externalPayloadType: externalProfile.payloadType,
        externalProcessingIntent: externalProfile.intent,
        externalCaptureOrigin: externalProfile.captureOrigin,
        externalTreatment: externalProfile.treatment,
        externalPrivacyHint: externalProfile.privacy,
        externalExpectedConsumer: externalProfile.consumer,
        externalTransportOnly: externalProfile.transportOnly,
        externalAutoInterpret: externalProfile.autoInterpret,
        externalProfileLabel: externalProfile.label,
        storageLabel: asset.path || asset.url ? "Servidor/Supabase" : "Local",
        manualTags: [],
        manualNote: "",
        extractedText: asset.extractedText || asset.previewText || "",
        extractionMethod: asset.extractionMethod || "",
        extractionStatus: asset.extractionStatus || asset.processingStatus || "",
        processedAt: asset.processedAt || "",
        analysisSuggested: false,
        inboxEvidence: true,
      };
    });
  const biometricAssets = (state.biometricImports || []).map((item) => toBiometricAsset(item));
  return [...biometricAssets, ...standaloneServerAssets, ...experienceAssets];
}

function toBiometricAsset(item = {}) {
  const manual = state.assetMetadata[item.id] || {};
  const externalProfile = getExternalAssetProfile(item);
  const metricNames = Array.isArray(item.metricNames) ? item.metricNames : [];
  const analysisText = Object.hasOwn(manual, "analysisText") ? manual.analysisText : item.analysisText || "";
  const extractedText = Object.hasOwn(manual, "extractedText") ? manual.extractedText : item.extractedText || "";
  const detectedLanguage = Object.hasOwn(manual, "detectedLanguage") ? manual.detectedLanguage : item.detectedLanguage || "data";
  const translatedText = Object.hasOwn(manual, "translatedText") ? manual.translatedText : item.translatedText || "";
  return {
    id: item.id,
    assetKey: item.id,
    name: item.name || "biometrics.csv",
    type: item.type || "text/csv",
    originalType: item.type || "text/csv",
    size: Number(item.size || 0),
    kind: "document",
    experienceId: "",
    experienceTitle: t("labels.biometricAssetExperienceTitle"),
    contextOnly: true,
    isDemo: false,
    category: "Salud",
    objective: state.language !== "es" ? "Biometric context" : "Contexto biometrico",
    eventId: "",
    eventTitle: "",
    timestamp: item.startAt || item.importedAt || new Date().toISOString(),
    location: "",
    people: "",
    notes: item.summaryText || "",
    language: detectedLanguage,
    detectedLanguage,
    translatedText,
    translationLanguage: manual.translationLanguage || item.translationLanguage || "",
    device: item.sourceDevice || "Apple Health export",
    sourceType: "biometric_file_import",
    externalSource: externalProfile.source,
    externalPayloadType: externalProfile.payloadType,
    externalProcessingIntent: externalProfile.intent,
    externalCaptureOrigin: externalProfile.captureOrigin,
    externalTreatment: externalProfile.treatment,
    externalPrivacyHint: externalProfile.privacy,
    externalExpectedConsumer: externalProfile.consumer,
    externalTransportOnly: externalProfile.transportOnly,
    externalAutoInterpret: externalProfile.autoInterpret,
    externalProfileLabel: externalProfile.label,
    capturedAt: item.startAt || item.importedAt || "",
    uploadedAt: item.importedAt || "",
    processingStatusRaw: "processed",
    permissions: "private",
    metadataFingerprint: item.fingerprint || item.id,
    storageLabel: state.language !== "es" ? "Local biometric file" : "Archivo biometrico local",
    manualTags: Array.isArray(manual.tags) ? manual.tags : ["biometria", ...metricNames.slice(0, 3)],
    manualNote: Object.hasOwn(manual, "note") ? manual.note : item.summaryText || "",
    analysisText,
    extractedText,
    extractionMethod: manual.extractionMethod || item.extractionMethod || "biometric_file_import",
    extractionStatus: manual.extractionStatus || item.extractionStatus || "automatic",
    processedAt: manual.processedAt || item.importedAt || "",
    analysisSuggested: Boolean(manual.suggested),
    previewText: item.previewText || item.summaryText || "",
    metadata: item.metadata || {},
  };
}

function hydrateBiometricImportsFromExperiences(experiences = state.experiences) {
  const existingIds = new Set((state.biometricImports || []).map((item) => item.id));
  const imported = [];
  (experiences || []).forEach((experience) => {
    const structuredContext = experience.metadata?.structuredContext || {};
    const structuredSignals = Array.isArray(structuredContext.signals) ? structuredContext.signals : [];
    const metricSignals = structuredSignals.length
       structuredSignals
      : Object.entries(structuredContext.metrics || {}).map(([type, value]) => ({
          type,
          value,
          date: structuredContext.capturedAt || experience.metadata?.capturedAt || experience.timestamp,
          source: structuredContext.connector || experience.sourceType || "Vibeapp",
        }));
    if (metricSignals.length) {
      const id = structuredContext.id || `structured-biometric-${simpleHash(`${experience.id}:${structuredContext.connector || "context"}`)}`;
      if (!existingIds.has(id)) {
        const rows = metricSignals.map(normalizeBiometricRow).filter((row) => row.date || row.type || row.value);
        const metricNames = detectBiometricMetricNames(rows);
        const dates = rows
          .map((row) => row.date)
          .filter(Boolean)
          .map((value) => new Date(value))
          .filter((date) => !Number.isNaN(date.getTime()))
          .sort((a, b) => a - b);
        const startAt = dates[0]?.toISOString() || experience.timestamp || "";
        const endAt = dates[dates.length - 1]?.toISOString() || experience.timestamp || "";
        const sourceDevice = detectBiometricSource(rows) || structuredContext.connector || "Health Connect";
        const metricText = metricNames.length ? metricNames.join(", ") : t("labels.biometricAssetNoMetrics");
        imported.push({
          id,
          name: structuredContext.connector === "android-health-connect" ? "health-connect-context.json" : "biometric-context.json",
          type: "application/json",
          size: JSON.stringify(structuredContext).length,
          sourceDevice,
          importedAt: experience.timestamp || new Date().toISOString(),
          startAt,
          endAt,
          recordCount: rows.length,
          metricNames,
          summaryText: state.language !== "es"
             ? `Native biometric context from ${sourceDevice}. ${rows.length} records. Signals: ${metricText}.`
            : `Contexto biométrico nativo desde ${sourceDevice}. ${rows.length} registros. Señales: ${metricText}.`,
          analysisText: state.language !== "es"
             ? `Native biometric context linked to ${experience.title || "experience"}. It informs energy, recovery, sleep, activity, and risk by date/time.`
            : `Contexto biométrico nativo vinculado a ${experience.title || "la experiencia"}. Informa energía, recuperación, sueño, actividad y riesgo por fecha/hora.`,
          extractedText: JSON.stringify(structuredContext, null, 2),
          previewText: structuredContext.summary || "",
          extractionMethod: "vibeapp-health-connect-structured-context",
          extractionStatus: "automatic",
          fingerprint: simpleHash(JSON.stringify(structuredContext)),
          metadata: {
            ...structuredContext,
            sourceType: "biometric_structured_context",
            linkedExperienceId: experience.id || "",
          },
          rows,
        });
        existingIds.add(id);
      }
    }
    const candidates = [
      ...(Array.isArray(experience.attachments) ? experience.attachments : []),
      ...(Array.isArray(experience.media) ? experience.media : []),
    ];
    candidates.forEach((asset) => {
      const metadata = asset.metadata || {};
      const biometric = metadata.biometricImport || experience.metadata?.biometricImport;
      const sourceType = String(asset.sourceType || metadata.sourceType || experience.metadata?.sourceType || "").toLowerCase();
      const isBiometric = Boolean(biometric) || sourceType.includes("biometric");
      if (!isBiometric) return;
      const id = asset.id || biometric?.id || `biometric-${simpleHash(`${experience.id}:${asset.name || ""}`)}`;
      if (existingIds.has(id)) return;
      const rawText = metadata.extractedText || asset.extractedText || asset.previewText || "";
      let parsed = null;
      if (rawText) {
        try {
          parsed = parseBiometricFile(rawText, { name: asset.name || biometric?.name || "biometrics.csv", type: asset.type || biometric?.type || "text/csv" });
        } catch {
          parsed = null;
        }
      }
      imported.push({
        id,
        name: asset.name || biometric?.name || "biometrics.csv",
        type: asset.type || biometric?.type || "text/csv",
        size: Number(asset.size || biometric?.size || 0),
        sourceDevice: biometric?.sourceDevice || metadata.sourceDevice || asset.sourceDevice || "Vibeapp biometric file",
        importedAt: biometric?.importedAt || asset.uploadedAt || experience.timestamp || new Date().toISOString(),
        startAt: biometric?.startAt || parsed?.startAt || experience.timestamp || "",
        endAt: biometric?.endAt || parsed?.endAt || experience.timestamp || "",
        recordCount: Number(biometric?.recordCount || parsed?.recordCount || 0),
        metricNames: Array.isArray(biometric?.metricNames) ? biometric.metricNames : parsed?.metricNames || [],
        summaryText: biometric?.summaryText || parsed?.summaryText || asset.previewText || experience.notes || "",
        analysisText: biometric?.analysisText || parsed?.analysisText || asset.analysisText || "",
        extractedText: rawText,
        previewText: asset.previewText || biometric?.summaryText || "",
        extractionMethod: metadata.extractionMethod || asset.extractionMethod || "vibeapp-biometric-file-import",
        extractionStatus: metadata.extractionStatus || asset.extractionStatus || "automatic",
        fingerprint: metadata.metadataFingerprint || asset.metadataFingerprint || simpleHash(rawText || id),
        metadata: {
          ...metadata,
          sourceType: "biometric_file_import",
          source: metadata.source || "vibeapp",
          linkedExperienceId: experience.id || "",
          fileName: asset.name || "",
        },
        rows: parsed?.rows?.slice(0, 20000) || [],
      });
      existingIds.add(id);
    });
  });
  if (!imported.length) return 0;
  state.biometricImports = [...imported, ...(state.biometricImports || [])];
  saveBiometricImports();
  return imported.length;
}

function getAssetMetadataKey(asset) {
  if (asset.id) return asset.id;
  return [asset.experienceId || "experience", asset.name || "asset", asset.type || "file", asset.size || 0].join(":");
}

function getAssetKind(attachment) {
  return inferMediaKind(attachment);
}

function getAssetProvenanceLabel(asset) {
  return asset?.isDemo ? t("labels.provenanceDemo") : t("labels.provenanceUser");
}

function getExternalAssetProfile(asset = {}) {
  const metadata = asset.metadata || {};
  const source = asset.externalSource || metadata.externalSource || "";
  const payloadType = asset.externalPayloadType || metadata.externalPayloadType || metadata.payloadType || "";
  const intent = asset.externalProcessingIntent || metadata.externalProcessingIntent || "";
  const treatment = asset.externalTreatment || metadata.externalTreatment || "";
  const privacy = asset.externalPrivacyHint || metadata.externalPrivacyHint || "";
  const consumer = asset.externalExpectedConsumer || metadata.externalExpectedConsumer || "";
  const transportOnly = Boolean(asset.externalTransportOnly || metadata.externalTransportOnly);
  const autoInterpret = Object.hasOwn(asset, "externalAutoInterpret")
    ? Boolean(asset.externalAutoInterpret)
    : Object.hasOwn(metadata, "externalAutoInterpret")
      ? Boolean(metadata.externalAutoInterpret)
      : !transportOnly;
  const captureOrigin = asset.externalCaptureOrigin || metadata.externalCaptureOrigin || "";
  const hasProfile = Boolean(source || payloadType || intent || treatment || consumer || transportOnly);
  return {
    hasProfile,
    source,
    payloadType,
    intent,
    treatment,
    privacy,
    consumer,
    transportOnly,
    autoInterpret,
    captureOrigin,
    label: buildExternalAssetProfileLabel({ source, payloadType, transportOnly }),
  };
}

function buildExternalAssetProfileLabel(profile = {}) {
  if (profile.transportOnly) return state.language !== "es" ? "Transport only" : "Solo transporte";
  const payload = String(profile.payloadType || "").replace(/_/g, " ").trim();
  if (payload) return sentenceCase(payload);
  return profile.source || "";
}

function renderAssetLibrary() {
  const assets = filterMultimodalAssets();
  const allAssets = collectMultimodalAssets();
  const dateFromInput = document.getElementById("assetDateFromFilter");
  const dateToInput = document.getElementById("assetDateToFilter");
  if (dateFromInput && dateFromInput.value !== state.assetFilters.dateFrom) dateFromInput.value = state.assetFilters.dateFrom;
  if (dateToInput && dateToInput.value !== state.assetFilters.dateTo) dateToInput.value = state.assetFilters.dateTo;
  document.getElementById("assetLibraryCount").textContent = `${assets.length} ${t("labels.items")}`;
  renderBiometricAssetPanel();
  renderAssetMetadataWorkflow();
  renderAssetWorkflowReadinessPanel(assets);
  renderAssetImportSummary();
  renderAssetActiveFilters();
  document.getElementById("assetMetricGrid").innerHTML = buildAssetMetrics(allAssets)
    .map(
      ([label, value]) => `
        <article class="metric-card compact-metric">
          <span>${escapeHtml(label)}</span>
          <strong>${escapeHtml(String(value))}</strong>
        </article>
      `,
    )
    .join("") + renderAssetSyncPendingSummary(allAssets);
  renderAssetProcessingSummary(allAssets);
  renderAudioReadinessPanel(allAssets);
  renderAssetProcessingActionPlan(assets);
  document.getElementById("assetLibraryGrid").innerHTML = assets.length
    ? assets.map(renderAssetCard).join("")
    : `<p class="card-meta">${t("labels.assetLibraryEmpty")}</p>`;
}

function renderAssetSyncPendingSummary(assets = collectMultimodalAssets()) {
  const pending = assets.filter((asset) => buildAssetStorageStatus(asset).needsSync);
  if (!pending.length) return "";
  const visible = pending.slice(0, 3);
  const detail = visible.map((asset) => asset.name || asset.experienceTitle || asset.assetKey || "asset").join(" - ");
  const more = pending.length > visible.length ? ` +${pending.length - visible.length}` : "";
  const feedback = state.assetSyncFeedback || null;
  return `
    <article class="metric-card compact-metric asset-sync-pending-detail">
      <span>${escapeHtml(t("labels.assetSyncPendingDetailTitle"))}</span>
      <strong>${escapeHtml(String(pending.length))}</strong>
      <p>${escapeHtml(t("labels.assetSyncPendingDetailText"))}</p>
      <small>${escapeHtml(detail + more)}</small>
      ${feedback ? `<small class="asset-sync-feedback ${feedback.type === "warn" ? "is-warn" : "is-ok"}">${escapeHtml(feedback.message)}</small>` : ""}
      <button class="primary-button small-button" type="button" data-asset-storage-action="repair" ${state.assetSyncInProgress ? "disabled" : ""}>${escapeHtml(state.assetSyncInProgress ? (state.language !== "es" ? "Syncing..." : "Sincronizando...") : t("labels.assetSyncPendingRepair"))}</button>
      <button class="ghost-button small-button" type="button" data-asset-storage-filter="pending">${escapeHtml(t("labels.assetSyncPendingAction"))}</button>
    </article>
  `;
}

function getPendingAssetSyncCandidates() {
  return collectMultimodalAssets()
    .filter((asset) => buildAssetStorageStatus(asset).needsSync)
    .map((asset) => {
      const experience = state.experiences.find((item) => item.id === asset.experienceId) || null;
      const attachment = experience?.attachments?.find((item) =>
        (asset.id && item.id === asset.id) ||
        (asset.assetKey && getAssetMetadataKey({ ...item, experienceId: experience.id }) === asset.assetKey),
      ) || null;
      return { asset, experience, attachment: attachment || (asset.dataUrl ? asset : null) };
    });
}

function attachmentFromPendingAsset(asset = {}) {
  return {
    id: asset.id || `attachment-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    name: asset.name || "media",
    type: asset.type || asset.originalType || "application/octet-stream",
    size: Number(asset.size || 0),
    dataUrl: asset.dataUrl || "",
    capturedAt: asset.capturedAt || asset.timestamp || new Date().toISOString(),
    source: asset.source || "local-retry",
    sourceDevice: asset.sourceDevice || asset.device || "",
    metadata: asset.metadata || {},
  };
}

async function repairPendingAssetsFromLibrary() {
  if (state.assetSyncInProgress) return;
  const before = getPendingAssetSyncCandidates();
  const language = state.language;
  if (!before.length) {
    state.assetSyncFeedback = {
      type: "ok",
      message: language !== "es" ? "There are no pending files to synchronize." : "No hay archivos pendientes por sincronizar.",
    };
    renderAssetLibrary();
    notify(state.assetSyncFeedback.message, "ok");
    return;
  }
  state.assetSyncInProgress = true;
  state.assetSyncFeedback = {
    type: "ok",
    message: language !== "es" ? `Syncing ${before.length} pending file(s)...` : `Sincronizando ${before.length} archivo(s) pendiente(s)...`,
  };
  renderAssetLibrary();
  const retryable = before.filter((item) => item.experience?.id && item.attachment?.dataUrl);
  if (!retryable.length) {
    state.assetSyncInProgress = false;
    state.assetSyncFeedback = {
      type: "warn",
      message: language !== "es"
        ? "The original local files are no longer available for upload from this browser."
        : "Los archivos locales originales ya no están disponibles para subirlos desde este navegador.",
    };
    renderAssetLibrary();
    notify(state.assetSyncFeedback.message, "warn");
    return;
  }
  const retryableExperienceIds = [...new Set(retryable.map((item) => item.experience.id))];
  let failedRequests = 0;
  for (const experienceId of retryableExperienceIds) {
    const index = state.experiences.findIndex((item) => item.id === experienceId);
    if (index < 0) continue;
    const pendingForExperience = retryable.filter((item) => item.experience.id === experienceId);
    const localExperience = state.experiences[index];
    const attachmentIds = new Set((localExperience.attachments || []).map((attachment) => attachment.id).filter(Boolean));
    const attachments = [...(localExperience.attachments || [])];
    for (const candidate of pendingForExperience) {
      if (!attachmentIds.has(candidate.attachment.id)) attachments.push(attachmentFromPendingAsset(candidate.attachment));
    }
    const result = await saveExperienceToApi({ ...localExperience, attachments });
    if (result?.experience) {
      state.experiences[index] = mergeLocalMediaCacheForExperience(result.experience, { ...localExperience, attachments });
    } else {
      failedRequests += 1;
    }
  }
  saveExperiences();
  await syncOfflineQueue({ silent: true });
  const after = getPendingAssetSyncCandidates();
  const resolved = Math.max(0, before.length - after.length);
  state.assetSyncInProgress = false;
  state.assetSyncFeedback = after.length
    ? {
        type: "warn",
        message: language !== "es"
          ? `${resolved} file(s) confirmed. ${after.length} remain pending${failedRequests ? " because the server did not confirm their upload" : ""}.`
          : `${resolved} archivo(s) confirmado(s). ${after.length} siguen pendientes${failedRequests ? " porque el servidor no confirmó su carga" : ""}.`,
      }
    : {
        type: "ok",
        message: language !== "es" ? "Pending files synchronized." : "Archivos pendientes sincronizados.",
      };
  renderAssetLibrary();
  notify(state.assetSyncFeedback.message, after.length ? "warn" : "ok");
}

