function buildAssetProcessingGroups(assets) {
  const labels = {
    extraction: t("labels.assetProcessingNeedsExtraction"),
    transcription: t("labels.assetProcessingNeedsTranscription"),
    description: t("labels.assetProcessingNeedsDescription"),
    "video-review": t("labels.assetProcessingNeedsVideoReview"),
  };
  const details =
    state.language !== "es"
       ? {
          extraction: "Documents that need text extraction or manual analytical text.",
          transcription: "Audio assets that need transcription or human notes.",
          description: "Images that need OCR, description, or visual context.",
          "video-review": "Videos that need scene notes, transcript, or audiovisual review.",
        }
      : {
          extraction: "Documentos que requieren extracción de texto o texto analítico manual.",
          transcription: "Audios que requieren transcripción o notas humanas.",
          description: "Imágenes que requieren OCR, descripción o contexto visual.",
          "video-review": "Videos que requieren notas de escena, transcripción o revisión audiovisual.",
        };
  return Object.keys(labels).map((code) => ({
    code,
    label: labels[code],
    detail: details[code],
    count: assets.filter((asset) => buildAssetProcessingStatus(asset).code === code).length,
  }));
}

function filterMultimodalAssets() {
  const query = state.assetFilters.query;
  return collectMultimodalAssets()
    .filter((asset) => {
      const tags = buildAssetTags(asset);
      const assetDate = new Date(asset.timestamp);
      const dateTokens = buildAssetDateTokens(asset.timestamp);
      const queryText = [
        asset.name,
        asset.experienceTitle,
        asset.category,
        asset.objective,
        asset.location,
        asset.people,
        asset.notes,
        asset.manualNote,
        asset.analysisText,
        asset.extractedText,
        asset.extractionMethod,
        asset.extractionStatus,
        asset.eventTitle,
        asset.eventId ? "event linked evento vinculado" : "whole experience toda la experiencia",
        asset.type,
        asset.originalType,
        asset.extension,
        asset.device,
        asset.storageLabel,
        asset.externalSource,
        asset.externalPayloadType,
        asset.externalProcessingIntent,
        asset.externalTreatment,
        asset.externalExpectedConsumer,
        asset.externalProfileLabel,
        ...dateTokens,
        ...tags,
      ]
        .join(" ")
        .toLowerCase();
      const queryMatch = !query || queryText.includes(query);
      const dateFromMatch = !state.assetFilters.dateFrom || assetDate >= new Date(`${state.assetFilters.dateFrom}T00:00:00`);
      const dateToMatch = !state.assetFilters.dateTo || assetDate <= new Date(`${state.assetFilters.dateTo}T23:59:59`);
      const typeMatch = state.assetFilters.type === "all" || asset.kind === state.assetFilters.type;
      const categoryMatch = state.assetFilters.category === "all" || asset.category === state.assetFilters.category;
      const readiness = buildAssetReadiness(asset);
      const processing = buildAssetProcessingStatus(asset);
      const storage = buildAssetStorageStatus(asset);
      const readinessMatch =
        state.assetFilters.readiness === "all" ||
        (state.assetFilters.readiness === "ready" && readiness.ready) ||
        (state.assetFilters.readiness === "review" && !readiness.ready);
      const processingMatch =
        state.assetFilters.processing === "all" ||
        (state.assetFilters.processing === "ready" && processing.ready) ||
        (state.assetFilters.processing === "pending" && !processing.ready) ||
        state.assetFilters.processing === processing.code;
      const provenanceMatch =
        state.assetFilters.provenance === "all" ||
        (state.assetFilters.provenance === "demo" && asset.isDemo) ||
        (state.assetFilters.provenance === "user" && !asset.isDemo);
      const eventLinkMatch =
        state.assetFilters.eventLink === "all" ||
        (state.assetFilters.eventLink === "linked" && Boolean(asset.eventId || asset.eventTitle)) ||
        (state.assetFilters.eventLink === "whole" && !asset.eventId && !asset.eventTitle);
      const hasAnalysisText = Boolean(String(asset.analysisText || "").trim());
      const analysisMatch =
        state.assetFilters.analysis === "all" ||
        (state.assetFilters.analysis === "with" && hasAnalysisText) ||
        (state.assetFilters.analysis === "without" && !hasAnalysisText);
      const storageMatch =
        !state.assetFilters.storage ||
        state.assetFilters.storage === "all" ||
        (state.assetFilters.storage === "pending" && storage.needsSync) ||
        (state.assetFilters.storage === "remote" && storage.remote);
      return queryMatch && dateFromMatch && dateToMatch && typeMatch && categoryMatch && readinessMatch && processingMatch && provenanceMatch && eventLinkMatch && analysisMatch && storageMatch;
    })
    .sort(compareAssetsForCurrentSort);
}

function compareAssetsForCurrentSort(a, b) {
  const sort = state.assetFilters.sort || "newest";
  if (sort === "oldest") return new Date(a.timestamp) - new Date(b.timestamp);
  if (sort === "name") return String(a.name || "").localeCompare(String(b.name || ""), state.language !== "es" ? "en" : "es");
  if (sort === "type") return getAssetKindLabel(a.kind).localeCompare(getAssetKindLabel(b.kind), state.language !== "es" ? "en" : "es");
  if (sort === "processing") {
    return buildAssetProcessingStatus(a).label.localeCompare(buildAssetProcessingStatus(b).label, state.language !== "es" ? "en" : "es");
  }
  return new Date(b.timestamp) - new Date(a.timestamp);
}

function buildAssetDateTokens(timestamp) {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return [];
  const iso = date.toISOString();
  return [
    iso.slice(0, 10),
    iso.slice(0, 7),
    String(date.getFullYear()),
    new Intl.DateTimeFormat(state.language !== "es" ? "en" : "es", { month: "long" }).format(date),
    new Intl.DateTimeFormat(state.language !== "es" ? "en" : "es", { dateStyle: "medium" }).format(date),
  ];
}

