function isTruthyImportFlag(value) {
  return ["1", "true", "yes", "si", "sí", "x", "clear", "limpiar", "borrar"].includes(String(value || "").trim().toLowerCase());
}

function parseAssetMetadataImportRows(rawText, file = {}) {
  const text = String(rawText || "").replace(/^\uFEFF/, "");
  const extension = getFileExtension(file.name || "");
  const isCsv = extension === "csv" || String(file.type || "").includes("csv");
  if (isCsv) return parseCsvTable(text);
  const payload = JSON.parse(text);
  return Array.isArray(payload) ? payload : Array.isArray(payload.assets) ? payload.assets : [];
}

function parseCsvTable(text) {
  const rows = [];
  let current = "";
  let row = [];
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    const next = text[index + 1];
    if (char === '"' && quoted && next === '"') {
      current += '"';
      index += 1;
    } else if (char === '"') {
      quoted = !quoted;
    } else if (char === "," && !quoted) {
      row.push(current);
      current = "";
    } else if ((char === "\n" || char === "\r") && !quoted) {
      if (char === "\r" && next === "\n") index += 1;
      row.push(current);
      if (row.some((cell) => String(cell || "").trim())) rows.push(row);
      row = [];
      current = "";
    } else {
      current += char;
    }
  }
  row.push(current);
  if (row.some((cell) => String(cell || "").trim())) rows.push(row);
  const headers = (rows.shift() || []).map((header) => String(header || "").trim());
  return rows.map((cells) =>
    headers.reduce((record, header, index) => {
      record[header] = cells[index] || "";
      return record;
    }, {}),
  );
}

