function answerExperienceMapQuestion() {
  const input = document.getElementById("experienceMapQuestionInput");
  const box = document.getElementById("experienceMapAnswer");
  const questionText = input.value.trim();
  const question = questionText.toLowerCase();
  if (!question) {
    box.textContent = t("labels.experienceMapAnswerEmpty");
    return;
  }
  const graph = buildExperienceMapGraph();
  const analysis = buildExperienceMapQuestionAnalysis(graph, questionText);
  if (analysis.routeId) {
    state.selectedExperienceMapRouteId = analysis.routeId;
    state.selectedExperienceMapNodeId = analysis.items[0]?.id || "";
    renderExperienceMap();
  }
  box.innerHTML = `
    <section class="question-answer-card">
      <span class="report-kicker">${t("labels.experienceMapAnswerReady")}</span>
      <h3>${escapeHtml(questionText)}</h3>
      <div class="question-answer-metrics">
        <article><span>${t("labels.experienceMapQuestionFocus")}</span><strong>${escapeHtml(analysis.focus)}</strong></article>
        <article><span>${t("metrics.avgEnergy")}</span><strong>${analysis.avgEnergy}/10</strong></article>
        <article><span>${t("labels.experienceMapLinks")}</span><strong>${analysis.linkCount}</strong></article>
      </div>
      <p>${escapeHtml(analysis.summary)}</p>
      <p class="question-action"><strong>${t("labels.experienceMapQuestionAction")}:</strong> ${escapeHtml(analysis.action)}</p>
      <div class="question-match-list">
        ${analysis.items
          .map(
            (item) => `
              <article>
                <strong>${escapeHtml(item.label)}</strong>
                <span>${escapeHtml(displayCategory(item.category))} · ${item.energy}/10 · ${escapeHtml(formatShortDate(item.timestamp))}</span>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

