function buildHumanCorrelations(experiences, analysis) {
  if (experiences.length < 3) return [];
  const workItems = experiences.filter((item) => normalizeCategoryName(item.category) === "Trabajo");
  const recoveryItems = experiences.filter((item) => ["Salud", "Espiritualidad", "Viajes / Paseos"].includes(normalizeCategoryName(item.category)));
  const socialItems = experiences.filter((item) => normalizeCategoryName(item.category) === "Social" || hasMeaningfulPeople(item.people));
  const learningItems = experiences.filter((item) => normalizeCategoryName(item.category) === "Aprendizaje" || String(item.notes || "").toLowerCase().includes("aprendi"));
  const weatherItems = experiences.filter((item) => ["calor", "lluvia", "clima", "frio", "viento", "humedad"].some((token) => `${item.location || ""} ${item.notes || ""}`.toLowerCase().includes(token)));
  const contextScore = state.contextImpact?.impactScore || 0;
  const saturatedPct = pct(experiences.filter((item) => item.mood === "Saturado").length, experiences.length);
  const lowEnergyPct = pct(experiences.filter((item) => Number(item.energy || 0) <= 4).length, experiences.length);
  const biometricSummary = summarizeBiometricSignalsForExperiences(experiences);
  const correlations = [
    buildCorrelationResult({
      source: state.language !== "es" ? "Work -> saturation" : "Trabajo -> saturación",
      title: state.language !== "es" ? "Work pressure and saturation" : "Presión de trabajo y saturación",
      score: workItems.length ? Math.round((pct(workItems.filter((item) => item.mood === "Saturado" || Number(item.energy || 0) <= 4).length, workItems.length) * 0.8) + Math.min(20, workItems.length * 2)) : 0,
      detail: state.language !== "es"
         ? `${workItems.length} work experiences compared against saturation and low energy.`
        : `${workItems.length} experiencias de trabajo comparadas contra saturación y baja energía.`,
      action: state.language !== "es" ? "If signal is high, schedule recovery after dense work blocks." : "Si la señal es alta, programa recuperación después de bloques densos de trabajo.",
    }),
    buildCorrelationResult({
      source: state.language !== "es" ? "Socialization -> wellbeing" : "Socialización -> bienestar",
      title: state.language !== "es" ? "Social connection and energy" : "Conexión social y energía",
      score: socialItems.length ? Math.round(average(socialItems.map((item) => Number(item.energy || 0))) * 10) : 0,
      detail: state.language !== "es"
         ? `${socialItems.length} experiences include people or social context.`
        : `${socialItems.length} experiencias incluyen personas o contexto social.`,
      action: state.language !== "es" ? "Compare recurring people with high-energy moments." : "Compara personas recurrentes con momentos de energía alta.",
      inverseTone: false,
    }),
    buildCorrelationResult({
      source: state.language !== "es" ? "Travel/recovery -> energy" : "Viajes/recuperación -> energía",
      title: state.language !== "es" ? "Recovery contexts and energy" : "Contextos de recuperación y energía",
      score: recoveryItems.length ? Math.round(average(recoveryItems.map((item) => Number(item.energy || 0))) * 10) : 0,
      detail: state.language !== "es"
         ? `${recoveryItems.length} recovery, health, home, spirituality, or travel/walk experiences analyzed.`
        : `${recoveryItems.length} experiencias de recuperación, salud, hogar, espiritualidad o viajes/paseos analizadas.`,
      action: state.language !== "es" ? "Repeat the contexts that raise energy and reduce saturation." : "Repite los contextos que elevan energía y reducen saturación.",
      inverseTone: false,
    }),
    buildCorrelationResult({
      source: state.language !== "es" ? "Learning -> resilience" : "Aprendizaje -> resiliencia",
      title: state.language !== "es" ? "Learning and resilience" : "Aprendizaje y resiliencia",
      score: learningItems.length ? Math.round((pct(learningItems.length, experiences.length) * 0.5) + (average(learningItems.map((item) => Number(item.energy || 0))) * 5)) : 0,
      detail: state.language !== "es"
         ? `${learningItems.length} learning signals appear in categories or notes.`
        : `${learningItems.length} señales de aprendizaje aparecen en categorías o notas.`,
      action: state.language !== "es" ? "Turn repeated learnings into explicit routines or experiments." : "Convierte aprendizajes repetidos en rutinas o experimentos explícitos.",
      inverseTone: false,
    }),
    buildCorrelationResult({
      source: state.language !== "es" ? "Biometrics -> energy" : "Biometría -> energía",
      title: state.language !== "es" ? "Biometric coverage and perceived energy" : "Cobertura biométrica y energía percibida",
      score: biometricSummary.coveragePct ? Math.round((biometricSummary.coveragePct * 0.45) + (biometricSummary.averageSuggestedEnergy ? biometricSummary.averageSuggestedEnergy * 5.5 : 0)) : 0,
      detail: state.language !== "es"
         ? `${biometricSummary.matched} experiences have nearby biometric context${biometricSummary.averageSuggestedEnergy ? `; suggested energy average is ${biometricSummary.averageSuggestedEnergy.toFixed(1)}/10.` : ", but the available signals are not enough for a reliable energy average."}`
        : `${biometricSummary.matched} experiencias tienen contexto biométrico cercano${biometricSummary.averageSuggestedEnergy ? `; la energía biométrica sugerida promedia ${biometricSummary.averageSuggestedEnergy.toFixed(1)}/10.` : ", pero las señales disponibles no alcanzan para calcular un promedio confiable de energía."}`,
      action: state.language !== "es" ? "Compare perceived energy against biometric signals before changing routines." : "Compara energía percibida contra señales biométricas antes de cambiar rutinas.",
      inverseTone: false,
    }),
    buildCorrelationResult({
      source: state.language !== "es" ? "Weather/context -> emotion" : "Clima/contexto -> emoción",
      title: state.language !== "es" ? "External context and emotional load" : "Contexto externo y carga emocional",
      score: Math.round(Math.max(contextScore, weatherItems.length ? pct(weatherItems.length, experiences.length) : 0, saturatedPct * 0.7 + lowEnergyPct * 0.3)),
      detail: state.language !== "es"
         ? `${weatherItems.length} experiences mention weather-like cues; active context impact is ${contextScore}/100.`
        : `${weatherItems.length} experiencias mencionan señales climáticas; el impacto contextual activo es ${contextScore}/100.`,
      action: state.language !== "es" ? "Run context analysis for the main location before planning dense days." : "Ejecuta análisis de contexto para la ubicación principal antes de planificar días densos.",
    }),
  ];
  return correlations.filter((item) => item.score > 0).sort((a, b) => b.score - a.score);
}

function buildCorrelationResult({ source, title, score, detail, action, inverseTone = true }) {
  const normalizedScore = Math.round(clampScore(score));
  const high = inverseTone ? normalizedScore >= 66 : normalizedScore >= 70;
  const medium = inverseTone ? normalizedScore >= 35 : normalizedScore >= 45;
  return {
    source,
    title,
    score: normalizedScore,
    signal: high ? (state.language !== "es" ? "High signal" : "Señal alta") : medium ? (state.language !== "es" ? "Medium signal" : "Señal media") : (state.language !== "es" ? "Low signal" : "Señal baja"),
    tone: high ? "high" : medium ? "medium" : "low",
    detail,
    action,
  };
}

function pct(count, total) {
  return total ? (count / total) * 100 : 0;
}

function clampScore(value) {
  return Math.max(0, Math.min(100, Number(value) || 0));
}

function buildEnergyTrendPoints(experiences) {
  const grouped = experiences.reduce((acc, item) => {
    const key = formatShortDate(item.timestamp);
    if (!acc[key]) acc[key] = [];
    acc[key].push(Number(item.energy || 0));
    return acc;
  }, {});
  return Object.entries(grouped)
    .map(([label, values]) => ({ label, energy: Number(average(values).toFixed(1)) }))
    .slice(-12);
}

function renderCategoryBreakdown(rows, totalMinutes) {
  if (!rows.length) {
    return `
      <section class="report-category-section">
        <h3>${t("labels.reportCategoryBreakdown")}</h3>
        <p class="card-meta">${t("labels.reportCategoryEmpty")}</p>
      </section>
    `;
  }
  return `
    <section class="report-category-section">
      <h3>${t("labels.reportCategoryBreakdown")}</h3>
      <div class="category-breakdown-list">
        ${rows
          .map((row) => {
            const share = totalMinutes ? Math.round((row.minutes / totalMinutes) * 100) : 0;
            return `
              <article class="category-breakdown-row">
                <div>
                  <strong>${escapeHtml(displayCategory(row.category))}</strong>
                  <p class="card-meta">${row.count} ${t("metrics.experiences").toLowerCase()} · ${(row.minutes / 60).toFixed(1)} ${t("labels.hoursShort")} · ${t("metrics.avgEnergy")}: ${row.avgEnergy}/10 · ${row.saturated} ${t("labels.saturatedShort")} · ${row.attachments} ${t("labels.attachments")}</p>
                </div>
                <div class="category-share">
                  <span>${share}%</span>
                  <div class="bar-track"><div class="bar-fill" style="width: ${Math.max(4, share)}%"></div></div>
                </div>
              </article>
            `;
          })
          .join("")}
      </div>
      ${renderBlueprintCategoryReading(rows)}
    </section>
  `;
}

function renderBlueprintCategoryReading(rows) {
  const readings = rows.map(buildBlueprintCategoryReading).filter(Boolean);
  if (!readings.length) return "";
  return `
    <section class="blueprint-category-reading">
      <div class="report-section-heading">
        <h3>${t("labels.blueprintCategoryReading")}</h3>
        <span class="pill">${t("labels.blueprintEstimated")}</span>
      </div>
      <div class="blueprint-category-grid">
        ${readings.map(renderBlueprintCategoryCard).join("")}
      </div>
    </section>
  `;
}

function renderBlueprintCategoryCard(reading) {
  const tone = Number(reading.avgEnergy || 0) >= 7 ? "strong" : reading.saturated > 0 ? "watch" : "medium";
  return `
    <article class="blueprint-category-card category-${tone}">
      <header>
        <strong>${escapeHtml(displayCategory(reading.category))}</strong>
        <span>${reading.count} ${t("metrics.experiences").toLowerCase()}</span>
      </header>
      <div class="blueprint-category-metrics">
        <span>${t("metrics.avgEnergy")}: ${reading.avgEnergy}/10</span>
        <span>${t("labels.saturatedShort")}: ${reading.saturated}</span>
      </div>
      <div class="category-reading-copy">
        <p><b>${t("labels.blueprintCategoryFocus")}:</b> ${escapeHtml(reading.focus)}</p>
        <p><b>${t("labels.blueprintCategoryRisk")}:</b> ${escapeHtml(reading.risk)}</p>
      </div>
      <small><b>${t("labels.blueprintCategoryAction")}:</b> ${escapeHtml(reading.action)}</small>
    </article>
  `;
}

