function downloadReport() {
  const payload = buildReportExportPayload();
  const content = JSON.stringify(payload, null, 2);
  const blob = new Blob([content], { type: "application/json" });
  downloadBlob(blob, "reporte-experiencias.json", content);
  markReportExport("json", payload, "ok");
  renderReportAcceptancePanel();
  notify(state.language !== "es" ? "Report JSON exported." : "JSON del reporte exportado.", "success");
}

function markReportExport(format, payload = buildReportExportPayload(), status = "ok") {
  const reportExperiences = getReportOutputScope().stories;
  state.reportExportAudit = {
    ...(state.reportExportAudit || {}),
    [format]: {
      at: new Date().toISOString(),
      status,
      experiences: reportExperiences.length,
      filters: { ...state.reportFilters },
      averageEnergy: payload?.summary?.averageEnergy ?? 0,
      evidence: payload?.multimodalEvidence?.length || 0,
    },
    lastFormat: format,
    lastStatus: status,
    lastAt: new Date().toISOString(),
  };
  saveReportExportAudit();
}

function markReportAcceptanceReview() {
  const payload = buildReportExportPayload();
  state.reportExportAudit = {
    ...(state.reportExportAudit || {}),
    review: {
      at: new Date().toISOString(),
      status: "ok",
      experiences: getReportOutputScope().stories.length,
      filters: { ...state.reportFilters },
      score: calculateReportAcceptanceReadiness().score,
      summary: payload.summary,
    },
    lastFormat: "review",
    lastStatus: "ok",
    lastAt: new Date().toISOString(),
  };
  saveReportExportAudit();
  renderReportAcceptancePanel();
  notify(state.language !== "es" ? "Report review registered." : "Revisión del reporte registrada.", "success");
}

function handleReportAcceptanceClick(event) {
  const action = event.target.closest("[data-report-acceptance-action]")?.dataset.reportAcceptanceAction;
  if (!action) return;
  if (event.target.closest("[onclick]")) return;
  setReportAcceptanceStatus(state.language !== "es" ? "Processing action..." : "Procesando acción...");
  if (action === "json") downloadReport();
  if (action === "csv") downloadCsvReport();
  if (action === "html") downloadPrintableReport();
  if (action === "pdf") downloadPdfReport();
  if (action === "review") markReportAcceptanceReview();
  if (action === "all") exportReportAcceptancePackage();
}

function setReportAcceptanceStatus(message) {
  const status = document.getElementById("reportAcceptanceActionStatus");
  if (status) status.textContent = message;
}

function renderReportDownloadFallback() {
  const item = state.lastDownload;
  if (!item?.url || !item?.filename) return "";
  const isReportFile = /reporte|aceptacion|experiencias/i.test(item.filename);
  if (!isReportFile) return "";
  const label = state.language !== "es" ? "Manual download available" : "Descarga manual disponible";
  const action = state.language !== "es" ? "Download again" : "Descargar de nuevo";
  const detail =
    state.language !== "es"
       ? "If the browser did not open the download automatically, use this link."
      : "Si el navegador no abrio la descarga automaticamente, usa este enlace.";
  return `
    <div class="report-download-fallback">
      <div>
        <strong>${escapeHtml(label)}: ${escapeHtml(item.filename)}</strong>
        <p>${escapeHtml(detail)}</p>
      </div>
      <a class="ghost-button" href="${escapeHtml(item.url)}" download="${escapeHtml(item.filename)}">${escapeHtml(action)}</a>
    </div>
  `;
}

function renderReportProjectExportLocation() {
  const item = state.lastServerExport;
  if (!item) return "";
  if (!item.ok) {
    return `
      <div class="report-export-location is-warning">
        <strong>${escapeHtml(state.language !== "es" ? "Project folder save failed" : "No se guardo en la carpeta del proyecto")}</strong>
        <p>${escapeHtml(item.message || item.error || "")}</p>
      </div>
    `;
  }
  const title = state.language !== "es" ? "Saved in project folder" : "Guardado en carpeta del proyecto";
  const detail =
    state.language !== "es"
       ? "This is the exact local path, independent from the browser download folder."
      : "Esta es la ruta local exacta, independiente de la carpeta de descargas del navegador.";
  return `
    <div class="report-export-location">
      <strong>${escapeHtml(title)}: ${escapeHtml(item.filename)}</strong>
      <p>${escapeHtml(detail)}</p>
      <code>${escapeHtml(item.path || item.relativePath || "")}</code>
    </div>
  `;
}

function exportReportAcceptancePackage() {
  const payload = buildReportExportPayload();
  const checks = buildReportAcceptanceChecks();
  const readiness = summarizeReadiness(checks.map((check) => check.ok));
  const pack = {
    generatedAt: new Date().toISOString(),
    appVersion: APP_VERSION,
    language: state.language,
    readiness,
    checks,
    audit: state.reportExportAudit || {},
    report: payload,
  };
  const content = JSON.stringify(pack, null, 2);
  downloadBlob(new Blob([content], { type: "application/json;charset=utf-8" }), "paquete-aceptacion-reporte.json", content);
  state.reportExportAudit = {
    ...(state.reportExportAudit || {}),
    package: {
      at: new Date().toISOString(),
      status: "ok",
      experiences: getReportExperiences().length,
      score: readiness.score,
    },
    lastFormat: "package",
    lastStatus: "ok",
    lastAt: new Date().toISOString(),
  };
  saveReportExportAudit();
  renderReportAcceptancePanel();
  notify(state.language !== "es" ? "Report acceptance package exported." : "Paquete de aceptación del reporte exportado.", "success");
}

function buildReportAcceptanceChecksLegacy() {
  const audit = state.reportExportAudit || {};
  if (!audit.lastAt) {
    return state.language !== "es" ? "No acceptance action has been run yet." : "Aun no se ha ejecutado ninguna accion de aceptacion.";
  }
  const lastFormat = audit.lastFormat || (state.language !== "es" ? "action" : "accion");
  const label = getReportAcceptanceActionLabel(lastFormat);
  const fileName = getReportExportFileName(lastFormat, audit.lastStatus);
  const purpose = getReportAcceptanceActionPurpose(lastFormat === "package" ? "all" : lastFormat);
  return state.language !== "es"
     ? `Last action: ${label} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}. ${fileName ? `Generated file: ${fileName}. ` : ""}${purpose}`
    : `Ultima accion: ${label} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}. ${fileName ? `Archivo generado: ${fileName}. ` : ""}${purpose}`;
  const reportExperiences = getReportExperiences();
  const payload = buildReportExportPayload();
  const hasNarrative = Boolean(payload.analysis?.executive?.length && payload.integratedReading?.length);
  const hasCharts = Boolean(payload.energyTrend?.length || payload.categoryBreakdown?.length);
  const hasEvidence = reportExperiences.length >= 3;
  const labels =
    state.language !== "es"
       ? {
          data: "Reportable data",
          narrative: "Narrative and insights",
          charts: "Charts and breakdowns",
          json: "JSON export tested",
          csv: "CSV export tested",
          html: "Printable HTML tested",
          pdf: "PDF or fallback tested",
          review: "Human review registered",
          pack: "Acceptance package exported",
        }
      : {
          data: "Datos reportables",
          narrative: "Narrativa y hallazgos",
          charts: "Gráficas y desgloses",
          json: "Exportación JSON probada",
          csv: "Exportación CSV probada",
          html: "HTML imprimible probado",
          pdf: "PDF o respaldo probado",
          review: "Revisión humana registrada",
          pack: "Paquete de aceptación exportado",
        };
  const formatDetail = (format) => {
    const item = audit[format];
    if (!item?.at) return state.language !== "es" ? "Not exported in this browser." : "No exportado en este navegador.";
    const status = item.status === "ok" ? (state.language !== "es" ? "successful" : "correcto") : item.status;
    return `${formatDate(item.at)} · ${status} · ${item.experiences || 0} ${state.language !== "es" ? "experiences" : "experiencias"}`;
  };
  return [
    {
      key: "data",
      label: labels.data,
      ok: hasEvidence,
      detail: state.language !== "es" ? `${reportExperiences.length} experiences in current report filter.` : `${reportExperiences.length} experiencias en el filtro actual.`,
    },
    {
      key: "narrative",
      label: labels.narrative,
      ok: hasNarrative,
      detail: state.language !== "es" ? `${payload.integratedReading?.length || 0} integrated readings.` : `${payload.integratedReading?.length || 0} lecturas integradas.`,
    },
    {
      key: "charts",
      label: labels.charts,
      ok: hasCharts,
      detail: state.language !== "es" ? `${payload.categoryBreakdown?.length || 0} categories and ${payload.energyTrend?.length || 0} trend points.` : `${payload.categoryBreakdown?.length || 0} categorías y ${payload.energyTrend?.length || 0} puntos de tendencia.`,
    },
    { key: "pdf", label: labels.pdf, ok: Boolean(audit.pdf?.at), detail: formatDetail("pdf") },
    { key: "review", label: labels.review, ok: audit.review?.status === "ok", detail: formatDetail("review") },
    { key: "package", label: labels.pack, ok: audit.package?.status === "ok", detail: formatDetail("package") },
  ];
}

function buildReportAcceptanceChecks() {
  const audit = state.reportExportAudit || {};
  const outputScope = getReportOutputScope();
  const reportExperiences = outputScope.stories;
  const payload = buildReportExportPayload();
  const hasNarrative = Boolean(payload.analysis?.executive?.length && payload.integratedReading?.length);
  const hasCharts = Boolean(payload.energyTrend?.length || payload.categoryBreakdown?.length);
  const hasEvidence = reportExperiences.length >= 3 || outputScope.evidence.length > 0 || outputScope.context.length > 0;
  const labels =
    state.language !== "es"
       ? {
          data: "Reportable data",
          narrative: "Narrative and insights",
          charts: "Charts and breakdowns",
          json: "JSON export tested",
          csv: "CSV export tested",
          html: "Printable HTML tested",
          pdf: "PDF or fallback tested",
          review: "Human review registered",
          pack: "Acceptance package exported",
        }
      : {
          data: "Datos reportables",
          narrative: "Narrativa y hallazgos",
          charts: "Graficas y desgloses",
          json: "Exportacion JSON probada",
          csv: "Exportacion CSV probada",
          html: "HTML imprimible probado",
          pdf: "PDF o respaldo probado",
          review: "Revision humana registrada",
          pack: "Paquete de aceptacion exportado",
        };
  const formatDetail = (format) => {
    const item = audit[format];
    if (!item?.at) return state.language !== "es" ? "Not exported in this browser." : "No exportado en este navegador.";
    const status = item.status === "ok" ? (state.language !== "es" ? "successful" : "correcto") : item.status;
    return `${formatDate(item.at)} · ${status} · ${item.experiences || 0} ${state.language !== "es" ? "experiences" : "experiencias"}`;
  };
  return [
    { key: "data", label: labels.data, ok: hasEvidence, detail: state.language !== "es" ? `${reportExperiences.length} experiences in current report filter.` : `${reportExperiences.length} experiencias en el filtro actual.` },
    { key: "narrative", label: labels.narrative, ok: hasNarrative, detail: state.language !== "es" ? `${payload.integratedReading?.length || 0} integrated readings.` : `${payload.integratedReading?.length || 0} lecturas integradas.` },
    { key: "charts", label: labels.charts, ok: hasCharts, detail: state.language !== "es" ? `${payload.categoryBreakdown?.length || 0} categories and ${payload.energyTrend?.length || 0} trend points.` : `${payload.categoryBreakdown?.length || 0} categorias y ${payload.energyTrend?.length || 0} puntos de tendencia.` },
    { key: "json", label: labels.json, ok: audit.json?.status === "ok", detail: formatDetail("json") },
    { key: "csv", label: labels.csv, ok: audit.csv?.status === "ok", detail: formatDetail("csv") },
    { key: "html", label: labels.html, ok: audit.html?.status === "ok", detail: formatDetail("html") },
    { key: "pdf", label: labels.pdf, ok: Boolean(audit.pdf?.at), detail: formatDetail("pdf") },
    { key: "review", label: labels.review, ok: audit.review?.status === "ok", detail: formatDetail("review") },
    { key: "package", label: labels.pack, ok: audit.package?.status === "ok", detail: formatDetail("package") },
  ];
}

function calculateReportAcceptanceReadiness() {
  return summarizeReadiness(buildReportAcceptanceChecks().map((check) => check.ok));
}

function renderReportAcceptancePanel() {
  const container = document.getElementById("reportAcceptancePanel");
  if (!container) return;
  const checks = buildReportAcceptanceChecks();
  const readiness = summarizeReadiness(checks.map((check) => check.ok));
  const title = state.language !== "es" ? "Report Acceptance Pack" : "Paquete de aceptación del reporte";
  const detail =
    state.language !== "es"
       ? `${readiness.ready}/${readiness.total} controls ready. The pilot should test exports before considering Reports closed.`
      : `${readiness.ready}/${readiness.total} controles listos. El piloto debe probar exportaciones antes de considerar Reportes cerrado.`;
  const actions = state.language !== "es"
     ? {
        review: "Register human review",
        json: "Download report JSON",
        csv: "Download table CSV",
        html: "Download printable HTML",
        pdf: "Download edited ReportLab PDF",
        all: "Download acceptance evidence",
      }
    : {
        review: "Registrar revisión",
        json: "Descargar reporte JSON",
        csv: "Descargar tabla CSV",
        html: "Descargar HTML imprimible",
        pdf: "Descargar PDF editado ReportLab",
        all: "Descargar evidencia de aceptacion",
      };
  const primaryActionKeys = ["review", "pdf", "all"];
  const actionHelp = primaryActionKeys.map((key) => ({
    key,
    label: actions[key],
    purpose: getReportAcceptanceActionPurpose(key),
  }));
  container.innerHTML = `
    <section>
      <div class="report-acceptance-heading">
        <div>
          <h3>${escapeHtml(title)}</h3>
          <p>${escapeHtml(detail)}</p>
        </div>
        <strong class="${readiness.score >= 85 ? "status-ok" : "status-warn"}">${escapeHtml(`${readiness.score}%`)}</strong>
      </div>
      <div class="report-acceptance-actions">
        <button class="primary-button" type="button" data-report-acceptance-action="review" title="${escapeHtml(getReportAcceptanceActionPurpose("review"))}" onclick="markReportAcceptanceReview()">${escapeHtml(actions.review)}</button>
        <button class="ghost-button" type="button" data-report-acceptance-action="pdf" title="${escapeHtml(getReportAcceptanceActionPurpose("pdf"))}" onclick="downloadPdfReport()">${escapeHtml(actions.pdf)}</button>
        <button class="ghost-button" type="button" data-report-acceptance-action="all" title="${escapeHtml(getReportAcceptanceActionPurpose("all"))}" onclick="exportReportAcceptancePackage()">${escapeHtml(actions.all)}</button>
      </div>
      <div class="report-acceptance-help" aria-label="${escapeHtml(state.language !== "es" ? "What each acceptance button does" : "Para que sirve cada boton de aceptacion")}">
        ${actionHelp
          .map(
            (item) => `
              <article>
                <strong>${escapeHtml(item.label)}</strong>
                <p>${escapeHtml(item.purpose)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
      <p id="reportAcceptanceActionStatus" class="report-acceptance-status" aria-live="polite">${escapeHtml(formatReportAcceptanceLastAction())}</p>
      ${renderReportDownloadFallback()}
      ${renderReportProjectExportLocation()}
      <div class="report-acceptance-grid">
        ${checks
          .map(
            (check) => `
              <article class="${check.ok ? "is-ready" : "is-review"}">
                <span class="${check.ok ? "status-ok" : "status-warn"}">${escapeHtml(check.ok ? (state.language !== "es" ? "Ready" : "Listo") : (state.language !== "es" ? "Review" : "Revisar"))}</span>
                <strong>${escapeHtml(check.label)}</strong>
                <p>${escapeHtml(check.detail)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function formatReportAcceptanceLastActionLegacy() {
  const audit = state.reportExportAudit || {};
  if (!audit.lastAt) {
    return state.language !== "es" ? "No acceptance action has been run yet." : "Aún no se ha ejecutado ninguna acción de aceptación.";
  }
  const format = audit.lastFormat || (state.language !== "es" ? "action" : "acción");
  return state.language !== "es"
     ? `Last action: ${format} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}.`
    : `Última acción: ${format} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}.`;
}

function getReportAcceptanceActionLabel(format) {
  const labels =
    state.language !== "es"
       ? {
          review: "human review",
          json: "report JSON",
          csv: "table CSV",
          html: "printable HTML",
          pdf: "PDF",
          package: "acceptance evidence",
          all: "acceptance evidence",
        }
      : {
          review: "revision humana",
          json: "reporte JSON",
          csv: "tabla CSV",
          html: "HTML imprimible",
          pdf: "PDF",
          package: "evidencia de aceptacion",
          all: "evidencia de aceptacion",
        };
  return labels[format] || format;
}

function getReportAcceptanceActionPurpose(action) {
  const purposes =
    state.language !== "es"
       ? {
          review: "Marks that a person reviewed the report on screen; it does not download a file.",
          json: "Exports the complete structured report for backup, audit, or later processing.",
          csv: "Exports the report table for Excel, Sheets, or simple data review.",
          html: "Exports a readable printable version with narrative, indicators, and evidence.",
          pdf: "Generates an edited ReportLab PDF. If the server is unavailable, the app keeps printable HTML as backup.",
          all: "Exports the acceptance evidence: readiness score, checks, actions run, and report snapshot.",
          package: "Exports the acceptance evidence: readiness score, checks, actions run, and report snapshot.",
        }
      : {
          review: "Marca que una persona reviso el reporte en pantalla; no descarga archivo.",
          json: "Exporta el reporte completo y estructurado para respaldo, auditoria o procesamiento posterior.",
          csv: "Exporta la tabla del reporte para Excel, Sheets o revision simple de datos.",
          html: "Exporta una version legible e imprimible con narrativa, indicadores y evidencia.",
          pdf: "Genera un PDF editado con ReportLab. Si el servidor no esta disponible, la app conserva HTML imprimible como respaldo.",
          all: "Exporta la evidencia de aceptacion: puntaje, controles, acciones ejecutadas y copia del reporte.",
          package: "Exporta la evidencia de aceptacion: puntaje, controles, acciones ejecutadas y copia del reporte.",
        };
  return purposes[action] || "";
}

function getReportExportFileName(format, status = "ok") {
  if (format === "json") return "reporte-experiencias.json";
  if (format === "csv") return "reporte-experiencias.csv";
  if (format === "html") return "reporte-experiencias.html";
  if (format === "pdf") return status === "ok" ? "reporte-experiencias.pdf" : "reporte-experiencias.html";
  if (format === "package" || format === "all") return "paquete-aceptacion-reporte.json";
  return "";
}

function formatReportAcceptanceLastAction() {
  const audit = state.reportExportAudit || {};
  if (!audit.lastAt) {
    return state.language !== "es" ? "No acceptance action has been run yet." : "Aun no se ha ejecutado ninguna accion de aceptacion.";
  }
  const format = audit.lastFormat || (state.language !== "es" ? "action" : "accion");
  const label = getReportAcceptanceActionLabel(format);
  const fileName = getReportExportFileName(format, audit.lastStatus);
  const purpose = getReportAcceptanceActionPurpose(format === "package" ? "all" : format);
  return state.language !== "es"
     ? `Last action: ${label} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}. ${fileName ? `Generated file: ${fileName}. ` : ""}${purpose}`
    : `Ultima accion: ${label} · ${formatDate(audit.lastAt)} · ${audit.lastStatus || "ok"}. ${fileName ? `Archivo generado: ${fileName}. ` : ""}${purpose}`;
}

function buildReportExportPayload() {
  const scopedStories = getReportExperiences();
  const outputScope = buildAnalyticalOutputScope(state.reportFilters || {}, "report", scopedStories);
  const presentationMode = getReportPresentationMode(outputScope);
  const reportExperiences = outputScope.stories;
  const evidenceInventory = buildEvidenceInventoryReport(outputScope);
  const rows = buildReportRows(reportExperiences);
  const analysis = buildExperienceAnalysis(reportExperiences);
  const dataQuality = calculateDataQuality(reportExperiences);
  const routeGraph = buildReportExperienceMapGraph(reportExperiences);
  const mapRoutes = buildExperienceMapRoutes(routeGraph).map((route) => ({
    id: route.id,
    title: route.title,
    avgEnergy: route.avgEnergy,
    dominant: route.dominant,
    count: route.items.length,
    experiences: route.items.map((item) => ({
      id: item.id,
      title: item.label,
      category: displayCategory(item.category),
      energy: item.energy,
      date: item.timestamp,
    })),
  }));
  return {
    generatedAt: new Date().toISOString(),
    language: state.language,
    filters: { ...state.reportFilters },
    outputScope: {
      basis: outputScope.basis,
      presentationMode,
      stories: outputScope.stories.length,
      evidence: outputScope.evidence.length,
      context: outputScope.context.length,
      excludedUnclassifiedEvidence: outputScope.excludedUnclassifiedEvidence,
    },
    summary: {
      totalExperiences: reportExperiences.length,
      capturedHours: Number((reportExperiences.reduce((sum, item) => sum + Number(item.duration || 0), 0) / 60).toFixed(1)),
      averageEnergy: reportExperiences.length ? Number(average(reportExperiences.map((item) => Number(item.energy || 0))).toFixed(1)) : null,
      topCategory: reportExperiences.length ? displayCategory(getTopCategory(reportExperiences)) : "",
    },
    dataQuality,
    analysis,
    biometricContext: buildBiometricIntelligenceSummary(reportExperiences),
    evidenceInventory,
    integratedReading: buildIntegratedReportCards(reportExperiences, analysis, dataQuality, buildExperienceMapRoutes(routeGraph)),
    predictiveOutlook: buildPredictiveOutlook(reportExperiences, analysis, dataQuality),
    mapRoutes,
    eventTimeline: buildReportEventTimeline(reportExperiences),
    humanKpis: buildHumanKpis(reportExperiences, analysis, dataQuality),
    humanCorrelations: buildHumanCorrelations(reportExperiences, analysis),
    multimodalEvidence: buildReportMultimodalEvidence(reportExperiences, outputScope.evidence),
    contextEvidence: buildReportMultimodalEvidence([], outputScope.context),
    livingMemory: buildLivingMemoryLog(reportExperiences, analysis),
    categoryBreakdown: buildCategoryBreakdown(reportExperiences),
    blueprintCategoryReading: buildCategoryBreakdown(reportExperiences).map(buildBlueprintCategoryReading).filter(Boolean),
    energyTrend: buildEnergyTrendPoints(reportExperiences),
    rows,
  };
}

function downloadCsvReport() {
  const rows = buildReportRows();
  const headers = Object.keys(rows[0] || {
    fecha: "",
    titulo: "",
    "categoría": "",
    objetivo: "",
    "duración_min": "",
    energia: "",
    estado: "",
    "ubicación": "",
    personas: "",
    eventos: "",
    resumen_eventos: "",
    adjuntos: "",
    notas: "",
  });
  const csv = [
    headers.join(","),
    ...rows.map((row) => headers.map((header) => csvCell(row[header])).join(",")),
  ].join("\n");
  downloadBlob(new Blob([csv], { type: "text/csv;charset=utf-8" }), "reporte-experiencias.csv", csv);
  markReportExport("csv", buildReportExportPayload(), "ok");
  renderReportAcceptancePanel();
  notify(state.language !== "es" ? "Report CSV exported." : "CSV del reporte exportado.", "success");
}

