function renderPublicationFinalMediaItem(item) {
  const caption = renderPublicationMediaCaption(item);
  if (!item.url && !item.dataUrl) {
    return `<figure class="publication-file media-sync-missing">${renderPublicationMediaSyncNotice(item)}${caption}</figure>`;
  }
  const source = escapeHtml(item.url || item.dataUrl);
  if (item.type.startsWith("image/")) {
    return `<figure><img src="${source}" alt="${escapeHtml(item.name)}" loading="lazy" />${caption}${renderPublicationMediaAction(item)}</figure>`;
  }
  if (item.type.startsWith("video/")) {
    return `<figure><video src="${source}" controls muted playsinline preload="metadata"></video>${caption}${renderPublicationMediaAction(item)}</figure>`;
  }
  if (item.type.startsWith("audio/")) {
    return `<figure class="publication-audio"><audio src="${source}" controls preload="metadata"></audio>${caption}${renderPublicationMediaAction(item)}</figure>`;
  }
  return `<figure class="publication-file">${renderPublicationFileBadge(item)}${caption}${renderPublicationMediaAction(item)}</figure>`;
}

function renderPublicationReadiness(draft) {
  const readiness = buildPublicationReadiness(draft);
  const statusLabel = readiness.score >= 75 ? t("labels.publicationReady") : t("labels.publicationNeedsReview");
  return `
    <section class="publication-readiness">
      <div class="publication-readiness-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationReadiness"))}</h3>
          <span>${escapeHtml(statusLabel)}</span>
        </div>
        <strong>${readiness.score}%</strong>
      </div>
      <div class="publication-check-grid">
        ${readiness.checks
          .map(
            (check) => `
              <article>
                <span>${escapeHtml(check.label)}</span>
                <strong>${check.score}%</strong>
                <p>${escapeHtml(check.detail)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
      <div class="publication-suggestions">
        <strong>${escapeHtml(t("labels.publicationSuggestions"))}</strong>
        <ul>
          ${readiness.suggestions.map((suggestion) => `<li>${escapeHtml(suggestion)}</li>`).join("")}
        </ul>
      </div>
    </section>
  `;
}

function renderPublicationClosureChecklist(draft) {
  const readiness = buildPublicationReadiness(draft);
  const channelStatus = getPublicationChannelStatus(draft.channel);
  const words = countWords(`${draft.summary} ${draft.body}`);
  const limit = getPublicationWordLimit(PUBLICATION_OUTPUT_CHANNEL);
  const totalMedia = (draft.media || []).length;
  const includedMedia = getApprovedPublicationMedia(draft).length;
  const textReady = words >= 45 && words <= limit;
  const mediaReady = !channelBenefitsFromMedia(draft.channel) || includedMedia > 0;
  const items = [
    {
      label: t("labels.publicationClosureApproval"),
      ready: draft.approvalStatus === "approved",
      detail:
        draft.approvalStatus === "approved"
          ? t("labels.publicationClosureApprovalReady")
          : t("labels.publicationClosureApprovalReview"),
    },
    {
      label: t("labels.publicationClosureText"),
      ready: textReady,
      detail: textReady
        ? `${t("labels.publicationClosureTextReady")} ${words}/${limit}.`
        : `${t("labels.publicationClosureTextReview")} ${words}/${limit}.`,
    },
    {
      label: t("labels.publicationClosurePrivacy"),
      ready: Boolean(draft.privacy),
      detail: draft.privacy ? t("labels.publicationClosurePrivacyReady") : t("labels.publicationClosurePrivacyReview"),
    },
    {
      label: t("labels.publicationClosureMedia"),
      ready: mediaReady,
      detail: mediaReady
        ? `${t("labels.publicationClosureMediaReady")} ${includedMedia}/${totalMedia}.`
        : `${t("labels.publicationClosureMediaReview")} ${includedMedia}/${totalMedia}.`,
    },
    {
      label: t("labels.publicationClosureChannel"),
      ready: readiness.score >= 75 && channelStatus.level !== "future",
      detail:
        readiness.score >= 75 && channelStatus.level !== "future"
           ? `${t("labels.publicationClosureChannelReady")} ${readiness.score}%. ${channelStatus.detail}`
          : `${t("labels.publicationClosureChannelReview")} ${readiness.score}%. ${channelStatus.detail}`,
    },
  ];
  const readyCount = items.filter((item) => item.ready).length;
  const progress = t("labels.publicationClosureProgress").replace("{ready}", String(readyCount)).replace("{total}", String(items.length));
  return `
    <section class="publication-closure-checklist">
      <div class="publication-section-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationClosureTitle"))}</h3>
          <p class="card-meta">${escapeHtml(t("labels.publicationClosureHelp"))}</p>
        </div>
        <span>${escapeHtml(progress)}</span>
      </div>
      <div class="publication-closure-grid">
        ${items
          .map(
            (item) => `
              <article class="publication-closure-item ${item.ready ? "is-ready" : "is-review"}">
                <span>${escapeHtml(item.ready ? t("labels.publicationClosureReady") : t("labels.publicationClosureReview"))}</span>
                <strong>${escapeHtml(item.label)}</strong>
                <p>${escapeHtml(item.detail)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function buildPublicationReadiness(draft) {
  const words = countWords(`${draft.summary} ${draft.body}`);
  const includedMedia = getApprovedPublicationMedia(draft).length;
  const totalMedia = (draft.media || []).length;
  const readability = scorePublicationReadability(words, PUBLICATION_OUTPUT_CHANNEL);
  const privacyScore = draft.privacy ? 92 : 48;
  const mediaScore = totalMedia ? Math.round((includedMedia / totalMedia) * 100) : channelBenefitsFromMedia(PUBLICATION_OUTPUT_CHANNEL) ? 45 : 80;
  const channelScore = scorePublicationChannelFit(draft, words, includedMedia);
  const directScore = 92;
  const score = Math.round((readability.score + privacyScore + mediaScore + channelScore.score + directScore) / 5);
  const suggestions = buildPublicationSuggestions({ draft, words, includedMedia, totalMedia, readability, privacyScore, mediaScore, channelScore });
  return {
    score,
    checks: [
      { label: t("labels.publicationReadability"), score: readability.score, detail: readability.detail },
      {
        label: t("labels.publicationPrivacy"),
        score: privacyScore,
        detail: draft.privacy
          ? state.language !== "es"
              ? "Automatic cleanup is active."
             : "La limpieza automática está activa."
          : state.language !== "es"
             ? "Automatic cleanup is disabled."
            : "La limpieza automática está desactivada.",
      },
      {
        label: t("labels.publicationMediaUse"),
        score: mediaScore,
        detail: totalMedia
          ? state.language !== "es"
              ? `${includedMedia}/${totalMedia} media assets selected.`
             : `${includedMedia}/${totalMedia} activos multimedia seleccionados.`
          : state.language !== "es"
             ? "No linked media is available."
            : "No hay multimedia vinculada disponible.",
      },
      { label: t("labels.publicationChannelFit"), score: channelScore.score, detail: channelScore.detail },
      {
        label: state.language !== "es" ? "Final output" : "Salida final",
        score: directScore,
        detail: state.language !== "es"
          ? "The app now generates one edited chronological premium PDF. Distribution happens outside Vibe."
          : "La app genera un unico PDF premium cronologico y editado. La distribucion se hace fuera de Vibe.",
      },
    ],
    suggestions,
  };
}

function countWords(value) {
  return String(value || "").trim().split(/\s+/).filter(Boolean).length;
}

function scorePublicationReadability(words, channel) {
  const limit = getPublicationWordLimit(channel);
  if (words <= limit) {
    return {
      score: words < 45 ? 68 : 92,
      detail: state.language !== "es" ? `${words} words; length is manageable.` : `${words} palabras; la extensión es manejable.`,
    };
  }
  const overRatio = Math.min(1, (words - limit) / Math.max(1, limit));
  return {
    score: Math.max(45, Math.round(88 - overRatio * 45)),
    detail:
      state.language !== "es"
         ? `${words} words; recommended limit for ${channel}: ${limit}.`
        : `${words} palabras; límite recomendado para ${channel}: ${limit}.`,
  };
}

function getPublicationWordLimit(channel) {
  const limits = {
    WhatsApp: 180,
    Instagram: 160,
    Facebook: 220,
    LinkedIn: 300,
    Email: 420,
    "PDF/HTML": 650,
    "PDF revista premium": 1200,
    "Blog/Web": 900,
  };
  return limits[channel] || 280;
}

function channelBenefitsFromMedia(channel) {
  return ["Instagram", "Facebook", "LinkedIn", "PDF/HTML", "PDF revista premium", "Blog/Web"].includes(channel);
}

function scorePublicationChannelFit(draft, words, includedMedia) {
  const limit = getPublicationWordLimit(PUBLICATION_OUTPUT_CHANNEL);
  let score = words <= limit ? 88 : 60;
  if (channelBenefitsFromMedia(PUBLICATION_OUTPUT_CHANNEL)) score += includedMedia ? 8 : -18;
  score = Math.max(35, Math.min(100, score));
  return {
    score,
    detail:
      state.language !== "es"
         ? `${displayPublicationType(draft.type)} prepared as an edited chronological premium PDF.`
        : `${displayPublicationType(draft.type)} preparada como PDF premium cronologico y editado.`,
  };
}

function buildPublicationSuggestions({ draft, words, includedMedia, totalMedia, readability, privacyScore, mediaScore, channelScore }) {
  const suggestions = [];
  const limit = getPublicationWordLimit(PUBLICATION_OUTPUT_CHANNEL);
  if (words > limit) {
    suggestions.push(
      state.language !== "es"
         ? "Shorten the draft or move detail into a longer section before generating the PDF."
        : "Reduce el borrador o mueve el detalle a un reporte más largo antes de publicar.",
    );
  }
  if (privacyScore < 75) {
    suggestions.push(
      state.language !== "es"
         ? "Activate privacy cleanup and manually review names, faces, locations, and sensitive data."
        : "Activa la limpieza de privacidad y revisa manualmente nombres, rostros, ubicaciones y datos sensibles.",
    );
  }
  if (mediaScore < 70) {
    suggestions.push(
      totalMedia
        ? state.language !== "es"
            ? "Select the strongest media assets so the publication feels less text-heavy."
           : "Selecciona los activos multimedia más fuertes para que la publicación no dependa solo del texto."
        : state.language !== "es"
           ? "Add media to the source experiences when the PDF needs a more visual story."
          : "Agrega multimedia a las experiencias fuente cuando el PDF necesite una pieza más visual.",
    );
  }
  if (channelScore.score < 75 || readability.score < 75) {
    suggestions.push(
      state.language !== "es"
         ? "Review tone, length, and editorial order before generating the final PDF."
        : "Revisa el tono, la extension y el orden editorial antes de generar el PDF final.",
    );
  }
  if (!suggestions.length) {
    suggestions.push(
      state.language !== "es"
         ? "Perform a final human review before exporting or sharing."
        : "Haz una revisión humana final antes de exportar o compartir.",
    );
  }
  return suggestions.slice(0, 3);
}

function renderPublicationMedia(media) {
  if (!media.length) return `<p class="card-meta">${escapeHtml(t("labels.publicationMediaEmpty"))}</p>`;
  const included = media.filter((item) => item.included !== false).length;
  const selectionLabel = included === media.length
    ? (state.language !== "es" ? "All media included" : "Toda la multimedia incluida")
    : included === 0
      ? (state.language !== "es" ? "No media included" : "Sin multimedia incluida")
      : (state.language !== "es" ? `${included} selected manually` : `${included} seleccionados manualmente`);
  return `
    <section class="publication-media">
      <div class="publication-section-heading">
        <div>
          <h3>${escapeHtml(t("labels.publicationMedia"))} · ${included}/${media.length}</h3>
          <p class="card-meta">${escapeHtml(selectionLabel)}. ${escapeHtml(t("labels.publicationMediaHelp"))}</p>
        </div>
        <div class="pill-row publication-media-actions">
          <button class="secondary-button" type="button" data-publication-media-bulk="recommended">${escapeHtml(state.language !== "es" ? "Recommended" : "Recomendado")}</button>
          <button class="secondary-button" type="button" data-publication-media-bulk="all">${escapeHtml(state.language !== "es" ? "Include all" : "Incluir todo")}</button>
          <button class="secondary-button" type="button" data-publication-media-bulk="none">${escapeHtml(state.language !== "es" ? "No media" : "Sin multimedia")}</button>
        </div>
      </div>
      <div class="publication-media-grid">
        ${media.map(renderPublicationMediaItem).join("")}
      </div>
    </section>
  `;
}

function renderPublicationMediaItem(item) {
  const checked = item.included !== false ? "checked" : "";
  const stateClass = item.included === false ? "publication-media-excluded" : "";
  const control = `
    <label class="publication-media-toggle">
      <input type="checkbox" data-publication-media-id="${escapeHtml(item.id)}" ${checked} />
      <span>${escapeHtml(item.included === false ? t("labels.publicationMediaExcluded") : t("labels.publicationMediaIncluded"))}</span>
    </label>
  `;
  const caption = renderPublicationMediaCaption(item);
  if (!item.url && !item.dataUrl) {
    return `<figure class="publication-file ${stateClass} media-sync-missing">${renderPublicationMediaSyncNotice(item)}${caption}${control}</figure>`;
  }
  const source = escapeHtml(item.url || item.dataUrl);
  if (item.type.startsWith("image/")) {
    return `<figure class="${stateClass}"><img src="${source}" alt="${escapeHtml(item.name)}" loading="lazy" />${caption}${renderPublicationMediaAction(item)}${control}</figure>`;
  }
  if (item.type.startsWith("video/")) {
    return `<figure class="${stateClass}"><video src="${source}" controls muted playsinline preload="metadata"></video>${caption}${renderPublicationMediaAction(item)}${control}</figure>`;
  }
  if (item.type.startsWith("audio/")) {
    return `<figure class="publication-audio ${stateClass}"><audio src="${source}" controls preload="metadata"></audio>${caption}${renderPublicationMediaAction(item)}${control}</figure>`;
  }
  return `<figure class="publication-file ${stateClass}">${renderPublicationFileBadge(item)}${caption}${renderPublicationMediaAction(item)}${control}</figure>`;
}

function renderPublicationFileBadge(item) {
  return `
    <div class="publication-file-badge">
      <strong>${escapeHtml(getPublicationMediaKindLabel(item))}</strong>
      <span>${escapeHtml(state.language !== "es" ? "Referenced in the story, not embedded visually." : "Referenciado en la historia; no se incrusta como imagen.")}</span>
    </div>
  `;
}

function renderPublicationMediaAction(item) {
  const source = item.url || item.dataUrl || "";
  if (!source) return "";
  const label = getPublicationMediaActionLabel(item);
  const downloadName = item.name || "vibe-media";
  return `
    <a class="publication-media-action" href="${escapeHtml(source)}" target="_blank" rel="noopener noreferrer" download="${escapeHtml(downloadName)}">
      ${escapeHtml(label)}
    </a>
  `;
}

function getPublicationMediaActionLabel(item) {
  if (String(item.type || "").startsWith("image/")) return state.language !== "es" ? "Open image" : "Abrir imagen";
  if (String(item.type || "").startsWith("video/")) return state.language !== "es" ? "Open or download video" : "Abrir o descargar video";
  if (String(item.type || "").startsWith("audio/")) return state.language !== "es" ? "Open or download audio" : "Abrir o descargar audio";
  if (isArchiveLikePublicationMedia(item)) return state.language !== "es" ? "Download ZIP/archive" : "Descargar ZIP/archivo";
  return state.language !== "es" ? "Open or download file" : "Abrir o descargar archivo";
}

function getPublicationMediaKindLabel(item) {
  if (String(item.type || "").startsWith("image/")) return state.language !== "es" ? "Image" : "Imagen";
  if (String(item.type || "").startsWith("video/")) return state.language !== "es" ? "Video" : "Video";
  if (String(item.type || "").startsWith("audio/")) return state.language !== "es" ? "Audio" : "Audio";
  if (isArchiveLikePublicationMedia(item)) return "ZIP";
  return state.language !== "es" ? "Document" : "Documento";
}

function isArchiveLikePublicationMedia(item) {
  const text = `${item.name || ""} ${item.type || ""}`.toLowerCase();
  return /\b(zip|rar|7z)\b/.test(text) || /\.(zip|rar|7z)$/.test(text);
}

function renderPublicationMediaSyncNotice(item) {
  return `
    <div class="publication-media-sync">
      <strong>${escapeHtml(t("labels.attachmentNeedsSync"))}</strong>
      <small>${escapeHtml(t("labels.attachmentNeedsSyncDetail"))}</small>
    </div>
  `;
}

function renderPublicationMediaCaption(item) {
  const context = [item.translatedText, item.analyticalText, item.manualNote, item.originalText].filter(Boolean).join(" ");
  const tags = (item.tags || []).slice(0, 4);
  const roleLabel = item.publicationRoleLabel || getPublicationMediaRole(item, state.currentPublicationDraft || {}, 0).label;
  const roleDetail = item.publicationRoleDetail || "";
  const mediaRole = String(item.type || "").startsWith("image/")
    ? (state.language !== "es" ? "Visual asset: can be shown in the PDF." : "Activo visual: puede mostrarse en el PDF.")
    : (state.language !== "es" ? "Support asset: summarized here; open/download from the app or HTML." : "Activo de apoyo: se resume aquí; se abre o descarga desde la app o HTML.");
  return `
    <figcaption class="publication-media-caption">
      <strong title="${escapeHtml(item.name)}">${escapeHtml(item.name)}</strong>
      <span title="${escapeHtml(item.experienceTitle)}">${escapeHtml(item.experienceTitle)}</span>
      <span class="publication-provenance ${item.isDemo ? "is-demo" : "is-user"}">${escapeHtml(item.provenance || "")}</span>
      <small class="publication-media-role"><b>${escapeHtml(state.language !== "es" ? "Editorial role" : "Rol editorial")}:</b> ${escapeHtml(roleLabel)}${roleDetail ? ` - ${escapeHtml(roleDetail)}` : ""}</small>
      <small><b>${escapeHtml(state.language !== "es" ? "Use" : "Uso")}:</b> ${escapeHtml(mediaRole)}</small>
      ${
        context || tags.length
           ? `<small><b>${escapeHtml(t("labels.publicationMediaContext"))}:</b> ${escapeHtml(shortPublicationText(context || tags.join(", "), 260))}</small>`
          : ""
      }
    </figcaption>
  `;
}

async function handlePublicationDistributionCopy(event) {
  const button = event.target.closest("[data-publication-copy-kit]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const key = button.dataset.publicationCopyKit;
  const kit = buildPublicationDistributionKit(draft);
  const value = {
    subject: kit.subject,
    short: kit.shortCopy,
    long: kit.longCopy,
    caption: kit.caption,
  }[key];
  if (!value) return;
  const copied = await copyTextToClipboard(value);
  addPublicationHistory(draft, "exported", state.language !== "es" ? `Copied ${key}` : `Copiado ${key}`);
  persistPublicationDraft(draft);
  document.getElementById("publicationStatus").textContent = copied
    ? (state.language !== "es" ? "Text copied from the final PDF draft." : "Texto copiado desde el borrador final del PDF.")
    : (state.language !== "es" ? "Could not copy automatically. Select the text manually." : "No se pudo copiar automaticamente. Selecciona el texto manualmente.");
}

function handlePublicationMediaBulkAction(event) {
  const button = event.target.closest("[data-publication-media-bulk]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const mode = button.dataset.publicationMediaBulk;
  const include = mode === "all";
  draft.media = mode === "recommended"
    ? applyRecommendedPublicationMediaSelection(draft.media || [], draft)
    : refreshPublicationMediaRoles(draft.media || [], draft).map((item) => ({ ...item, included: include }));
  draft.pages = syncPublicationPagesWithMedia(draft);
  draft.stats = { ...(draft.stats || {}), media: draft.media.filter((item) => item.included !== false).length };
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(
    draft,
    "media",
    mode === "recommended"
      ? (state.language !== "es" ? "Recommended media selection applied" : "Seleccion recomendada de multimedia aplicada")
      : include
        ? (state.language !== "es" ? "All media included" : "Toda la multimedia incluida")
      : (state.language !== "es" ? "Publication without media" : "Publicacion sin multimedia"),
  );
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  renderPublications();
  document.getElementById("publicationStatus").textContent = mode === "recommended"
    ? (state.language !== "es" ? "Recommended media selection applied for this type and channel." : "Seleccion recomendada aplicada para este tipo y canal.")
    : include
      ? (state.language !== "es" ? "All media will be included in the publication." : "Toda la multimedia quedo incluida en la publicacion.")
    : (state.language !== "es" ? "The publication will be generated without media." : "La publicacion se generara sin multimedia.");
}

function handlePublicationMediaSelection(event) {
  const input = event.target.closest("[data-publication-media-id]");
  if (!input) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const mediaId = input.dataset.publicationMediaId;
  draft.media = refreshPublicationMediaRoles(draft.media || [], draft).map((item) => (item.id === mediaId ? { ...item, included: input.checked } : item));
  draft.pages = syncPublicationPagesWithMedia(draft);
  draft.stats = { ...(draft.stats || {}), media: draft.media.filter((item) => item.included !== false).length };
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "media", input.checked ? t("labels.publicationMediaIncluded") : t("labels.publicationMediaExcluded"));
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  renderPublications();
}

function handlePublicationDraftEdit(event) {
  const pageField = event.target.closest("[data-publication-page-field]");
  if (pageField) {
    const draft = state.currentPublicationDraft || state.publicationDrafts[0];
    if (!draft) return;
    const index = Number(pageField.dataset.publicationPageIndex);
    const key = pageField.dataset.publicationPageField;
    if (!Number.isInteger(index) || !["title", "subtitle", "body"].includes(key)) return;
    const pages = normalizePublicationPages(draft);
    if (!pages[index]) return;
    pages[index] = { ...pages[index], [key]: pageField.value, editedManually: true };
    draft.pages = pages;
    draft.approvalStatus = "review";
    draft.approvedAt = "";
    addPublicationHistory(draft, "edited", state.language !== "es" ? `Page ${index + 1}` : `Pagina ${index + 1}`, { coalesceMs: 15000 });
    state.currentPublicationDraft = draft;
    state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
    savePublicationDrafts();
    document.getElementById("publicationStatus").textContent = t("labels.publicationSaved");
    refreshPublicationFinalDocumentOnly(draft);
    renderPublicationDraftListOnly();
    return;
  }
  const field = event.target.closest("[data-publication-field]");
  if (!field) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const key = field.dataset.publicationField;
  if (!["title", "summary", "body"].includes(key)) return;
  draft[key] = field.value;
  draft.pages = syncPublicationDraftPagesFromTopLevel(draft, key);
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "edited", t(`labels.publication${key.charAt(0).toUpperCase() + key.slice(1)}Field`) || key, { coalesceMs: 15000 });
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = t("labels.publicationSaved");
  document.querySelectorAll(`[data-publication-final="${key}"]`).forEach((node) => {
    node.textContent = draft[key];
  });
  refreshPublicationFinalDocumentOnly(draft);
  renderPublicationDraftListOnly();
}

function handlePublicationTemplateClick(event) {
  const button = event.target.closest("[data-publication-template]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  const template = publicationTemplates.find((item) => item.id === button.dataset.publicationTemplate);
  if (!draft || !template) return;
  draft.templateId = template.id;
  draft.type = template.type;
  draft.style = template.style;
  draft.channel = PUBLICATION_OUTPUT_CHANNEL;
  draft.approvalStatus = "review";
  draft.approvedAt = "";
  addPublicationHistory(draft, "template", `${displayPublicationType(template.type)} · ${displayPublicationStyle(template.style)} · ${PUBLICATION_OUTPUT_CHANNEL}`);
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  document.getElementById("publicationTypeInput").value = template.type;
  document.getElementById("publicationStyleInput").value = template.style;
  document.getElementById("publicationChannelInput").value = PUBLICATION_OUTPUT_CHANNEL;
  draft.body = applyPublicationTemplateStructure(draft, template);
  draft.media = refreshPublicationMediaRoles(draft.media || [], draft);
  draft.pages = syncPublicationPagesWithMedia(draft);
  draft.stats = { ...(draft.stats || {}), media: draft.media.filter((item) => item.included !== false).length };
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = t("labels.publicationTemplateSelected");
  renderPublications();
}

function applyPublicationTemplateStructure(draft, template = {}) {
  const body = String(draft?.body || "").trim();
  const title = draft?.title || "Publicacion";
  const mediaCount = (draft?.media || []).filter((item) => item.included !== false).length;
  const guides = {
    clinical: ["Resumen claro para compartir", "Datos observados y documentos revisados", "Preguntas o puntos por confirmar", "Nota de cuidado"],
    travel: ["Portada del viaje", "Ruta y momentos memorables", "Galeria comentada", "Recomendaciones para recordar o compartir"],
    learning: ["Tema aprendido", "Evidencia y ejemplos", "Ideas que vale la pena repetir", "Siguiente practica sugerida"],
    family: ["Recuerdo principal", "Personas y momentos", "Fotos, audios o videos seleccionados", "Cierre emocional"],
    sequence: ["Gancho inicial", "Escenas sugeridas", "Texto en pantalla", "Cierre breve"],
    album: ["Portada de memoria", "Galeria seleccionada", "Momentos y personas", "Recuerdo final"],
    business: ["Resumen ejecutivo", "Hallazgos principales", "Evidencia", "Proximas acciones"],
    visual: ["Mensaje principal", "Imagen o activo protagonista", "Texto breve para publicar", "Cierre"],
    editorial: ["Apertura narrativa", "Contexto", "Momentos y evidencia", "Lectura final"],
    carousel: ["Lamina 1: portada", "Laminas 2-4: momentos visuales", "Lamina 5: aprendizaje o dato", "Lamina final: cierre"],
    carouselBusiness: ["Problema o contexto", "Evidencia principal", "Hallazgo", "Recomendacion", "Cierre profesional"],
    letter: ["Saludo", "Contexto humano", "Relato principal", "Anexos o medios", "Cierre personal"],
    dossier: ["Portada", "Resumen ejecutivo", "Capitulos de la experiencia", "Evidencia multimedia", "Recomendaciones", "Anexos"],
    health: ["Motivo de la consulta", "Datos observados", "Documentos o biometria", "Preguntas para revisar", "Proximo paso"],
    blog: ["Titulo editorial", "Entrada", "Desarrollo con evidencia", "Galeria o anexos", "Cierre"],
  };
  const sections = guides[template.tone] || guides.editorial;
  if (sections.some((section) => body.includes(section))) return body;
  const firstBlock = body || (state.language !== "es" ? "Edit this block with the final publication text." : "Edita este bloque con el texto final de la publicacion.");
  return `${title}

${sections.map((section, index) => `${index + 1}. ${section}
${index === 0 ? firstBlock : (state.language !== "es" ? "Edit this block before exporting." : "Edita este bloque antes de exportar.")}`).join("\n\n")}

${state.language !== "es" ? "Selected media" : "Multimedia seleccionada"}: ${mediaCount} activos.`;
}

function handlePublicationApprovalClick(event) {
  const button = event.target.closest("[data-publication-approval]");
  if (!button) return;
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) return;
  const approved = button.dataset.publicationApproval === "approved";
  draft.approvalStatus = approved ? "approved" : "review";
  draft.approvedAt = approved ? new Date().toISOString() : "";
  addPublicationHistory(draft, "approval", displayPublicationApprovalStatus(draft.approvalStatus));
  state.currentPublicationDraft = draft;
  state.publicationDrafts = state.publicationDrafts.map((item) => (item.id === draft.id ? draft : item));
  savePublicationDrafts();
  document.getElementById("publicationStatus").textContent = approved
    ? t("labels.publicationApprovedMessage")
    : t("labels.publicationReviewMessage");
  renderPublications();
}

function renderPublicationDraftListOnly() {
  document.getElementById("publicationCount").textContent = `${state.publicationDrafts.length} ${t("labels.items")}`;
  document.getElementById("publicationDraftList").innerHTML = state.publicationDrafts.length
    ? state.publicationDrafts.map(renderPublicationDraftItem).join("")
    : `<p class="card-meta">${t("labels.publicationHistoryEmpty")}</p>`;
}

function renderPublicationDraftItem(draft) {
  return `
    <article class="publication-draft-item">
      <button class="ghost-button" type="button" data-publication-action="open" data-publication-id="${escapeHtml(draft.id)}">
        <strong>${escapeHtml(draft.title)}</strong>
        <span>${escapeHtml(formatDate(draft.createdAt))} · ${escapeHtml(displayPublicationType(draft.type))}</span>
      </button>
      <button class="danger-button" type="button" data-publication-action="delete" data-publication-id="${escapeHtml(draft.id)}">${t("buttons.delete")}</button>
    </article>
  `;
}

function handlePublicationDraftAction(event) {
  const button = event.target.closest("[data-publication-action]");
  if (!button) return;
  const draft = state.publicationDrafts.find((item) => item.id === button.dataset.publicationId);
  if (!draft) return;
  if (button.dataset.publicationAction === "open") {
    state.currentPublicationDraft = draft;
  } else if (button.dataset.publicationAction === "delete") {
    state.publicationDrafts = state.publicationDrafts.filter((item) => item.id !== draft.id);
    if (state.currentPublicationDraft?.id === draft.id) state.currentPublicationDraft = state.publicationDrafts[0] || null;
    savePublicationDrafts();
  }
  renderPublications();
}

function exportCurrentPublicationHtml() {
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) {
    document.getElementById("publicationStatus").textContent = t("labels.publicationEmpty");
    return;
  }
  const warning = draft.approvalStatus !== "approved" ? t("labels.publicationExportReviewWarning") : "";
  addPublicationHistory(draft, "exported", "HTML");
  persistPublicationDraft(draft);
  const html = buildPublicationHtml(draft);
  downloadPublicationBlob(new Blob([html], { type: "text/html;charset=utf-8" }), "publicacion-inteligente.html", warning);
}

function buildPublicationExportDraft(draft) {
  const exportDraft = { ...draft, pages: normalizePublicationPages(draft) };
  ["title", "summary", "body"].forEach((key) => {
    exportDraft.pages = syncPublicationDraftPagesFromTopLevel(exportDraft, key);
  });
  return {
    ...exportDraft,
    distributionKit: buildPublicationDistributionKit(draft),
    channelStudio: buildPublicationChannelStudio(draft),
  };
}

async function exportCurrentPublicationPdf() {
  const draft = state.currentPublicationDraft || state.publicationDrafts[0];
  if (!draft) {
    document.getElementById("publicationStatus").textContent = t("labels.publicationEmpty");
    return;
  }
  const warning = draft.approvalStatus !== "approved" ? t("labels.publicationExportReviewWarning") : "";
  if (!state.apiOnline) {
    setPublicationProgress({
      title: t("labels.publicationProgressApiCheck"),
      detail: t("labels.publicationProgressApiCheckDetail"),
      percent: 8,
    });
  }
  if (!(await ensureApiOnlineForExport())) {
    document.getElementById("publicationStatus").textContent = t("labels.publicationProgressApiUnavailable");
    failPublicationProgress(document.getElementById("publicationStatus").textContent);
    notify(document.getElementById("publicationStatus").textContent, "error");
    return;
  }
  try {
    document.getElementById("publicationStatus").textContent = state.language !== "es" ? "Generating edited ReportLab publication PDF..." : "Generando PDF editado ReportLab de publicacion...";
    setPublicationProgress({
      title: t("labels.publicationProgressPdfStart"),
      detail: t("labels.publicationProgressPdfStartDetail"),
      percent: 15,
    });
    const blob = await generatePublicationPdfBlob(draft);
    setPublicationProgress({
      title: t("labels.publicationProgressPdfDownload"),
      detail: t("labels.publicationProgressPdfDownloadDetail"),
      percent: 80,
    });
    addPublicationHistory(draft, "exported", "PDF ReportLab");
    persistPublicationDraft(draft);
    downloadPublicationBlob(blob, "publicacion-inteligente.pdf", warning);
    finishPublicationProgress("publicacion-inteligente.pdf");
    document.getElementById("publicationStatus").textContent = state.language !== "es" ? "Edited ReportLab publication PDF generated." : "PDF editado ReportLab de publicacion generado.";
  } catch (error) {
    console.warn("Publication PDF export failed", error);
    const detail = getExportErrorDetail(error);
    document.getElementById("publicationStatus").textContent = state.language !== "es" ? `ReportLab PDF failed. Detail: ${detail}` : `Fallo el PDF ReportLab. Detalle: ${detail}`;
    failPublicationProgress(document.getElementById("publicationStatus").textContent);
    notify(document.getElementById("publicationStatus").textContent, "error");
  }
}

async function generatePublicationPdfBlob(draft) {
  const html = buildPublicationHtml(draft);
  const exportDraft = buildPublicationExportDraft(draft);
  setPublicationProgress({
    title: t("labels.publicationProgressPdfServer"),
    detail: t("labels.publicationProgressPdfServerDetail"),
    percent: 45,
  });
  const response = await fetch(`${API_BASE}/publication/pdf`, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...authHeader() },
    body: JSON.stringify({ html, draft: exportDraft, title: draft.title, language: state.language }),
  });
  if (!response.ok) throw new Error(await response.text());
  return response.blob();
}

