function buildReportRows(experiences = getReportOutputScope().stories) {
  return experiences.map((item) => ({
    fecha: formatDate(item.timestamp),
    titulo: item.title,
    "categoría": displayCategory(item.category),
    origen: getIntegrationSourceProfile(item).active ? getIntegrationSourceProfile(item).family : "PWA / manual",
    objetivo: item.objective || "",
    "duración_min": item.duration,
    energia: item.energy,
    estado: item.mood,
    "ubicación": item.location,
    personas: item.people,
    eventos: getExperienceEventTimeline(item).length,
    resumen_eventos: buildExperienceEventSummary(item),
    adjuntos: item.attachments?.length || 0,
    notas: item.notes,
  }));
}

function getReportExperiences() {
  if (state.reportFilters.scope === "single") {
    const selected = state.experiences.find((item) => item.id === state.reportFilters.experienceId);
    return selected && !isSupersededExperience(selected) ? [selected] : [];
  }
  const now = Date.now();
  const scope = state.reportFilters.scope || "all";
  const periodDays = ["period", "filters"].includes(scope) && state.reportFilters.period !== "all" ? Number(state.reportFilters.period) : null;
  const since = periodDays ? now - periodDays * 24 * 60 * 60 * 1000 : null;
  return [...state.experiences]
    .filter((item) => {
      if (isSupersededExperience(item)) return false;
      const dateMatch = !since || new Date(item.timestamp).getTime() >= since;
      const customDateMatch = experienceMatchesDateRange(item, state.reportFilters.dateFrom || "", state.reportFilters.dateTo || "");
      const useFieldFilters = scope === "filters";
      const categoryMatch = !useFieldFilters || state.reportFilters.category === "all" || item.category === state.reportFilters.category;
      const sourceMatch = !useFieldFilters || experienceMatchesIntegrationSource(item, state.reportFilters.source || "all");
      const participantMatch =
        !state.reportFilters.pilotParticipantId ||
        state.reportFilters.pilotParticipantId === "all" ||
        experienceMatchesPilotParticipant(item, state.reportFilters.pilotParticipantId);
      const peopleText = `${item.people || ""}`.toLowerCase();
      const objectiveText = `${item.objective || ""}`.toLowerCase();
      const eventText = buildExperienceEventSearchText(item).toLowerCase();
      const peopleMatch = !useFieldFilters || !state.reportFilters.people || peopleText.includes(state.reportFilters.people);
      const objectiveMatch = !useFieldFilters || !state.reportFilters.objective || objectiveText.includes(state.reportFilters.objective);
      const eventMatch = !useFieldFilters || !state.reportFilters.eventQuery || eventText.includes(state.reportFilters.eventQuery);
      return dateMatch && customDateMatch && categoryMatch && sourceMatch && participantMatch && peopleMatch && objectiveMatch && eventMatch;
    })
    .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
}

function csvCell(value) {
  return `"${String(value || "").replace(/"/g, '""')}"`;
}

function downloadBlob(blob, filename, serverContent = null, options = {}) {
  const url = URL.createObjectURL(blob);
  if (state.lastDownloadUrl) URL.revokeObjectURL(state.lastDownloadUrl);
  state.lastDownloadUrl = url;
  state.lastDownload = {
    filename,
    url,
    type: blob.type || "application/octet-stream",
    at: new Date().toISOString(),
  };
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  link.style.display = "none";
  document.body.appendChild(link);
  link.click();
  setTimeout(() => link.remove(), 1000);
  if (serverContent !== null) saveExportToProjectFolder(filename, serverContent);
  if (!options.skipObsidian) syncMarkdownBlobToObsidian(blob, filename, { source: "download" });
}

function isMarkdownExport(blob, filename = "") {
  return /\.m(?:d|arkdown)$/i.test(String(filename || ""))
    || String(blob?.type || "").toLowerCase().includes("text/markdown");
}

function inferObsidianTargetForFilename(filename = "") {
  const normalized = String(filename || "").toLowerCase();
  if (/publicacion|publication/.test(normalized)) return "publications";
  if (/hallazgo|insight|finding|reporte|report/.test(normalized)) return "generated_report";
  if (/mapa|map|obsidian/.test(normalized)) return "generated_map";
  if (/manual|guia|guide/.test(normalized)) return "manual";
  if (/experiencia|experience/.test(normalized)) return "experiences";
  if (/biometr|health|oura|apple-health/.test(normalized)) return "biometrics";
  if (/activo|asset|multimedia/.test(normalized)) return "assets";
  return "inbox";
}

const LOCAL_OBSIDIAN_DB_NAME = "vibepwa-local-obsidian";
const LOCAL_OBSIDIAN_STORE_NAME = "handles";
const LOCAL_OBSIDIAN_HANDLE_KEY = "vault";
const RECOMMENDED_OBSIDIAN_VAULT_PATH = "C:\\Users\\msusf\\Documents\\Codex\\2026-05-09\\files-mentioned-by-the-user-meta\\obsidian-vault-vibe";

function supportsLocalObsidianVault() {
  return Boolean(window.showDirectoryPicker && window.indexedDB);
}

function openLocalObsidianDb() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(LOCAL_OBSIDIAN_DB_NAME, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore(LOCAL_OBSIDIAN_STORE_NAME);
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("indexeddb_open_failed"));
  });
}

async function readLocalObsidianHandle() {
  if (!supportsLocalObsidianVault()) return null;
  const db = await openLocalObsidianDb();
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(LOCAL_OBSIDIAN_STORE_NAME, "readonly");
      const request = tx.objectStore(LOCAL_OBSIDIAN_STORE_NAME).get(LOCAL_OBSIDIAN_HANDLE_KEY);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error || new Error("indexeddb_read_failed"));
    });
  } finally {
    db.close();
  }
}

async function writeLocalObsidianHandle(handle) {
  if (!supportsLocalObsidianVault()) return;
  const db = await openLocalObsidianDb();
  try {
    await new Promise((resolve, reject) => {
      const tx = db.transaction(LOCAL_OBSIDIAN_STORE_NAME, "readwrite");
      tx.objectStore(LOCAL_OBSIDIAN_STORE_NAME).put(handle, LOCAL_OBSIDIAN_HANDLE_KEY);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error("indexeddb_write_failed"));
    });
  } finally {
    db.close();
  }
}

async function deleteLocalObsidianHandle() {
  if (!supportsLocalObsidianVault()) return;
  const db = await openLocalObsidianDb();
  try {
    await new Promise((resolve, reject) => {
      const tx = db.transaction(LOCAL_OBSIDIAN_STORE_NAME, "readwrite");
      tx.objectStore(LOCAL_OBSIDIAN_STORE_NAME).delete(LOCAL_OBSIDIAN_HANDLE_KEY);
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error("indexeddb_delete_failed"));
    });
  } finally {
    db.close();
  }
}

async function ensureLocalObsidianPermission(handle, mode = "readwrite") {
  if (!handle?.queryPermission || !handle?.requestPermission) return "denied";
  const options = { mode };
  let permission = await handle.queryPermission(options);
  if (permission !== "granted") permission = await handle.requestPermission(options);
  return permission;
}

async function hasChildDirectoryHandle(parentHandle, name) {
  try {
    await parentHandle.getDirectoryHandle(name, { create: false });
    return true;
  } catch {
    return false;
  }
}

async function hasObsidianMarkerDirectory(handle) {
  return hasChildDirectoryHandle(handle, ".obsidian");
}

async function resolveLocalObsidianVaultHandle(selectedHandle) {
  if (!selectedHandle) throw new Error("obsidian_vault_not_selected");
  if (await hasObsidianMarkerDirectory(selectedHandle)) {
    return { handle: selectedHandle, correctedFromParent: false };
  }
  const childVaults = [];
  if (selectedHandle.values) {
    for await (const entry of selectedHandle.values()) {
      if (entry.kind !== "directory") continue;
      if (await hasObsidianMarkerDirectory(entry)) childVaults.push(entry);
    }
  }
  if (childVaults.length === 1) {
    return { handle: childVaults[0], correctedFromParent: true, parentName: selectedHandle.name || "" };
  }
  if (childVaults.length > 1) throw new Error("obsidian_multiple_vaults_found");
  throw new Error("obsidian_vault_marker_missing");
}

async function ensureConnectedLocalObsidianVaultHandle() {
  const vault = state.localObsidianVault || {};
  if (!vault.handle || !supportsLocalObsidianVault()) throw new Error("obsidian_vault_not_connected");
  const resolved = await resolveLocalObsidianVaultHandle(vault.handle);
  const permission = await ensureLocalObsidianPermission(resolved.handle);
  if (permission !== "granted") {
    state.localObsidianVault = { ...vault, connected: false, permission, lastError: "permission_required" };
    renderLocalObsidianVaultStatus();
    throw new Error("obsidian_vault_permission_required");
  }
  if (resolved.handle !== vault.handle || !vault.connected || vault.name !== resolved.handle.name) {
    state.localObsidianVault = {
      ...vault,
      handle: resolved.handle,
      connected: true,
      permission,
      name: resolved.handle.name || "Obsidian",
      correctedFromParent: Boolean(resolved.correctedFromParent),
      parentName: resolved.parentName || vault.parentName || "",
      lastError: "",
    };
    await writeLocalObsidianHandle(resolved.handle).catch(() => {});
    renderLocalObsidianVaultStatus();
  }
  return resolved.handle;
}

async function loadStoredLocalObsidianVault() {
  if (!supportsLocalObsidianVault()) {
    state.localObsidianVault = {
      ...(state.localObsidianVault || {}),
      connected: false,
      permission: "unsupported",
      lastError: "unsupported_browser",
    };
    renderLocalObsidianVaultStatus();
    return;
  }
  try {
    const handle = await readLocalObsidianHandle();
    if (!handle) {
      renderLocalObsidianVaultStatus();
      return;
    }
    const resolved = await resolveLocalObsidianVaultHandle(handle);
    const permission = await ensureLocalObsidianPermission(resolved.handle);
    state.localObsidianVault = {
      ...(state.localObsidianVault || {}),
      handle: resolved.handle,
      connected: permission === "granted",
      permission,
      name: resolved.handle.name || "Obsidian",
      correctedFromParent: Boolean(resolved.correctedFromParent),
      parentName: resolved.parentName || "",
      lastError: permission === "granted" ? "" : "permission_required",
    };
    if (resolved.handle !== handle) await writeLocalObsidianHandle(resolved.handle).catch(() => {});
  } catch (error) {
    state.localObsidianVault = {
      ...(state.localObsidianVault || {}),
      connected: false,
      permission: "error",
      lastError: error.message,
    };
  }
  renderLocalObsidianVaultStatus();
}

async function connectLocalObsidianVault() {
  if (!supportsLocalObsidianVault()) {
    notify(
      languageText(
        "Este navegador no permite conectar carpetas locales. Usa Chrome o Edge en el PC.",
        "This browser cannot connect local folders. Use Chrome or Edge on the PC.",
        "Ce navigateur ne peut pas connecter de dossiers locaux. Utilise Chrome ou Edge sur le PC.",
        "Este navegador nao permite conectar pastas locais. Use Chrome ou Edge no PC.",
      ),
      "warn",
    );
    renderLocalObsidianVaultStatus();
    return;
  }
  try {
    const handle = await window.showDirectoryPicker({
      id: "vibe-obsidian-vault",
      mode: "readwrite",
      startIn: "documents",
    });
    const resolved = await resolveLocalObsidianVaultHandle(handle);
    const permission = await ensureLocalObsidianPermission(resolved.handle);
    if (permission !== "granted") throw new Error("permission_denied");
    await writeLocalObsidianHandle(resolved.handle);
    state.localObsidianVault = {
      ...(state.localObsidianVault || {}),
      handle: resolved.handle,
      connected: true,
      permission,
      name: resolved.handle.name || "Obsidian",
      correctedFromParent: Boolean(resolved.correctedFromParent),
      parentName: resolved.parentName || "",
      lastError: "",
    };
    renderLocalObsidianVaultStatus();
    notify(
      languageText(
        `Bóveda local conectada: ${state.localObsidianVault.name}. Los Markdown se guardarán ahí.`,
        `Local vault connected: ${state.localObsidianVault.name}. Markdown exports will be saved there.`,
        `Bóveda locale connectée : ${state.localObsidianVault.name}. Les exports Markdown y seront enregistrés.`,
        `Cofre local conectado: ${state.localObsidianVault.name}. Os Markdown serao salvos ali.`,
      ),
      "success",
    );
  } catch (error) {
    state.localObsidianVault = {
      ...(state.localObsidianVault || {}),
      connected: false,
      permission: "denied",
      lastError: error.message,
    };
    renderLocalObsidianVaultStatus();
    notify(
      languageText(
        "No se conectó la bóveda local. La descarga normal sigue disponible.",
        "The local vault was not connected. Normal download remains available.",
        "La bóveda locale n'a pas été connectée. Le téléchargement normal reste disponible.",
        "O cofre local nao foi conectado. O download normal continua disponivel.",
      ),
      "warn",
    );
  }
}

