            <button class="primary-button" type="button" data-core-mvp-action="finish-real-session" ${canFinishSession ? "" : "disabled"} title="${escapeHtml(canFinishSession ? labels.finishSession : labels.finishBlocked)}">${escapeHtml(labels.finishSession)}</button>
