function buildMultiDevicePersistenceChecks() {
  const host = window.location.hostname;
  const isPublishedHost = Boolean(host && !["localhost", "127.0.0.1", "::1"].includes(host));
  const storage = calculateAssetStorageReadiness();
  const hasBackup = Boolean(state.backupAudit?.at);
  const supabaseConfigured = Boolean(state.config?.persistence === "supabase" || state.persistence === "supabase");
  const authReady = Boolean(state.session?.access_token);
  const remoteDataReady = supabaseConfigured && state.apiOnline;
  const storageReady = !storage.total || storage.pendingSync === 0;
  const cloudServerReady = Boolean(state.health?.cloudReady || state.health?.deploymentMode === "production");
  const labels = state.language !== "es"
     ? {
        ready: "Ready",
        review: "Review",
        remote: "Remote persistence",
        remoteDetail: remoteDataReady ? "The app is connected to Supabase through the local API." : "Supabase persistence must be active before multiple devices share data.",
        auth: "User identity",
        authDetail: authReady ? "Supabase Auth session is active." : "Sign in is required so each device reads and writes as the same user.",
        storage: "Private media storage",
        storageDetail: storageReady ? "Current assets have no pending private Storage sync." : `${storage.pendingSync} assets still need remote Storage sync.`,
        cloud: "Cloud server mode",
        cloudDetail: cloudServerReady ? "The backend reports a production/cloud-ready bind." : "For deployment, set HOST=0.0.0.0 and NODE_ENV=production.",
        published: "Published URL",
        publishedDetail: isPublishedHost ? `Running from ${host}.` : "Still running on localhost; mobile/tablet access needs a deployed URL or LAN/PWA setup.",
        backup: "Backup and restore",
        backupDetail: hasBackup ? "Recent backup or restore audit exists." : "Create one backup before moving users across devices.",
        report: "Reports anywhere",
        reportDetail: remoteDataReady ? "Reports can use shared data once opened from the deployed app." : "Reports remain local until Supabase persistence is active.",
      }
    : {
        ready: "Listo",
        review: "Revisar",
        remote: "Persistencia remota",
        remoteDetail: remoteDataReady ? "La app está conectada a Supabase a través de la API local." : "La persistencia Supabase debe estar activa para compartir datos entre dispositivos.",
        auth: "Identidad de usuario",
        authDetail: authReady ? "La sesión de Supabase Auth está activa." : "Se requiere iniciar sesión para que cada dispositivo lea y escriba como el mismo usuario.",
        storage: "Storage privado de archivos",
        storageDetail: storageReady ? "Los activos actuales no tienen sincronización pendiente con Storage privado." : `${storage.pendingSync} activos requieren sincronización remota con Storage.`,
        cloud: "Modo servidor cloud",
        cloudDetail: cloudServerReady ? "El backend reporta configuración productiva o lista para cloud." : "Para desplegar, define HOST=0.0.0.0 y NODE_ENV=production.",
        published: "URL publicada",
        publishedDetail: isPublishedHost ? `Ejecutándose desde ${host}.` : "Aún se ejecuta en localhost; móvil/tablet requieren una URL desplegada o configuración LAN/PWA.",
        backup: "Respaldo y restauración",
        backupDetail: hasBackup ? "Existe auditoría reciente de respaldo o restauración." : "Crea un respaldo antes de mover usuarios entre dispositivos.",
        report: "Reportes en cualquier dispositivo",
        reportDetail: remoteDataReady ? "Los reportes podrán usar datos compartidos al abrirse desde la app desplegada." : "Los reportes siguen siendo locales hasta activar persistencia Supabase.",
      };
  return [
    { key: "remote", label: labels.remote, detail: labels.remoteDetail, ok: remoteDataReady, view: "admin", focus: "supabasePilotGatePanel" },
    { key: "auth", label: labels.auth, detail: labels.authDetail, ok: authReady, view: "auth" },
    { key: "storage", label: labels.storage, detail: labels.storageDetail, ok: storageReady, view: "admin", focus: "assetProcessingActionPlan" },
    { key: "cloud", label: labels.cloud, detail: labels.cloudDetail, ok: cloudServerReady, view: "admin", focus: "publishPlanPanel" },
    { key: "published", label: labels.published, detail: labels.publishedDetail, ok: isPublishedHost, view: "admin", focus: "publishPlanPanel" },
    { key: "backup", label: labels.backup, detail: labels.backupDetail, ok: hasBackup, view: "admin", focus: "pilotClosureRecordPanel" },
    { key: "reports", label: labels.report, detail: labels.reportDetail, ok: remoteDataReady, view: "report" },
  ].map((check) => ({ ...check, readyLabel: labels.ready, reviewLabel: labels.review }));
}

function renderMultiDevicePersistencePanel() {
  const container = document.getElementById("multiDevicePersistencePanel");
  if (!container) return;
  const checks = buildMultiDevicePersistenceChecks();
  const readiness = summarizeReadiness(checks.map((check) => check.ok));
  const next = checks.find((check) => !check.ok);
  const labels = state.language !== "es"
     ? {
        title: "Multi-Device Persistence",
        subtitle: "Gate for using the same app from desktop, mobile, and tablet without losing ownership, files, or report history.",
        score: `${readiness.ready}/${readiness.total} controls ready`,
        next: "Next required step",
        allReady: "Ready for private multi-device validation.",
        open: "Open",
      }
    : {
        title: "Persistencia multidispositivo",
        subtitle: "Compuerta para usar la misma app desde desktop, móvil y tablet sin perder dueño, archivos ni historial de reportes.",
        score: `${readiness.ready}/${readiness.total} controles listos`,
        next: "Siguiente paso requerido",
        allReady: "Lista para validación privada multidispositivo.",
        open: "Abrir",
      };
  container.innerHTML = `
    <section>
      <div class="multi-device-heading">
        <div>
          <h3>${escapeHtml(labels.title)}</h3>
          <p>${escapeHtml(labels.subtitle)}</p>
        </div>
        <strong class="${readiness.score >= 85 ? "status-ok" : "status-warn"}">${escapeHtml(`${readiness.score}%`)}</strong>
      </div>
      <div class="multi-device-next ${next ? "" : "is-ready"}">
        <div>
          <strong>${escapeHtml(labels.next)}</strong>
          <p>${escapeHtml(next ? `${next.label}: ${next.detail}` : labels.allReady)}</p>
        </div>
        ${next ? `<button class="primary-button" type="button" data-backlog-view="${escapeHtml(next.view || "admin")}" data-backlog-focus="${escapeHtml(next.focus || "")}">${escapeHtml(labels.open)}</button>` : ""}
      </div>
      <p class="multi-device-score">${escapeHtml(labels.score)}</p>
      <div class="multi-device-grid">
        ${checks
          .map(
            (check) => `
              <article class="${check.ok ? "is-ready" : "is-review"}">
                <span class="${check.ok ? "status-ok" : "status-warn"}">${escapeHtml(check.ok ? check.readyLabel : check.reviewLabel)}</span>
                <strong>${escapeHtml(check.label)}</strong>
                <p>${escapeHtml(check.detail)}</p>
                <button class="ghost-button" type="button" data-backlog-view="${escapeHtml(check.view || "admin")}" data-backlog-focus="${escapeHtml(check.focus || "")}">${escapeHtml(labels.open)}</button>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

