function handleProductSettingsAction(event) {
  const button = event.target.closest("[data-product-settings-action]");
  if (!button) return;
  const action = button.dataset.productSettingsAction;
  const actions = {
    refresh: reloadCurrentAppVersion,
    voice: startVoiceCommand,
    backup: exportLocalBackup,
    restore: openRestoreBackupPicker,
    sync: syncOfflineQueue,
    verify: runSupabaseDiagnostics,
    selftest: runSupabaseSelfTest,
    privacy: applyRecommendedPrivacySettings,
    "show-key": toggleLocalKeyVisibility,
    "apply-key": applyLocalKeyToCurrentData,
    unlock: unlockLocalData,
    "load-demo": loadDemoData,
    "clear-demo": clearDemoData,
    "clear-local": clearLocalData,
    "reset-cloud": resetCloudDataForFreshStart,
  };
  actions[action]?.();
  window.setTimeout(renderProductSettingsPanel, 50);
}

function handleDashboardPrimaryAction(event) {
  const action = event.target.closest("[data-dashboard-action]")?.dataset.dashboardAction;
  if (action === "reset-cloud") {
    resetCloudDataForFreshStart();
  }
}

function renderAdminRecovery(error) {
  const status = document.getElementById("adminHubStatus");
  if (status) status.textContent = state.language !== "es" ? "Admin available" : "Administración disponible";
  const container = document.getElementById("adminGlobalProgressPanel") || document.getElementById("adminView");
  if (!container) return;
  const detail = error?.message || String(error || "");
  container.innerHTML = `
    <article class="data-status-card is-warning">
      <strong>${escapeHtml(state.language !== "es" ? "Administration opened in recovery mode" : "Administración abierta en modo recuperación")}</strong>
      <p>${escapeHtml(state.language !== "es"
         ? "Your administrator access is not blocked. One internal panel did not finish rendering, but navigation and core controls remain available."
        : "Tu acceso de administrador no está bloqueado. Un panel interno no terminó de renderizar, pero la navegación y los controles principales siguen disponibles.")}</p>
      ${detail ? `<small>${escapeHtml(detail)}</small>` : ""}
    </article>
  `;
}

function renderStartupRecovery(error) {
  console.error("Startup failed", error);
  const detail = error?.message || String(error || "");
  const dashboard = document.getElementById("dashboardView");
  if (dashboard) dashboard.classList.add("active-view");
  document.querySelector('[data-view="dashboard"]')?.classList.add("active");
  const panel = document.getElementById("dashboardDataStatusPanel") || document.getElementById("dashboardView");
  if (panel) {
    panel.innerHTML = `
      <article class="data-status-card is-warning">
        <strong>${escapeHtml(state.language !== "es" ? "App recovered with limited startup" : "App recuperada con inicio limitado")}</strong>
        <p>${escapeHtml(state.language !== "es"
           ? "Navigation remains available. Open Administration if you need to review the detail."
          : "La navegación sigue disponible. Abre Administración si necesitas revisar el detalle.")}</p>
        ${detail ? `<small>${escapeHtml(detail)}</small>` : ""}
      </article>
    `;
  }
  renderAuthStatus();
  renderNotifications();
}

function renderAdminSafe() {
  renderAdmin();
}

function renderAdmin() {
  try {
    renderAdminUnsafe();
  } catch (error) {
    console.error("Admin render failed", error);
    renderAdminRecovery(error);
  }
}

