function buildSupabasePilotGate() {
  const diagnostics = state.supabaseDiagnostics;
  const selfTest = state.supabaseSelfTest;
  const getDiagnostic = (id) => diagnostics?.checks?.find((check) => check.id === id);
  const checks = [
    {
      key: "config",
      label: state.language !== "es" ? "Supabase configured" : "Supabase configurado",
      ok: Boolean(state.apiOnline && state.persistence === "supabase" && state.config?.supabaseUrl && state.config?.supabasePublishableKey),
      detail: state.persistence === "supabase"
        ? state.language !== "es" ? "API is using Supabase persistence." : "La API usa persistencia Supabase."
        : state.language !== "es" ? "Activate STORAGE_ADAPTER=supabase." : "Activa STORAGE_ADAPTER=supabase.",
    },
    {
      key: "session",
      label: state.language !== "es" ? "User session" : "Sesión de usuario",
      ok: Boolean(state.session?.access_token),
      detail: state.session?.access_token
        ? state.language !== "es" ? "Active Supabase Auth token." : "Token activo de Supabase Auth."
        : state.language !== "es" ? "Sign in before inviting pilot users." : "Inicia sesión antes de invitar usuarios piloto.",
      action: "auth",
    },
    {
      key: "diagnostics",
      label: state.language !== "es" ? "Diagnostics clean" : "Diagnóstico sin errores",
      ok: diagnostics?.status === "ok",
      detail: diagnostics
        ? formatDiagnosticSummary(diagnostics)
        : state.language !== "es" ? "Run Verify cloud." : "Ejecuta Verificar nube.",
      action: "diagnostics",
    },
    {
      key: "storage",
      label: state.language !== "es" ? "Private Storage" : "Storage privado",
      ok: getDiagnostic("storage")?.status === "ok",
      detail: getDiagnostic("storage")?.detail || (state.language !== "es" ? "Verify that experience-media is private and that the real test validates signed URLs." : "Verifica que experience-media sea privado y que la prueba real valide URLs firmadas."),
      action: "diagnostics",
    },
    {
      key: "selfTest",
      label: state.language !== "es" ? "Real flow test" : "Prueba de flujo real",
      ok: selfTest?.status === "ok",
      detail: selfTest
        ? formatSelfTestSummary(selfTest)
        : state.language !== "es" ? "Run the real Supabase test: profile, private upload, signed URL, read, search, and cleanup." : "Ejecuta la prueba real Supabase: perfil, subida privada, URL firmada, lectura, búsqueda y limpieza.",
      action: "selfTest",
    },
    {
      key: "offline",
      label: state.language !== "es" ? "Offline queue clear" : "Cola sin conexión limpia",
      ok: state.offlineQueue.length === 0,
      detail: state.offlineQueue.length
        ? state.language !== "es" ? `${state.offlineQueue.length} pending changes.` : `${state.offlineQueue.length} cambios pendientes.`
        : state.language !== "es" ? "No pending changes." : "Sin pendientes.",
      action: "sync",
    },
  ];
  const ready = checks.filter((check) => check.ok).length;
  const score = Math.round((ready / checks.length) * 100);
  return {
    checks,
    ready,
    total: checks.length,
    score,
    ok: ready === checks.length,
    blockers: checks.filter((check) => !check.ok),
  };
}

function renderSupabasePilotGatePanel() {
  const container = document.getElementById("supabasePilotGatePanel");
  if (!container) return;
  const gate = buildSupabasePilotGate();
  container.innerHTML = `
    <div class="supabase-pilot-gate-heading">
      <div>
        <h3>${escapeHtml(state.language !== "es" ? "Supabase Pilot Gate" : "Compuerta Supabase del piloto")}</h3>
        <p class="card-meta">${escapeHtml(state.language !== "es" ? `${gate.ready}/${gate.total} controls ready. Active API is not enough; the real flow must be verified.` : `${gate.ready}/${gate.total} controles listos. API activa no basta; el flujo real debe estar verificado.`)}</p>
      </div>
      <strong class="${gate.ok ? "status-ok" : "status-warn"}">${escapeHtml(`${gate.score}%`)}</strong>
    </div>
    <div class="supabase-pilot-gate-actions">
      <button class="ghost-button" type="button" data-supabase-gate-action="diagnostics">${escapeHtml(state.language !== "es" ? "Verify cloud" : "Verificar nube")}</button>
      <button class="ghost-button" type="button" data-supabase-gate-action="selfTest">${escapeHtml(state.language !== "es" ? "Test full flow" : "Probar flujo completo")}</button>
      <button class="ghost-button" type="button" data-supabase-gate-action="auth">${escapeHtml(state.language !== "es" ? "Open access" : "Abrir acceso")}</button>
      <button class="ghost-button" type="button" data-supabase-gate-action="sync">${escapeHtml(state.language !== "es" ? "Sync queue" : "Sincronizar cola")}</button>
    </div>
    <div class="supabase-pilot-gate-grid">
      ${gate.checks
        .map(
          (check) => `
            <article class="${check.ok ? "is-ready" : "is-review"}">
              <span class="${check.ok ? "status-ok" : "status-warn"}">${escapeHtml(check.ok ? (state.language !== "es" ? "Ready" : "Listo") : (state.language !== "es" ? "Review" : "Revisar"))}</span>
              <strong>${escapeHtml(check.label)}</strong>
              <p>${escapeHtml(check.detail)}</p>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function handleSupabasePilotGateClick(event) {
  const action = event.target.closest("[data-supabase-gate-action]")?.dataset.supabaseGateAction;
  if (!action) return;
  if (action === "diagnostics") {
    runSupabaseDiagnostics();
    return;
  }
  if (action === "selfTest") {
    runSupabaseSelfTest();
    return;
  }
  if (action === "auth") {
    state.pendingAuthReturn = "diagnostics";
    showAuthView();
    return;
  }
  if (action === "sync") {
    syncOfflineQueue();
  }
}

function calculateAssetAnalysisReadiness() {
  const assets = collectMultimodalAssets();
  const withText = assets.filter((asset) => String(asset.analysisText || "").trim()).length;
  const suggested = assets.filter((asset) => asset.analysisSuggested).length;
  const processingPending = assets.filter((asset) => !buildAssetProcessingStatus(asset).ready).length;
  return {
    total: assets.length,
    withText,
    suggested,
    processingPending,
    pending: Math.max(0, assets.length - withText),
    score: assets.length ? Math.round((withText / assets.length) * 100) : 100,
  };
}

function calculateAssetStorageReadiness() {
  const assets = collectMultimodalAssets();
  const remote = assets.filter(isRemoteAsset).length;
  const cached = assets.filter((asset) => asset.dataUrl || asset.previewText).length;
  const pendingSync = assets.filter((asset) => buildAssetStorageStatus(asset).needsSync).length;
  return {
    total: assets.length,
    remote,
    cached,
    pendingSync,
  };
}

function renderOfflineQueuePanel() {
  const container = document.getElementById("offlineQueuePanel");
  if (!container) return;
  const queue = state.offlineQueue || [];
  const rows = queue.slice(0, 6);
  const guidance = getOfflineQueueGuidance();
  const needsAuth = queue.length && !state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase");
  const demoQueueCount = queue.filter(isDemoOfflineMutation).length;
  container.innerHTML = `
    <div class="offline-queue-heading">
      <div>
        <h3>${t("labels.offlineQueueTitle")}</h3>
        <p class="card-meta">${queue.length ? `${queue.length} ${t("labels.offlineQueuePending")}` : t("labels.offlineQueueEmpty")}</p>
      </div>
      <div class="offline-queue-actions">
        ${needsAuth ? `<button class="primary-button" type="button" data-offline-action="auth">${t("labels.offlineQueueOpenAuth")}</button>` : ""}
        <button class="ghost-button" type="button" data-offline-action="retry">${t("labels.offlineQueueRetry")}</button>
        <button class="ghost-button" type="button" data-offline-action="reconcile" ${queue.length ? "" : "disabled"}>${t("labels.offlineQueueReconcile")}</button>
        <button class="ghost-button" type="button" data-offline-action="clear-demo" ${demoQueueCount ? "" : "disabled"}>${t("labels.offlineQueueClearDemo")}</button>
        <button class="danger-button" type="button" data-offline-action="clear" ${queue.length ? "" : "disabled"}>${t("labels.offlineQueueClear")}</button>
      </div>
    </div>
    ${queue.length ? `<p class="offline-queue-guidance">${escapeHtml(guidance)}</p>` : ""}
    ${
      rows.length
         ? `<div class="offline-queue-list">
            ${rows.map(renderOfflineQueueItem).join("")}
          </div>
          ${queue.length > rows.length ? `<p class="card-meta">+${queue.length - rows.length} ${t("labels.items")}</p>` : ""}`
        : ""
    }
  `;
}

function renderDemoDataPanel() {
  const container = document.getElementById("demoDataPanel");
  if (!container) return;
  const demoItems = state.experiences.filter((item) => item.isDemo);
  const realItems = state.experiences.filter((item) => !item.isDemo);
  const demoAgendaItems = state.agendaEvents.filter((item) => item.isDemo);
  const canSync = Boolean(demoItems.length && state.session?.access_token && state.apiOnline);
  const needsAuth = Boolean(demoItems.length && !state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase"));
  const detail = demoItems.length
    ? canSync
      ? t("labels.demoDataRemoteReady")
      : t("labels.demoDataLocal")
    : t("labels.demoDataEmpty");
  container.innerHTML = `
    <div class="demo-data-heading">
      <div>
        <h3>${t("labels.demoDataTitle")}</h3>
        <p class="card-meta">${demoItems.length || demoAgendaItems.length ? `${demoItems.length} ${t("labels.demoDataLoaded")} · ${demoAgendaItems.length} Agenda · ${realItems.length} reales` : detail}</p>
      </div>
      <div class="demo-data-actions">
        <button class="ghost-button" type="button" data-demo-action="load">${t("labels.demoDataLoad")}</button>
        ${needsAuth ? `<button class="primary-button" type="button" data-demo-action="auth">${t("labels.offlineQueueOpenAuth")}</button>` : ""}
        ${canSync ? `<button class="primary-button" type="button" data-demo-action="sync">${t("labels.demoDataSync")}</button>` : ""}
        <button class="danger-button" type="button" data-demo-action="clear" ${demoItems.length || demoAgendaItems.length ? "" : "disabled"}>${t("labels.demoDataClear")}</button>
      </div>
    </div>
    <p class="demo-data-guidance">${escapeHtml(detail)}</p>
  `;
}

function getOfflineQueueGuidance() {
  if (!state.offlineQueue.length) return t("labels.offlineQueueEmpty");
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    return t("labels.offlineQueueNextLogin");
  }
  if (!state.apiOnline) return t("labels.offlineQueueNextApi");
  return `${t("labels.offlineQueueNextRetry")} ${t("labels.offlineQueueAutoRetry")}`;
}

function renderOfflineQueueItem(item) {
  const title = item.payload?.title || item.entityId || item.id;
  const reason = getOfflineQueueReason(item.reason);
  const isDemo = isDemoOfflineMutation(item);
  const resolution = getOfflineConflictResolution(item);
  return `
    <article class="offline-queue-item">
      <div>
        <strong>${escapeHtml(item.type || "sync")}: ${escapeHtml(title)}</strong>
        <p class="card-meta">${t("labels.offlineQueueCreated")}: ${escapeHtml(formatDate(item.createdAt))}</p>
        <p class="card-meta">${t("labels.offlineQueueReason")}: ${escapeHtml(reason)}</p>
        <p class="offline-resolution"><b>${t("labels.offlineQueueConflictPolicy")}:</b> ${escapeHtml(resolution)}</p>
      </div>
      <div class="offline-queue-item-actions">
        ${isDemo ? `<span class="pill">${t("labels.offlineQueueDemo")}</span>` : ""}
        <span class="pill">${Number(item.attempts || 0)} ${t("labels.offlineQueueAttempts")}</span>
        <button class="ghost-button" type="button" data-offline-action="retry-one" data-offline-id="${escapeHtml(item.id)}">${t("labels.offlineQueueRetryOne")}</button>
        <button class="ghost-button" type="button" data-offline-action="review" data-offline-id="${escapeHtml(item.id)}">${t("labels.offlineQueueReview")}</button>
        <button class="ghost-button" type="button" data-offline-action="keep-local" data-offline-id="${escapeHtml(item.id)}">${t("labels.offlineQueueKeepLocal")}</button>
        <button class="danger-button" type="button" data-offline-action="discard" data-offline-id="${escapeHtml(item.id)}">${t("labels.offlineQueueDiscard")}</button>
      </div>
    </article>
  `;
}

function getOfflineConflictResolution(item) {
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    return t("labels.offlineQueueConflictNeedsAuth");
  }
  if (!state.apiOnline) return t("labels.offlineQueueConflictNeedsApi");
  if (item.conflictPolicy === "delete_wins" || item.type === "delete") return t("labels.offlineQueueConflictDeleteWins");
  return t("labels.offlineQueueConflictLocalWins");
}

function getOfflineQueueReason(reason) {
  if (reason === "api_unavailable") return t("labels.offlineQueueReasonApi");
  if (reason === "auth_required") return t("labels.offlineQueueReasonAuth");
  if (reason === "media_pending") return t("labels.offlineQueueReasonMedia");
  return t("labels.offlineQueueReasonError");
}

function isDemoOfflineMutation(item) {
  if (item?.payload?.isDemo || item?.payload?.demoBatch || item?.payload?.metadata?.isDemo || item?.payload?.metadata?.demoBatch) return true;
  const local = state.experiences.find((experience) => experience.id === item?.entityId);
  if (local?.isDemo || local?.demoBatch) return true;
  return isLegacyDemoExperience(item?.payload);
}

function isLegacyDemoExperience(experience) {
  if (!experience?.title) return false;
  const title = normalizeComparableText(experience.title);
  const category = normalizeCategoryName(experience.category);
  return demoExperiences.some(
    (demo) => normalizeComparableText(demo.title) === title && normalizeCategoryName(demo.category) === category,
  );
}

function normalizeComparableText(value) {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

async function runSupabaseSelfTest() {
  const status = document.getElementById("embeddingStatus");
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    status.textContent = t("labels.supabaseDiagnosticsNeedsSession");
    state.supabaseSelfTest = {
      status: "warn",
      steps: [
        {
          id: "auth",
          label: "Auth",
          status: "warn",
          detail: t("labels.supabaseDiagnosticsNeedsSession"),
          action: state.language !== "es" ? "Sign in and run the real flow test again." : "Inicia sesión y vuelve a ejecutar la prueba real.",
          actionType: "openAuth",
        },
      ],
    };
    saveSupabaseSelfTest();
    renderAdmin();
    focusSupabaseSelfTestPanel();
    return;
  }
  status.textContent = t("labels.supabaseSelfTestRunning");
    try {
      state.supabaseSelfTest = await apiRequest("/supabase/self-test", { method: "POST" });
      saveSupabaseSelfTest();
    status.textContent = state.supabaseSelfTest?.status === "ok" ? t("labels.supabaseSelfTestReady") : t("labels.supabaseSelfTestReadyWithErrors");
    await hydrateFromApi();
  } catch (error) {
    const needsSession = error.status === 401 || String(error.message || "").includes("API 401");
    if (needsSession) expireAuthSession();
    state.supabaseSelfTest = {
      status: needsSession ? "warn" : "error",
      steps: [
        {
          id: "selfTest",
          label: needsSession ? "Auth" : "Prueba real",
          status: needsSession ? "warn" : "error",
          detail: needsSession ? t("labels.supabaseDiagnosticsNeedsSession") : error.message || "No se pudo ejecutar la prueba real.",
          action: needsSession
            ? state.language !== "es"
                ? "Sign in and run the real flow test again."
               : "Inicia sesión y vuelve a ejecutar la prueba real."
            : state.language !== "es"
               ? "Run Verify Supabase first and resolve the pending closure action."
              : "Ejecuta Verificar nube primero y resuelve la acción pendiente.",
          actionType: needsSession ? "openAuth" : "openAdmin",
        },
      ],
    };
    saveSupabaseSelfTest();
    status.textContent = needsSession ? t("labels.supabaseDiagnosticsNeedsSession") : "No se pudo ejecutar la prueba real Supabase.";
  }
  renderAdmin();
  focusSupabaseSelfTestPanel();
}

function focusSupabaseSelfTestPanel() {
  const container = document.getElementById("supabaseSelfTest");
  if (!container) return;
  container.closest("details")?.setAttribute("open", "");
  window.setTimeout(() => {
    container.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 80);
}

async function runSupabaseDiagnostics() {
  const status = document.getElementById("embeddingStatus");
  if (!state.session?.access_token && (state.config?.persistence === "supabase" || state.persistence === "supabase")) {
    status.textContent = t("labels.supabaseDiagnosticsNeedsSession");
    state.supabaseDiagnostics = {
      status: "warn",
      checks: [
        {
          id: "auth",
          label: "Auth",
          status: "warn",
          detail: t("labels.supabaseDiagnosticsNeedsSession"),
          action: state.language !== "es" ? "Sign in from the app access panel and run Verify cloud again." : "Inicia sesión desde el panel de acceso y vuelve a ejecutar Verificar nube.",
          actionType: "openAuth",
        },
      ],
    };
    renderSupabaseDiagnostics();
    return;
  }
  status.textContent = t("labels.supabaseDiagnosticsRunning");
  try {
    state.supabaseDiagnostics = await apiRequest("/supabase/diagnostics");
    await loadUploadAttempts({ silent: true });
    status.textContent = t("labels.supabaseDiagnosticsReady");
  } catch (error) {
    const needsSession = error.status === 401 || String(error.message || "").includes("API 401");
    if (needsSession) expireAuthSession();
    state.supabaseDiagnostics = {
      status: needsSession ? "warn" : "error",
      checks: [
        {
          id: "diagnostics",
          label: "Auth",
          status: needsSession ? "warn" : "error",
          detail: needsSession ? t("labels.supabaseDiagnosticsNeedsSession") : error.message || "No se pudo ejecutar la verificación.",
          action: needsSession
            ? state.language !== "es"
                ? "Sign in from the app access panel and run Verify Supabase again."
               : "Inicia sesión desde el panel de acceso y vuelve a ejecutar Verificar nube."
            : state.language !== "es"
               ? "Review the local API and run the verification again."
              : "Revisa la API local y vuelve a ejecutar la verificación.",
          actionType: needsSession ? "openAuth" : "openAdmin",
        },
      ],
    };
    status.textContent = needsSession ? t("labels.supabaseDiagnosticsNeedsSession") : "No se pudo verificar Supabase.";
  }
  renderSupabaseDiagnostics();
  renderAdmin();
}

async function loadUploadAttempts(options = {}) {
  if (!state.apiOnline || !state.session?.access_token) {
    state.uploadAttempts = [];
    state.uploadAttemptsCheckedAt = new Date().toISOString();
    return [];
  }
  try {
    const attempts = await apiRequest("/upload-attempts?limit=12");
    state.uploadAttempts = Array.isArray(attempts) ? attempts : [];
    state.uploadAttemptsCheckedAt = new Date().toISOString();
    if (!options.silent) document.getElementById("embeddingStatus").textContent = state.language !== "es" ? "Attachment upload history updated." : "Historial de adjuntos actualizado.";
    return state.uploadAttempts;
  } catch (error) {
    if (!options.silent) document.getElementById("embeddingStatus").textContent = state.language !== "es" ? "Could not read attachment upload history." : "No se pudo leer el historial de adjuntos.";
    return state.uploadAttempts || [];
  }
}

function renderSupabaseSelfTest() {
  const result = state.supabaseSelfTest;
  const container = document.getElementById("supabaseSelfTest");
  if (!container) return;
  const steps = result?.steps || [];
  const statusText = result ? formatSelfTestSummary(result) : t("labels.supabaseSelfTestEmpty");
  const showAssetMatrix = Boolean(result);
  container.innerHTML = `
    <div class="supabase-diagnostics-heading">
      <div>
        <h3>${t("labels.supabaseSelfTestTitle")}</h3>
        <p class="card-meta">${escapeHtml(statusText)}</p>
      </div>
      ${result?.checkedAt ? `<span class="pill">${escapeHtml(formatDate(result.checkedAt))}</span>` : ""}
    </div>
    ${result ? renderSelfTestPlainSummary(result) : ""}
    ${showAssetMatrix ? renderSelfTestAssetMatrix(steps) : ""}
    ${steps.length ? `<div class="diagnostic-grid">${steps.map((step) => renderDiagnosticCheck(step, "selfTest")).join("")}</div>` : ""}
  `;
}

function renderSelfTestPlainSummary(result) {
  const steps = result?.steps || [];
  const stepOk = (id) => steps.find((step) => step.id === id)?.status === "ok";
  const missingTableErrors = steps.filter((step) => /Could not find the table|PGRST205|schema cache/i.test(`${step.detail || ""} ${step.action || ""}`));
  const filesOk = ["storage", "audioStorage", "videoStorage", "documentStorage", "archiveStorage", "experienceRead"].every(stepOk);
  const assetsOk = stepOk("workspaceAssets");
  const agendaMissing = missingTableErrors.some((step) => String(step.detail || "").includes("agenda_events"));
  const workspaceMissing = missingTableErrors.some((step) => /participants|assets|experience_events/i.test(String(step.detail || "")));
  const labels = state.language !== "es"
     ? {
        titleOk: "What this result means",
        filesOk: "File upload is working: image, audio, video, document, and ZIP reached private Storage and can be read with signed URLs.",
        filesReview: "File upload still needs review. Check the cards below for the first failed asset family.",
        sharedOk: "The shared assets table is available, so other devices can rebuild the asset inventory from Supabase.",
        sharedReview: "The files work, but the shared Supabase structure is incomplete. Apply the pending SQL before calling this flow complete.",
        required: "Required SQL",
        agenda: "Agenda table missing",
        workspace: "Workspace, participants, events, or assets table missing",
        done: "All core checks passed.",
        review: "Action required",
      }
    : {
        titleOk: "Qué significa este resultado",
        filesOk: "La carga de archivos funciona: imagen, audio, video, documento y ZIP llegaron a Storage privado y se leen con URLs firmadas.",
        filesReview: "La carga de archivos aún requiere revisión. Revisa abajo la primera familia de activos que falló.",
        sharedOk: "La tabla compartida de activos está disponible, por lo que otros dispositivos pueden reconstruir el inventario desde Supabase.",
        sharedReview: "Los archivos funcionan, pero la estructura compartida de Supabase está incompleta. Aplica el SQL pendiente antes de considerar completo este flujo.",
        required: "SQL requerido",
        agenda: "Falta la tabla de Agenda",
        workspace: "Faltan tablas de workspace, participantes, eventos o activos",
        done: "Todos los controles centrales pasaron.",
        review: "Acción requerida",
      };
  const required = [
    workspaceMissing ? "database/workspace-events-assets.sql" : "",
    agendaMissing ? "database/agenda-events.sql" : "",
  ].filter(Boolean);
  return `
    <section class="self-test-plain-summary ${result.status === "ok" ? "is-ready" : "is-review"}">
      <div>
        <span class="${result.status === "ok" ? "status-ok" : "status-warn"}">${escapeHtml(result.status === "ok" ? labels.done : labels.review)}</span>
        <h4>${escapeHtml(labels.titleOk)}</h4>
      </div>
      <p>${escapeHtml(filesOk ? labels.filesOk : labels.filesReview)}</p>
      <p>${escapeHtml(assetsOk ? labels.sharedOk : labels.sharedReview)}</p>
      ${
        required.length
           ? `<p><strong>${escapeHtml(labels.required)}:</strong> ${escapeHtml(required.join(" + "))}</p>`
          : ""
      }
      ${
        missingTableErrors.length
           ? `<div class="self-test-missing-tables">
              ${workspaceMissing ? `<span class="pill">${escapeHtml(labels.workspace)}</span>` : ""}
              ${agendaMissing ? `<span class="pill">${escapeHtml(labels.agenda)}</span>` : ""}
            </div>`
          : ""
      }
    </section>
  `;
}

function renderSelfTestAssetMatrix(steps = []) {
  const findStep = (id) => steps.find((step) => step.id === id);
  const labels = state.language !== "es"
     ? {
        title: "Asset families tested",
        help: "This follows the CLIO-style pattern: private Storage, signed URL, shared asset row, and local cache only as fallback.",
        ready: "Ready",
        review: "Review",
        storage: "Storage",
        readback: "Read-back",
        assets: "Assets table",
        image: "Image",
        audio: "Audio",
        video: "Video",
        document: "Document",
        archive: "ZIP",
        archiveNote: "Transport only",
      }
    : {
        title: "Familias de activos probadas",
        help: "Sigue el patrón tipo CLIO: Storage privado, URL firmada, fila compartida de activo y caché local solo como respaldo.",
        ready: "Listo",
        review: "Revisar",
        storage: "Storage",
        readback: "Lectura",
        assets: "Tabla assets",
        image: "Imagen",
        audio: "Audio",
        video: "Video",
        document: "Documento",
        archive: "ZIP",
        archiveNote: "Solo transporte",
      };
  const rows = [
    { key: "image", label: labels.image, storage: "storage" },
    { key: "audio", label: labels.audio, storage: "audioStorage" },
    { key: "video", label: labels.video, storage: "videoStorage" },
    { key: "document", label: labels.document, storage: "documentStorage" },
    { key: "archive", label: labels.archive, storage: "archiveStorage", note: labels.archiveNote },
  ].map((row) => {
    const storageStep = findStep(row.storage);
    const readStep = findStep("experienceRead");
    const assetStep = findStep("workspaceAssets");
    const ready = storageStep?.status === "ok" && readStep?.status === "ok" && assetStep?.status === "ok";
    return { ...row, storageStep, readStep, assetStep, ready };
  });
  return `
    <section class="self-test-asset-matrix">
      <div>
        <h4>${escapeHtml(labels.title)}</h4>
        <p class="card-meta">${escapeHtml(labels.help)}</p>
      </div>
      <div class="asset-family-grid">
        ${rows
          .map(
            (row) => `
              <article class="${row.ready ? "is-ready" : "is-review"}">
                <span class="${row.ready ? "status-ok" : "status-warn"}">${escapeHtml(row.ready ? labels.ready : labels.review)}</span>
                <strong>${escapeHtml(row.label)}</strong>
                ${row.note ? `<small>${escapeHtml(row.note)}</small>` : ""}
                <p>${escapeHtml(labels.storage)}: ${escapeHtml(row.storageStep?.status === "ok" ? labels.ready : labels.review)}</p>
                <p>${escapeHtml(labels.readback)}: ${escapeHtml(row.readStep?.status === "ok" ? labels.ready : labels.review)}</p>
                <p>${escapeHtml(labels.assets)}: ${escapeHtml(row.assetStep?.status === "ok" ? labels.ready : labels.review)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

