async function handlePilotInviteKitClick(event) {
  const action = event.target.closest("[data-pilot-invite-action]")?.dataset.pilotInviteAction;
  if (action === "copy-message") {
    const copied = await copyTextToClipboard(buildPilotInviteKit().invitation);
    const status = document.getElementById("embeddingStatus");
    if (status) status.textContent = copied ? (state.language !== "es" ? "Pilot invitation copied." : "Invitación piloto copiada.") : (state.language !== "es" ? "Could not copy invitation." : "No se pudo copiar la invitación.");
    return;
  }
  if (action === "export-markdown") {
    downloadBlob(new Blob([buildPilotInviteMarkdown()], { type: "text/markdown;charset=utf-8" }), `kit-invitacion-piloto-${PILOT_TARGET_USERS}-usuarios.md`);
    return;
  }
  handleParallelBacklogClick(event);
}

function getExternalIntegrationOptions() {
  return state.language !== "es"
     ? [
        {
          title: "Integrate by MCP or API",
          status: "Recommended first",
          detail: "Best path for Clio, devices, wearables, voice, calendar, Google services, and media. It keeps both apps independent and reduces migration risk.",
          next: "Define an integration contract before building.",
        },
        {
          title: "Reuse selected code",
          status: "Evaluate later",
          detail: "Useful only after reviewing the repository, license, secrets, architecture, and dependencies. Clio is Flutter/Dart while this MVP is web JavaScript.",
          next: "Audit the repository before copying anything.",
        },
        {
          title: "Shared GitHub environment",
          status: "Recommended",
          detail: "Create a shared organization or workspace with separated repos, issues, integration contracts, and a coordinated roadmap.",
          next: "Use GitHub to manage contracts, issues, and pull requests.",
        },
        {
          title: "Keep projects separate",
          status: "Valid fallback",
          detail: "Useful if ownership, privacy, or product direction should remain fully independent.",
          next: "Revisit after the pilot or after repository review.",
        },
      ]
    : [
        {
          title: "Integrar por MCP o API",
          status: "Recomendado primero",
          detail: "Mejor camino para Clio, dispositivos, wearables, voz, calendario, servicios Google y multimedia. Mantiene ambas apps independientes y reduce riesgo de migración.",
          next: "Definir un contrato de integración antes de construir.",
        },
        {
          title: "Reutilizar código seleccionado",
          status: "Evaluar después",
          detail: "Solo conviene tras revisar repositorio, licencia, secretos, arquitectura y dependencias. Clio es Flutter/Dart y este MVP es web JavaScript.",
          next: "Auditar el repositorio antes de copiar cualquier parte.",
        },
        {
          title: "Ambiente compartido en GitHub",
          status: "Recomendado",
          detail: "Crear una organización o espacio compartido con repos separados, issues, contratos de integración y roadmap coordinado.",
          next: "Usar GitHub para contratos, issues y pull requests.",
        },
        {
          title: "Mantener proyectos separados",
          status: "Alternativa válida",
          detail: "Sirve si propiedad, privacidad o dirección de producto deben permanecer totalmente independientes.",
          next: "Revisar después del piloto o después de auditar el repositorio.",
        },
      ];
}

