async function handleExternalIntegrationClick(event) {
  const action = event.target.closest("[data-external-integration-action]")?.dataset.externalIntegrationAction;
  if (!action) return;
  const isContract = action === "copy-contract";
  const copied = await copyTextToClipboard(isContract ? buildExternalIntegrationContractMarkdown() : buildExternalIntegrationMarkdown());
  const status = document.getElementById("embeddingStatus");
  if (status) {
    status.textContent = copied
      ? isContract
        ? state.language !== "es" ? "Integration contract copied." : "Contrato de integración copiado."
        : state.language !== "es" ? "External integration strategy copied." : "Estrategia de integración externa copiada."
      : isContract
        ? state.language !== "es" ? "Could not copy integration contract." : "No se pudo copiar el contrato de integración."
        : state.language !== "es" ? "Could not copy integration strategy." : "No se pudo copiar la estrategia de integración.";
  }
}

function buildParallelWorkstreams(readiness = calculateDevelopmentReadiness()) {
  const backlog = buildParallelBacklog();
  const pendingFunctional = backlog.filter((item) => item.track === t("labels.backlogFunctional") && !item.ready);
  const pendingTechnical = backlog.filter((item) => item.track === t("labels.backlogTechnical") && !item.ready);
  const pilot = calculatePilotReadiness();
  const pilotPending = pilot.checks.filter((check) => !check.ok);
  const manual = calculateManualReviewSummary();
  const integrationReady = true;
  const labels = state.language !== "es"
     ? {
        functional: "Functional closure",
        technical: "Technical closure",
        pilot: `${PILOT_TARGET_USERS}-user pilot`,
        qa: "QA, manual, and grammar",
        integrations: "External integrations",
        functionalOwner: "Main Codex + functional subagent",
        technicalOwner: "Main Codex + technical QA",
        pilotOwner: "Main Codex + pilot reviewer",
        qaOwner: "QA/manual subagent",
        integrationOwner: "Main Codex + Clio/repo reviewer",
        noPending: "No blocking item detected in this stream.",
        open: "Open next",
        copy: "Copy parallel plan",
      }
    : {
        functional: "Cierre funcional",
        technical: "Cierre técnico",
        pilot: `Piloto de ${PILOT_TARGET_USERS} usuarios`,
        qa: "QA, manual y gramática",
        integrations: "Integraciones externas",
        functionalOwner: "Codex principal + subagente funcional",
        technicalOwner: "Codex principal + QA técnico",
        pilotOwner: "Codex principal + revisor del piloto",
        qaOwner: "Subagente QA/manual",
        integrationOwner: "Codex principal + revisor Clio/repositorio",
        noPending: "No se detecta bloqueo en este frente.",
        open: "Abrir siguiente",
        copy: "Copiar plan paralelo",
      };
  const manualPending = manual.total - manual.reviewed;
  return {
    labels,
    streams: [
      {
        key: "functional",
        title: labels.functional,
        owner: labels.functionalOwner,
        score: readiness.functional.score,
        status: pendingFunctional.length ? "review" : "ready",
        detail: pendingFunctional.length
          ? pendingFunctional.slice(0, 3).map((item) => item.title).join(" · ")
          : labels.noPending,
        next: pendingFunctional[0] || { view: "report", action: labels.open },
      },
      {
        key: "technical",
        title: labels.technical,
        owner: labels.technicalOwner,
        score: readiness.technical.score,
        status: pendingTechnical.length ? "review" : "ready",
        detail: pendingTechnical.length
          ? pendingTechnical.slice(0, 3).map((item) => item.title).join(" · ")
          : labels.noPending,
        next: pendingTechnical[0] || { view: "admin", action: labels.open },
      },
      {
        key: "pilot",
        title: labels.pilot,
        owner: labels.pilotOwner,
        score: pilot.score,
        status: pilotPending.length ? "review" : "ready",
        detail: pilotPending.length
          ? pilotPending.slice(0, 3).map((item) => item.label).join(" · ")
          : pilot.recommendation,
        next: pilotPending[0] || { view: "admin", focus: "pilotClosureRecordPanel", action: labels.open },
      },
      {
        key: "qa",
        title: labels.qa,
        owner: labels.qaOwner,
        score: manual.score,
        status: manualPending ? "review" : "ready",
        detail: state.language !== "es"
           ? `${manual.reviewed}/${manual.total} manual sections reviewed. Grammar and visible copy are checked during each block.`
          : `${manual.reviewed}/${manual.total} secciones del manual revisadas. La gramática y textos visibles se revisan en cada bloque.`,
        next: { view: "manual", action: labels.open },
      },
      {
        key: "integrations",
        title: labels.integrations,
        owner: labels.integrationOwner,
        score: integrationReady ? 100 : 0,
        status: integrationReady ? "ready" : "review",
        detail: state.language !== "es"
           ? "API/MCP-first strategy, minimum contract, and normalized signal metadata are documented. Repository review remains a future step."
          : "La estrategia API/MCP, el contrato mínimo y los metadatos de señal normalizada están documentados. La revisión del repositorio queda como paso futuro.",
        next: { view: "admin", focus: "externalIntegrationPanel", action: labels.open },
      },
    ],
  };
}

function renderParallelWorkstreamsPanel(readiness = calculateDevelopmentReadiness()) {
  const container = document.getElementById("parallelWorkstreamsPanel");
  if (!container) return;
  const plan = buildParallelWorkstreams(readiness);
  const pending = plan.streams.filter((item) => item.status !== "ready").length;
  container.innerHTML = `
    <div class="parallel-workstreams-heading">
      <div>
        <h3>${escapeHtml(state.language !== "es" ? "Parallel Closure Plan" : "Plan de cierre paralelo")}</h3>
        <p class="card-meta">${escapeHtml(state.language !== "es" ? `${pending} streams need attention. Use this board to avoid scattered mini-tasks.` : `${pending} frentes requieren atención. Usa este tablero para evitar mini tareas dispersas.`)}</p>
      </div>
      <button class="ghost-button" type="button" data-parallel-workstreams-action="copy">${escapeHtml(plan.labels.copy)}</button>
    </div>
    <div class="parallel-workstreams-grid">
      ${plan.streams
        .map(
          (item) => `
            <article class="${item.status === "ready" ? "is-ready" : "is-review"}">
              <header>
                <div>
                  <span>${escapeHtml(item.owner)}</span>
                  <strong>${escapeHtml(item.title)}</strong>
                </div>
                <b>${escapeHtml(`${item.score}%`)}</b>
              </header>
              <p>${escapeHtml(item.detail)}</p>
              <button class="ghost-button" type="button" data-backlog-view="${escapeHtml(item.next?.view || "admin")}" data-backlog-focus="${escapeHtml(item.next?.focus || "")}" data-backlog-run="${escapeHtml(item.next?.run || "")}">
                ${escapeHtml(item.next?.action || plan.labels.open)}
              </button>
            </article>
          `,
        )
        .join("")}
    </div>
  `;
}

function buildParallelWorkstreamsMarkdown(readiness = calculateDevelopmentReadiness()) {
  const plan = buildParallelWorkstreams(readiness);
  const labels = state.language !== "es"
     ? { title: "Parallel Closure Plan", owner: "Owner", score: "Score", status: "Status", next: "Next action" }
    : { title: "Plan de cierre paralelo", owner: "Responsable sugerido", score: "Puntaje", status: "Estado", next: "Siguiente acción" };
  return [
    `# ${labels.title}`,
    "",
    `**${state.language !== "es" ? "Version" : "Versión"}:** ${APP_VERSION}`,
    "",
    ...plan.streams.flatMap((item) => [
      `## ${item.title}`,
      "",
      `- ${labels.owner}: ${item.owner}`,
      `- ${labels.score}: ${item.score}%`,
      `- ${labels.status}: ${item.status === "ready" ? (state.language !== "es" ? "Ready" : "Listo") : (state.language !== "es" ? "Review" : "Revisar")}`,
      `- ${item.detail}`,
      `- ${labels.next}: ${item.next?.action || plan.labels.open}`,
      "",
    ]),
  ].join("\n");
}

async function handleParallelWorkstreamsClick(event) {
  const action = event.target.closest("[data-parallel-workstreams-action]")?.dataset.parallelWorkstreamsAction;
  if (action === "copy") {
    const copied = await copyTextToClipboard(buildParallelWorkstreamsMarkdown());
    const status = document.getElementById("embeddingStatus");
    if (status) {
      status.textContent = copied
        ? state.language !== "es" ? "Parallel closure plan copied." : "Plan de cierre paralelo copiado."
        : state.language !== "es" ? "Could not copy parallel plan." : "No se pudo copiar el plan paralelo.";
    }
    return;
  }
  handleParallelBacklogClick(event);
}

function renderParallelBacklog(readiness) {
  const backlog = buildParallelBacklog();
  document.getElementById("parallelBacklog").innerHTML = `
    <div class="parallel-backlog-heading">
      <div>
        <h3>${t("labels.parallelBacklogTitle")}</h3>
        <p class="card-meta">${t("labels.parallelBacklogStatus")} · ${readiness.functional.pending + readiness.technical.pending} ${t("labels.pendingModules")}</p>
      </div>
      <div class="pill-row">
        <span class="pill">${t("labels.functionalReadiness")}: ${readiness.functional.score}%</span>
        <span class="pill">${t("labels.technicalReadiness")}: ${readiness.technical.score}%</span>
      </div>
    </div>
    <div class="parallel-backlog-grid">
      ${backlog.map(renderBacklogCard).join("")}
    </div>
  `;
}

function renderBacklogCard(item) {
  const statusLabel = item.ready ? t("labels.backlogReady") : t("labels.backlogPending");
  const statusClass = item.ready ? "status-ok" : "status-warn";
  return `
    <article class="backlog-card ${item.ready ? "is-ready" : "is-pending"}">
      <header>
        <div>
          <span class="card-meta">${escapeHtml(item.track)}</span>
          <strong>${escapeHtml(item.title)}</strong>
        </div>
        <span class="${statusClass}">${statusLabel}</span>
      </header>
      <p>${escapeHtml(item.detail)}</p>
      <button class="ghost-button" type="button" data-backlog-view="${escapeHtml(item.view)}" data-backlog-focus="${escapeHtml(item.focus || "")}" data-backlog-run="${escapeHtml(item.run || "")}">
        ${escapeHtml(item.action || t("labels.backlogOpen"))}
      </button>
    </article>
  `;
}

