function calculateDailyReadiness() {
  const checks = buildDailyReliabilityChecks();
  const ready = checks.filter((item) => item.ok).length;
  const interactiveChecks = checks.filter((item) => item.interactive);
  const contentChecks = checks.filter((item) => item.content);
  return {
    score: Math.round((ready / checks.length) * 100),
    interactiveReady: interactiveChecks.every((item) => item.ok),
    contentReady: contentChecks.every((item) => item.ok),
    missing: checks.filter((item) => !item.ok).map((item) => item.key),
  };
}

function calculateAssetWorkflowReadiness() {
  return summarizeReadiness(buildAssetWorkflowChecks().map((check) => check.ok));
}

function calculateDevelopmentReadiness() {
  const experienceMapGraph = buildExperienceMapGraph();
  const dailyReadiness = calculateDailyReadiness();
  const assetWorkflowReadiness = calculateAssetWorkflowReadiness();
  const assetAnalysisReadiness = calculateAssetAnalysisReadiness();
  const assetWorkflowChecks = buildAssetWorkflowChecks();
  const assetWorkflowMap = assetWorkflowChecks.reduce((acc, check) => {
    acc[check.key] = check.ok;
    return acc;
  }, {});
  const plannedCapabilityChecks = {
    multimodalFoundation: true,
    intelligentAgenda: true,
    intelligentPublications: true,
  };
  const functionalChecks = [
    Boolean(state.experiences.length),
    dailyReadiness.interactiveReady,
    dailyReadiness.contentReady,
    dailyReadiness.score >= 80,
    calculateDataQuality(state.experiences).score >= 70,
    Boolean(buildInsights().length),
    Boolean(getReportExperiences().length),
    experienceMapGraph.nodes.length >= 8 && experienceMapGraph.links.length >= 8 && buildExperienceMapRoutes(experienceMapGraph).length >= 2,
    buildHumanKpis(getReportExperiences(), buildExperienceAnalysis(getReportExperiences()), calculateDataQuality(getReportExperiences())).length >= 8,
    buildHumanCorrelations(getReportExperiences(), buildExperienceAnalysis(getReportExperiences())).length >= 3,
    getReportExperiences().length >= 4,
    Boolean(state.contextImpact),
    plannedCapabilityChecks.multimodalFoundation,
    assetWorkflowReadiness.score >= 85,
    assetAnalysisReadiness.total === 0 || assetAnalysisReadiness.withText > 0 || assetAnalysisReadiness.suggested > 0,
    plannedCapabilityChecks.intelligentAgenda,
    plannedCapabilityChecks.intelligentPublications,
  ];
  const technicalChecks = [
    state.apiOnline,
    state.persistence === "supabase",
    Boolean(state.health?.routineScheduler?.status === "active"),
    state.offlineQueue.length === 0,
    Boolean(state.health?.contextProviders?.environmental?.status === "available"),
    Boolean(state.health?.contextProviders?.geopolitical?.status === "available"),
    state.config?.vectorSearch !== "disabled",
    Boolean(state.session?.access_token),
    assetWorkflowReadiness.score >= 85,
    Boolean(assetWorkflowMap.exports && state.assetWorkflowAudit?.templateCsvExportedAt && state.assetWorkflowAudit?.editableCsvExportedAt),
    Boolean(assetWorkflowMap.import),
    Boolean(assetWorkflowMap.ids && assetWorkflowMap.humanReview),
    Boolean(assetWorkflowMap.suggestions),
  ];
  return {
    functional: summarizeReadiness(functionalChecks),
    technical: summarizeReadiness(technicalChecks),
  };
}

function calculateTotalProductProgress(readiness) {
  const localMvp = Math.round((readiness.functional.score * 0.78) + (readiness.technical.score * 0.22));
  const pilot50 = Math.round(
    96 * 0.18 + // Captura, librería y panel para operación controlada.
      94 * 0.18 + // Base multimodal con revisión humana.
      92 * 0.16 + // Reportes, hallazgos y visualizaciones.
      90 * 0.12 + // Agenda local e importación/exportación manual.
      90 * 0.12 + // Publicaciones con aprobación humana y exportación manual.
      86 * 0.14 + // Supabase, privacidad, respaldos y operación.
      65 * 0.05 + // Automatizaciones locales suficientes para piloto.
      40 * 0.05, // Conectores/IA avanzada no bloquean el piloto.
  );
  const fullProduct = Math.round(
    92 * 0.14 + // Captura, librería y panel base.
      91 * 0.14 + // Base multimodal.
      89 * 0.12 + // Reportes, hallazgos y visualizaciones.
      86 * 0.11 + // Agenda MVP.
      86 * 0.11 + // Publicaciones MVP.
      84 * 0.12 + // Supabase, administración y operación.
      82 * 0.13 + // Contrato, rutas, kit, ingesta validada desde Vibeapp, handoff visible en Panel, simulador, normalizadores, permisos Android Health Connect y resumen biometrico central listos; OAuth/SDK en vivo siguen posteriores.
      14 * 0.13, // IA predictiva y agentes todavía futuros.
  );
  return {
    mvp: Math.max(0, Math.min(100, localMvp)),
    pilot: Math.max(0, Math.min(100, pilot50)),
    full: Math.max(0, Math.min(100, fullProduct)),
  };
}

function summarizeReadiness(checks) {
  const total = checks.length;
  const ready = checks.filter(Boolean).length;
  return {
    total,
    ready,
    pending: total - ready,
    score: Math.round((ready / total) * 100),
  };
}

function renderProfileSettings() {
  const profile = state.profile || {};
  document.getElementById("profileNameInput").value = profile.name || "";
  document.getElementById("profileEmailInput").value = profile.email || state.session?.user?.email || "";
  document.getElementById("profileTimezoneInput").value = profile.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || "America/New_York";
  document.getElementById("profileGenderInput").value = profile.gender || "";
  document.getElementById("profileBirthYearInput").value = profile.birthYear || "";
  document.getElementById("profileExperienceTypeInput").value = profile.experienceType || "auto";
}

async function saveProfileSettings(event) {
  event.preventDefault();
  const status = document.getElementById("profileSettingsStatus");
  const nextProfile = {
    ...(state.profile || {}),
    name: document.getElementById("profileNameInput").value.trim() || "Usuario de Experience Hub",
    email: document.getElementById("profileEmailInput").value.trim() || state.session?.user?.email,
    timezone: document.getElementById("profileTimezoneInput").value.trim() || Intl.DateTimeFormat().resolvedOptions().timeZone,
    gender: document.getElementById("profileGenderInput").value,
    birthYear: Number(document.getElementById("profileBirthYearInput").value) || null,
    experienceType: document.getElementById("profileExperienceTypeInput").value || "auto",
    language: state.language,
  };
  state.profile = nextProfile;
  saveLocalProfile(nextProfile);
  if (!state.apiOnline) {
    status.textContent = t("labels.profileSavedLocal");
    renderProfileSettings();
    return;
  }
  if (state.persistence === "supabase" && !state.session?.access_token) {
    status.textContent = t("labels.profileSaveAuthRequired");
    renderProfileSettings();
    return;
  }
  try {
    state.profile = await apiRequest("/profile", {
      method: "PUT",
      body: JSON.stringify(nextProfile),
    });
    saveLocalProfile(state.profile);
    status.textContent = t("labels.profileSaved");
    renderProfileSettings();
  } catch (error) {
    status.textContent =
      error.status === 401
        ? t("labels.profileSaveAuthRequired")
        : `No se pudo guardar el perfil en Supabase. Copia local conservada. ${error.message || ""}`.trim();
  }
}

async function refreshOps(options = {}) {
  if (!state.apiOnline || !state.session?.access_token) {
    state.ops = { jobs: [], logs: [] };
    renderOps();
    renderNotifications();
    return;
  }
  if (!options.silent) document.getElementById("embeddingStatus").textContent = "Actualizando operación...";
  try {
    const previousLogId = state.ops?.logs?.[0]?.id || state.lastSeenLogId;
    state.ops = await apiRequest("/jobs");
    captureOpsNotifications(previousLogId, options);
    if (!options.silent) document.getElementById("embeddingStatus").textContent = "Operación actualizada.";
  } catch {
    if (!options.silent) document.getElementById("embeddingStatus").textContent = "No se pudo leer operación.";
  }
  renderOps();
  renderNotifications();
  if (document.getElementById("automationView")?.classList.contains("active-view")) {
    renderAutomations();
  }
}

function setupOpsPolling() {
  setInterval(() => {
    if (!state.apiOnline || !state.session?.access_token) return;
    refreshOps({ silent: true, poll: true });
    loadBackendRoutines().then(renderAutomations).catch(() => {});
  }, 60_000);
}

function captureOpsNotifications(previousLogId, options = {}) {
  const logs = state.ops?.logs || [];
  if (logs[0]?.id) {
    state.lastSeenLogId = logs[0].id;
    saveLastSeenLogId(logs[0].id);
  }
  const freshLogs = [];
  for (const log of logs) {
    if (!previousLogId || log.id === previousLogId) break;
    freshLogs.push(log);
  }
  freshLogs
    .filter((log) => /Routine (completed|checked)|Scheduled routine/i.test(log.message || ""))
    .reverse()
    .forEach((log) => {
      addNotification({
        id: log.id,
        type: log.level === "error" ? "warn" : "ok",
        title: t("labels.scheduledRoutineNotice"),
        detail: log.message,
        createdAt: log.createdAt,
      });
    });
  if (freshLogs.length && !options.silent) {
    renderNotifications();
  }
}

function addNotification(notification) {
  if (state.notifications.some((item) => item.id === notification.id)) return;
  state.notifications = [notification, ...state.notifications].slice(0, 4);
}

function notify(detail, type = "ok") {
  addNotification({
    id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    type,
    title: type === "warn" ? (state.language !== "es" ? "Attention" : "Atención") : (state.language !== "es" ? "Ready" : "Listo"),
    detail,
    createdAt: new Date().toISOString(),
  });
  renderNotifications();
}

function renderNotifications() {
  const container = document.getElementById("notificationCenter");
  if (!container) return;
  if (!state.notifications.length) {
    container.innerHTML = `<span class="notification-empty">${t("labels.noNotifications")}</span>`;
    return;
  }
  container.innerHTML = state.notifications
    .map(
      (item) => `
        <article class="notification-card ${item.type === "warn" ? "notification-warn" : ""}">
          <strong>${escapeHtml(item.title)}</strong>
          <span>${escapeHtml(item.detail)}</span>
        </article>
      `,
    )
    .join("");
}

function renderOps() {
  const container = document.getElementById("opsLogList");
  if (!container) return;
  const jobs = state.ops?.jobs || [];
  const logs = state.ops?.logs || [];
  const jobHtml = jobs.length
    ? jobs
        .slice(0, 5)
        .map(
          (job) => `
            <article class="ops-row">
              <strong>${escapeHtml(job.type)}</strong>
              <span class="pill">${escapeHtml(job.status)}</span>
              <p class="card-meta">${escapeHtml(job.createdAt)}${job.result ? ` · ${escapeHtml(JSON.stringify(job.result))}` : ""}</p>
            </article>
          `,
        )
        .join("")
    : `<p class="card-meta">Sin tareas recientes.</p>`;
  const logHtml = logs.length
    ? logs
        .slice(0, 8)
        .map(
          (log) => `
            <article class="ops-row">
              <strong>${escapeHtml(log.message)}</strong>
              <span class="pill">${escapeHtml(log.level)}</span>
              <p class="card-meta">${escapeHtml(log.createdAt)}</p>
            </article>
          `,
        )
        .join("")
    : `<p class="card-meta">Sin registros recientes.</p>`;
  container.innerHTML = `
    <div class="ops-section"><h3>Tareas</h3>${jobHtml}</div>
    <div class="ops-section"><h3>Registros</h3>${logHtml}</div>
  `;
}

function buildInsights(experiences = state.experiences) {
  if (experiences.length === 0) {
    return [
      {
        type: state.language !== "es" ? "Recommendation" : "Recomendación",
        confidence: 70,
        title: state.language !== "es" ? "Start by capturing three moments" : "Empieza capturando tres momentos",
        description: state.language !== "es"
           ? "The system needs base experiences to detect energy, context, and learning patterns."
          : "El sistema necesita experiencias base para detectar patrones de energía, contexto y aprendizaje.",
        action: state.language !== "es"
           ? "Add one work, one wellbeing, and one learning experience to activate comparisons."
          : "Carga una experiencia de trabajo, una de bienestar y una de aprendizaje para activar comparaciones.",
      },
    ];
  }

  const analysis = buildExperienceAnalysis(experiences);
  const highEnergy = analysis.highEnergy;
  const top = analysis.topCategory;
  const saturated = analysis.saturated;
  const learnings = analysis.learnings;
  const insights = [
    {
      type: state.language !== "es" ? "Pattern" : "Patrón",
      confidence: 88,
      title: state.language !== "es" ? `${displayCategory(top)} leads your recent log` : `${displayCategory(top)} domina tu registro reciente`,
      description: analysis.focus || (state.language !== "es"
         ? `${displayCategory(top)} concentrates more time than other categories. Review whether that distribution reflects your current goals.`
        : `La categoría ${displayCategory(top)} concentra más tiempo que las demás. Conviene revisar si ese reparto refleja tus objetivos actuales.`),
      action: state.language !== "es"
         ? `Review whether ${displayCategory(top)} should remain the priority or whether time should move toward another category.`
        : `Revisa si ${displayCategory(top)} debe mantenerse como prioridad o si conviene redistribuir tiempo hacia otra categoría.`,
    },
    {
      type: "Tendencia",
      confidence: 82,
      title: state.language !== "es" ? "Energy compared by period" : "Energía comparada por periodo",
      description: analysis.trend || (state.language !== "es" ? "There is not enough data yet to compare energy trends between periods." : "Aún no hay suficientes datos para comparar tendencia de energía entre periodos."),
      action: state.language !== "es" ? "Use the 7- or 30-day report filter to check whether the trend holds." : "Usa el filtro de 7 o 30 días en Reportes para revisar si la tendencia se sostiene.",
    },
    {
      type: saturated.length ? (state.language !== "es" ? "Risk" : "Riesgo") : (state.language !== "es" ? "Achievement" : "Logro"),
      confidence: saturated.length ? 84 : 76,
      title: saturated.length ? (state.language !== "es" ? "Saturation signals detected" : "Señales de saturación detectadas") : (state.language !== "es" ? "No dominant saturation" : "Sin saturación dominante"),
      description: analysis.risk || (state.language !== "es" ? "Recent emotional state remains stable; this is a good moment to measure goal progress." : "El estado emocional reciente se mantiene estable; buen momento para medir progreso de objetivos."),
      action: saturated.length
        ? (state.language !== "es" ? "Schedule a recovery routine or reduce load in the most saturated category." : "Programa una rutina de recuperación o reduce carga en la categoría con más saturación.")
        : (state.language !== "es" ? "Keep the current pattern and capture context notes to validate stability." : "Mantén el patrón actual y captura notas de contexto para validar la estabilidad."),
    },
    {
      type: state.language !== "es" ? "Recommendation" : "Recomendación",
      confidence: 81,
      title: state.language !== "es" ? "Turn learnings into actions" : "Convierte aprendizajes en acciones",
      description: state.language !== "es"
         ? `${learnings.length} experiences contain explicit learning. Add next actions to close the memory-action loop.`
        : `${learnings.length} experiencias contienen aprendizaje explícito. Agrega acciones pendientes para cerrar el ciclo memoria-acción.`,
      action: state.language !== "es"
         ? "Filter Learning in the library and turn the three most repeated learnings into next steps."
        : "Filtra Aprendizaje en la librería y convierte los tres aprendizajes más repetidos en próximos pasos.",
    },
  ];

  if (highEnergy.length) {
    insights.splice(2, 0, {
      type: state.language !== "es" ? "Correlation" : "Correlación",
      confidence: 78,
      title: state.language !== "es" ? "High energy linked to clear context" : "Alta energía conectada con contexto claro",
      description: state.language !== "es"
         ? `${highEnergy.length} experiences show high energy. ${analysis.energyDrivers || "Use those contexts as candidates for proactive routines."}`
        : `${highEnergy.length} experiencias aparecen con energía alta. ${analysis.energyDrivers || "Usa esos contextos como candidatos para rutinas proactivas."}`,
      action: state.language !== "es"
         ? "Repeat the context of experiences with energy 8/10 or higher and measure whether the pattern holds."
        : "Repite el contexto de las experiencias con energía 8/10 o superior y mide si el patrón se mantiene.",
    });
  }

  if (state.contextImpact) {
    insights.push({
      type: state.language !== "es" ? "Context" : "Contexto",
      confidence: 74,
      title: state.language !== "es" ? "External impact is active in the reading" : "Impacto externo activo en la lectura",
      description: state.language !== "es"
         ? `Current context analysis is ${state.contextImpact.impactScore}/100: ${state.contextImpact.summary}`
        : `El análisis contextual actual marca ${state.contextImpact.impactScore}/100: ${state.contextImpact.summary}`,
      action: state.language !== "es"
         ? "Before planning critical experiences, review the place in Dashboard and compare weather/news with registered energy."
        : "Antes de planificar experiencias críticas, revisa el lugar en el Panel y compara clima/noticias con energía registrada.",
    });
  }

  if (analysis.biometricContext?.status === "active") {
    const hasReliableBiometricEnergy = Number.isFinite(Number(analysis.biometricContext.averageSuggestedEnergy))
      && Number(analysis.biometricContext.averageSuggestedEnergy) > 0;
    const biometricEnergyDescription = hasReliableBiometricEnergy
      ? (state.language !== "es"
          ? ` Suggested energy averages ${Number(analysis.biometricContext.averageSuggestedEnergy).toFixed(1)}/10.`
          : ` La energía sugerida promedia ${Number(analysis.biometricContext.averageSuggestedEnergy).toFixed(1)}/10.`)
      : (state.language !== "es"
          ? " There is not enough biometric evidence yet for a reliable energy estimate."
          : " Todavía no hay evidencia biométrica suficiente para estimar energía con confianza.");
    insights.push({
      type: state.language !== "es" ? "Biometrics" : "Biometría",
      confidence: Math.round(Math.min(92, 62 + analysis.biometricContext.coveragePct * 0.3)),
      title: state.language !== "es" ? "Body context now informs this reading" : "El contexto corporal ya informa esta lectura",
      description: state.language !== "es"
         ? `${Math.round(analysis.biometricContext.coveragePct)}% of the selected experiences have nearby biometric context.${biometricEnergyDescription}`
        : `${Math.round(analysis.biometricContext.coveragePct)}% de las experiencias seleccionadas tiene contexto biométrico cercano.${biometricEnergyDescription}`,
      action: analysis.biometricContext.biometricRiskScore >= 40
        ? (state.language !== "es" ? "Before adding demanding activities, review sleep, heart rate, and recovery signals in the Dashboard." : "Antes de sumar actividades exigentes, revisa sueño, frecuencia y recuperación en el Panel.")
        : (state.language !== "es" ? "Keep capturing perceived energy; compare it with biometric suggestions to calibrate future reports." : "Sigue capturando energía percibida; compárala con la sugerencia biométrica para calibrar reportes futuros."),
    });
  }

  return insights;
}

function buildExperienceAnalysis(experiences) {
  const list = [...experiences].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
  const midpoint = Math.floor(list.length / 2);
  const previous = list.slice(0, midpoint);
  const recent = list.slice(midpoint);
  const recentEnergy = recent.length ? average(recent.map((item) => item.energy)) : 0;
  const previousEnergy = previous.length ? average(previous.map((item) => item.energy)) : recentEnergy;
  const energyDelta = recent.length && previous.length ? Number((recentEnergy - previousEnergy).toFixed(1)) : 0;
  const topCategory = getTopCategory(list);
  const categoryBreakdown = buildCategoryBreakdown(list);
  const saturated = list.filter((item) => item.mood === "Saturado");
  const highEnergy = list.filter((item) => item.energy >= 8);
  const lowEnergy = list.filter((item) => item.energy <= 4);
  const learnings = list.filter((item) => item.category === "Aprendizaje" || String(item.notes || "").toLowerCase().includes("aprendi"));
  const topObjective = topValue(list.map((item) => item.objective).filter(Boolean));
  const topPerson = topValue(list.flatMap((item) => splitListField(item.people)));
  const topLocation = topValue(list.map((item) => item.location).filter((value) => value && value !== "Sin ubicación"));
  const biometricContext = buildBiometricIntelligenceSummary(list);
  const trend = list.length < 4
    ? (state.language !== "es" ? "At least four experiences are needed for a reliable trend." : "Se necesitan al menos cuatro experiencias para una tendencia confiable.")
    : energyDelta > 0.5
      ? (state.language !== "es" ? `Recent energy is up ${energyDelta} points versus the previous period.` : `La energía reciente sube ${energyDelta} puntos frente al periodo anterior.`)
      : energyDelta < -0.5
        ? (state.language !== "es" ? `Recent energy is down ${Math.abs(energyDelta)} points versus the previous period.` : `La energía reciente baja ${Math.abs(energyDelta)} puntos frente al periodo anterior.`)
        : (state.language !== "es" ? "Recent energy remains stable versus the previous period." : "La energía reciente se mantiene estable frente al periodo anterior.");
  const focus = topObjective
    ? (state.language !== "es" ? `The most repeated goal is "${topObjective}", with ${displayCategory(topCategory)} as the primary life area.` : `El objetivo más repetido es "${topObjective}", con predominio del Área de vida ${displayCategory(topCategory)}.`)
    : (state.language !== "es" ? `The primary life area is ${displayCategory(topCategory)}; more specific goals still need to be captured.` : `El Área de vida principal es ${displayCategory(topCategory)}; aún falta capturar objetivos más específicos.`);
  const risk = saturated.length || lowEnergy.length
    ? (state.language !== "es" ? `${saturated.length} saturated experiences and ${lowEnergy.length} low-energy experiences need follow-up.` : `${saturated.length} experiencias saturadas y ${lowEnergy.length} con energía baja requieren seguimiento.`)
    : (state.language !== "es" ? "There are no strong saturation or low-energy signals in the filtered set." : "No hay señales fuertes de saturación o energía baja en el conjunto filtrado.");
  const energyDrivers = topLocation || topPerson
    ? state.language !== "es"
        ? `Higher-energy contexts can be compared with ${topLocation ? `location ${topLocation}` : `person ${topPerson}`}.`
      : `Los contextos de mayor energía se pueden comparar con ${topLocation ? `ubicación ${topLocation}` : `persona ${topPerson}`}.`
    : "";
  const action = saturated.length || biometricContext.biometricRiskScore >= 60
    ? (state.language !== "es" ? "Prioritize recovery, reduce friction, and avoid adding load to saturated contexts." : "Prioriza recuperación, reduce fricción y evita concentrar nuevas cargas en los contextos saturados.")
    : highEnergy.length
      ? (state.language !== "es" ? "Replicate the conditions of high-energy experiences and turn them into routines." : "Replica las condiciones de las experiencias con energía alta y conviértelas en rutina.")
      : (state.language !== "es" ? "Improve capture quality with goal, people, and location for more precise recommendations." : "Aumenta la calidad de captura con objetivo, persona y ubicación para obtener recomendaciones más precisas.");
  return {
    executive: [trend, focus, risk],
    trend,
    focus,
    risk,
    action,
    biometricContext,
    energyDrivers,
    topCategory,
    saturated,
    highEnergy,
    lowEnergy,
    learnings,
    categoryBreakdown,
  };
}

function buildCategoryBreakdown(experiences) {
  const grouped = experiences.reduce((acc, item) => {
    const category = normalizeCategoryName(item.category);
    if (!acc[category]) {
      acc[category] = { category, count: 0, minutes: 0, energy: [], saturated: 0, attachments: 0 };
    }
    acc[category].count += 1;
    acc[category].minutes += Number(item.duration || 0);
    acc[category].energy.push(Number(item.energy || 0));
    acc[category].saturated += item.mood === "Saturado" ? 1 : 0;
    acc[category].attachments += item.attachments?.length || 0;
    return acc;
  }, {});
  return Object.values(grouped)
    .map((row) => ({
      ...row,
      avgEnergy: row.energy.length ? Number(average(row.energy).toFixed(1)) : 0,
      energy: undefined,
    }))
    .sort((a, b) => b.minutes - a.minutes || b.count - a.count);
}

function topValue(values) {
  const counts = values.reduce((acc, value) => {
    const key = String(value || "").trim();
    if (key) acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  return Object.entries(counts).sort((a, b) => b[1] - a[1])[0]?.[0] || "";
}

function splitListField(value) {
  return String(value || "")
    .split(/[,;]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

async function answerQuestion() {
  const question = document.getElementById("questionInput").value.trim().toLowerCase();
  const answerBox = document.getElementById("answerBox");
  if (!question) {
    answerBox.textContent = state.language !== "es"
       ? "Ask a question about energy, categories, people, locations, or learnings."
      : "Haz una pregunta sobre energía, categorías, personas, ubicaciones o aprendizajes.";
    return;
  }

  answerBox.textContent = state.language !== "es" ? "Searching related experiences..." : "Buscando experiencias relacionadas...";
  const scopedExperiences = getInsightsExperiences();
  const selectedParticipantId = state.insightsFilters?.pilotParticipantId || "all";
  const matches = (await semanticSearch(question)).filter(
    (item) => experienceMatchesPilotParticipant(item, selectedParticipantId),
  );

  const target = matches.length ? matches : scopedExperiences;
  const avg = target.length ? average(target.map((item) => item.energy)).toFixed(1) : "0.0";
  const categoriesFound = [...new Set(target.map((item) => displayCategory(item.category)))].slice(0, 4).join(", ");
  const sample = target.slice(0, 3);
  answerBox.innerHTML = `
    <section class="question-answer-card">
      <span class="report-kicker">${state.language !== "es" ? "System answer" : "Respuesta del sistema"}</span>
      <h3>${escapeHtml(question)}</h3>
      <div class="question-answer-metrics">
        <article><span>${state.language !== "es" ? "Matches" : "Coincidencias"}</span><strong>${matches.length}</strong></article>
        <article><span>${t("metrics.avgEnergy")}</span><strong>${avg}/10</strong></article>
        <article><span>${state.language !== "es" ? "Categories" : "Categorías"}</span><strong>${escapeHtml(categoriesFound || (state.language !== "es" ? "no data" : "sin datos"))}</strong></article>
      </div>
      <p>${state.contextImpact ? `${state.language !== "es" ? "Current external context" : "Contexto externo actual"}: ${escapeHtml(state.contextImpact.summary)}` : (state.language !== "es" ? "This answer will be enriched automatically when city-level context is available." : "Esta respuesta se enriquecerá automáticamente cuando haya contexto de ciudad disponible.")}</p>
      ${
        sample.length
           ? `<div class="question-match-list">
              ${sample
                .map(
                  (item) => `
                    <article>
                      <strong>${escapeHtml(item.title)}</strong>
                      <span>${escapeHtml(displayCategory(item.category))} · ${formatShortDate(item.timestamp)} · ${item.energy}/10</span>
                    </article>
                  `,
                )
                .join("")}
            </div>`
          : ""
      }
    </section>
  `;
}

async function semanticSearch(question) {
  if (state.apiOnline) {
    try {
      const payload = await apiRequest("/search/semantic", {
        method: "POST",
        body: JSON.stringify({ query: question, limit: 8 }),
      });
      if (Array.isArray(payload.results)) return payload.results.map((result) => result.experience);
    } catch (error) {
      markApiConnectivityFailure(error);
    }
  }
  return semanticSearchExperiences(question);
}

async function backfillEmbeddings() {
  const status = document.getElementById("embeddingStatus");
  if (!state.apiOnline) {
    status.textContent = "API no disponible para actualizar embeddings.";
    return;
  }
  status.textContent = "Actualizando embeddings...";
  try {
    const result = await apiRequest("/jobs/embeddings", {
      method: "POST",
      body: JSON.stringify({ limit: 200 }),
    });
    state.embeddingStatus = `Job ${result.jobId} en cola.`;
    status.textContent = state.embeddingStatus;
    await refreshOps({ silent: true });
  } catch {
    status.textContent = "No se pudieron actualizar embeddings. Revisa la sesión de Supabase.";
  }
}

async function syncWorkspaceStructure() {
  const status = document.getElementById("embeddingStatus");
  if (!state.apiOnline) {
    status.textContent = state.language !== "es" ? "API unavailable for structure sync." : "API no disponible para sincronizar estructura.";
    return;
  }
  status.textContent = state.language !== "es" ? "Syncing workspace structure..." : "Sincronizando estructura workspace...";
  try {
    const result = await apiRequest("/workspace/backfill", {
      method: "POST",
      body: JSON.stringify({}),
    });
    const ok = result.status === "ok" || result.status === "partial";
    status.textContent = ok
      ? state.language !== "es"
        ? `Structure sync: ${result.syncedExperiences} experiences, ${result.syncedParticipants || 0} participants, ${result.syncedEvents} events, ${result.syncedAssets} assets.`
       : `Estructura sincronizada: ${result.syncedExperiences} experiencias, ${result.syncedParticipants || 0} participantes, ${result.syncedEvents} eventos, ${result.syncedAssets} activos.`
      : state.language !== "es"
         ? "Migration required: apply database/workspace-events-assets.sql first."
        : "Migración requerida: aplica primero database/workspace-events-assets.sql.";
    await runSupabaseDiagnostics();
  } catch {
    status.textContent = state.language !== "es"
       ? "Could not sync structure. Check session and Supabase migration."
      : "No se pudo sincronizar la estructura. Revisa sesión y migración Supabase.";
  }
}

function semanticSearchExperiences(question) {
  const queryVector = vectorize(question);
  return state.experiences
    .map((item) => ({
      item,
      score: cosineSimilarity(queryVector, vectorize(`${item.title} ${item.objective} ${item.category} ${item.mood} ${item.location} ${item.people} ${item.notes}`)),
    }))
    .filter((entry) => entry.score > 0.08)
    .sort((a, b) => b.score - a.score)
    .map((entry) => entry.item);
}

function vectorize(text) {
  const synonyms = {
    clima: "weather weather tiempo lluvia viento temperatura",
    weather: "weather clima lluvia viento temperatura",
    energia: "energy focus mood energía ánimo productividad",
    energy: "energy focus mood energía ánimo productividad",
    geopolitica: "geopolitical news conflict protest security election noticias",
    noticias: "news geopolitical conflict protest security election",
    aprendizaje: "learning study insight skill conocimiento",
    familia: "family social hogar relaciones",
  };
  return tokenize(text).reduce((vector, token) => {
    const expanded = synonyms[token] ? tokenize(`${token} ${synonyms[token]}`) : [token];
    expanded.forEach((term) => {
      vector[term] = (vector[term] || 0) + 1;
    });
    return vector;
  }, {});
}

function tokenize(text) {
  return String(text)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .split(/[^a-z0-9]+/)
    .filter((token) => token.length > 2);
}

function cosineSimilarity(a, b) {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  let dot = 0;
  let normA = 0;
  let normB = 0;
  keys.forEach((key) => {
    dot += (a[key] || 0) * (b[key] || 0);
    normA += (a[key] || 0) ** 2;
    normB += (b[key] || 0) ** 2;
  });
  return dot / (Math.sqrt(normA) * Math.sqrt(normB) || 1);
}

function getFilteredExperiences() {
  return [...state.experiences]
    .filter((item) => {
      if (isSupersededExperience(item)) return false;
      const text = `${item.title} ${item.objective} ${item.notes} ${item.people} ${item.location} ${getExperiencePilotParticipantLabel(item)} ${buildExperienceEventSearchText(item)}`.toLowerCase();
      const queryMatch = !state.filters.query || text.includes(state.filters.query);
      const categoryMatch = state.filters.category === "all" || item.category === state.filters.category;
      const moodMatch = state.filters.mood === "all" || item.mood === state.filters.mood;
      return queryMatch && categoryMatch && moodMatch;
    })
    .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
}

function getFilteredLibraryExperiences() {
  return [...state.experiences]
    .filter((item) => {
      if (isSupersededExperience(item)) return false;
      const text = `${item.title} ${item.objective} ${item.notes} ${item.people} ${item.location} ${item.category} ${getExperiencePilotParticipantLabel(item)} ${buildExperienceEventSearchText(item)}`.toLowerCase();
      const queryMatch = !state.libraryFilters.query || text.includes(state.libraryFilters.query);
      const categoryMatch = state.libraryFilters.category === "all" || item.category === state.libraryFilters.category;
      const hasMedia = (item.attachments?.length || 0) > 0;
      const mediaMatch =
        state.libraryFilters.media === "all" ||
        (state.libraryFilters.media === "with-media" && hasMedia) ||
        (state.libraryFilters.media === "without-media" && !hasMedia);
      const sourceMatch = state.libraryFilters.source === "all" || getExperienceSourceKey(item) === state.libraryFilters.source;
      const participantMatch =
        state.libraryFilters.pilotParticipantId === "all" ||
        item.pilotParticipantId === state.libraryFilters.pilotParticipantId;
      return queryMatch && categoryMatch && mediaMatch && sourceMatch && participantMatch;
    })
    .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
}

function categoryTotals(experiences = state.experiences) {
  return experiences.reduce((totals, item) => {
    const category = normalizeCategoryName(item.category);
    totals[category] = (totals[category] || 0) + item.duration;
    return totals;
  }, {});
}

function getTopCategory(experiences = state.experiences) {
  const totals = categoryTotals(experiences);
  const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
  return sorted[0]?.[0] || "Sin datos";
}

function readPrivacySettings() {
  return {
    localProcessing: document.getElementById("localProcessing").checked,
    shareAnalytics: document.getElementById("shareAnalytics").checked,
    sensitiveMode: document.getElementById("sensitiveMode").checked,
  };
}

function hasEncryptedLocalData() {
  try {
    return Boolean(JSON.parse(localStorage.getItem("experience-hub-data") || "null")?.encrypted);
  } catch {
    return false;
  }
}

function renderLocalKeyStatus() {
  const status = document.getElementById("localKeyStatus");
  if (!status) return;
  const key = document.getElementById("localKeyInput")?.value || "";
  const sensitive = document.getElementById("sensitiveMode")?.checked;
  const encryptedStored = hasEncryptedLocalData();
  let message = t("labels.localKeyOff");
  let tone = "neutral";
  if (encryptedStored) {
    message = t("labels.localKeyEncryptedStored");
    tone = "warning";
  } else if (sensitive && key) {
    message = t("labels.localKeyReady");
    tone = "success";
  } else if (sensitive && !key) {
    message = t("labels.localKeyMissing");
    tone = "warning";
  }
  status.textContent = message;
  status.dataset.tone = tone;
  renderPrivacyChecklist();
}

function renderPrivacyChecklist() {
  const box = document.getElementById("privacyChecklist");
  if (!box) return;
  const key = document.getElementById("localKeyInput")?.value || "";
  const settings = readPrivacySettings();
  const encryptedStored = hasEncryptedLocalData();
  const checks = [
    { label: t("labels.privacyChecklistLocal"), ok: settings.localProcessing },
    { label: t("labels.privacyChecklistAnalytics"), ok: !settings.shareAnalytics },
    { label: t("labels.privacyChecklistSensitive"), ok: settings.sensitiveMode },
    { label: t("labels.privacyChecklistKey"), ok: Boolean(key || encryptedStored) },
  ];
  const ready = checks.every((item) => item.ok);
  const message = ready
    ? t("labels.privacyChecklistReady")
    : settings.sensitiveMode && !key && !encryptedStored
      ? t("labels.privacyChecklistNeedsKey")
      : t("labels.privacyChecklistNeedsRecommended");
  box.dataset.tone = ready ? "success" : "warning";
  box.innerHTML = `
    <strong>${escapeHtml(message)}</strong>
    <div>
      ${checks.map((item) => `<span class="${item.ok ? "is-ok" : "is-missing"}">${item.ok ? "?" : "!"} ${escapeHtml(item.label)}</span>`).join("")}
    </div>
  `;
}

function toggleLocalKeyVisibility() {
  const input = document.getElementById("localKeyInput");
  const button = document.getElementById("toggleLocalKeyButton");
  if (!input || !button) return;
  input.type = input.type === "password" ? "text" : "password";
  button.textContent = input.type === "password" ? t("buttons.showLocalKey") : t("buttons.hideLocalKey");
}

function handleSensitiveModeChange() {
  const key = document.getElementById("localKeyInput").value;
  if (readPrivacySettings().sensitiveMode && !key) {
    document.getElementById("localKeyInput").focus();
  }
  renderLocalKeyStatus();
}

function applyRecommendedPrivacySettings() {
  document.getElementById("localProcessing").checked = true;
  document.getElementById("shareAnalytics").checked = false;
  document.getElementById("sensitiveMode").checked = true;
  renderLocalKeyStatus();
  const keyInput = document.getElementById("localKeyInput");
  if (keyInput && !keyInput.value) keyInput.focus();
  const status = document.getElementById("embeddingStatus");
  if (status) status.textContent = t("labels.privacyRecommendedApplied");
}

async function applyLocalKeyToCurrentData() {
  const key = document.getElementById("localKeyInput").value;
  const status = document.getElementById("embeddingStatus");
  if (!key) {
    renderLocalKeyStatus();
    if (status) status.textContent = t("labels.localKeyMissing");
    return;
  }
  if (!confirm(t("labels.localKeyConfirm"))) return;
  try {
    const encrypted = await encryptLocalPayload(state.experiences, key);
    localStorage.setItem("experience-hub-data", JSON.stringify(encrypted));
    document.getElementById("sensitiveMode").checked = true;
    renderLocalKeyStatus();
    if (status) status.textContent = t("labels.localKeyApplied");
  } catch {
    if (status) status.textContent = t("labels.localKeyApplyFailed");
  }
}

async function encryptLocalPayload(payload, passphrase) {
  const json = JSON.stringify(payload);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveAesKey(passphrase, salt);
  const encoded = new TextEncoder().encode(json);
  const encrypted = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, encoded);
  return {
    encrypted: true,
    algorithm: "AES-GCM",
    kdf: "PBKDF2-SHA-256",
    iterations: 150000,
    createdAt: new Date().toISOString(),
    salt: bytesToBase64(salt),
    iv: bytesToBase64(iv),
    data: bytesToBase64(new Uint8Array(encrypted)),
  };
}

async function unlockLocalData() {
  const key = document.getElementById("localKeyInput").value;
  const status = document.getElementById("embeddingStatus");
  if (!key) {
    if (status) status.textContent = "Escribe la clave local para desbloquear.";
    return;
  }
  try {
    const saved = JSON.parse(localStorage.getItem("experience-hub-data") || "null");
    if (!saved?.encrypted) {
      if (status) status.textContent = "No hay datos locales cifrados.";
      return;
    }
    const unlocked = await decryptLocalPayload(saved, key);
    state.experiences = normalizeExperiences(Array.isArray(unlocked) ? unlocked : unlocked.experiences || []);
    saveExperiences();
    renderAll();
    if (status) status.textContent = `${state.experiences.length} experiencias locales desbloqueadas.`;
    renderLocalKeyStatus();
  } catch {
    if (status) status.textContent = "No se pudo desbloquear con esa clave.";
    renderLocalKeyStatus();
  }
}

async function decryptLocalPayload(payload, passphrase) {
  if (payload.algorithm === "xor-local-mvp") return decryptLegacyLocalPayload(payload, passphrase);
  const salt = base64ToBytes(payload.salt);
  const iv = base64ToBytes(payload.iv);
  const key = await deriveAesKey(passphrase, salt);
  const encrypted = base64ToBytes(payload.data);
  const decrypted = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, encrypted);
  return JSON.parse(new TextDecoder().decode(decrypted));
}

async function deriveAesKey(passphrase, salt) {
  const material = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(passphrase),
    { name: "PBKDF2" },
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 150000,
      hash: "SHA-256",
    },
    material,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

function decryptLegacyLocalPayload(payload, passphrase) {
  const key = deriveLegacyLocalKey(passphrase);
  const encrypted = Array.from(atob(payload.data), (char) => char.charCodeAt(0));
  const decoded = encrypted.map((value, index) => String.fromCharCode(value ^ key[index % key.length])).join("");
  return JSON.parse(decoded);
}

function deriveLegacyLocalKey(passphrase) {
  const seed = String(passphrase || "experience-hub");
  const key = [];
  let hash = 2166136261;
  for (let index = 0; index < seed.length; index += 1) {
    hash ^= seed.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  for (let index = 0; index < 32; index += 1) {
    hash ^= index;
    hash = Math.imul(hash, 16777619);
    key.push(hash & 255);
  }
  return key;
}

function bytesToBase64(bytes) {
  return btoa(String.fromCharCode(...bytes));
}

function base64ToBytes(value) {
  return Uint8Array.from(atob(value), (char) => char.charCodeAt(0));
}

function bytesToHex(bytes) {
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function average(values) {
  return values.reduce((sum, value) => sum + value, 0) / Math.max(1, values.length);
}

function formatFileSize(bytes = 0) {
  const size = Number(bytes) || 0;
  if (size < 1024) return `${size} B`;
  if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
  return `${(size / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(value) {
  const date = new Date(value);
  if (!value || Number.isNaN(date.getTime())) {
    return state.language !== "es" ? "No date" : "Sin fecha";
  }
  return new Intl.DateTimeFormat("es", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function formatShortDate(value) {
  const date = new Date(value);
  if (!value || Number.isNaN(date.getTime())) {
    return state.language !== "es" ? "No date" : "Sin fecha";
  }
  return new Intl.DateTimeFormat("es", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(date);
}

function attachmentKind(attachment) {
  if (attachment.type.startsWith("video/")) return "video";
  if (attachment.type.startsWith("audio/")) return "audio";
  return "imagen";
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function toDatetimeLocal(value) {
  const date = new Date(value);
  const offset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 16);
}
